export interface Ingredient {
  id: string;
  name: string;
  unit: 'kg' | 'g' | 'unit' | 'lt' | 'ml';
  stock: number;
  minStock: number;
  costPerUnit: number;
}

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  category: 'Cortes' | 'Acompañamientos' | 'Bebidas' | 'Postres';
  recipe: {
    ingredientId: string;
    amount: number;
  }[];
}

export interface Sale {
  id: string;
  timestamp: Date;
  items: {
    menuItemId: string;
    quantity: number;
    priceAtSale: number;
  }[];
  total: number;
}

export type View = 'dashboard' | 'inventory' | 'menu' | 'sales' | 'analysis';

