import { GoogleGenAI, Type } from "@google/genai";
import { Ingredient, MenuItem, Sale } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getBusinessAnalysis = async (
  ingredients: Ingredient[],
  menu: MenuItem[],
  sales: Sale[]
) => {
  const prompt = `
    Analiza el estado actual de este restaurante de asados:
    Inventario: ${JSON.stringify(ingredients)}
    Menú: ${JSON.stringify(menu)}
    Ventas Recientes: ${JSON.stringify(sales)}

    Por favor, proporciona:
    1. Resumen de rentabilidad por plato.
    2. Alertas de inventario crítico.
    3. Recomendaciones estratégicas para maximizar ganancias (ej. qué plato promocionar).
    4. Análisis de desperdicio o costos.
    Responde de forma profesional en español y formato Markdown.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    return "Lo siento, no pude generar el análisis en este momento.";
  }
};

