import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Ingredient, Sale, MenuItem } from '../types';

interface DashboardProps {
  ingredients: Ingredient[];
  sales: Sale[];
  menu: MenuItem[];
}

const Dashboard: React.FC<DashboardProps> = ({ ingredients, sales, menu }) => {
  const totalRevenue = sales.reduce((sum, s) => sum + s.total, 0);
  const lowStockCount = ingredients.filter(i => i.stock <= i.minStock).length;

  // Calculate top selling items for the chart
  const salesByItem: Record<string, number> = {};
  sales.forEach(sale => {
    sale.items.forEach(item => {
      const menuItem = menu.find(m => m.id === item.menuItemId);
      if (menuItem) {
        salesByItem[menuItem.name] = (salesByItem[menuItem.name] || 0) + item.quantity;
      }
    });
  });

  const chartData = Object.entries(salesByItem).map(([name, qty]) => ({ name, qty }));

  return (
    <div className="space-y-6 animate-fadeIn">
      <header className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-slate-800">Panel de Control</h2>
        <span className="text-sm text-slate-500">{new Date().toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</span>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Ventas Totales</p>
          <p className="text-3xl font-bold text-green-600 mt-1">${totalRevenue.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Alertas de Inventario</p>
          <p className={`text-3xl font-bold mt-1 ${lowStockCount > 0 ? 'text-red-500' : 'text-slate-800'}`}>
            {lowStockCount} items bajos
          </p>
        </div>
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-sm font-medium">Transacciones</p>
          <p className="text-3xl font-bold text-blue-600 mt-1">{sales.length}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="font-semibold text-slate-800 mb-6">Platos más Vendidos</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip 
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="qty" fill="#ea580c" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <h3 className="font-semibold text-slate-800 mb-4">Stock Crítico</h3>
          <div className="space-y-4 max-h-[250px] overflow-y-auto">
            {ingredients.filter(i => i.stock <= i.minStock).map(item => (
              <div key={item.id} className="flex items-center justify-between p-3 bg-red-50 rounded-lg border border-red-100">
                <div>
                  <p className="font-medium text-red-900">{item.name}</p>
                  <p className="text-xs text-red-700">Mínimo: {item.minStock} {item.unit} | Actual: {item.stock} {item.unit}</p>
                </div>
                <button className="px-3 py-1 bg-red-600 text-white text-xs rounded hover:bg-red-700 transition-colors">
                  Reordenar
                </button>
              </div>
            ))}
            {lowStockCount === 0 && (
              <div className="text-center py-12 text-slate-400">
                <p>Todo el inventario está en niveles óptimos.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

