import React from 'react';
import { MenuItem, Ingredient } from '../types';

interface MenuManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, ingredients }) => {
  const calculateCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => {
      const ingredient = ingredients.find(i => i.id === item.ingredientId);
      return total + (ingredient ? ingredient.costPerUnit * item.amount : 0);
    }, 0);
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-fadeIn">
      {menu.map((item) => {
        const cost = calculateCost(item.recipe);
        const margin = ((item.price - cost) / item.price) * 100;

        return (
          <div key={item.id} className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 hover:border-orange-200 transition-all group">
            <div className="flex justify-between items-start mb-4">
              <div>
                <span className="text-[10px] font-bold tracking-wider uppercase bg-orange-100 text-orange-700 px-2 py-0.5 rounded-full mb-2 inline-block">
                  {item.category}
                </span>
                <h3 className="text-xl font-bold text-slate-900">{item.name}</h3>
                <p className="text-slate-500 text-sm">{item.description}</p>
              </div>
              <div className="text-right">
                <p className="text-2xl font-black text-slate-900">${item.price.toFixed(2)}</p>
                <span className="text-xs font-semibold text-green-600">Margen: {margin.toFixed(1)}%</span>
              </div>
            </div>

            <div className="bg-slate-50 p-4 rounded-lg mb-4">
              <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Composición del Costo</h4>
              <div className="space-y-1">
                {item.recipe.map((r, idx) => {
                  const ing = ingredients.find(i => i.id === r.ingredientId);
                  return (
                    <div key={idx} className="flex justify-between text-sm text-slate-700">
                      <span>{ing?.name} ({r.amount} {ing?.unit})</span>
                      <span className="font-medium">${(r.amount * (ing?.costPerUnit || 0)).toFixed(2)}</span>
                    </div>
                  );
                })}
                <div className="border-t border-slate-200 pt-2 mt-2 flex justify-between font-bold text-slate-800">
                  <span>Costo Total Estimado:</span>
                  <span>${cost.toFixed(2)}</span>
                </div>
              </div>
            </div>

            <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              <button className="flex-1 py-2 bg-slate-100 text-slate-700 text-sm font-medium rounded-lg hover:bg-slate-200 transition-colors">
                Editar Receta
              </button>
              <button className="flex-1 py-2 bg-slate-900 text-white text-sm font-medium rounded-lg hover:bg-slate-800 transition-colors">
                Actualizar Precio
              </button>
            </div>
          </div>
        );
      })}

      <div className="border-2 border-dashed border-slate-200 rounded-xl flex items-center justify-center p-12 hover:bg-slate-50 transition-colors cursor-pointer">
        <div className="text-center">
          <span className="text-4xl text-slate-300 block mb-2">➕</span>
          <p className="font-medium text-slate-500">Nuevo Plato al Menú</p>
        </div>
      </div>
    </div>
  );
};

export default MenuManager;

import React, { useState } from 'react';
import { Sale, MenuItem } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  onAddSale: (saleItems: { menuItemId: string, quantity: number }[]) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, menu, onAddSale }) => {
  const [cart, setCart] = useState<Record<string, number>>({});

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string) => {
    if (!cart[id]) return;
    const newCart = { ...cart };
    if (newCart[id] === 1) delete newCart[id];
    else newCart[id] -= 1;
    setCart(newCart);
  };

  const handleCheckout = () => {
    const items = Object.entries(cart).map(([menuItemId, quantity]) => ({
      menuItemId,
      quantity
    }));
    if (items.length === 0) return;
    onAddSale(items);
    setCart({});
  };

  const cartTotal = Object.entries(cart).reduce((total, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return total + (item ? item.price * qty : 0);
  }, 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h2 className="text-xl font-bold text-slate-800 mb-6">Punto de Venta</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {menu.map(item => (
              <div key={item.id} className="p-4 border border-slate-100 rounded-xl hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center bg-slate-50/30">
                <div>
                  <h4 className="font-bold text-slate-900">{item.name}</h4>
                  <p className="text-sm text-slate-500">${item.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  <button onClick={() => addToCart(item.id)} className="w-8 h-8 bg-orange-600 text-white rounded-full flex items-center justify-center hover:bg-orange-700 transition-colors">
                    +
                  </button>
                  {cart[item.id] && (
                    <>
                      <span className="font-bold text-slate-800">{cart[item.id]}</span>
                      <button onClick={() => removeFromCart(item.id)} className="w-8 h-8 bg-slate-200 text-slate-600 rounded-full flex items-center justify-center hover:bg-slate-300 transition-colors">
                        -
                      </button>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <h2 className="text-xl font-bold text-slate-800 mb-6">Últimas Ventas</h2>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-slate-500 text-xs font-semibold uppercase">
                <tr>
                  <th className="px-4 py-3">Fecha/Hora</th>
                  <th className="px-4 py-3">Detalle</th>
                  <th className="px-4 py-3 text-right">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {[...sales].reverse().slice(0, 5).map(sale => (
                  <tr key={sale.id} className="text-sm">
                    <td className="px-4 py-3 text-slate-500">
                      {new Date(sale.timestamp).toLocaleString('es-ES', { hour: '2-digit', minute: '2-digit' })}
                    </td>
                    <td className="px-4 py-3 text-slate-900">
                      {sale.items.map(i => {
                        const m = menu.find(mi => mi.id === i.menuItemId);
                        return `${i.quantity}x ${m?.name}`;
                      }).join(', ')}
                    </td>
                    <td className="px-4 py-3 text-right font-bold text-slate-900">
                      ${sale.total.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-xl flex flex-col sticky top-6 max-h-[calc(100vh-3rem)]">
        <h3 className="text-xl font-bold mb-6 flex items-center gap-2">
          <span>🛒</span> Cuenta Actual
        </h3>
        <div className="flex-1 overflow-y-auto space-y-4 mb-6 pr-2 custom-scrollbar">
          {Object.entries(cart).map(([id, qty]) => {
            const item = menu.find(m => m.id === id);
            return (
              <div key={id} className="flex justify-between items-center pb-4 border-b border-slate-800 last:border-0">
                <div>
                  <p className="font-medium">{item?.name}</p>
                  <p className="text-xs text-slate-400">{qty} x ${item?.price.toFixed(2)}</p>
                </div>
                <p className="font-bold text-orange-400">${(qty * (item?.price || 0)).toFixed(2)}</p>
              </div>
            );
          })}
          {Object.keys(cart).length === 0 && (
            <div className="text-center py-12 text-slate-500 italic">
              El carrito está vacío
            </div>
          )}
        </div>

        <div className="border-t border-slate-800 pt-6 space-y-4">
          <div className="flex justify-between text-lg">
            <span className="text-slate-400">Subtotal:</span>
            <span>${(cartTotal * 0.81).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-lg">
            <span className="text-slate-400">IVA (19%):</span>
            <span>${(cartTotal * 0.19).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-2xl font-black pt-2">
            <span>Total:</span>
            <span className="text-orange-500">${cartTotal.toFixed(2)}</span>
          </div>
          <button 
            disabled={Object.keys(cart).length === 0}
            onClick={handleCheckout}
            className="w-full py-4 bg-orange-600 text-white rounded-xl font-bold text-lg hover:bg-orange-700 transition-all active:scale-[0.98] disabled:bg-slate-800 disabled:text-slate-600 disabled:cursor-not-allowed"
          >
            CONFIRMAR VENTA
          </button>
        </div>
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState, useEffect } from 'react';
import { getBusinessAnalysis } from '../services/geminiService';
import { Ingredient, MenuItem, Sale } from '../types';

interface AnalysisViewProps {
  ingredients: Ingredient[];
  menu: MenuItem[];
  sales: Sale[];
}

const AnalysisView: React.FC<AnalysisViewProps> = ({ ingredients, menu, sales }) => {
  const [analysis, setAnalysis] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    const fetchAnalysis = async () => {
      setLoading(true);
      const result = await getBusinessAnalysis(ingredients, menu, sales);
      setAnalysis(result || 'No se pudo generar el análisis.');
      setLoading(false);
    };
    fetchAnalysis();
  }, [ingredients, menu, sales]);

  return (
    <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-100 max-w-4xl mx-auto animate-fadeIn">
      <div className="flex items-center gap-4 mb-8">
        <div className="w-12 h-12 bg-orange-100 rounded-full flex items-center justify-center text-2xl">
          🤖
        </div>
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Análisis Inteligente (Gemini AI)</h2>
          <p className="text-slate-500">Perspectivas basadas en tus datos actuales para optimizar tu negocio.</p>
        </div>
      </div>

      {loading ? (
        <div className="space-y-4 py-12">
          <div className="h-4 bg-slate-100 rounded w-3/4 animate-pulse"></div>
          <div className="h-4 bg-slate-100 rounded w-full animate-pulse"></div>
          <div className="h-4 bg-slate-100 rounded w-5/6 animate-pulse"></div>
          <div className="h-4 bg-slate-100 rounded w-1/2 animate-pulse"></div>
          <p className="text-center text-slate-400 mt-4 font-medium italic">Consultando al Chef Digital...</p>
        </div>
      ) : (
        <div className="prose prose-slate max-w-none">
          {analysis.split('\n').map((line, i) => {
            if (line.startsWith('###')) return <h3 key={i} className="text-xl font-bold mt-6 mb-3 text-slate-800">{line.replace('###', '')}</h3>;
            if (line.startsWith('##')) return <h2 key={i} className="text-2xl font-bold mt-8 mb-4 text-slate-900 border-b pb-2">{line.replace('##', '')}</h2>;
            if (line.trim().startsWith('-')) return <li key={i} className="ml-4 mb-2 text-slate-600">{line.replace('-', '').trim()}</li>;
            if (line.trim().startsWith('*')) return <li key={i} className="ml-4 mb-2 text-slate-600">{line.replace('*', '').trim()}</li>;
            return <p key={i} className="mb-4 text-slate-600 leading-relaxed">{line}</p>;
          })}
