import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import MenuManager from './components/MenuManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import { View, Ingredient, MenuItem, Sale } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [ingredients, setIngredients] = useState<Ingredient[]>(INITIAL_INGREDIENTS);
  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [sales, setSales] = useState<Sale[]>([]);

  // Function to handle stock updates
  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  // Function to register a new sale and deduct inventory
  const addSale = (saleItems: { menuItemId: string, quantity: number }[]) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * si.quantity;

      // Deduct from inventory based on recipe
      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * si.quantity));
        });
      }

      return {
        menuItemId: si.menuItemId,
        quantity: si.quantity,
        priceAtSale: price
      };
    });

    const newSale: Sale = {
      id: Date.now().toString(),
      timestamp: new Date(),
      items: itemsWithPrices,
      total
    };

    setSales(prev => [...prev, newSale]);
  };

  const renderView = () => {
    switch (view) {
      case 'dashboard':
        return <Dashboard ingredients={ingredients} sales={sales} menu={menu} />;
      case 'inventory':
        return <Inventory ingredients={ingredients} onUpdateStock={updateStock} />;
      case 'menu':
        return <MenuManager menu={menu} ingredients={ingredients} />;
      case 'sales':
        return <SalesManager sales={sales} menu={menu} onAddSale={addSale} />;
      case 'analysis':
        return <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />;
      default:
        return <Dashboard ingredients={ingredients} sales={sales} menu={menu} />;
    }
  };

  return (
    <div className="flex bg-slate-50 min-h-screen text-slate-900">
      <Sidebar currentView={view} onNavigate={setView} />

      <main className="flex-1 p-8 overflow-y-auto">
        <div className="max-w-6xl mx-auto">
          {renderView()}
        </div>
      </main>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: #1e293b;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #475569;
          border-radius: 20px;
        }
      `}</style>
    </div>
  );
};

export default App;

