export const getBusinessAnalysis = async (
  ingredients: Ingredient[],
  menu: MenuItem[],
  sales: Sale[]
) => {
  const prompt = `
    Analiza el estado actual de este restaurante de asados:
    Inventario: ${JSON.stringify(ingredients)}
    Menú: ${JSON.stringify(menu)}
    Ventas Recientes: ${JSON.stringify(sales)}

    Por favor, proporciona:
    1. Resumen de rentabilidad por plato.
    2. Alertas de inventario crítico.
    3. Recomendaciones estratégicas para maximizar ganancias (ej. qué plato promocionar).
    4. Análisis de desperdicio o costos.
    Responde de forma profesional en español y formato Markdown.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Error calling Gemini API:", error);
    return "Lo siento, no pude generar el análisis en este momento.";
  }
};

import React, { useState } from 'react';
import { Sale, MenuItem } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  onAddSale: (saleItems: { menuItemId: string, quantity: number }[]) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, menu, onAddSale }) => {
  const [cart, setCart] = useState<Record<string, number>>({});

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string) => {
    if (!cart[id]) return;
    const newCart = { ...cart };
    if (newCart[id] === 1) delete newCart[id];
    else newCart[id] -= 1;
    setCart(newCart);
  };

  const handleCheckout = () => {
    const items = Object.entries(cart).map(([menuItemId, quantity]) => ({
      menuItemId,
      quantity
    }));
    if (items.length === 0) return;
    onAddSale(items);
    setCart({});
  };

  // Fixed: Explicitly typed total and cast qty to number to resolve arithmetic operation errors
  const cartTotal: number = Object.entries(cart).reduce((total: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return total + (item ? item.price * quantity : 0);
  }, 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h2 className="text-xl font-bold text-slate-800 mb-6">Punto de Venta</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {menu.map(item => (
              <div key={item.id} className="p-4 border border-slate-100 rounded-xl hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center bg-slate-50/30">
                <div>
                  <h4 className="font-bold text-slate-900">{item.name}</h4>
                  <p className="text-sm text-slate-500">${item.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  <button onClick={() => addToCart(item.id)} className="w-8 h-8 bg-orange-600 text-white rounded-full flex items-center justify-center hover:bg-orange-700 transition-colors">
                    +
                  </button>
                  {cart[item.id] && (
                    <>
                      <span className="font-bold text-slate-800">{cart[item.id]}</span>
                      <button onClick={() => removeFromCart(item.id)} className="w-8 h-8 bg-slate-200 text-slate-600 rounded-full flex items-center justify-center hover:bg-slate-300 transition-colors">
                        -
                      </button>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <h2 className="text-xl font-bold text-slate-800 mb-6">Últimas Ventas</h2>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-slate-500 text-xs font-semibold uppercase">
                <tr>
                  <th className="px-4 py-3">Fecha/Hora</th>
                  <th className="px-4 py-3">Detalle</th>
                  <th className="px-4 py-3 text-right">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {[...sales].reverse().slice(0, 5).map(sale => (
                  <tr key={sale.id} className="text-sm">
                    <td className="px-4 py-3 text-slate-500">
                      {new Date(sale.timestamp).toLocaleString('es-ES', { hour: '2-digit', minute: '2-digit' })}
                    </td>
                    <td className="px-4 py-3 text-slate-900">
                      {sale.items.map(i => {
                        const m = menu.find(mi => mi.id === i.menuItemId);
                        return `${i.quantity}x ${m?.name}`;
                      }).join(', ')}
                    </td>
                    <td className="px-4 py-3 text-right font-bold text-slate-900">
                      ${sale.total.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-xl flex flex-col sticky top-6 max-h-[calc(100vh-3rem)]">
        <h3 className="text-xl font-bold mb-6 flex items-center gap-2">
          <span>🛒</span> Cuenta Actual
        </h3>
        <div className="flex-1 overflow-y-auto space-y-4 mb-6 pr-2 custom-scrollbar">
          {Object.entries(cart).map(([id, qty]) => {
            const item = menu.find(m => m.id === id);
            return (
              <div key={id} className="flex justify-between items-center pb-4 border-b border-slate-800 last:border-0">
                <div>
                  <p className="font-medium">{item?.name}</p>
                  <p className="text-xs text-slate-400">{qty} x ${item?.price.toFixed(2)}</p>
                </div>
                {/* Fixed: Cast qty to number for arithmetic operation */}
                <p className="font-bold text-orange-400">${((qty as number) * (item?.price || 0)).toFixed(2)}</p>
              </div>
            );
          })}
          {Object.keys(cart).length === 0 && (
            <div className="text-center py-12 text-slate-500 italic">
              El carrito está vacío
            </div>
          )}
        </div>

        <div className="border-t border-slate-800 pt-6 space-y-4">
          <div className="flex justify-between text-lg">
            <span className="text-slate-400">Subtotal:</span>
            <span>${(cartTotal * 0.81).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-lg">
            <span className="text-slate-400">IVA (19%):</span>
            <span>${(cartTotal * 0.19).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-2xl font-black pt-2">
            <span>Total:</span>
            <span className="text-orange-500">${cartTotal.toFixed(2)}</span>
          </div>
          <button 
            disabled={Object.keys(cart).length === 0}
            onClick={handleCheckout}
            className="w-full py-4 bg-orange-600 text-white rounded-xl font-bold text-lg hover:bg-orange-700 transition-all active:scale-[0.98] disabled:bg-slate-800 disabled:text-slate-600 disabled:cursor-not-allowed"
          >
            CONFIRMAR VENTA
          </button>
        </div>
      </div>
    </div>
  );
};

