          <h2 className="text-xl font-bold text-slate-800">Gestión de Menú y Precios</h2>
          <p className="text-slate-500 text-sm">Controla tus márgenes de ganancia y costos de receta.</p>
        </div>
        <button className="bg-slate-900 text-white px-6 py-2 rounded-xl font-bold hover:bg-orange-600 transition-colors">
          Nuevo Plato
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {menu.map((item) => {
          const cost = calculateCost(item.recipe);
          const margin = ((item.price - cost) / item.price) * 100;

          return (
            <div key={item.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:border-orange-200 transition-all group relative overflow-hidden">
              <div className="flex justify-between items-start mb-4">
                <div className="flex-1">
                  <span className="text-[10px] font-black tracking-widest uppercase bg-orange-100 text-orange-700 px-3 py-1 rounded-full mb-3 inline-block">
                    {item.category}
                  </span>
                  <h3 className="text-xl font-black text-slate-900 mb-1">{item.name}</h3>
                  <p className="text-slate-500 text-sm line-clamp-2 pr-4">{item.description}</p>
                </div>
                <div className="text-right">
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Precio Venta</label>
                  <div className="flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1">
                    <span className="text-slate-400 font-bold">$</span>
                    <input 
                      type="number"
                      value={item.price}
                      onChange={(e) => onUpdatePrice(item.id, parseFloat(e.target.value) || 0)}
                      className="w-20 bg-transparent font-black text-xl text-slate-900 focus:outline-none"
                    />
                  </div>
                  <div className={`text-xs font-bold mt-2 ${margin > 60 ? 'text-green-600' : 'text-orange-500'}`}>
                    Margen: {margin.toFixed(1)}%
                  </div>
                </div>
              </div>

              <div className="bg-slate-50 p-4 rounded-xl mb-4 border border-slate-100">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-orange-400"></span> Desglose de Receta
                </h4>
                <div className="space-y-2">
                  {item.recipe.map((r, idx) => {
                    const ing = ingredients.find(i => i.id === r.ingredientId);
                    const lineCost = r.amount * (ing?.costPerUnit || 0);
                    return (
                      <div key={idx} className="flex justify-between text-xs text-slate-600">
                        <span className="flex-1">{ing?.name} <span className="text-slate-400 italic">({r.amount} {ing?.unit})</span></span>
                        <span className="font-bold text-slate-800">${lineCost.toFixed(2)}</span>
                      </div>
                    );
                  })}
                  <div className="border-t border-slate-200 pt-3 mt-2 flex justify-between font-black text-sm text-slate-900">
                    <span>Costo Total Producción:</span>
                    <span className="text-orange-600">${cost.toFixed(2)}</span>
