                  <div key={item.cartId} className="flex justify-between items-center text-sm">
                    <div className="flex-1">
                      <p className="font-bold text-slate-800">{item.name}</p>
                      <select 
                        className="text-[10px] bg-white border rounded px-1 mt-1 text-slate-500"
                        onChange={(e) => {
                          const newCart = [...cart];
                          const idx = newCart.findIndex(c => c.cartId === item.cartId);
                          newCart[idx].customization = e.target.value;
                          setCart(newCart);
                        }}
                      >
                        <option>Término Medio</option>
                        <option>Tres Cuartos</option>
                        <option>Bien Cocido</option>
                        <option>Azulado (Sellado)</option>
                      </select>
                    </div>
                    <div className="flex items-center gap-4">
                      <span className="font-bold text-slate-900">${item.price.toFixed(2)}</span>
                      <button onClick={() => removeFromCart(item.cartId)} className="text-red-400 font-bold hover:text-red-600">×</button>
                    </div>
                  </div>
                ))}
              </div>
              <div className="border-t border-slate-200 pt-4 space-y-2">
                <div className="flex justify-between font-black text-2xl text-slate-900">
                  <span>Total</span>
                  <span className="text-orange-600">${total.toFixed(2)}</span>
                </div>
                <button 
                  disabled={!customer.name || !customer.phone || cart.length === 0}
                  onClick={() => {
                    onPlaceOrder(cart, customer);
                    setStep('success');
                  }}
                  className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl mt-6 hover:bg-orange-600 transition-all disabled:bg-slate-300 shadow-xl active:scale-[0.98]"
                >
                  PAGAR AHORA
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {cart.length > 0 && step === 'browsing' && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-full max-w-md px-4 animate-bounce">
          <button 
            onClick={() => setStep('checkout')}
            className="w-full bg-slate-900 text-white py-5 rounded-[30px] shadow-2xl flex justify-between items-center px-8 hover:bg-orange-600 transition-all group"
          >
            <span className="font-black text-lg">VER CARRITO ({cart.length})</span>
            <div className="flex items-center gap-4">
              <span className="font-bold text-xl group-hover:scale-110 transition-transform">${total.toFixed(2)}</span>
              <span className="text-2xl">➔</span>
            </div>
          </button>
        </div>
      )}
    </div>
  );
};

