              <input required type="text" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.name} onChange={e => setNewIng({...newIng, name: e.target.value})} />
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Unidad</label>
