interface InventoryProps {
  ingredients: Ingredient[];
  onUpdateStock: (id: string, amount: number) => void;
  onAddIngredient: (ingredient: Omit<Ingredient, 'id'>) => void;
  onDeleteIngredient: (id: string) => void;
}

const Inventory: React.FC<InventoryProps> = ({ ingredients, onUpdateStock, onAddIngredient, onDeleteIngredient }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [adjustingId, setAdjustingId] = useState<string | null>(null);
  const [adjustAmount, setAdjustAmount] = useState<number>(0);
  const [deleteConfirmItem, setDeleteConfirmItem] = useState<Ingredient | null>(null);

  const [newIng, setNewIng] = useState({
    name: '',
    unit: 'kg' as Ingredient['unit'],
    stock: 0,
    minStock: 0,
    costPerUnit: 0,
    sellingPrice: 0
  });

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddIngredient(newIng);
    setNewIng({ name: '', unit: 'kg', stock: 0, minStock: 0, costPerUnit: 0, sellingPrice: 0 });
    setShowAddForm(false);
  };

  const handleQuickAdjust = (id: string) => {
    onUpdateStock(id, adjustAmount);
    setAdjustingId(null);
    setAdjustAmount(0);
  };

  const confirmDelete = () => {
    if (deleteConfirmItem) {
      onDeleteIngredient(deleteConfirmItem.id);
      setDeleteConfirmItem(null);
    }
  };

  const totalInventoryValue = ingredients.reduce((sum, item) => sum + (item.stock * item.costPerUnit), 0);

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* Modal de Confirmación de Eliminación */}
      {deleteConfirmItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-sm w-full shadow-2xl transform transition-all scale-100 animate-scaleIn">
            <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-3xl mb-6 mx-auto">
              ⚠️
            </div>
            <h3 className="text-2xl font-black text-slate-900 text-center mb-2">¿Eliminar Insumo?</h3>
            <p className="text-slate-500 text-center mb-8 leading-relaxed">
              Estás a punto de borrar <span className="font-black text-slate-900">"{deleteConfirmItem.name}"</span>. Esta acción es irreversible y podría afectar tus recetas.
            </p>
            <div className="flex gap-3">
              <button 
                onClick={() => setDeleteConfirmItem(null)}
                className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold hover:bg-slate-200 transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={confirmDelete}
                className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-bold hover:bg-red-700 shadow-lg shadow-red-200 transition-all"
              >
                Sí, Eliminar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Header Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-slate-900 text-white p-6 rounded-[2rem] shadow-xl">
          <p className="text-slate-400 text-xs font-black uppercase tracking-widest mb-1">Valor Total Invertido</p>
          <p className="text-3xl font-black text-orange-500">L. {totalInventoryValue.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-black uppercase tracking-widest mb-1">Items en Stock</p>
          <p className="text-3xl font-black text-slate-800">{ingredients.length} Variedades</p>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-xs font-black uppercase tracking-widest mb-1">Alertas Rojas</p>
          <p className="text-3xl font-black text-red-500">{ingredients.filter(i => i.stock <= i.minStock).length}</p>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
          <div>
            <h2 className="text-2xl font-black text-slate-900">Almacén de Insumos</h2>
            <p className="text-slate-500 font-medium">Gestiona materias primas y rentabilidad directa.</p>
          </div>
          <button 
            onClick={() => setShowAddForm(!showAddForm)}
            className="bg-orange-600 text-white px-6 py-3 rounded-2xl font-black text-sm hover:bg-orange-700 transition-all flex items-center gap-2 shadow-lg shadow-orange-200"
          >
            {showAddForm ? '✕ CANCELAR' : '➕ NUEVO PRODUCTO'}
          </button>
        </div>

        {showAddForm && (
          <form onSubmit={handleAddSubmit} className="p-8 bg-orange-50 border-b border-orange-100 grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-4 animate-fadeIn">
            <div className="col-span-1 lg:col-span-2">
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Nombre</label>
              <input required type="text" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.name} onChange={e => setNewIng({...newIng, name: e.target.value})} />
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Unidad</label>
              <select className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.unit} onChange={e => setNewIng({...newIng, unit: e.target.value as any})}>
                <option value="kg">Kilogramos</option>
                <option value="g">Gramos</option>
                <option value="unit">Unidad</option>
                <option value="lt">Litros</option>
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Costo Compra (L.)</label>
              <input required type="number" step="0.01" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.costPerUnit} onChange={e => setNewIng({...newIng, costPerUnit: parseFloat(e.target.value)})} />
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Precio Venta (L.)</label>
              <input required type="number" step="0.01" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.sellingPrice} onChange={e => setNewIng({...newIng, sellingPrice: parseFloat(e.target.value)})} />
            </div>
            <div className="flex items-end">
              <button type="submit" className="w-full bg-slate-900 text-white p-3 rounded-xl font-black text-xs hover:bg-slate-800 transition-all uppercase">
                Guardar
              </button>
            </div>
          </form>
        )}

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
              <tr>
                <th className="px-8 py-5">Insumo</th>
                <th className="px-8 py-5 text-center">Stock / Mín</th>
                <th className="px-8 py-5">Costo Unit.</th>
                <th className="px-8 py-5">Precio Venta</th>
                <th className="px-8 py-5">Ganancia %</th>
                <th className="px-8 py-5">Valor Inv.</th>
                <th className="px-8 py-5 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {ingredients.map((item) => {
                const profit = item.sellingPrice ? item.sellingPrice - item.costPerUnit : 0;
                const margin = item.sellingPrice ? (profit / item.sellingPrice) * 100 : 0;
                const invValue = item.stock * item.costPerUnit;

                return (
                  <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-8 py-5">
                      <p className="font-black text-slate-900">{item.name}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase">Por {item.unit}</p>
                    </td>
                    <td className="px-8 py-5 text-center">
                      <div className="flex flex-col items-center">
                        <span className={`px-3 py-1 rounded-full text-xs font-black ${
                          item.stock <= item.minStock ? 'bg-red-100 text-red-600 animate-pulse' : 'bg-green-100 text-green-700'
                        }`}>
                          {item.stock} {item.unit}
                        </span>
                        <span className="text-[9px] font-bold text-slate-300 mt-1 uppercase">Mín: {item.minStock}</span>
                      </div>
                    </td>
                    <td className="px-8 py-5 font-bold text-slate-600">L. {item.costPerUnit.toFixed(2)}</td>
                    <td className="px-8 py-5 font-bold text-slate-900">L. {item.sellingPrice?.toFixed(2) || '0.00'}</td>
                    <td className="px-8 py-5">
                      <span className={`font-black text-sm ${margin > 50 ? 'text-green-500' : 'text-orange-500'}`}>
                        {margin.toFixed(1)}%
                      </span>
                    </td>
                    <td className="px-8 py-5 font-black text-slate-900">L. {invValue.toFixed(2)}</td>
                    <td className="px-8 py-5 text-right">
                      <div className="flex items-center justify-end gap-3">
                        {adjustingId === item.id ? (
                          <div className="flex items-center gap-2 animate-fadeIn">
                            <input 
                              type="number" 
                              className="w-20 p-2 border-2 border-orange-500 rounded-xl focus:outline-none font-bold text-sm"
                              placeholder="Cant."
                              value={adjustAmount}
                              onChange={(e) => setAdjustAmount(parseFloat(e.target.value) || 0)}
                              autoFocus
                            />
                            <button 
                              onClick={() => handleQuickAdjust(item.id)}
                              className="bg-slate-900 text-white p-2 rounded-xl text-xs font-bold"
                            >
                              OK
                            </button>
                            <button 
                              onClick={() => setAdjustingId(null)}
                              className="text-slate-400 hover:text-slate-600 font-bold text-xs"
                            >
                              ✕
                            </button>
                          </div>
                        ) : (
                          <>
                            <button 
                              onClick={() => setAdjustingId(item.id)}
                              className="bg-slate-100 text-slate-400 px-3 py-2 rounded-xl hover:bg-orange-600 hover:text-white transition-all font-black text-[10px] uppercase tracking-tighter"
                            >
                              Ajustar Stock
                            </button>
                            <button 
                              onClick={() => setDeleteConfirmItem(item)}
                              className="p-2 text-slate-300 hover:text-red-500 transition-colors"
                              title="Eliminar Insumo"
                            >
                              <span className="text-lg">🗑️</span>
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
      <style>{`
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.3s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

export default Inventory;

import React from 'react';
import { MenuItem, Ingredient } from '../types';

interface MenuManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  onUpdatePrice: (id: string, newPrice: number) => void;
}

const MenuManager: React.FC<MenuManagerProps> = ({ menu, ingredients, onUpdatePrice }) => {
  const calculateCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => {
      const ingredient = ingredients.find(i => i.id === item.ingredientId);
      return total + (ingredient ? ingredient.costPerUnit * item.amount : 0);
    }, 0);
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="flex justify-between items-center bg-white p-4 rounded-xl shadow-sm border border-slate-100">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Gestión de Menú y Precios</h2>
          <p className="text-slate-500 text-sm">Controla tus márgenes de ganancia y costos de receta.</p>
        </div>
        <button className="bg-slate-900 text-white px-6 py-2 rounded-xl font-bold hover:bg-orange-600 transition-colors">
          Nuevo Plato
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {menu.map((item) => {
          const cost = calculateCost(item.recipe);
          const margin = ((item.price - cost) / (item.price || 1)) * 100;

          return (
            <div key={item.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:border-orange-200 transition-all group relative overflow-hidden">
              <div className="flex justify-between items-start mb-4">
                <div className="flex-1">
                  <span className="text-[10px] font-black tracking-widest uppercase bg-orange-100 text-orange-700 px-3 py-1 rounded-full mb-3 inline-block">
                    {item.category}
                  </span>
                  <h3 className="text-xl font-black text-slate-900 mb-1">{item.name}</h3>
                  <p className="text-slate-500 text-sm line-clamp-2 pr-4">{item.description}</p>
                </div>
                <div className="text-right">
                  <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1">Precio Venta</label>
                  <div className="flex items-center gap-1 bg-slate-50 border border-slate-200 rounded-lg px-2 py-1">
                    <span className="text-slate-400 font-bold">L.</span>
                    <input 
                      type="number"
                      value={item.price}
                      onChange={(e) => onUpdatePrice(item.id, parseFloat(e.target.value) || 0)}
                      className="w-20 bg-transparent font-black text-xl text-slate-900 focus:outline-none"
                    />
                  </div>
                  <div className={`text-xs font-bold mt-2 ${margin > 60 ? 'text-green-600' : 'text-orange-500'}`}>
                    Margen: {margin.toFixed(1)}%
                  </div>
                </div>
              </div>

              <div className="bg-slate-50 p-4 rounded-xl mb-4 border border-slate-100">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                  <span className="w-1.5 h-1.5 rounded-full bg-orange-400"></span> Desglose de Receta
                </h4>
                <div className="space-y-2">
                  {item.recipe.map((r, idx) => {
                    const ing = ingredients.find(i => i.id === r.ingredientId);
                    const lineCost = r.amount * (ing?.costPerUnit || 0);
                    return (
                      <div key={idx} className="flex justify-between text-xs text-slate-600">
                        <span className="flex-1">{ing?.name} <span className="text-slate-400 italic">({r.amount} {ing?.unit})</span></span>
                        <span className="font-bold text-slate-800">L. {lineCost.toFixed(2)}</span>
                      </div>
                    );
                  })}
                  <div className="border-t border-slate-200 pt-3 mt-2 flex justify-between font-black text-sm text-slate-900">
                    <span>Costo Total Producción:</span>
                    <span className="text-orange-600">L. {cost.toFixed(2)}</span>
                  </div>
                </div>
              </div>

              <div className="flex gap-2">
                <button className="flex-1 py-2.5 bg-slate-100 text-slate-700 text-xs font-bold rounded-lg hover:bg-slate-200 transition-colors uppercase tracking-wider">
                  Configurar Receta
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default MenuManager;

import React, { useState } from 'react';
import { Sale, MenuItem } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  onAddSale: (saleItems: { menuItemId: string, quantity: number }[]) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, menu, onAddSale }) => {
  const [cart, setCart] = useState<Record<string, number>>({});

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string) => {
    if (!cart[id]) return;
    const newCart = { ...cart };
    if (newCart[id] === 1) delete newCart[id];
    else newCart[id] -= 1;
    setCart(newCart);
  };

  const handleCheckout = () => {
    const items = Object.entries(cart).map(([menuItemId, quantity]) => ({
      menuItemId,
      quantity
    }));
    if (items.length === 0) return;
    onAddSale(items);
    setCart({});
  };

  // Fixed: Explicitly typed total and cast qty to number to resolve arithmetic operation errors
  const cartTotal: number = Object.entries(cart).reduce((total: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return total + (item ? item.price * quantity : 0);
  }, 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h2 className="text-xl font-bold text-slate-800 mb-6">Punto de Venta</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {menu.map(item => (
              <div key={item.id} className="p-4 border border-slate-100 rounded-xl hover:shadow-md transition-shadow cursor-pointer flex justify-between items-center bg-slate-50/30">
                <div>
                  <h4 className="font-bold text-slate-900">{item.name}</h4>
                  <p className="text-sm text-slate-500">L. {item.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  <button onClick={() => addToCart(item.id)} className="w-8 h-8 bg-orange-600 text-white rounded-full flex items-center justify-center hover:bg-orange-700 transition-colors">
                    +
                  </button>
                  {cart[item.id] && (
                    <>
                      <span className="font-bold text-slate-800">{cart[item.id]}</span>
                      <button onClick={() => removeFromCart(item.id)} className="w-8 h-8 bg-slate-200 text-slate-600 rounded-full flex items-center justify-center hover:bg-slate-300 transition-colors">
                        -
                      </button>
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <h2 className="text-xl font-bold text-slate-800 mb-6">Últimas Ventas</h2>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-slate-500 text-xs font-semibold uppercase">
                <tr>
                  <th className="px-4 py-3">Fecha/Hora</th>
                  <th className="px-4 py-3">Detalle</th>
                  <th className="px-4 py-3 text-right">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {[...sales].reverse().slice(0, 5).map(sale => (
                  <tr key={sale.id} className="text-sm">
                    <td className="px-4 py-3 text-slate-500">
                      {new Date(sale.timestamp).toLocaleString('es-HN', { hour: '2-digit', minute: '2-digit' })}
                    </td>
                    <td className="px-4 py-3 text-slate-900">
                      {sale.items.map(i => {
                        const m = menu.find(mi => mi.id === i.menuItemId);
                        return `${i.quantity}x ${m?.name}`;
                      }).join(', ')}
                    </td>
                    <td className="px-4 py-3 text-right font-bold text-slate-900">
                      L. {sale.total.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-xl flex flex-col sticky top-6 max-h-[calc(100vh-3rem)]">
        <h3 className="text-xl font-bold mb-6 flex items-center gap-2">
          <span>🛒</span> Cuenta Actual
        </h3>
        <div className="flex-1 overflow-y-auto space-y-4 mb-6 pr-2 custom-scrollbar">
          {Object.entries(cart).map(([id, qty]) => {
            const item = menu.find(m => m.id === id);
            return (
              <div key={id} className="flex justify-between items-center pb-4 border-b border-slate-800 last:border-0">
                <div>
                  <p className="font-medium">{item?.name}</p>
                  <p className="text-xs text-slate-400">{qty} x L. {item?.price.toFixed(2)}</p>
                </div>
                {/* Fixed: Cast qty to number for arithmetic operation */}
                <p className="font-bold text-orange-400">L. {((qty as number) * (item?.price || 0)).toFixed(2)}</p>
              </div>
            );
          })}
          {Object.keys(cart).length === 0 && (
            <div className="text-center py-12 text-slate-500 italic">
              El carrito está vacío
            </div>
          )}
        </div>

        <div className="border-t border-slate-800 pt-6 space-y-4">
          <div className="flex justify-between text-lg">
            <span className="text-slate-400">Subtotal:</span>
            <span>L. {(cartTotal * 0.85).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-lg">
            <span className="text-slate-400">ISV (15%):</span>
            <span>L. {(cartTotal * 0.15).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-2xl font-black pt-2">
            <span>Total:</span>
            <span className="text-orange-500">L. {cartTotal.toFixed(2)}</span>
          </div>
          <button 
            disabled={Object.keys(cart).length === 0}
            onClick={handleCheckout}
            className="w-full py-4 bg-orange-600 text-white rounded-xl font-bold text-lg hover:bg-orange-700 transition-all active:scale-[0.98] disabled:bg-slate-800 disabled:text-slate-600 disabled:cursor-not-allowed"
          >
            CONFIRMAR VENTA
          </button>
        </div>
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState } from 'react';
import { MenuItem, Sale } from '../types';

interface OnlineOrderProps {
  menu: MenuItem[];
  onPlaceOrder: (items: any, customerInfo: any) => void;
  onBackToAdmin: () => void;
}

const OnlineOrder: React.FC<OnlineOrderProps> = ({ menu, onPlaceOrder, onBackToAdmin }) => {
  const [cart, setCart] = useState<any[]>([]);
  const [step, setStep] = useState<'browsing' | 'checkout' | 'success'>('browsing');
  const [customer, setCustomer] = useState({ name: '', phone: '', email: '' });

  const categories = Array.from(new Set(menu.map(m => m.category)));

  const addToCart = (item: MenuItem) => {
    setCart([...cart, { ...item, cartId: Date.now(), customization: 'Término Medio' }]);
  };

  const removeFromCart = (cartId: number) => {
    setCart(cart.filter(c => c.cartId !== cartId));
  };

  const total = cart.reduce((sum, item) => sum + item.price, 0);

  if (step === 'success') {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center text-5xl mb-6 shadow-xl shadow-green-200">
          ✓
        </div>
        <h1 className="text-4xl font-black text-slate-900 mb-2">¡Pedido Confirmado!</h1>
        <p className="text-slate-500 mb-8 max-w-md text-lg">Tu asado está en manos de nuestros expertos. Te avisaremos cuando esté listo.</p>
        <button 
          onClick={() => { setStep('browsing'); setCart([]); }}
          className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-lg hover:bg-orange-600 transition-all shadow-xl"
        >
          Hacer otro pedido
