  const lowStockCount = ingredients.filter(i => i.stock <= i.minStock).length;

  const salesByItem: Record<string, number> = {};
  sales.forEach(sale => {
    sale.items.forEach(item => {
      const menuItem = menu.find(m => m.id === item.menuItemId);
      if (menuItem) {
        salesByItem[menuItem.name] = (salesByItem[menuItem.name] || 0) + item.quantity;
      }
    });
  });

  const chartData = Object.entries(salesByItem).map(([name, qty]) => ({ name, qty }));

  return (
    <div className="space-y-6 animate-fadeIn pb-8">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
        <h2 className="text-2xl font-bold text-slate-800">Panel de Control</h2>
        <span className="text-sm text-slate-500 bg-white px-3 py-1 rounded-full border border-slate-100 shadow-sm font-medium">
          {new Date().toLocaleDateString('es-HN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
        </span>
      </header>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 md:gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-xs font-black uppercase tracking-widest">Ventas Totales</p>
          <p className="text-3xl font-black text-green-600 mt-2">L. {totalRevenue.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <p className="text-slate-500 text-xs font-black uppercase tracking-widest">Stock Crítico</p>
          <p className={`text-3xl font-black mt-2 ${lowStockCount > 0 ? 'text-red-500' : 'text-slate-800'}`}>
            {lowStockCount} items
          </p>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 sm:col-span-2 md:col-span-1">
          <p className="text-slate-500 text-xs font-black uppercase tracking-widest">Transacciones</p>
          <p className="text-3xl font-black text-blue-600 mt-2">{sales.length}</p>
