              <div>
                <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Costo (L.)</label>
                <input required type="number" step="0.01" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.costPerUnit} onChange={e => setNewIng({...newIng, costPerUnit: parseFloat(e.target.value)})} />
              </div>
              <div>
                <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Venta (L.)</label>
                <input required type="number" step="0.01" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.sellingPrice} onChange={e => setNewIng({...newIng, sellingPrice: parseFloat(e.target.value)})} />
              </div>
            </div>
            <div className="sm:col-span-2 lg:col-span-1 flex items-end">
              <button type="submit" className="w-full bg-slate-900 text-white p-3 rounded-xl font-black text-xs hover:bg-slate-800 transition-all uppercase">
                GUARDAR INSUMO
              </button>
            </div>
          </form>
        )}

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left min-w-[800px]">
            <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
              <tr>
                <th className="px-6 py-4">Insumo</th>
                <th className="px-6 py-4 text-center">Stock Actual</th>
                <th className="px-6 py-4">Costo Unit.</th>
                <th className="px-6 py-4">Precio Venta</th>
                <th className="px-6 py-4">Margen %</th>
                <th className="px-6 py-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {ingredients.map((item) => {
                const profit = item.sellingPrice ? item.sellingPrice - item.costPerUnit : 0;
                const margin = item.sellingPrice ? (profit / item.sellingPrice) * 100 : 0;

                return (
                  <tr key={item.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <p className="font-black text-slate-900">{item.name}</p>
