                            <button onClick={() => setDeleteConfirmItem(item)} className="p-2 text-slate-400 hover:text-red-500">🗑️</button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

