import React from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  onUpdatePrice: (id: string, newPrice: number) => void;
}

const PriceManager: React.FC<PriceManagerProps> = ({ menu, ingredients, onUpdatePrice }) => {
  const calculateCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => {
      const ingredient = ingredients.find(i => i.id === item.ingredientId);
      return total + (ingredient ? ingredient.costPerUnit * item.amount : 0);
    }, 0);
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex flex-col md:flex-row justify-between items-center gap-6 shadow-2xl">
        <div className="text-center md:text-left">
          <h2 className="text-3xl font-black mb-1">Control de Rentabilidad</h2>
          <p className="text-slate-400 text-sm uppercase tracking-widest font-bold">Ajuste de precios y análisis de costos</p>
        </div>
        <div className="flex gap-4">
          <div className="bg-slate-800 px-6 py-4 rounded-2xl border border-slate-700">
            <p className="text-[10px] font-black text-slate-500 uppercase mb-1">Margen Promedio</p>
            <p className="text-xl font-black text-orange-500">62.4%</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-4">
        {menu.map((item) => {
          const cost = calculateCost(item.recipe);
          const profit = item.price - cost;
          const margin = (profit / (item.price || 1)) * 100;

          return (
            <div key={item.id} className="bg-white p-6 md:p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col lg:flex-row gap-8 items-start lg:items-center hover:border-orange-200 transition-all">
              <div className="flex-1">
                <span className="text-[9px] font-black tracking-widest uppercase bg-slate-100 text-slate-500 px-3 py-1 rounded-full mb-3 inline-block">
                  {item.category}
                </span>
                <h3 className="text-2xl font-black text-slate-900 mb-2">{item.name}</h3>

                <div className="flex flex-wrap gap-4 mt-4">
                  <div className="bg-slate-50 px-4 py-2 rounded-xl">
                    <p className="text-[9px] font-black text-slate-400 uppercase">Costo Fabricación</p>
                    <p className="text-sm font-bold text-slate-700">L. {cost.toFixed(2)}</p>
                  </div>
                  <div className="bg-slate-50 px-4 py-2 rounded-xl">
                    <p className="text-[9px] font-black text-slate-400 uppercase">Utilidad Bruta</p>
                    <p className="text-sm font-bold text-green-600">L. {profit.toFixed(2)}</p>
                  </div>
                  <div className={`px-4 py-2 rounded-xl ${margin < 40 ? 'bg-red-50' : 'bg-green-50'}`}>
                    <p className="text-[9px] font-black text-slate-400 uppercase">Margen</p>
                    <p className={`text-sm font-black ${margin < 40 ? 'text-red-600' : 'text-green-600'}`}>
                      {margin.toFixed(1)}%
                    </p>
                  </div>
                </div>
              </div>

              <div className="w-full lg:w-64 bg-slate-50 p-6 rounded-3xl border border-slate-100">
                <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-3">Precio de Venta</label>
                <div className="flex items-center gap-2 bg-white border-2 border-slate-200 rounded-2xl px-4 py-3 focus-within:border-orange-500 transition-all">
                  <span className="text-slate-400 font-black">L.</span>
                  <input 
                    type="number"
                    step="0.01"
                    value={item.price}
                    onChange={(e) => onUpdatePrice(item.id, parseFloat(e.target.value) || 0)}
                    className="w-full bg-transparent font-black text-2xl text-slate-900 focus:outline-none"
                  />
                </div>
              </div>

              <div className="w-full lg:w-auto">
                <button className="w-full lg:w-auto px-6 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-orange-600 transition-all shadow-xl shadow-slate-200">
                  Ver Receta Detallada
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default PriceManager;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [ingredients, setIngredients] = useState<Ingredient[]>(INITIAL_INGREDIENTS);
  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [sales, setSales] = useState<Sale[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([
    { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
    { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
  ]);

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido Online',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        {/* Mobile Header */}
        <div className="lg:hidden bg-slate-900 text-white p-4 flex justify-between items-center sticky top-0 z-30 shadow-md">
          <h1 className="text-xl font-bold flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-800 rounded-lg transition-colors"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                onUpdateStock={updateStock} 
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && <Menu menu={menu} />}
            {view === 'prices' && <PriceManager menu={menu} ingredients={ingredients} onUpdatePrice={updatePrice} />}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [ingredients, setIngredients] = useState<Ingredient[]>(INITIAL_INGREDIENTS);
  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [sales, setSales] = useState<Sale[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([
    { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
    { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
  ]);

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (id: string, newRecipe: MenuItem['recipe'], newPrice?: number) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { ...item, recipe: newRecipe, price: newPrice !== undefined ? newPrice : item.price } 
        : item
    ));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido Online',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        {/* Mobile Header */}
        <div className="lg:hidden bg-slate-900 text-white p-4 flex justify-between items-center sticky top-0 z-30 shadow-md">
          <h1 className="text-xl font-bold flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-800 rounded-lg transition-colors"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                onUpdateStock={updateStock} 
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && <Menu menu={menu} />}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  onUpdatePrice: (id: string, newPrice: number) => void;
  onUpdateRecipe: (id: string, newRecipe: MenuItem['recipe'], newPrice: number) => void;
}

const PriceManager: React.FC<PriceManagerProps> = ({ menu, ingredients, onUpdatePrice, onUpdateRecipe }) => {
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [tempRecipe, setTempRecipe] = useState<MenuItem['recipe']>([]);
  const [tempPrice, setTempPrice] = useState<number>(0);

  const calculateCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => {
      const ingredient = ingredients.find(i => i.id === item.ingredientId);
      return total + (ingredient ? ingredient.costPerUnit * item.amount : 0);
    }, 0);
  };

  const startEditing = (item: MenuItem) => {
    setEditingItem(item);
    setTempRecipe([...item.recipe]);
    setTempPrice(item.price);
  };

  const addIngredientToRecipe = () => {
    if (ingredients.length > 0) {
      setTempRecipe([...tempRecipe, { ingredientId: ingredients[0].id, amount: 0 }]);
    }
  };

  const removeIngredientFromRecipe = (index: number) => {
    setTempRecipe(tempRecipe.filter((_, i) => i !== index));
  };

  const updateRecipeItem = (index: number, field: 'ingredientId' | 'amount', value: any) => {
    const updated = [...tempRecipe];
    updated[index] = { ...updated[index], [field]: value };
    setTempRecipe(updated);
  };

  const handleSave = () => {
    if (editingItem) {
      onUpdateRecipe(editingItem.id, tempRecipe, tempPrice);
      setEditingItem(null);
    }
  };

  const currentProductionCost = calculateCost(tempRecipe);
  const currentMargin = tempPrice > 0 ? ((tempPrice - currentProductionCost) / tempPrice) * 100 : 0;

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Editor de Receta */}
      {editingItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] w-full max-w-2xl p-6 md:p-10 shadow-2xl animate-scaleIn my-8">
            <header className="flex justify-between items-start mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Editar Receta y Costos</h3>
                <p className="text-orange-600 font-bold uppercase text-[10px] tracking-widest">{editingItem.name}</p>
              </div>
              <button onClick={() => setEditingItem(null)} className="text-slate-400 hover:text-slate-900 text-xl">✕</button>
            </header>

            <div className="space-y-6">
              <section>
                <div className="flex justify-between items-center mb-4">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Ingredientes Utilizados</h4>
                  <button 
                    onClick={addIngredientToRecipe}
                    className="text-[10px] font-black bg-orange-100 text-orange-700 px-3 py-1.5 rounded-lg hover:bg-orange-200 transition-colors"
                  >
                    + AÑADIR ITEM
                  </button>
                </div>

                <div className="space-y-3 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
                  {tempRecipe.map((ri, idx) => {
                    const ing = ingredients.find(i => i.id === ri.ingredientId);
                    return (
                      <div key={idx} className="flex flex-col sm:flex-row gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-100 group">
                        <div className="flex-1">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">Insumo</label>
                          <select 
                            className="w-full bg-white border border-slate-200 rounded-xl p-2 text-xs font-bold focus:outline-none focus:border-orange-500"
                            value={ri.ingredientId}
                            onChange={(e) => updateRecipeItem(idx, 'ingredientId', e.target.value)}
                          >
                            {ingredients.map(i => (
                              <option key={i.id} value={i.id}>{i.name} ({i.unit})</option>
                            ))}
                          </select>
                        </div>
                        <div className="w-full sm:w-24">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">Cant.</label>
                          <input 
                            type="number"
                            step="0.01"
                            className="w-full bg-white border border-slate-200 rounded-xl p-2 text-xs font-bold focus:outline-none focus:border-orange-500"
                            value={ri.amount}
                            onChange={(e) => updateRecipeItem(idx, 'amount', parseFloat(e.target.value) || 0)}
                          />
                        </div>
                        <div className="w-full sm:w-28 flex flex-col justify-end">
                          <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Costo Línea</p>
                          <div className="flex items-center justify-between">
                            <span className="text-xs font-black text-slate-900">L. {(ri.amount * (ing?.costPerUnit || 0)).toFixed(2)}</span>
                            <button 
                              onClick={() => removeIngredientFromRecipe(idx)}
                              className="text-red-400 hover:text-red-600 font-bold ml-2"
                            >
                              🗑️
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </section>

              <section className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-slate-100">
                <div className="bg-slate-900 p-5 rounded-3xl text-white">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Resumen de Costos</p>
                  <div className="flex justify-between items-end">
                    <div>
                      <span className="text-xs text-slate-500 block">Producción Total:</span>
                      <span className="text-2xl font-black text-orange-500">L. {currentProductionCost.toFixed(2)}</span>
                    </div>
                  </div>
                </div>

                <div className="bg-orange-50 p-5 rounded-3xl border border-orange-100">
                  <label className="block text-[9px] font-black text-orange-700 uppercase tracking-widest mb-2">Precio de Venta Sugerido</label>
                  <div className="flex items-center gap-2 bg-white border-2 border-orange-200 rounded-2xl px-4 py-2 focus-within:border-orange-500 transition-all">
                    <span className="text-orange-400 font-black">L.</span>
                    <input 
                      type="number"
                      step="0.01"
                      className="w-full bg-transparent font-black text-xl text-slate-900 focus:outline-none"
                      value={tempPrice}
                      onChange={(e) => setTempPrice(parseFloat(e.target.value) || 0)}
                    />
                  </div>
                  <p className={`text-[10px] font-black mt-2 uppercase ${currentMargin > 60 ? 'text-green-600' : 'text-orange-600'}`}>
                    Margen de Ganancia: {currentMargin.toFixed(1)}%
                  </p>
                </div>
              </section>

              <button 
                onClick={handleSave}
                className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-green-600 transition-all shadow-xl"
              >
                GUARDAR CAMBIOS EN RECETA
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex flex-col md:flex-row justify-between items-center gap-6 shadow-2xl">
        <div className="text-center md:text-left">
          <h2 className="text-3xl font-black mb-1">Gestión de Rentabilidad</h2>
          <p className="text-slate-400 text-sm uppercase tracking-widest font-bold">Control financiero de cada plato</p>
        </div>
        <div className="bg-slate-800 px-8 py-4 rounded-2xl border border-slate-700 text-center">
          <p className="text-[10px] font-black text-slate-500 uppercase mb-1 tracking-tighter">Promedio de Ganancia</p>
          <p className="text-2xl font-black text-green-500">62.4%</p>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6">
        {menu.map((item) => {
          const cost = calculateCost(item.recipe);
          const profit = item.price - cost;
          const margin = (profit / (item.price || 1)) * 100;

          return (
            <div key={item.id} className="bg-white p-6 md:p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col lg:flex-row gap-8 items-start lg:items-center hover:border-orange-100 transition-all group">
              <div className="flex-1">
                <div className="flex items-center gap-3 mb-2">
                  <span className="text-[9px] font-black tracking-widest uppercase bg-slate-100 text-slate-500 px-3 py-1 rounded-full">
                    {item.category}
                  </span>
                  <span className="text-xs font-bold text-slate-300">ID: {item.id}</span>
                </div>
                <h3 className="text-2xl font-black text-slate-900 mb-2 group-hover:text-orange-600 transition-colors">{item.name}</h3>

                <div className="flex flex-wrap gap-3 mt-4">
                  <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100">
                    <p className="text-[9px] font-black text-slate-400 uppercase mb-0.5">Costo Unit.</p>
                    <p className="text-sm font-bold text-slate-700">L. {cost.toFixed(2)}</p>
                  </div>
                  <div className="bg-green-50 px-4 py-2 rounded-xl border border-green-100">
                    <p className="text-[9px] font-black text-green-700/50 uppercase mb-0.5">Utilidad</p>
                    <p className="text-sm font-bold text-green-600">L. {profit.toFixed(2)}</p>
                  </div>
                  <div className={`px-4 py-2 rounded-xl border ${margin < 40 ? 'bg-red-50 border-red-100' : 'bg-blue-50 border-blue-100'}`}>
                    <p className="text-[9px] font-black text-slate-400 uppercase mb-0.5">Márgen %</p>
                    <p className={`text-sm font-black ${margin < 40 ? 'text-red-600' : 'text-blue-600'}`}>
                      {margin.toFixed(1)}%
                    </p>
                  </div>
                </div>
              </div>

              <div className="w-full lg:w-48 text-right">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Precio de Venta</p>
                <p className="text-3xl font-black text-slate-900 mb-4">L. {item.price.toFixed(2)}</p>
                <button 
                  onClick={() => startEditing(item)}
                  className="w-full py-3.5 bg-slate-100 text-slate-600 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-orange-600 hover:text-white transition-all"
                >
                  MODIFICAR RECETA
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default PriceManager;

export interface Ingredient {
  id: string;
  name: string;
  unit: 'kg' | 'g' | 'unit' | 'lt' | 'ml';
  stock: number;
  minStock: number;
  costPerUnit: number;
  sellingPrice?: number;
}

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  category: 'Cortes' | 'Acompañamientos' | 'Bebidas' | 'Postres';
  recipe: {
    ingredientId: string;
    amount: number;
    displayUnit?: 'Kg' | 'Lb' | 'Oz' | 'Unid';
  }[];
}

export interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  notes: string;
  orderHistory: string[];
}

export interface Sale {
  id: string;
  timestamp: Date;
  customerId?: string;
  items: {
    menuItemId: string;
    quantity: number;
    priceAtSale: number;
    customization?: string;
  }[];
  total: number;
}

export type View = 'dashboard' | 'inventory' | 'menu' | 'prices' | 'sales' | 'analysis' | 'reports' | 'customers' | 'online-order';

import React, { useState, useMemo } from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  onUpdatePrice: (id: string, newPrice: number) => void;
  onUpdateRecipe: (id: string, newRecipe: MenuItem['recipe'], newPrice: number) => void;
}

type DisplayUnit = 'Kg' | 'Lb' | 'Oz' | 'Unid';

const PriceManager: React.FC<PriceManagerProps> = ({ menu, ingredients, onUpdatePrice, onUpdateRecipe }) => {
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [tempRecipe, setTempRecipe] = useState<MenuItem['recipe']>([]);
  const [tempPrice, setTempPrice] = useState<number>(0);

  // Factores de conversión basados en KG como base para peso
  const CONVERSION_FACTORS: Record<DisplayUnit, number> = {
    'Kg': 1,
    'Lb': 0.453592,
    'Oz': 0.0283495,
    'Unid': 1
  };

  const calculateLineCost = (ingredientId: string, amount: number) => {
    const ingredient = ingredients.find(i => i.id === ingredientId);
    if (!ingredient) return 0;
    // El amount en la receta siempre se guarda en la unidad base del ingrediente (asumimos Kg para pesos)
    return amount * ingredient.costPerUnit;
  };

  const calculateTotalCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => {
      return total + calculateLineCost(item.ingredientId, item.amount);
    }, 0);
  };

  const startEditing = (item: MenuItem) => {
    setEditingItem(item);
    setTempRecipe(item.recipe.map(r => ({
      ...r,
      displayUnit: r.displayUnit || (ingredients.find(i => i.id === r.ingredientId)?.unit === 'unit' ? 'Unid' : 'Kg')
    })));
    setTempPrice(item.price);
  };

  const addIngredientToRecipe = () => {
    if (ingredients.length > 0) {
      const firstIng = ingredients[0];
      const defaultUnit: DisplayUnit = firstIng.unit === 'unit' ? 'Unid' : 'Kg';
      setTempRecipe([...tempRecipe, { ingredientId: firstIng.id, amount: 0, displayUnit: defaultUnit }]);
    }
  };

  const removeIngredientFromRecipe = (index: number) => {
    setTempRecipe(tempRecipe.filter((_, i) => i !== index));
  };

  const updateRecipeItem = (index: number, updates: Partial<MenuItem['recipe'][0]>) => {
    const updated = [...tempRecipe];
    const current = updated[index];
    const next = { ...current, ...updates };

    const ingredient = ingredients.find(i => i.id === next.ingredientId);
    if (!ingredient) return;

    // Si cambió el ingrediente, ajustamos la unidad por defecto
    if (updates.ingredientId) {
      next.displayUnit = ingredient.unit === 'unit' ? 'Unid' : 'Kg';
      next.amount = 0;
    }

    updated[index] = next;
    setTempRecipe(updated);
  };

  // Función para manejar el cambio manual del costo de línea
  const handleLineCostChange = (index: number, newCost: number) => {
    const updated = [...tempRecipe];
    const item = updated[index];
    const ingredient = ingredients.find(i => i.id === item.ingredientId);

    if (ingredient && ingredient.costPerUnit > 0) {
      // Calculamos la cantidad necesaria en la unidad base para llegar a ese costo
      const newBaseAmount = newCost / ingredient.costPerUnit;
      updated[index] = { ...item, amount: newBaseAmount };
      setTempRecipe(updated);
    }
  };

  const handleSave = () => {
    if (editingItem) {
      onUpdateRecipe(editingItem.id, tempRecipe, tempPrice);
      setEditingItem(null);
    }
  };

  const currentProductionCost = useMemo(() => calculateTotalCost(tempRecipe), [tempRecipe, ingredients]);
  const currentMargin = tempPrice > 0 ? ((tempPrice - currentProductionCost) / tempPrice) * 100 : 0;

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Editor de Receta */}
      {editingItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] w-full max-w-4xl p-6 md:p-10 shadow-2xl animate-scaleIn my-8">
            <header className="flex justify-between items-start mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Configuración de Producción</h3>
                <p className="text-orange-600 font-bold uppercase text-[10px] tracking-widest">Plato: {editingItem.name}</p>
              </div>
              <button onClick={() => setEditingItem(null)} className="text-slate-400 hover:text-slate-900 text-xl p-2">✕</button>
            </header>

            <div className="space-y-6">
              <section>
                <div className="flex justify-between items-center mb-4">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Insumos y Cantidades</h4>
                  <button 
                    onClick={addIngredientToRecipe}
                    className="text-[10px] font-black bg-orange-600 text-white px-4 py-2 rounded-xl hover:bg-orange-700 transition-all shadow-lg shadow-orange-100"
                  >
                    + AGREGAR INGREDIENTE
                  </button>
                </div>

                <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                  {tempRecipe.map((ri, idx) => {
                    const ing = ingredients.find(i => i.id === ri.ingredientId);
                    const lineCost = calculateLineCost(ri.ingredientId, ri.amount);

                    // Cantidad mostrada según la unidad seleccionada
                    const displayAmount = ri.amount / CONVERSION_FACTORS[ri.displayUnit || 'Kg'];

                    return (
