        <div className="flex-1 overflow-y-auto space-y-4 mb-6 pr-2 custom-scrollbar min-h-[100px] max-h-[300px] lg:max-h-none">
          {Object.entries(cart).map(([id, qty]) => {
            const item = menu.find(m => m.id === id);
            return (
              <div key={id} className="flex justify-between items-center pb-4 border-b border-slate-800 last:border-0 animate-fadeIn">
                <div className="flex-1">
                  <p className="font-bold text-sm">{item?.name}</p>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{qty} x L. {item?.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  <p className="font-black text-orange-400 text-sm">L. {((qty as number) * (item?.price || 0)).toFixed(2)}</p>
                  <button onClick={() => removeFromCart(id)} className="text-red-500 hover:text-red-400 p-1">✕</button>
                </div>
              </div>
            );
          })}
          {Object.keys(cart).length === 0 && (
            <div className="text-center py-12 text-slate-500 italic text-sm">Selecciona productos para comenzar</div>
          )}
        </div>

        <div className="border-t border-slate-800 pt-6 space-y-4">
          <div className="flex justify-between text-xs font-bold uppercase tracking-widest text-slate-400">
            <span>ISV (15%)</span>
            <span>L. {(cartTotal * 0.15).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-2xl font-black pt-2">
            <span>TOTAL</span>
            <span className="text-orange-500">L. {cartTotal.toFixed(2)}</span>
          </div>
          <button 
            disabled={Object.keys(cart).length === 0}
            onClick={handleCheckout}
            className="w-full py-4 bg-orange-600 text-white rounded-2xl font-black text-sm uppercase tracking-[0.2em] hover:bg-orange-700 transition-all active:scale-[0.98] disabled:bg-slate-800 disabled:text-slate-600 disabled:cursor-not-allowed shadow-xl shadow-orange-900/40"
          >
            CONFIRMAR VENTA
          </button>
        </div>
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [ingredients, setIngredients] = useState<Ingredient[]>(INITIAL_INGREDIENTS);
  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [sales, setSales] = useState<Sale[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([
    { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
    { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
  ]);

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (id: string, newRecipe: MenuItem['recipe'], newPrice?: number) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { ...item, recipe: newRecipe, price: newPrice !== undefined ? newPrice : item.price } 
        : item
    ));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido Online',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        {/* Mobile Header - Actualizado a Blanco Hueso */}
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && <Menu menu={menu} />}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Ingredient } from '../types';

interface InventoryProps {
  ingredients: Ingredient[];
  onUpdateStock: (id: string, amount: number) => void;
  onUpdateIngredient: (id: string, updates: Partial<Ingredient>) => void;
  onAddIngredient: (ingredient: Omit<Ingredient, 'id'>) => void;
  onDeleteIngredient: (id: string) => void;
}

const Inventory: React.FC<InventoryProps> = ({ ingredients, onUpdateStock, onUpdateIngredient, onAddIngredient, onDeleteIngredient }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [adjustingId, setAdjustingId] = useState<string | null>(null);
  const [adjustAmount, setAdjustAmount] = useState<number>(0);
  const [editingCostsId, setEditingCostsId] = useState<string | null>(null);
  const [editFields, setEditFields] = useState({ costPerUnit: 0, sellingPrice: 0 });
  const [deleteConfirmItem, setDeleteConfirmItem] = useState<Ingredient | null>(null);

  const [newIng, setNewIng] = useState({
    name: '',
    unit: 'kg' as Ingredient['unit'],
    stock: 0,
    minStock: 0,
    costPerUnit: 0,
    sellingPrice: 0
  });

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddIngredient(newIng);
    setNewIng({ name: '', unit: 'kg', stock: 0, minStock: 0, costPerUnit: 0, sellingPrice: 0 });
    setShowAddForm(false);
  };

  const handleQuickAdjust = (id: string) => {
    onUpdateStock(id, adjustAmount);
    setAdjustingId(null);
    setAdjustAmount(0);
  };

  const startEditingCosts = (item: Ingredient) => {
    setEditingCostsId(item.id);
    setEditFields({ costPerUnit: item.costPerUnit, sellingPrice: item.sellingPrice || 0 });
  };

  const saveCosts = (id: string) => {
    onUpdateIngredient(id, { 
      costPerUnit: editFields.costPerUnit, 
      sellingPrice: editFields.sellingPrice 
    });
    setEditingCostsId(null);
  };

  const confirmDelete = () => {
    if (deleteConfirmItem) {
      onDeleteIngredient(deleteConfirmItem.id);
      setDeleteConfirmItem(null);
    }
  };

  const totalInventoryValue = ingredients.reduce((sum, item) => sum + (item.stock * item.costPerUnit), 0);

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {deleteConfirmItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white rounded-[2rem] p-6 md:p-8 max-w-sm w-full shadow-2xl transform transition-all animate-scaleIn mx-auto">
            <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-3xl mb-4 mx-auto">⚠️</div>
            <h3 className="text-xl font-black text-slate-900 text-center mb-2">¿Eliminar Insumo?</h3>
            <p className="text-slate-500 text-center text-sm mb-6 leading-relaxed">
              Borrarás <span className="font-black text-slate-900">"{deleteConfirmItem.name}"</span>. Esta acción no se puede deshacer.
            </p>
            <div className="flex gap-3">
              <button onClick={() => setDeleteConfirmItem(null)} className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold text-sm">Cancelar</button>
              <button onClick={confirmDelete} className="flex-1 py-3 bg-red-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-red-200">Eliminar</button>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        <div className="bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col justify-center">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Valor Total</p>
          <p className="text-2xl md:text-3xl font-black text-orange-500">L. {totalInventoryValue.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-center">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Items Totales</p>
          <p className="text-2xl md:text-3xl font-black text-slate-800">{ingredients.length}</p>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-center sm:col-span-2 lg:col-span-1">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Bajo Stock</p>
          <p className="text-2xl md:text-3xl font-black text-red-500">{ingredients.filter(i => i.stock <= i.minStock).length}</p>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-6 md:p-8 border-b border-slate-50 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-slate-50/30">
          <div>
            <h2 className="text-xl font-black text-slate-900">Almacén de Insumos</h2>
            <p className="text-slate-500 text-xs font-medium">Gestión de stock y rentabilidad.</p>
          </div>
          <button 
            onClick={() => setShowAddForm(!showAddForm)}
            className="w-full sm:w-auto bg-orange-600 text-white px-6 py-3 rounded-xl font-black text-xs hover:bg-orange-700 transition-all flex items-center justify-center gap-2 shadow-lg shadow-orange-100"
          >
            {showAddForm ? '✕ CANCELAR' : '➕ NUEVO INSUMO'}
          </button>
        </div>

        {showAddForm && (
          <form onSubmit={handleAddSubmit} className="p-6 md:p-8 bg-orange-50 border-b border-orange-100 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 animate-fadeIn">
            <div className="sm:col-span-2 lg:col-span-1">
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Nombre</label>
              <input required type="text" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.name} onChange={e => setNewIng({...newIng, name: e.target.value})} />
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Unidad</label>
              <select className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.unit} onChange={e => setNewIng({...newIng, unit: e.target.value as any})}>
                <option value="kg">Kilogramos</option>
                <option value="g">Gramos</option>
                <option value="unit">Unidad</option>
                <option value="lt">Litros</option>
              </select>
            </div>
            <div className="grid grid-cols-2 gap-4 sm:col-span-2 lg:col-span-1">
              <div>
                <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Costo (L.)</label>
                <input required type="number" step="0.01" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.costPerUnit} onChange={e => setNewIng({...newIng, costPerUnit: parseFloat(e.target.value)})} />
              </div>
              <div>
                <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Venta (L.)</label>
                <input required type="number" step="0.01" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.sellingPrice} onChange={e => setNewIng({...newIng, sellingPrice: parseFloat(e.target.value)})} />
              </div>
            </div>
            <div className="sm:col-span-2 lg:col-span-1 flex items-end">
              <button type="submit" className="w-full bg-slate-900 text-white p-3 rounded-xl font-black text-xs hover:bg-slate-800 transition-all uppercase">
                GUARDAR INSUMO
              </button>
            </div>
          </form>
        )}

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left min-w-[800px]">
            <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
              <tr>
                <th className="px-6 py-4">Insumo</th>
                <th className="px-6 py-4 text-center">Stock Actual</th>
                <th className="px-6 py-4">Costo Unit.</th>
                <th className="px-6 py-4">Precio Venta</th>
                <th className="px-6 py-4">Margen %</th>
                <th className="px-6 py-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {ingredients.map((item) => {
                const isEditingCosts = editingCostsId === item.id;
                const profit = (isEditingCosts ? editFields.sellingPrice : (item.sellingPrice || 0)) - (isEditingCosts ? editFields.costPerUnit : item.costPerUnit);
                const currentSellingPrice = isEditingCosts ? editFields.sellingPrice : (item.sellingPrice || 0);
                const margin = currentSellingPrice ? (profit / currentSellingPrice) * 100 : 0;

                return (
                  <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-6 py-4">
                      <p className="font-black text-slate-900">{item.name}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase">{item.unit}</p>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex items-center justify-center gap-2">
                        <span className={`px-3 py-1 rounded-full text-[10px] font-black ${
                            item.stock <= item.minStock ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-700'
                        }`}>
                            {item.stock} {item.unit}
                        </span>
                        {adjustingId === item.id ? (
                            <div className="flex items-center gap-1">
                                <input 
                                    type="number" 
                                    className="w-16 p-2 border-2 border-orange-500 rounded-lg text-xs"
                                    value={adjustAmount}
                                    onChange={(e) => setAdjustAmount(parseFloat(e.target.value) || 0)}
                                    autoFocus
                                />
                                <button onClick={() => handleQuickAdjust(item.id)} className="bg-slate-900 text-white p-2 rounded-lg text-[10px]">OK</button>
                            </div>
                        ) : (
                            <button onClick={() => setAdjustingId(item.id)} className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-orange-600 transition-opacity">📦±</button>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      {isEditingCosts ? (
                        <div className="flex items-center gap-1">
                          <span className="text-slate-400 text-xs font-black">L.</span>
                          <input 
                            type="number" 
                            step="0.01"
                            className="w-20 p-2 border-2 border-orange-500 rounded-lg text-xs font-black"
                            value={editFields.costPerUnit}
                            onChange={(e) => setEditFields({...editFields, costPerUnit: parseFloat(e.target.value) || 0})}
                          />
                        </div>
                      ) : (
                        <p className="font-bold text-slate-600 text-sm">L. {item.costPerUnit.toFixed(2)}</p>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      {isEditingCosts ? (
                        <div className="flex items-center gap-1">
                          <span className="text-slate-400 text-xs font-black">L.</span>
                          <input 
                            type="number" 
                            step="0.01"
                            className="w-20 p-2 border-2 border-orange-500 rounded-lg text-xs font-black"
                            value={editFields.sellingPrice}
                            onChange={(e) => setEditFields({...editFields, sellingPrice: parseFloat(e.target.value) || 0})}
                          />
                        </div>
                      ) : (
                        <p className="font-bold text-slate-900 text-sm">L. {item.sellingPrice?.toFixed(2) || '0.00'}</p>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`font-black text-xs ${margin > 40 ? 'text-green-500' : 'text-orange-500'}`}>
                        {margin.toFixed(1)}%
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end gap-2">
                        {isEditingCosts ? (
                          <>
                            <button onClick={() => saveCosts(item.id)} className="bg-green-600 text-white px-3 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest shadow-lg shadow-green-100">Guardar</button>
                            <button onClick={() => setEditingCostsId(null)} className="text-slate-400 hover:text-slate-900 p-2">✕</button>
                          </>
                        ) : (
                          <>
                            <button onClick={() => startEditingCosts(item)} className="p-2 text-slate-400 hover:text-orange-600" title="Editar Costos">✏️</button>
                            <button onClick={() => setDeleteConfirmItem(item)} className="p-2 text-slate-400 hover:text-red-500" title="Eliminar">🗑️</button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

