import { Ingredient, MenuItem } from './types';

export const INITIAL_INGREDIENTS: Ingredient[] = [
  { id: '1', name: 'Lomo de Res', unit: 'kg', stock: 15, minStock: 5, costPerUnit: 12.5 },
  { id: '2', name: 'Pechuga de Pollo', unit: 'kg', stock: 10, minStock: 3, costPerUnit: 6.0 },
