import React, { useState } from 'react';
import { Ingredient } from '../types';

interface InventoryProps {
  ingredients: Ingredient[];
  onUpdateStock: (id: string, amount: number) => void;
  onUpdateIngredient: (id: string, updates: Partial<Ingredient>) => void;
  onAddIngredient: (ingredient: Omit<Ingredient, 'id'>) => void;
  onDeleteIngredient: (id: string) => void;
}

const Inventory: React.FC<InventoryProps> = ({ ingredients, onUpdateStock, onUpdateIngredient, onAddIngredient, onDeleteIngredient }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [adjustingId, setAdjustingId] = useState<string | null>(null);
  const [adjustAmount, setAdjustAmount] = useState<number>(0);
  const [editingCostsId, setEditingCostsId] = useState<string | null>(null);
  const [editFields, setEditFields] = useState({ costPerUnit: 0 });
  const [deleteConfirmItem, setDeleteConfirmItem] = useState<Ingredient | null>(null);

  const [newIng, setNewIng] = useState({
    name: '',
    unit: 'kg' as Ingredient['unit'],
    stock: 0,
    minStock: 0,
    costPerUnit: 0
  });

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddIngredient(newIng);
    setNewIng({ name: '', unit: 'kg', stock: 0, minStock: 0, costPerUnit: 0 });
    setShowAddForm(false);
  };

  const handleQuickAdjust = (id: string) => {
    onUpdateStock(id, adjustAmount);
    setAdjustingId(null);
    setAdjustAmount(0);
  };

  const startEditingCosts = (item: Ingredient) => {
    setEditingCostsId(item.id);
    setEditFields({ costPerUnit: item.costPerUnit });
  };

  const saveCosts = (id: string) => {
    onUpdateIngredient(id, { 
      costPerUnit: editFields.costPerUnit
    });
    setEditingCostsId(null);
  };

  const confirmDelete = () => {
    if (deleteConfirmItem) {
      onDeleteIngredient(deleteConfirmItem.id);
      setDeleteConfirmItem(null);
    }
  };

  const totalInventoryValue = ingredients.reduce((sum, item) => sum + (item.stock * item.costPerUnit), 0);

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {deleteConfirmItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white rounded-[2rem] p-6 md:p-8 max-w-sm w-full shadow-2xl transform transition-all animate-scaleIn mx-auto">
            <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-3xl mb-4 mx-auto">⚠️</div>
            <h3 className="text-xl font-black text-slate-900 text-center mb-2">¿Eliminar Insumo?</h3>
            <p className="text-slate-500 text-center text-sm mb-6 leading-relaxed">
              Borrarás <span className="font-black text-slate-900">"{deleteConfirmItem.name}"</span>. Esta acción no se puede deshacer.
            </p>
            <div className="flex gap-3">
              <button onClick={() => setDeleteConfirmItem(null)} className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold text-sm">Cancelar</button>
              <button onClick={confirmDelete} className="flex-1 py-3 bg-red-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-red-200">Eliminar</button>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        <div className="bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col justify-center">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Valor Total</p>
          <p className="text-2xl md:text-3xl font-black text-orange-500">L. {totalInventoryValue.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-center">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Items Totales</p>
          <p className="text-2xl md:text-3xl font-black text-slate-800">{ingredients.length}</p>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-center sm:col-span-2 lg:col-span-1">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Bajo Stock</p>
          <p className="text-2xl md:text-3xl font-black text-red-500">{ingredients.filter(i => i.stock <= i.minStock).length}</p>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-6 md:p-8 border-b border-slate-50 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-slate-50/30">
          <div>
            <h2 className="text-xl font-black text-slate-900">Almacén de Insumos</h2>
            <p className="text-slate-500 text-xs font-medium">Gestión de stock de materia prima.</p>
          </div>
          <button 
            onClick={() => setShowAddForm(!showAddForm)}
            className="w-full sm:w-auto bg-orange-600 text-white px-6 py-3 rounded-xl font-black text-xs hover:bg-orange-700 transition-all flex items-center justify-center gap-2 shadow-lg shadow-orange-100"
          >
            {showAddForm ? '✕ CANCELAR' : '➕ NUEVO INSUMO'}
          </button>
        </div>

        {showAddForm && (
          <form onSubmit={handleAddSubmit} className="p-6 md:p-8 bg-orange-50 border-b border-orange-100 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 animate-fadeIn">
            <div className="sm:col-span-2 lg:col-span-1">
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Nombre</label>
              <input required type="text" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.name} onChange={e => setNewIng({...newIng, name: e.target.value})} />
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Unidad</label>
              <select className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.unit} onChange={e => setNewIng({...newIng, unit: e.target.value as any})}>
                <option value="kg">Kilogramos</option>
                <option value="g">Gramos</option>
                <option value="unit">Unidad</option>
                <option value="lt">Litros</option>
              </select>
            </div>
            <div className="sm:col-span-2 lg:col-span-1">
              <label className="block text-[10px] font-black uppercase text-orange-700 mb-1">Costo Unit. (L.)</label>
              <input required type="number" step="0.01" className="w-full p-3 rounded-xl border-2 border-orange-200 focus:outline-none focus:border-orange-500" value={newIng.costPerUnit} onChange={e => setNewIng({...newIng, costPerUnit: parseFloat(e.target.value)})} />
            </div>
            <div className="sm:col-span-2 lg:col-span-1 flex items-end">
              <button type="submit" className="w-full bg-slate-900 text-white p-3 rounded-xl font-black text-xs hover:bg-slate-800 transition-all uppercase">
                GUARDAR INSUMO
              </button>
            </div>
          </form>
        )}

        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left min-w-[600px]">
            <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
              <tr>
                <th className="px-6 py-4">Insumo</th>
                <th className="px-6 py-4 text-center">Stock Actual</th>
                <th className="px-6 py-4">Costo Unitario</th>
                <th className="px-6 py-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {ingredients.map((item) => {
                const isEditingCosts = editingCostsId === item.id;

                return (
                  <tr key={item.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-6 py-4">
                      <p className="font-black text-slate-900">{item.name}</p>
