                                    onChange={(e) => setAdjustAmount(parseFloat(e.target.value) || 0)}
                                    autoFocus
                                    onBlur={() => handleQuickAdjust(item.id)}
                                    onKeyDown={(e) => e.key === 'Enter' && handleQuickAdjust(item.id)}
                                />
                                <button onClick={() => handleQuickAdjust(item.id)} className="bg-slate-900 text-white p-2 rounded-lg text-[10px]">OK</button>
                            </div>
                        ) : (
                            <button onClick={() => setAdjustingId(item.id)} className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-orange-600 transition-opacity" title="Ajustar Stock">📦±</button>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2 max-w-[140px]">
                        <span className="text-slate-400 text-xs font-black">L.</span>
                        <input 
                          type="number"
                          step="0.01"
                          defaultValue={item.costPerUnit}
                          onBlur={(e) => handleCostUpdate(item.id, e.target.value)}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                              handleCostUpdate(item.id, (e.target as HTMLInputElement).value);
                              (e.target as HTMLInputElement).blur();
                            }
                          }}
                          className="w-full bg-slate-50 border-2 border-slate-100 rounded-xl px-3 py-2 text-sm font-black text-slate-700 focus:outline-none focus:border-orange-500 focus:bg-white transition-all outline-none"
                        />
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={() => setDeleteConfirmItem(item)} 
                        className="p-3 text-slate-300 hover:text-red-500 bg-transparent rounded-full transition-all hover:bg-red-50"
                        title="Eliminar Insumo"
                      >
                        🗑️
                      </button>
                    </td>
                  </tr>
                );
              })}
              {ingredients.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-12 text-center text-slate-400 italic">No hay insumos registrados en el almacén</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [ingredients, setIngredients] = useState<Ingredient[]>(INITIAL_INGREDIENTS);
  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [sales, setSales] = useState<Sale[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([
    { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
    { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
  ]);

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (id: string, newRecipe: MenuItem['recipe'], newPrice?: number, newName?: string) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name 
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now()
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido Online',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        {/* Mobile Header - Actualizado a Blanco Hueso */}
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && <Menu menu={menu} />}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  onUpdatePrice: (id: string, newPrice: number) => void;
  onUpdateRecipe: (id: string, newRecipe: MenuItem['recipe'], newPrice: number, newName: string) => void;
  onAddMenuItem: (item: Omit<MenuItem, 'id'>) => void;
  onDeleteMenuItem: (id: string) => void;
}

type DisplayUnit = 'Kg' | 'Lb' | 'Oz' | 'Unid';

const PriceManager: React.FC<PriceManagerProps> = ({ menu, ingredients, onUpdatePrice, onUpdateRecipe, onAddMenuItem, onDeleteMenuItem }) => {
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [tempRecipe, setTempRecipe] = useState<MenuItem['recipe']>([]);
  const [tempPrice, setTempPrice] = useState<number>(0);
  const [tempName, setTempName] = useState<string>('');

  // Estado para el formulario de nuevo plato
  const [showAddForm, setShowAddForm] = useState(false);
  const [newItem, setNewItem] = useState<Omit<MenuItem, 'id'>>({
    name: '',
    description: '',
    price: 0,
    category: 'Cortes',
    recipe: []
  });

  // Estado para confirmación de eliminación
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  const CONVERSION_FACTORS: Record<DisplayUnit, number> = {
    'Kg': 1,
    'Lb': 0.453592,
    'Oz': 0.0283495,
    'Unid': 1
  };

  const calculateLineCost = (ingredientId: string, amount: number) => {
    const ingredient = ingredients.find(i => i.id === ingredientId);
    if (!ingredient) return 0;
    return amount * ingredient.costPerUnit;
  };

  const calculateTotalCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => {
      return total + calculateLineCost(item.ingredientId, item.amount);
    }, 0);
  };

  const startEditing = (item: MenuItem) => {
    setEditingItem(item);
    setTempName(item.name);
    setTempRecipe(item.recipe.map(r => ({
      ...r,
      displayUnit: r.displayUnit || (ingredients.find(i => i.id === r.ingredientId)?.unit === 'unit' ? 'Unid' : 'Kg')
    })));
    setTempPrice(item.price);
  };

  const addIngredientToRecipe = () => {
    if (ingredients.length > 0) {
      const firstIng = ingredients[0];
      const defaultUnit: DisplayUnit = firstIng.unit === 'unit' ? 'Unid' : 'Kg';
      setTempRecipe([...tempRecipe, { ingredientId: firstIng.id, amount: 0, displayUnit: defaultUnit }]);
    }
  };

  const removeIngredientFromRecipe = (index: number) => {
    setTempRecipe(tempRecipe.filter((_, i) => i !== index));
  };

  const updateRecipeItem = (index: number, updates: Partial<MenuItem['recipe'][0]>) => {
    const updated = [...tempRecipe];
    const current = updated[index];
    const next = { ...current, ...updates };

    const ingredient = ingredients.find(i => i.id === next.ingredientId);
    if (!ingredient) return;

    if (updates.ingredientId) {
      next.displayUnit = ingredient.unit === 'unit' ? 'Unid' : 'Kg';
      next.amount = 0;
    }

    updated[index] = next;
    setTempRecipe(updated);
  };

  const handleLineCostChange = (index: number, newCost: number) => {
    const updated = [...tempRecipe];
    const item = updated[index];
    const ingredient = ingredients.find(i => i.id === item.ingredientId);

    if (ingredient && ingredient.costPerUnit > 0) {
      const newBaseAmount = newCost / ingredient.costPerUnit;
      updated[index] = { ...item, amount: newBaseAmount };
      setTempRecipe(updated);
    }
  };

  const handleSave = () => {
    if (editingItem) {
      onUpdateRecipe(editingItem.id, tempRecipe, tempPrice, tempName);
      setEditingItem(null);
    }
  };

  const handleAddNewItem = (e: React.FormEvent) => {
    e.preventDefault();
    onAddMenuItem(newItem);
    setNewItem({
      name: '',
      description: '',
      price: 0,
      category: 'Cortes',
      recipe: []
    });
    setShowAddForm(false);
  };

  const confirmDelete = () => {
    if (deleteConfirmId) {
      onDeleteMenuItem(deleteConfirmId);
      setDeleteConfirmId(null);
    }
  };

  const currentProductionCost = useMemo(() => calculateTotalCost(tempRecipe), [tempRecipe, ingredients]);
  const currentMargin = tempPrice > 0 ? ((tempPrice - currentProductionCost) / tempPrice) * 100 : 0;

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Editor de Receta */}
      {editingItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] w-full max-w-4xl p-6 md:p-10 shadow-2xl animate-scaleIn my-8">
            <header className="flex justify-between items-start mb-8">
              <div className="flex-1 mr-4">
                <h3 className="text-2xl font-black text-slate-900">Configuración de Producción</h3>
                <div className="mt-2 group relative">
                    <label className="block text-[10px] font-black uppercase text-orange-600 tracking-widest mb-1 ml-1">Editar Nombre del Plato</label>
                    <input 
                      type="text"
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-orange-500 rounded-xl px-3 py-2 text-sm font-black text-slate-900 transition-all outline-none"
                      value={tempName}
                      onChange={(e) => setTempName(e.target.value)}
                    />
                </div>
              </div>
              <button onClick={() => setEditingItem(null)} className="text-slate-400 hover:text-slate-900 text-xl p-2">✕</button>
            </header>

            <div className="space-y-6">
              <section>
                <div className="flex justify-between items-center mb-4">
                  <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest">Insumos y Cantidades</h4>
                  <button 
                    onClick={addIngredientToRecipe}
                    className="text-[10px] font-black bg-orange-600 text-white px-4 py-2 rounded-xl hover:bg-orange-700 transition-all shadow-lg shadow-orange-100"
                  >
                    + AGREGAR INGREDIENTE
                  </button>
                </div>

                <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                  {tempRecipe.map((ri, idx) => {
                    const ing = ingredients.find(i => i.id === ri.ingredientId);
                    const lineCost = calculateLineCost(ri.ingredientId, ri.amount);
                    const displayAmount = ri.amount / CONVERSION_FACTORS[ri.displayUnit || 'Kg'];

                    return (
                      <div key={idx} className="grid grid-cols-1 md:grid-cols-12 gap-3 p-5 bg-slate-50 rounded-3xl border border-slate-100 items-end group transition-all hover:bg-white hover:shadow-md">
                        <div className="md:col-span-4">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 ml-1">Insumo</label>
                          <select 
                            className="w-full bg-white border-2 border-slate-200 rounded-2xl p-3 text-xs font-bold focus:outline-none focus:border-orange-500 transition-all"
                            value={ri.ingredientId}
                            onChange={(e) => updateRecipeItem(idx, { ingredientId: e.target.value })}
                          >
                            {ingredients.map(i => (
                              <option key={i.id} value={i.id}>{i.name}</option>
                            ))}
                          </select>
                        </div>

                        <div className="md:col-span-2">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 ml-1">Unidad</label>
                          <select 
                            className="w-full bg-white border-2 border-slate-200 rounded-2xl p-3 text-xs font-bold focus:outline-none focus:border-orange-500 transition-all"
                            value={ri.displayUnit}
                            onChange={(e) => updateRecipeItem(idx, { displayUnit: e.target.value as DisplayUnit })}
                          >
                            <option value="Kg">Kilogramos (Kg)</option>
                            <option value="Lb">Libras (Lb)</option>
                            <option value="Oz">Onzas (Oz)</option>
                            <option value="Unid">Unidades (Unid)</option>
                          </select>
                        </div>

                        <div className="md:col-span-2">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 ml-1">Cantidad</label>
                          <input 
                            type="number"
                            step="0.001"
                            className="w-full bg-white border-2 border-slate-200 rounded-2xl p-3 text-xs font-bold focus:outline-none focus:border-orange-500 transition-all"
                            value={Number(displayAmount.toFixed(3))}
                            onChange={(e) => {
                                const val = parseFloat(e.target.value) || 0;
                                const baseAmount = val * CONVERSION_FACTORS[ri.displayUnit || 'Kg'];
                                updateRecipeItem(idx, { amount: baseAmount });
                            }}
                          />
                        </div>

                        <div className="md:col-span-3">
                          <label className="block text-[9px] font-black text-slate-400 uppercase mb-1.5 ml-1">Costo Línea (Editable)</label>
                          <div className="flex items-center gap-2">
                            <div className="relative flex-1">
                                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-slate-400">L.</span>
                                <input 
                                    type="number"
                                    step="0.01"
                                    className="w-full bg-white border-2 border-orange-100 rounded-2xl p-3 pl-7 text-xs font-black text-slate-900 focus:outline-none focus:border-orange-500 transition-all"
                                    value={Number(lineCost.toFixed(2))}
                                    onChange={(e) => handleLineCostChange(idx, parseFloat(e.target.value) || 0)}
                                />
                            </div>
                            <button 
                              onClick={() => removeIngredientFromRecipe(idx)}
                              className="p-3 text-red-300 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
                            >
                              🗑️
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </section>

              <section className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-6 border-t border-slate-100">
                <div className="bg-slate-900 p-6 rounded-[2rem] text-white flex justify-between items-center">
                  <div>
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Costo Producción</p>
                    <p className="text-3xl font-black text-orange-500">L. {currentProductionCost.toFixed(2)}</p>
                  </div>
                </div>

                <div className="bg-orange-50 p-6 rounded-[2rem] border border-orange-100">
                  <label className="block text-[9px] font-black text-orange-700 uppercase tracking-widest mb-2 ml-1">Precio Venta</label>
                  <div className="flex items-center gap-2 bg-white border-2 border-orange-200 rounded-2xl px-5 py-3 focus-within:border-orange-500 shadow-sm">
                    <span className="text-orange-400 font-black text-lg">L.</span>
                    <input 
                      type="number"
                      step="0.01"
                      className="w-full bg-transparent font-black text-2xl text-slate-900 focus:outline-none"
                      value={tempPrice}
                      onChange={(e) => setTempPrice(parseFloat(e.target.value) || 0)}
                    />
                  </div>
                </div>
              </section>

              <div className="flex gap-4">
                <button 
                  onClick={() => setEditingItem(null)}
                  className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                >
                  CANCELAR
                </button>
                <button 
                  onClick={handleSave}
                  className="flex-[2] py-4 bg-slate-900 text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-green-600 transition-all shadow-xl shadow-slate-200"
                >
                  GUARDAR CAMBIOS
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Confirmación de Eliminación */}
      {deleteConfirmId && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white rounded-[2rem] p-8 max-w-sm w-full shadow-2xl animate-scaleIn text-center">
            <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-3xl mb-4 mx-auto">⚠️</div>
            <h3 className="text-xl font-black text-slate-900 mb-2">¿Eliminar Producto?</h3>
            <p className="text-slate-500 text-sm mb-6 leading-relaxed">
              Esta acción eliminará el producto del menú y su receta. No se puede deshacer.
            </p>
            <div className="flex gap-3">
              <button onClick={() => setDeleteConfirmId(null)} className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-bold text-sm">Cancelar</button>
              <button onClick={confirmDelete} className="flex-1 py-3 bg-red-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-red-200">Confirmar</button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white flex flex-col md:flex-row justify-between items-center gap-6 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-orange-500/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="text-center md:text-left relative z-10">
          <h2 className="text-3xl font-black mb-1">Gestión de Menú</h2>
          <p className="text-slate-400 text-sm uppercase tracking-widest font-bold">Ajusta precios, recetas y nuevos platos</p>
        </div>
        <button 
          onClick={() => setShowAddForm(!showAddForm)}
          className="bg-orange-600 text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-orange-700 transition-all shadow-xl shadow-orange-900/20 relative z-10"
        >
          {showAddForm ? '✕ CERRAR FORMULARIO' : '➕ NUEVO PLATO'}
        </button>
      </div>

      {showAddForm && (
        <form onSubmit={handleAddNewItem} className="bg-white p-8 rounded-[2.5rem] border-2 border-orange-100 shadow-sm animate-fadeIn space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="md:col-span-2">
              <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Nombre del Plato</label>
              <input 
                required
                type="text" 
                className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl transition-all outline-none font-bold"
                placeholder="Ej. Punta de Anca especial"
                value={newItem.name}
                onChange={e => setNewItem({...newItem, name: e.target.value})}
              />
            </div>
            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Categoría</label>
              <select 
                className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl transition-all outline-none font-bold"
                value={newItem.category}
                onChange={e => setNewItem({...newItem, category: e.target.value as any})}
              >
                <option value="Cortes">Cortes</option>
                <option value="Acompañamientos">Acompañamientos</option>
                <option value="Bebidas">Bebidas</option>
                <option value="Postres">Postres</option>
              </select>
            </div>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Descripción</label>
            <textarea 
              className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl transition-all outline-none font-medium h-24"
              placeholder="Breve descripción para el menú del cliente..."
              value={newItem.description}
              onChange={e => setNewItem({...newItem, description: e.target.value})}
            />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Precio Venta Sugerido (L.)</label>
              <input 
                required
                type="number" 
                step="0.01"
                className="w-full p-4 bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl transition-all outline-none font-black text-xl"
                value={newItem.price}
                onChange={e => setNewItem({...newItem, price: parseFloat(e.target.value) || 0})}
              />
            </div>
            <div className="flex items-end">
              <button 
                type="submit"
                className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-green-600 transition-all shadow-xl"
              >
                CREAR Y FINALIZAR
              </button>
            </div>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-6">
        {menu.map((item) => {
          const cost = calculateTotalCost(item.recipe);
          const profit = item.price - cost;
          const margin = (profit / (item.price || 1)) * 100;

          return (
            <div key={item.id} className="bg-white p-6 md:p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col lg:flex-row gap-8 items-start lg:items-center hover:border-orange-200 transition-all group relative">
              <button 
                onClick={() => setDeleteConfirmId(item.id)}
                className="absolute top-6 right-6 lg:static p-3 text-slate-300 hover:text-red-500 bg-slate-50 lg:bg-transparent rounded-full transition-all"
                title="Eliminar producto"
