                🗑️
              </button>

              <div className="flex-1">
                <div className="flex items-center gap-3 mb-3">
                  <span className="text-[9px] font-black tracking-widest uppercase bg-slate-100 text-slate-500 px-3 py-1 rounded-full border border-slate-50">
                    {item.category}
                  </span>
                </div>
                <h3 className="text-2xl font-black text-slate-900 mb-2 group-hover:text-orange-600 transition-colors">{item.name}</h3>
                <p className="text-xs text-slate-400 italic line-clamp-1 mb-4">{item.description}</p>

                <div className="flex flex-wrap gap-3 mt-5">
                  <div className="bg-slate-50 px-5 py-3 rounded-2xl border border-slate-100">
                    <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Costo Prod.</p>
                    <p className="text-base font-black text-slate-700">L. {cost.toFixed(2)}</p>
