                  <div className={`px-5 py-3 rounded-2xl border ${margin < 40 ? 'bg-red-50 border-red-100' : 'bg-blue-50 border-blue-100'}`}>
                    <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Margen Real</p>
                    <p className={`text-base font-black ${margin < 40 ? 'text-red-600' : 'text-blue-600'}`}>
                      {margin.toFixed(1)}%
                    </p>
                  </div>
                </div>
              </div>

              <div className="w-full lg:w-64 flex flex-col items-end gap-4">
                <div className="text-right">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Precio Venta</p>
                  <p className="text-4xl font-black text-slate-900">L. {item.price.toFixed(2)}</p>
                </div>
                <button 
                  onClick={() => startEditing(item)}
                  className="w-full py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-orange-600 transition-all shadow-lg active:scale-95 flex items-center justify-center gap-2"
                >
                  ⚙️ CONFIGURAR RECETA
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

