                            title="Guardar"
                          >
                            ✅
                          </button>
                          <button 
                            onClick={cancelEditing}
                            className="p-2 bg-slate-200 text-slate-600 rounded-lg hover:bg-slate-300 transition-all text-xs"
                            title="Cancelar"
                          >
                            ✕
                          </button>
                        </div>
                      ) : (
                        <div className="flex justify-end gap-1">
                          <button 
                            onClick={() => startEditing(item)}
