          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Costo Promedio</p>
          <p className="text-2xl font-black text-blue-600">L. {avgCost}</p>
        </div>
      </div>

      {/* Controles de Búsqueda y Filtrado */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-4 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="relative w-full md:w-96">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
          <input 
            type="text" 
            placeholder="Buscar insumo por nombre..."
            className="w-full bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl py-3 pl-12 pr-4 outline-none transition-all font-medium"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-2 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
          <button 
            onClick={() => setFilterType('all')}
            className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filterType === 'all' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:text-slate-900'}`}
          >
            Todos
          </button>
          <button 
            onClick={() => setFilterType('low')}
            className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filterType === 'low' ? 'bg-red-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:text-red-500'}`}
          >
            Bajo Stock
          </button>
          <button 
            onClick={() => setShowAddForm(!showAddForm)}
            className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${showAddForm ? 'bg-orange-600 text-white' : 'bg-orange-50 text-orange-600 border border-orange-100'}`}
          >
            {showAddForm ? '✕ Cancelar' : '➕ Nuevo Insumo'}
          </button>
        </div>
      </div>

      {/* Formulario de Nuevo Insumo */}
      {showAddForm && (
        <form onSubmit={handleAddSubmit} className="bg-orange-50 border border-orange-100 p-8 rounded-[2.5rem] grid grid-cols-1 md:grid-cols-4 gap-6 animate-fadeIn">
          <div className="md:col-span-2">
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Nombre del Insumo</label>
            <input required type="text" className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" placeholder="Ej. Lomo de Res Premium" value={newIng.name} onChange={e => setNewIng({...newIng, name: e.target.value})} />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Unidad Base</label>
            <select className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" value={newIng.unit} onChange={e => setNewIng({...newIng, unit: e.target.value as any})}>
              <option value="kg">Kilogramos (kg)</option>
              <option value="g">Gramos (g)</option>
              <option value="unit">Unidad (unit)</option>
              <option value="lt">Litros (lt)</option>
              <option value="ml">Mililitros (ml)</option>
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Costo Unit. (L.)</label>
            <input required type="number" step="0.01" className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" value={newIng.costPerUnit} onChange={e => setNewIng({...newIng, costPerUnit: parseFloat(e.target.value)})} />
          </div>
          <div className="md:col-span-1">
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Stock Mínimo</label>
            <input required type="number" step="0.1" className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" value={newIng.minStock} onChange={e => setNewIng({...newIng, minStock: parseFloat(e.target.value)})} />
          </div>
          <div className="md:col-span-3 flex items-end">
            <p className="text-xs text-orange-600 font-medium italic">Configura correctamente el stock mínimo para recibir alertas de reabastecimiento.</p>
          </div>
          <div className="flex items-end">
            <button type="submit" className="w-full bg-slate-900 text-white p-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl">
              GUARDAR INSUMO
            </button>
          </div>
        </form>
      )}

      {/* Tabla de Inventario Mejorada - Columnas Separadas */}
      <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left min-w-[900px]">
            <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
              <tr>
                <th className="px-8 py-5">Nombre del Insumo</th>
                <th className="px-6 py-5 text-center">Stock Actual</th>
                <th className="px-6 py-5 text-center">Unidad</th>
                <th className="px-6 py-5 text-center">Ajuste</th>
                <th className="px-8 py-5">Costo Unitario</th>
                <th className="px-8 py-5 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredIngredients.map((item) => {
                const isEditing = editingId === item.id;
                const isCritical = item.stock <= item.minStock;
                const isWarning = item.stock <= (item.minStock * 1.5);

                return (
                  <tr key={item.id} className={`${isEditing ? 'bg-orange-50/50' : 'hover:bg-slate-50/40'} transition-all group`}>
                    <td className="px-8 py-5">
                      {isEditing ? (
                        <input 
                          type="text"
                          className="w-full p-3 border-2 border-orange-500 rounded-xl text-sm font-black bg-white outline-none shadow-inner"
                          value={editValues.name || ''}
                          onChange={(e) => setEditValues({ ...editValues, name: e.target.value })}
                          autoFocus
                        />
                      ) : (
                        <div>
                          <p className="font-black text-slate-900 text-base">{item.name}</p>
                          <div className="flex items-center gap-2 mt-1">
                            <span className={`w-1.5 h-1.5 rounded-full ${isCritical ? 'bg-red-500 animate-pulse' : isWarning ? 'bg-orange-400' : 'bg-green-500'}`}></span>
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Mínimo sugerido: {item.minStock} {item.unit}</span>
                          </div>
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-5 text-center">
                      {isEditing ? (
                        <input 
                          type="number"
                          className="w-24 p-3 border-2 border-orange-500 rounded-xl text-sm font-black text-center bg-white outline-none"
                          value={editValues.stock}
                          onChange={(e) => setEditValues({ ...editValues, stock: parseFloat(e.target.value) || 0 })}
                        />
                      ) : (
                        <span className={`px-4 py-2 rounded-full text-xs font-black border ${
                          isCritical ? 'bg-red-50 text-red-600 border-red-100' : 
                          isWarning ? 'bg-orange-50 text-orange-600 border-orange-100' : 
                          'bg-green-50 text-green-700 border-green-100'
                        }`}>
                          {item.stock}
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-5 text-center">
                      {isEditing ? (
                        <select 
                          className="p-3 border-2 border-orange-200 rounded-xl text-xs font-bold bg-white"
                          value={editValues.unit}
                          onChange={(e) => setEditValues({ ...editValues, unit: e.target.value as any })}
                        >
                          <option value="kg">kg</option>
                          <option value="g">g</option>
                          <option value="unit">unit</option>
                          <option value="lt">lt</option>
                          <option value="ml">ml</option>
                        </select>
                      ) : (
                        <span className="text-slate-500 font-bold uppercase text-[10px] tracking-widest bg-slate-100 px-3 py-1 rounded-lg">
                          {item.unit}
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-5 text-center">
                      {!isEditing && (
                        <div className="flex items-center justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => handleQuickAdjust(item.id, -1)}
                            className="w-8 h-8 rounded-lg bg-slate-100 text-slate-600 flex items-center justify-center font-black hover:bg-red-100 hover:text-red-600 transition-all shadow-sm"
                          >
                            -
                          </button>
                          <button 
                            onClick={() => handleQuickAdjust(item.id, 1)}
                            className="w-8 h-8 rounded-lg bg-slate-100 text-slate-600 flex items-center justify-center font-black hover:bg-green-100 hover:text-green-600 transition-all shadow-sm"
                          >
                            +
                          </button>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-2">
                        <span className="text-slate-400 text-[10px] font-black uppercase">L.</span>
                        <input 
                          type="number"
                          step="0.01"
                          value={isEditing ? editValues.costPerUnit : item.costPerUnit}
                          readOnly={!isEditing}
                          onChange={(e) => isEditing && setEditValues({ ...editValues, costPerUnit: parseFloat(e.target.value) || 0 })}
                          className={`w-24 p-2 text-sm font-black text-slate-700 transition-all outline-none rounded-xl ${
                            isEditing ? 'bg-white border-2 border-orange-500' : 'bg-transparent border-2 border-transparent'
                          }`}
                        />
                      </div>
                    </td>
                    <td className="px-8 py-5 text-right">
                      {isEditing ? (
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => saveEdit(item.id)}
                            className="w-10 h-10 bg-green-600 text-white rounded-xl hover:bg-green-700 transition-all flex items-center justify-center shadow-lg shadow-green-100"
                            title="Confirmar"
                          >
                            ✓
                          </button>
                          <button 
                            onClick={cancelEditing}
                            className="w-10 h-10 bg-slate-200 text-slate-600 rounded-xl hover:bg-slate-300 transition-all flex items-center justify-center"
                            title="Cancelar"
                          >
                            ✕
                          </button>
                        </div>
                      ) : (
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => startEditing(item)}
                            className="p-3 text-slate-400 hover:text-orange-600 bg-slate-50 hover:bg-white rounded-xl transition-all border border-transparent hover:border-slate-100 shadow-sm opacity-0 group-hover:opacity-100"
                            title="Editar Insumo"
                          >
                            ✏️
                          </button>
                          <button 
                            onClick={() => setDeleteConfirmItem(item)} 
                            className="p-3 text-slate-400 hover:text-red-500 bg-slate-50 hover:bg-white rounded-xl transition-all border border-transparent hover:border-slate-100 shadow-sm opacity-0 group-hover:opacity-100"
                            title="Eliminar Insumo"
                          >
                            🗑️
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
              {filteredIngredients.length === 0 && (
                <tr>
                  <td colSpan={6} className="py-20 text-center">
                    <div className="text-5xl mb-4 opacity-20">📦</div>
                    <p className="font-black text-slate-300 uppercase text-xs tracking-widest">No se encontraron insumos</p>
                    <button onClick={() => { setSearchTerm(''); setFilterType('all'); }} className="mt-4 text-orange-600 font-bold text-sm hover:underline">Limpiar filtros</button>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

export interface Ingredient {
  id: string;
  name: string;
  unit: string;
  stock: number;
  minStock: number;
  costPerUnit: number;
}

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  category: 'Cortes' | 'Acompañamientos' | 'Bebidas' | 'Postres';
  recipe: {
    ingredientId: string;
    amount: number;
    displayUnit?: 'Kg' | 'Lb' | 'Oz' | 'Unid';
  }[];
}

export interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  notes: string;
  orderHistory: string[];
}

export interface Sale {
  id: string;
  timestamp: Date;
  customerId?: string;
  items: {
    menuItemId: string;
    quantity: number;
    priceAtSale: number;
    customization?: string;
  }[];
  total: number;
}

export type View = 'dashboard' | 'inventory' | 'menu' | 'prices' | 'sales' | 'analysis' | 'reports' | 'customers' | 'online-order';

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [ingredients, setIngredients] = useState<Ingredient[]>(INITIAL_INGREDIENTS);
  const [menu, setMenu] = useState<MenuItem[]>(INITIAL_MENU);
  const [availableUnits, setAvailableUnits] = useState<string[]>(['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz']);
  const [sales, setSales] = useState<Sale[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([
    { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
    { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
  ]);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: MenuItem['category'],
    newDescription?: string
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now()
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido Online',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                availableUnits={availableUnits}
                onAddUnit={addUnit}
                onDeleteUnit={deleteUnit}
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && <Menu menu={menu} />}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Ingredient } from '../types';

interface InventoryProps {
  ingredients: Ingredient[];
  availableUnits: string[];
  onAddUnit: (unit: string) => void;
  onDeleteUnit: (unit: string) => void;
  onUpdateStock: (id: string, amount: number) => void;
  onUpdateIngredient: (id: string, updates: Partial<Ingredient>) => void;
  onAddIngredient: (ingredient: Omit<Ingredient, 'id'>) => void;
  onDeleteIngredient: (id: string) => void;
}

const Inventory: React.FC<InventoryProps> = ({ 
  ingredients, 
  availableUnits,
  onAddUnit,
  onDeleteUnit,
  onUpdateStock, 
  onUpdateIngredient, 
  onAddIngredient, 
  onDeleteIngredient 
}) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [showUnitManager, setShowUnitManager] = useState(false);
  const [newUnitInput, setNewUnitInput] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValues, setEditValues] = useState<Partial<Ingredient>>({});
  const [deleteConfirmItem, setDeleteConfirmItem] = useState<Ingredient | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<'all' | 'low'>('all');

  const [newIng, setNewIng] = useState({
    name: '',
    unit: 'kg',
    stock: 0,
    minStock: 0,
    costPerUnit: 0
  });

  // Filtrado y búsqueda
  const filteredIngredients = useMemo(() => {
    return ingredients.filter(ing => {
      const matchesSearch = ing.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = filterType === 'all' || ing.stock <= ing.minStock;
      return matchesSearch && matchesFilter;
    });
  }, [ingredients, searchTerm, filterType]);

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddIngredient(newIng);
    setNewIng({ name: '', unit: availableUnits[0] || 'kg', stock: 0, minStock: 0, costPerUnit: 0 });
    setShowAddForm(false);
  };

  const handleAddUnit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newUnitInput.trim()) {
      onAddUnit(newUnitInput);
      setNewUnitInput('');
    }
  };

  const startEditing = (item: Ingredient) => {
    setEditingId(item.id);
    setEditValues({ ...item });
  };

  const cancelEditing = () => {
    setEditingId(null);
    setEditValues({});
  };

  const saveEdit = (id: string) => {
    onUpdateIngredient(id, editValues);
    setEditingId(null);
    setEditValues({});
  };

  const handleQuickAdjust = (id: string, delta: number) => {
    onUpdateStock(id, delta);
  };

  const confirmDelete = () => {
    if (deleteConfirmItem) {
      onDeleteIngredient(deleteConfirmItem.id);
      setDeleteConfirmItem(null);
    }
  };

  const totalValue = ingredients.reduce((sum, item) => sum + (item.stock * item.costPerUnit), 0);
  const avgCost = ingredients.length > 0 ? (totalValue / ingredients.length).toFixed(2) : "0";

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Gestor de Unidades */}
      {showUnitManager && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-md w-full shadow-2xl transform animate-scaleIn">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900">Configurar Unidades</h3>
              <button onClick={() => setShowUnitManager(false)} className="text-slate-400 hover:text-slate-900">✕</button>
            </div>

            <form onSubmit={handleAddUnit} className="flex gap-2 mb-6">
              <input 
                type="text" 
                placeholder="Nueva unidad (ej: caja, lb)"
                className="flex-1 bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-orange-500"
                value={newUnitInput}
                onChange={(e) => setNewUnitInput(e.target.value)}
              />
              <button type="submit" className="bg-orange-600 text-white px-4 py-2 rounded-xl font-black text-xs uppercase hover:bg-orange-700 transition-all">
                Añadir
              </button>
            </form>

            <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar pr-2">
              {availableUnits.map(unit => (
                <div key={unit} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl border border-slate-100 group">
                  <span className="font-bold text-slate-700 uppercase text-xs tracking-widest">{unit}</span>
                  <button 
                    onClick={() => onDeleteUnit(unit)}
                    className="text-red-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100"
                  >
                    🗑️
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal de Confirmación de Borrado */}
      {deleteConfirmItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-sm w-full shadow-2xl text-center transform animate-scaleIn">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-4xl mb-4 mx-auto">🗑️</div>
            <h3 className="text-xl font-black text-slate-900 mb-2">¿Eliminar Insumo?</h3>
            <p className="text-slate-500 text-sm mb-8 leading-relaxed">
              Borrarás <span className="font-bold text-slate-800">"{deleteConfirmItem.name}"</span>. 
              Esto podría afectar el cálculo de costos de los platos vinculados.
            </p>
            <div className="flex gap-3">
              <button onClick={() => setDeleteConfirmItem(null)} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:bg-slate-200">Cancelar</button>
              <button onClick={confirmDelete} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest transition-all hover:bg-red-700 shadow-lg shadow-red-200">Eliminar</button>
            </div>
          </div>
        </div>
      )}

      {/* Tarjetas de Resumen */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-slate-900 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden group border border-slate-800">
          <div className="absolute top-0 right-0 p-3 opacity-10 text-4xl group-hover:scale-110 transition-transform">💰</div>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Valor Inventario</p>
          <p className="text-2xl font-black text-orange-500">L. {totalValue.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm group">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Items Únicos</p>
          <p className="text-2xl font-black text-slate-900">{ingredients.length}</p>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Stock Crítico</p>
          <p className={`text-2xl font-black ${ingredients.filter(i => i.stock <= i.minStock).length > 0 ? 'text-red-500' : 'text-green-600'}`}>
            {ingredients.filter(i => i.stock <= i.minStock).length} Alertas
          </p>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Costo Promedio</p>
          <p className="text-2xl font-black text-blue-600">L. {avgCost}</p>
        </div>
      </div>

      {/* Controles de Búsqueda y Filtrado */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-4 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="relative w-full md:w-96">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
          <input 
            type="text" 
            placeholder="Buscar insumo por nombre..."
            className="w-full bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl py-3 pl-12 pr-4 outline-none transition-all font-medium"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-2 w-full md:w-auto overflow-x-auto pb-2 md:pb-0">
          <button 
            onClick={() => setFilterType('all')}
            className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filterType === 'all' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:text-slate-900'}`}
          >
            Todos
          </button>
          <button 
            onClick={() => setFilterType('low')}
            className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${filterType === 'low' ? 'bg-red-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 hover:text-red-500'}`}
          >
            Bajo Stock
          </button>
          <button 
            onClick={() => setShowAddForm(!showAddForm)}
            className={`flex-1 md:flex-none px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${showAddForm ? 'bg-orange-600 text-white' : 'bg-orange-50 text-orange-600 border border-orange-100'}`}
          >
            {showAddForm ? '✕ Cancelar' : '➕ Nuevo Insumo'}
          </button>
        </div>
      </div>

      {/* Formulario de Nuevo Insumo */}
      {showAddForm && (
        <form onSubmit={handleAddSubmit} className="bg-orange-50 border border-orange-100 p-8 rounded-[2.5rem] grid grid-cols-1 md:grid-cols-4 gap-6 animate-fadeIn">
          <div className="md:col-span-2">
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Nombre del Insumo</label>
            <input required type="text" className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" placeholder="Ej. Lomo de Res Premium" value={newIng.name} onChange={e => setNewIng({...newIng, name: e.target.value})} />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Unidad Base</label>
            <select className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" value={newIng.unit} onChange={e => setNewIng({...newIng, unit: e.target.value})}>
              {availableUnits.map(unit => (
                <option key={unit} value={unit}>{unit.toUpperCase()}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Costo Unit. (L.)</label>
            <input required type="number" step="0.01" className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" value={newIng.costPerUnit} onChange={e => setNewIng({...newIng, costPerUnit: parseFloat(e.target.value)})} />
          </div>
          <div className="md:col-span-1">
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Stock Mínimo</label>
            <input required type="number" step="0.1" className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" value={newIng.minStock} onChange={e => setNewIng({...newIng, minStock: parseFloat(e.target.value)})} />
          </div>
          <div className="md:col-span-3 flex items-end">
            <p className="text-xs text-orange-600 font-medium italic">Configura correctamente el stock mínimo para recibir alertas de reabastecimiento.</p>
          </div>
          <div className="flex items-end">
            <button type="submit" className="w-full bg-slate-900 text-white p-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl">
              GUARDAR INSUMO
            </button>
          </div>
        </form>
      )}

      {/* Tabla de Inventario Mejorada - Columnas Separadas */}
      <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left min-w-[900px]">
            <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
              <tr>
                <th className="px-8 py-5">Nombre del Insumo</th>
                <th className="px-6 py-5 text-center">Stock Actual</th>
                <th className="px-6 py-5 text-center">
                  <div className="flex items-center justify-center gap-2">
                    Unidad
                    <button 
                      onClick={() => setShowUnitManager(true)}
                      className="p-1 hover:bg-slate-200 rounded-md transition-all"
                      title="Configurar unidades"
                    >
                      ⚙️
                    </button>
                  </div>
                </th>
                <th className="px-6 py-5 text-center">Ajuste</th>
                <th className="px-8 py-5">Costo Unitario</th>
                <th className="px-8 py-5 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredIngredients.map((item) => {
                const isEditing = editingId === item.id;
                const isCritical = item.stock <= item.minStock;
                const isWarning = item.stock <= (item.minStock * 1.5);

                return (
                  <tr key={item.id} className={`${isEditing ? 'bg-orange-50/50' : 'hover:bg-slate-50/40'} transition-all group`}>
                    <td className="px-8 py-5">
                      {isEditing ? (
                        <input 
                          type="text"
                          className="w-full p-3 border-2 border-orange-500 rounded-xl text-sm font-black bg-white outline-none shadow-inner"
                          value={editValues.name || ''}
                          onChange={(e) => setEditValues({ ...editValues, name: e.target.value })}
                          autoFocus
                        />
                      ) : (
                        <div>
                          <p className="font-black text-slate-900 text-base">{item.name}</p>
                          <div className="flex items-center gap-2 mt-1">
                            <span className={`w-1.5 h-1.5 rounded-full ${isCritical ? 'bg-red-500 animate-pulse' : isWarning ? 'bg-orange-400' : 'bg-green-500'}`}></span>
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Mínimo sugerido: {item.minStock} {item.unit}</span>
                          </div>
                        </div>
                      )}
                    </td>
                    <td className="px-6 py-5 text-center">
                      {isEditing ? (
                        <input 
                          type="number"
                          className="w-24 p-3 border-2 border-orange-500 rounded-xl text-sm font-black text-center bg-white outline-none"
                          value={editValues.stock}
                          onChange={(e) => setEditValues({ ...editValues, stock: parseFloat(e.target.value) || 0 })}
                        />
                      ) : (
                        <span className={`px-4 py-2 rounded-full text-xs font-black border ${
                          isCritical ? 'bg-red-50 text-red-600 border-red-100' : 
                          isWarning ? 'bg-orange-50 text-orange-600 border-orange-100' : 
                          'bg-green-50 text-green-700 border-green-100'
                        }`}>
                          {item.stock}
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-5 text-center">
                      {isEditing ? (
                        <select 
                          className="p-3 border-2 border-orange-200 rounded-xl text-xs font-bold bg-white outline-none focus:border-orange-500"
                          value={editValues.unit}
                          onChange={(e) => setEditValues({ ...editValues, unit: e.target.value })}
                        >
                          {availableUnits.map(unit => (
                            <option key={unit} value={unit}>{unit.toUpperCase()}</option>
                          ))}
                        </select>
                      ) : (
                        <span className="text-slate-500 font-bold uppercase text-[10px] tracking-widest bg-slate-100 px-3 py-1 rounded-lg">
                          {item.unit}
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-5 text-center">
                      {!isEditing && (
                        <div className="flex items-center justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => handleQuickAdjust(item.id, -1)}
                            className="w-8 h-8 rounded-lg bg-slate-100 text-slate-600 flex items-center justify-center font-black hover:bg-red-100 hover:text-red-600 transition-all shadow-sm"
                          >
                            -
                          </button>
                          <button 
                            onClick={() => handleQuickAdjust(item.id, 1)}
                            className="w-8 h-8 rounded-lg bg-slate-100 text-slate-600 flex items-center justify-center font-black hover:bg-green-100 hover:text-green-600 transition-all shadow-sm"
                          >
                            +
                          </button>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-2">
                        <span className="text-slate-400 text-[10px] font-black uppercase">L.</span>
                        <input 
                          type="number"
                          step="0.01"
                          value={isEditing ? editValues.costPerUnit : item.costPerUnit}
                          readOnly={!isEditing}
                          onChange={(e) => isEditing && setEditValues({ ...editValues, costPerUnit: parseFloat(e.target.value) || 0 })}
                          className={`w-24 p-2 text-sm font-black text-slate-700 transition-all outline-none rounded-xl ${
                            isEditing ? 'bg-white border-2 border-orange-500' : 'bg-transparent border-2 border-transparent'
                          }`}
                        />
                      </div>
                    </td>
                    <td className="px-8 py-5 text-right">
                      {isEditing ? (
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => saveEdit(item.id)}
                            className="w-10 h-10 bg-green-600 text-white rounded-xl hover:bg-green-700 transition-all flex items-center justify-center shadow-lg shadow-green-100"
                            title="Confirmar"
                          >
                            ✓
                          </button>
                          <button 
                            onClick={cancelEditing}
                            className="w-10 h-10 bg-slate-200 text-slate-600 rounded-xl hover:bg-slate-300 transition-all flex items-center justify-center"
                            title="Cancelar"
                          >
                            ✕
                          </button>
                        </div>
                      ) : (
                        <div className="flex justify-end gap-2">
                          <button 
                            onClick={() => startEditing(item)}
                            className="p-3 text-slate-400 hover:text-orange-600 bg-slate-50 hover:bg-white rounded-xl transition-all border border-transparent hover:border-slate-100 shadow-sm opacity-0 group-hover:opacity-100"
                            title="Editar Insumo"
                          >
                            ✏️
                          </button>
                          <button 
                            onClick={() => setDeleteConfirmItem(item)} 
                            className="p-3 text-slate-400 hover:text-red-500 bg-slate-50 hover:bg-white rounded-xl transition-all border border-transparent hover:border-slate-100 shadow-sm opacity-0 group-hover:opacity-100"
                            title="Eliminar Insumo"
                          >
                            🗑️
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
              {filteredIngredients.length === 0 && (
                <tr>
                  <td colSpan={6} className="py-20 text-center">
                    <div className="text-5xl mb-4 opacity-20">📦</div>
                    <p className="font-black text-slate-300 uppercase text-xs tracking-widest">No se encontraron insumos</p>
                    <button onClick={() => { setSearchTerm(''); setFilterType('all'); }} className="mt-4 text-orange-600 font-bold text-sm hover:underline">Limpiar filtros</button>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState } from 'react';
import { Sale, MenuItem } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  onAddSale: (saleItems: { menuItemId: string, quantity: number }[]) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, menu, onAddSale }) => {
  const [cart, setCart] = useState<Record<string, number>>({});
  const [showMobileCart, setShowMobileCart] = useState(false);
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string) => {
    if (!cart[id]) return;
    const newCart = { ...cart };
    if (newCart[id] === 1) delete newCart[id];
    else newCart[id] -= 1;
    setCart(newCart);
  };

  const handleCheckout = () => {
    const items = Object.entries(cart).map(([menuItemId, quantity]) => ({
      menuItemId,
      quantity
    }));
    if (items.length === 0) return;
    onAddSale(items);
    setCart({});
    setShowMobileCart(false);
  };

  const cartTotal: number = Object.entries(cart).reduce((total: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return total + (item ? item.price * quantity : 0);
  }, 0);

  // Added explicit types (a: number, b: number) to fix: Operator '+' cannot be applied to types 'unknown' and 'unknown'.
  const cartCount = Object.values(cart).reduce((a: number, b: number) => a + b, 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fadeIn pb-24 lg:pb-8">
      {/* Modal de Detalle de Venta */}
      {selectedSale && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-8 shadow-2xl animate-scaleIn">
            <header className="flex justify-between items-start mb-6">
              <div>
                <h3 className="text-xl font-black text-slate-900">Detalle de Venta</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">
                  ID: #{selectedSale.id} • {new Date(selectedSale.timestamp).toLocaleString()}
                </p>
              </div>
              <button 
                onClick={() => setSelectedSale(null)}
                className="w-10 h-10 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-full flex items-center justify-center transition-colors"
              >
                ✕
              </button>
            </header>

            <div className="space-y-4 mb-8 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
              {selectedSale.items.map((item, idx) => {
                const menuItem = menu.find(m => m.id === item.menuItemId);
                return (
                  <div key={idx} className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div className="flex justify-between items-start mb-1">
                      <span className="font-black text-slate-900 text-sm">
                        {item.quantity}x {menuItem?.name || 'Producto Desconocido'}
                      </span>
                      <span className="font-bold text-slate-600 text-sm">
                        L. {(item.quantity * item.priceAtSale).toFixed(2)}
                      </span>
                    </div>
                    {item.customization && (
                      <p className="text-[11px] text-orange-600 font-bold italic mt-1 bg-orange-50 px-2 py-1 rounded-lg inline-block">
                        Nota: {item.customization}
                      </p>
                    )}
                    <p className="text-[10px] text-slate-400 font-medium">Precio unitario: L. {item.priceAtSale.toFixed(2)}</p>
                  </div>
                );
              })}
            </div>

            <div className="pt-6 border-t border-slate-100 flex justify-between items-center">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Cobrado</p>
                <p className="text-3xl font-black text-slate-900">L. {selectedSale.total.toFixed(2)}</p>
              </div>
              <button 
                onClick={() => setSelectedSale(null)}
                className="px-8 py-3 bg-slate-900 text-white rounded-xl font-black text-xs uppercase tracking-widest hover:bg-orange-600 transition-all"
              >
                CERRAR
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100">
          <h2 className="text-xl font-black text-slate-800 mb-6 uppercase tracking-widest text-sm">Carta de Menú</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {menu.map(item => (
              <div key={item.id} className="p-4 border border-slate-100 rounded-2xl hover:border-orange-300 transition-all flex justify-between items-center bg-slate-50/40 group">
                <div>
                  <h4 className="font-black text-slate-900 text-sm">{item.name}</h4>
                  <p className="text-xs font-bold text-orange-600">L. {item.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  {cart[item.id] > 0 && (
                    <div className="flex items-center gap-2 animate-fadeIn">
                      <button onClick={() => removeFromCart(item.id)} className="w-8 h-8 bg-white border border-slate-200 text-slate-600 rounded-full flex items-center justify-center hover:bg-slate-100 shadow-sm">-</button>
                      <span className="font-black text-sm w-4 text-center">{cart[item.id]}</span>
                    </div>
                  )}
                  <button 
                    onClick={() => addToCart(item.id)} 
                    className="w-10 h-10 bg-slate-900 text-white rounded-full flex items-center justify-center hover:bg-orange-600 transition-all shadow-lg active:scale-90"
                  >
                    +
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden hidden sm:block">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-black text-slate-800 uppercase tracking-widest text-sm">Ventas Recientes</h2>
            <span className="text-[10px] font-bold text-slate-400 uppercase italic">Haz clic en una fila para ver detalles</span>
          </div>
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left min-w-[500px]">
              <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <tr>
                  <th className="px-4 py-3">Hora</th>
                  <th className="px-4 py-3">Resumen de Pedido</th>
                  <th className="px-4 py-3 text-right">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {[...sales].reverse().slice(0, 10).map(sale => (
                  <tr 
                    key={sale.id} 
                    onClick={() => setSelectedSale(sale)}
                    className="text-xs cursor-pointer hover:bg-orange-50 transition-all group"
                  >
                    <td className="px-4 py-4 text-slate-400 font-bold group-hover:text-orange-600">
                      {new Date(sale.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </td>
                    <td className="px-4 py-4 text-slate-900 font-bold">
                      {sale.items.map(i => {
                        const m = menu.find(mi => mi.id === i.menuItemId);
                        return `${i.quantity}x ${m?.name}`;
                      }).join(', ')}
                    </td>
                    <td className="px-4 py-4 text-right font-black text-slate-900">
                      L. {sale.total.toFixed(2)}
                    </td>
                  </tr>
                ))}
                {sales.length === 0 && (
                  <tr>
                    <td colSpan={3} className="py-12 text-center text-slate-400 italic">No hay ventas registradas hoy</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Cart (Sidebar on Desktop, Floating Drawer on Mobile) */}
      <div className={`
        fixed inset-x-0 bottom-0 z-40 bg-slate-900 text-white p-6 rounded-t-[2.5rem] shadow-2xl transition-transform duration-300 transform
        lg:translate-y-0 lg:static lg:rounded-3xl lg:flex lg:flex-col lg:h-[calc(100vh-8rem)] lg:sticky lg:top-6
        ${showMobileCart ? 'translate-y-0' : 'translate-y-[calc(100%-80px)] lg:translate-y-0'}
      `}>
        <div 
          className="flex justify-between items-center mb-6 cursor-pointer lg:cursor-default"
          onClick={() => setShowMobileCart(!showMobileCart)}
        >
          <h3 className="text-lg font-black uppercase tracking-widest flex items-center gap-2">
            <span>🛒</span> Carrito <span className="bg-orange-600 text-[10px] px-2 py-1 rounded-full">{cartCount}</span>
          </h3>
          <span className="lg:hidden text-xl">{showMobileCart ? '↓' : '↑'}</span>
        </div>

        <div className="flex-1 overflow-y-auto space-y-4 mb-6 pr-2 custom-scrollbar min-h-[100px] max-h-[300px] lg:max-h-none">
          {Object.entries(cart).map(([id, qty]) => {
            const item = menu.find(m => m.id === id);
            return (
              <div key={id} className="flex justify-between items-center pb-4 border-b border-slate-800 last:border-0 animate-fadeIn">
                <div className="flex-1">
                  <p className="font-bold text-sm">{item?.name}</p>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{qty} x L. {item?.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  <p className="font-black text-orange-400 text-sm">L. {((qty as number) * (item?.price || 0)).toFixed(2)}</p>
                  <button onClick={() => removeFromCart(id)} className="text-red-500 hover:text-red-400 p-1">✕</button>
                </div>
              </div>
            );
          })}
          {Object.keys(cart).length === 0 && (
            <div className="text-center py-12 text-slate-500 italic text-sm">Selecciona productos para comenzar</div>
          )}
        </div>

        <div className="border-t border-slate-800 pt-6 space-y-4">
          <div className="flex justify-between text-xs font-bold uppercase tracking-widest text-slate-400">
            <span>ISV (15%)</span>
            <span>L. {(cartTotal * 0.15).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-2xl font-black pt-2">
            <span>TOTAL</span>
            <span className="text-orange-500">L. {cartTotal.toFixed(2)}</span>
          </div>
          <button 
            disabled={Object.keys(cart).length === 0}
            onClick={handleCheckout}
            className="w-full py-4 bg-orange-600 text-white rounded-2xl font-black text-sm uppercase tracking-[0.2em] hover:bg-orange-700 transition-all active:scale-[0.98] disabled:bg-slate-800 disabled:text-slate-600 disabled:cursor-not-allowed shadow-xl shadow-orange-900/40"
          >
            CONFIRMAR VENTA
          </button>
        </div>
      </div>
    </div>
  );
};

