import React, { useState, useMemo } from 'react';
import { Ingredient } from '../types';

interface InventoryProps {
  ingredients: Ingredient[];
  availableUnits: string[];
  onAddUnit: (unit: string) => void;
  onDeleteUnit: (unit: string) => void;
  onUpdateStock: (id: string, amount: number) => void;
  onUpdateIngredient: (id: string, updates: Partial<Ingredient>) => void;
  onAddIngredient: (ingredient: Omit<Ingredient, 'id'>) => void;
  onDeleteIngredient: (id: string) => void;
}

const Inventory: React.FC<InventoryProps> = ({ 
  ingredients, 
  availableUnits,
  onAddUnit,
  onDeleteUnit,
  onUpdateStock, 
  onUpdateIngredient, 
  onAddIngredient, 
  onDeleteIngredient 
}) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [showUnitManager, setShowUnitManager] = useState(false);
  const [newUnitInput, setNewUnitInput] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValues, setEditValues] = useState<Partial<Ingredient>>({});
  const [deleteConfirmItem, setDeleteConfirmItem] = useState<Ingredient | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<'all' | 'low'>('all');

  const [newIng, setNewIng] = useState({
    name: '',
    unit: availableUnits[0] || 'kg',
    stock: 0,
    minStock: 0,
    costPerUnit: 0
  });

  const filteredIngredients = useMemo(() => {
    return ingredients.filter(ing => {
      const matchesSearch = ing.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = filterType === 'all' || ing.stock <= ing.minStock;
      return matchesSearch && matchesFilter;
    });
  }, [ingredients, searchTerm, filterType]);

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddIngredient(newIng);
    setNewIng({ name: '', unit: availableUnits[0] || 'kg', stock: 0, minStock: 0, costPerUnit: 0 });
    setShowAddForm(false);
  };

  const handleAddUnit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newUnitInput.trim()) {
      onAddUnit(newUnitInput);
      setNewUnitInput('');
    }
  };

  const startEditing = (item: Ingredient) => {
    setEditingId(item.id);
    setEditValues({ ...item });
  };

  const saveEdit = (id: string) => {
    onUpdateIngredient(id, editValues);
    setEditingId(null);
    setEditValues({});
  };

  const totalValue = ingredients.reduce((sum, item) => sum + (item.stock * item.costPerUnit), 0);
  const avgCost = ingredients.length > 0 ? (totalValue / ingredients.length).toFixed(2) : "0";

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Gestor de Unidades */}
      {showUnitManager && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-md w-full shadow-2xl transform animate-scaleIn">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900">Configurar Unidades</h3>
              <button onClick={() => setShowUnitManager(false)} className="text-slate-400 hover:text-slate-900">✕</button>
            </div>
            <form onSubmit={handleAddUnit} className="flex gap-2 mb-6">
              <input 
                type="text" 
                placeholder="Nueva unidad (ej: caja, lb)"
                className="flex-1 bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-orange-500"
                value={newUnitInput}
                onChange={(e) => setNewUnitInput(e.target.value)}
              />
              <button type="submit" className="bg-orange-600 text-white px-4 py-2 rounded-xl font-black text-xs uppercase hover:bg-orange-700 transition-all">Añadir</button>
            </form>
            <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar pr-2">
              {availableUnits.map(unit => (
                <div key={unit} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl border border-slate-100 group">
                  <span className="font-bold text-slate-700 uppercase text-xs tracking-widest">{unit}</span>
                  <button onClick={() => onDeleteUnit(unit)} className="text-red-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100">🗑️</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal Confirmación de Borrado */}
      {deleteConfirmItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-sm w-full shadow-2xl text-center transform animate-scaleIn">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-4xl mb-4 mx-auto">🗑️</div>
            <h3 className="text-xl font-black text-slate-900 mb-2">¿Eliminar Insumo?</h3>
            <p className="text-slate-500 text-sm mb-8 leading-relaxed">Borrarás <b>"{deleteConfirmItem.name}"</b>.</p>
            <div className="flex gap-3">
              <button onClick={() => setDeleteConfirmItem(null)} className="flex-1 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-xs uppercase tracking-widest transition-all">Cancelar</button>
              <button onClick={() => { onDeleteIngredient(deleteConfirmItem.id); setDeleteConfirmItem(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest transition-all">Eliminar</button>
            </div>
          </div>
        </div>
      )}

      {/* Tarjetas de Resumen */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-slate-900 text-white p-6 rounded-[2rem] shadow-xl border border-slate-800">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Valor Inventario</p>
          <p className="text-2xl font-black text-orange-500">L. {totalValue.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Items Únicos</p>
          <p className="text-2xl font-black text-slate-900">{ingredients.length}</p>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Stock Crítico</p>
          <p className={`text-2xl font-black ${ingredients.filter(i => i.stock <= i.minStock).length > 0 ? 'text-red-500' : 'text-green-600'}`}>
            {ingredients.filter(i => i.stock <= i.minStock).length} Alertas
          </p>
        </div>
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mb-1">Costo Promedio</p>
          <p className="text-2xl font-black text-blue-600">L. {avgCost}</p>
        </div>
      </div>

      {/* Búsqueda y Filtros */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white p-4 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="relative w-full md:w-96">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
          <input 
            type="text" 
            placeholder="Buscar insumo..."
            className="w-full bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl py-3 pl-12 pr-4 outline-none transition-all font-medium"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2 w-full md:w-auto overflow-x-auto">
          <button onClick={() => setFilterType('all')} className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${filterType === 'all' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-400'}`}>Todos</button>
          <button onClick={() => setFilterType('low')} className={`px-6 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${filterType === 'low' ? 'bg-red-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400'}`}>Stock Bajo</button>
          <button onClick={() => setShowAddForm(!showAddForm)} className="bg-orange-600 text-white px-6 py-3 rounded-xl text-[10px] font-black uppercase transition-all shadow-lg hover:bg-orange-700">➕ Nuevo Insumo</button>
        </div>
      </div>

      {/* Formulario */}
      {showAddForm && (
        <form onSubmit={handleAddSubmit} className="bg-orange-50 border border-orange-100 p-8 rounded-[2.5rem] grid grid-cols-1 md:grid-cols-4 gap-6 animate-fadeIn">
          <div className="md:col-span-2">
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Nombre</label>
            <input required type="text" className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" placeholder="Nombre del insumo" value={newIng.name} onChange={e => setNewIng({...newIng, name: e.target.value})} />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Unidad</label>
            <select className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" value={newIng.unit} onChange={e => setNewIng({...newIng, unit: e.target.value})}>
              {availableUnits.map(unit => <option key={unit} value={unit}>{unit.toUpperCase()}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-orange-700 mb-2 ml-1">Costo Unitario (L.)</label>
            <input required type="number" step="0.01" className="w-full p-4 rounded-2xl border-2 border-orange-200 focus:outline-none focus:border-orange-500 font-bold bg-white" value={newIng.costPerUnit} onChange={e => setNewIng({...newIng, costPerUnit: parseFloat(e.target.value)})} />
          </div>
          <button type="submit" className="md:col-start-4 bg-slate-900 text-white p-4 rounded-2xl font-black text-xs uppercase hover:bg-slate-800 transition-all shadow-xl">Guardar Insumo</button>
        </form>
      )}

      {/* Tabla Unificada */}
      <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-left min-w-[800px]">
            <thead className="bg-slate-50 text-slate-400 uppercase text-[10px] font-black tracking-widest">
              <tr>
                <th className="px-8 py-5">Nombre del Insumo</th>
                <th className="px-8 py-5 text-center flex items-center justify-center gap-2">
                  Stock / Unidad
                  <button onClick={() => setShowUnitManager(true)} className="p-1 hover:bg-slate-200 rounded-md transition-all">⚙️</button>
                </th>
                <th className="px-8 py-5 text-center">Ajuste Rápido</th>
                <th className="px-8 py-5">Costo Unitario</th>
                <th className="px-8 py-5 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredIngredients.map((item) => {
                const isEditing = editingId === item.id;
                const isCritical = item.stock <= item.minStock;
                return (
                  <tr key={item.id} className={`${isEditing ? 'bg-orange-50/50' : 'hover:bg-slate-50/40'} transition-all group`}>
                    <td className="px-8 py-5">
                      {isEditing ? (
                        <input type="text" className="w-full p-3 border-2 border-orange-500 rounded-xl text-sm font-black outline-none" value={editValues.name || ''} onChange={(e) => setEditValues({ ...editValues, name: e.target.value })} autoFocus />
                      ) : (
                        <div>
                          <p className="font-black text-slate-900 text-base">{item.name}</p>
                          <p className="text-[9px] font-black text-slate-400 uppercase">Mín: {item.minStock} {item.unit}</p>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-5 text-center">
                      {isEditing ? (
                        <div className="flex items-center justify-center gap-2">
                          <input type="number" className="w-20 p-3 border-2 border-orange-500 rounded-xl text-sm font-black text-center" value={editValues.stock} onChange={(e) => setEditValues({ ...editValues, stock: parseFloat(e.target.value) || 0 })} />
                          <select className="p-3 border-2 border-orange-200 rounded-xl text-xs font-bold" value={editValues.unit} onChange={(e) => setEditValues({ ...editValues, unit: e.target.value })}>
                            {availableUnits.map(unit => <option key={unit} value={unit}>{unit.toUpperCase()}</option>)}
                          </select>
                        </div>
                      ) : (
                        <span className={`px-4 py-2 rounded-full text-xs font-black border ${isCritical ? 'bg-red-50 text-red-600 border-red-100' : 'bg-green-50 text-green-700 border-green-100'}`}>
                          {item.stock} <span className="opacity-60">{item.unit}</span>
                        </span>
                      )}
                    </td>
                    <td className="px-8 py-5 text-center">
                      {!isEditing && (
                        <div className="flex items-center justify-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => onUpdateStock(item.id, -1)} className="w-8 h-8 rounded-lg bg-slate-100 text-slate-600 flex items-center justify-center font-black hover:bg-red-100 hover:text-red-600">-</button>
                          <button onClick={() => onUpdateStock(item.id, 1)} className="w-8 h-8 rounded-lg bg-slate-100 text-slate-600 flex items-center justify-center font-black hover:bg-green-100 hover:text-green-600">+</button>
                        </div>
                      )}
                    </td>
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-2 font-black text-slate-700">
                        <span>L.</span>
                        <input type="number" step="0.01" value={isEditing ? editValues.costPerUnit : item.costPerUnit} readOnly={!isEditing} onChange={(e) => isEditing && setEditValues({ ...editValues, costPerUnit: parseFloat(e.target.value) || 0 })} className={`w-24 p-2 text-sm font-black outline-none rounded-xl ${isEditing ? 'bg-white border-2 border-orange-500' : 'bg-transparent border-none'}`} />
                      </div>
                    </td>
                    <td className="px-8 py-5 text-right">
                      {isEditing ? (
                        <div className="flex justify-end gap-2">
                          <button onClick={() => saveEdit(item.id)} className="w-10 h-10 bg-green-600 text-white rounded-xl hover:bg-green-700 transition-all">✓</button>
                          <button onClick={() => setEditingId(null)} className="w-10 h-10 bg-slate-200 text-slate-600 rounded-xl hover:bg-slate-300">✕</button>
                        </div>
                      ) : (
                        <div className="flex justify-end gap-2">
                          <button onClick={() => startEditing(item)} className="p-3 text-slate-400 hover:text-orange-600 opacity-0 group-hover:opacity-100">✏️</button>
                          <button onClick={() => setDeleteConfirmItem(item)} className="p-3 text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100">🗑️</button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Inventory;

import React, { useState, useMemo } from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  onUpdatePrice: (id: string, newPrice: number) => void;
  onUpdateRecipe: (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice: number, 
    newName: string, 
    newCategory: MenuItem['category'],
    newDescription: string
  ) => void;
  onAddMenuItem: (item: Omit<MenuItem, 'id'>) => void;
  onDeleteMenuItem: (id: string) => void;
}

const PriceManager: React.FC<PriceManagerProps> = ({ menu, ingredients, onUpdatePrice, onUpdateRecipe, onAddMenuItem, onDeleteMenuItem }) => {
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [tempRecipe, setTempRecipe] = useState<MenuItem['recipe']>([]);
  const [tempPrice, setTempPrice] = useState<number>(0);
  const [tempName, setTempName] = useState<string>('');
  const [tempCategory, setTempCategory] = useState<MenuItem['category']>('Cortes');
  const [tempDescription, setTempDescription] = useState<string>('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [newItem, setNewItem] = useState<Omit<MenuItem, 'id'>>({
    name: '',
    description: '',
    price: 0,
    category: 'Cortes',
    recipe: []
  });
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  const calculateLineCost = (ingredientId: string, amount: number) => {
    const ingredient = ingredients.find(i => i.id === ingredientId);
    return ingredient ? amount * ingredient.costPerUnit : 0;
  };

  const calculateTotalCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => total + calculateLineCost(item.ingredientId, item.amount), 0);
  };

  const startEditing = (item: MenuItem) => {
    setEditingItem(item);
    setTempName(item.name);
    setTempCategory(item.category);
    setTempDescription(item.description);
    setTempRecipe([...item.recipe]);
    setTempPrice(item.price);
  };

  const addIngredientToRecipe = () => {
    if (ingredients.length > 0) {
