import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Inicialización de estado con persistencia
  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ ...s, timestamp: new Date(s.timestamp) }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  // Guardar en localStorage cuando cambie el estado
  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const addCategory = (category: string) => {
    const cleanCat = category.trim();
    if (cleanCat && !categories.includes(cleanCat)) {
      setCategories([...categories, cleanCat]);
    }
  };

  const deleteCategory = (category: string) => {
    setCategories(categories.filter(c => c !== category));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: string,
    newDescription?: string
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now()
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido Online',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                availableUnits={availableUnits}
                onAddUnit={addUnit}
                onDeleteUnit={deleteUnit}
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && <Menu menu={menu} />}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                categories={categories}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  categories: string[];
  onAddCategory: (category: string) => void;
  onDeleteCategory: (category: string) => void;
  onUpdatePrice: (id: string, newPrice: number) => void;
  onUpdateRecipe: (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice: number, 
    newName: string, 
    newCategory: string,
    newDescription: string
  ) => void;
  onAddMenuItem: (item: Omit<MenuItem, 'id'>) => void;
  onDeleteMenuItem: (id: string) => void;
}

const PriceManager: React.FC<PriceManagerProps> = ({ 
  menu, 
  ingredients, 
  categories,
  onAddCategory,
  onDeleteCategory,
  onUpdatePrice, 
  onUpdateRecipe, 
  onAddMenuItem, 
  onDeleteMenuItem 
}) => {
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isEditingName, setIsEditingName] = useState<boolean>(false);
  const [tempRecipe, setTempRecipe] = useState<MenuItem['recipe']>([]);
  const [tempPrice, setTempPrice] = useState<number>(0);
  const [tempName, setTempName] = useState<string>('');
  const [tempCategory, setTempCategory] = useState<string>('');
  const [tempDescription, setTempDescription] = useState<string>('');

  const [showAddForm, setShowAddForm] = useState(false);
  const [showCategoryManager, setShowCategoryManager] = useState(false);
  const [newCategoryInput, setNewCategoryInput] = useState('');

  const [newItemData, setNewItemData] = useState<Omit<MenuItem, 'id'>>({
    name: '',
    description: '',
    price: 0,
    category: categories[0] || 'General',
    recipe: []
  });

  const calculateLineCost = (ingredientId: string, amount: number) => {
    const ingredient = ingredients.find(i => i.id === ingredientId);
    return ingredient ? amount * ingredient.costPerUnit : 0;
  };

  const calculateTotalCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => total + calculateLineCost(item.ingredientId, item.amount), 0);
  };

  const startEditing = (item: MenuItem) => {
    setEditingItem(item);
    setTempName(item.name);
    setTempCategory(item.category);
    setTempDescription(item.description);
    setTempRecipe([...item.recipe]);
    setTempPrice(item.price);
    setIsEditingName(false);
  };

  const addIngredientToRecipe = () => {
    if (ingredients.length > 0) {
      setTempRecipe([...tempRecipe, { ingredientId: ingredients[0].id, amount: 0 }]);
    }
  };

  const updateRecipeItem = (index: number, updates: Partial<MenuItem['recipe'][0]>) => {
    const updated = [...tempRecipe];
    updated[index] = { ...updated[index], ...updates };
    setTempRecipe(updated);
  };

  const handleSave = () => {
    if (editingItem) {
      // Pasamos explícitamente el tempName para asegurar que se actualice el nombre del plato
      onUpdateRecipe(
        editingItem.id, 
        tempRecipe, 
        tempPrice, 
        tempName, 
        tempCategory, 
        tempDescription
      );
      setEditingItem(null);
    }
  };

  const handleCreateNewItem = (e: React.FormEvent) => {
    e.preventDefault();
    onAddMenuItem(newItemData);
    setShowAddForm(false);
    setNewItemData({
      name: '',
      description: '',
      price: 0,
      category: categories[0] || 'General',
      recipe: []
    });
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCategoryInput.trim()) {
      onAddCategory(newCategoryInput.trim());
      setNewCategoryInput('');
    }
  };

  const currentProductionCost = useMemo(() => calculateTotalCost(tempRecipe), [tempRecipe, ingredients]);
  const currentMargin = useMemo(() => {
    if (tempPrice <= 0) return 0;
    return ((tempPrice - currentProductionCost) / tempPrice) * 100;
  }, [tempPrice, currentProductionCost]);

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Category Manager */}
      {showCategoryManager && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-md w-full shadow-2xl transform animate-scaleIn">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900">Gestionar Categorías</h3>
              <button onClick={() => setShowCategoryManager(false)} className="text-slate-400 hover:text-slate-900 p-2">✕</button>
            </div>
            <form onSubmit={handleAddCategory} className="flex gap-2 mb-6">
              <input 
                type="text" 
                placeholder="Nueva categoría..."
                className="flex-1 bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-orange-500"
                value={newCategoryInput}
                onChange={(e) => setNewCategoryInput(e.target.value)}
              />
              <button type="submit" className="bg-orange-600 text-white px-4 py-2 rounded-xl font-black text-xs uppercase hover:bg-orange-700 transition-all">Añadir</button>
            </form>
            <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar pr-2">
              {categories.map(cat => (
                <div key={cat} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl border border-slate-100 group">
                  <span className="font-bold text-slate-700 uppercase text-[10px] tracking-widest">{cat}</span>
                  <button onClick={() => onDeleteCategory(cat)} className="text-red-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100">🗑️</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal Editor Full Screen / Immersive */}
      {editingItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-xl transition-all duration-300">
          <div className="bg-white w-full h-full lg:h-[90vh] lg:max-w-6xl lg:rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-scaleIn">

            {/* Header Fijo */}
            <header className="px-6 py-4 lg:px-10 lg:py-6 border-b border-slate-100 flex justify-between items-center bg-white shrink-0">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-[10px] font-black text-orange-500 uppercase tracking-[0.2em] bg-orange-50 px-2 py-0.5 rounded">Editor de Receta</span>
                </div>
                <div className="flex items-center gap-3">
                  {isEditingName ? (
                    <div className="flex items-center gap-2 w-full max-w-xl">
                      <input 
                        className="flex-1 p-2 bg-slate-50 border-2 border-orange-500 rounded-xl font-black text-xl lg:text-3xl outline-none" 
                        value={tempName} 
                        onChange={e => setTempName(e.target.value)} 
                        autoFocus
                      />
                      <button 
                        onClick={() => setIsEditingName(false)}
                        className="bg-green-600 text-white p-3 rounded-xl hover:bg-green-700 shadow-lg shadow-green-100"
                        title="Confirmar nombre"
                      >
                        ✓
                      </button>
                    </div>
                  ) : (
                    <div className="flex items-center gap-3 truncate">
                      <h3 className="text-xl lg:text-3xl font-black text-slate-900 truncate">{tempName}</h3>
                      <button 
                        onClick={() => setIsEditingName(true)}
                        className="p-2 text-slate-400 hover:text-orange-600 transition-colors"
                        title="Editar nombre"
                      >
                        ✏️
                      </button>
                    </div>
                  )}
                </div>
              </div>
              <button 
                onClick={() => setEditingItem(null)} 
                className="ml-4 w-10 h-10 lg:w-12 lg:h-12 bg-slate-50 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-full flex items-center justify-center transition-all shrink-0"
              >
                ✕
              </button>
            </header>

            {/* Contenido Desplazable */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 lg:p-10">
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

                {/* Columna Izquierda: Información y Precios */}
                <div className="lg:col-span-4 space-y-8">
                  <section className="space-y-4">
                    <h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-l-2 border-orange-500 pl-3">Datos Generales</h4>
                    <div className="space-y-4">
                      <div>
                        <div className="flex justify-between items-center mb-2">
                          <label className="block text-[10px] font-bold text-slate-500 uppercase">Categoría del Plato</label>
                          <button onClick={() => setShowCategoryManager(true)} className="text-[9px] font-black text-orange-600 uppercase tracking-tighter hover:underline">⚙️ Gestionar</button>
                        </div>
                        <select 
                          className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-sm outline-none focus:border-orange-500 transition-all" 
                          value={tempCategory} 
                          onChange={e => setTempCategory(e.target.value)}
                        >
                          {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2">Descripción Corta</label>
                        <textarea 
                          rows={3}
                          className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-medium text-sm outline-none focus:border-orange-500 transition-all resize-none" 
                          value={tempDescription} 
                          onChange={e => setTempDescription(e.target.value)}
                          placeholder="Escribe los detalles del plato..."
                        />
                      </div>
                    </div>
                  </section>

                  <section className="p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-xl shadow-slate-200">
                    <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-6">Resumen Económico</h4>
                    <div className="space-y-6">
                      <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-slate-400">Costo de Producción</span>
                        <span className="text-xl font-black">L. {currentProductionCost.toFixed(2)}</span>
                      </div>
                      <div className="flex justify-between items-center border-t border-slate-800 pt-6">
                        <span className="text-sm font-bold text-slate-400">Precio de Venta</span>
                        <div className="flex items-center gap-2 bg-slate-800 p-2 rounded-xl">
                          <span className="text-orange-500 font-black">L.</span>
                          <input 
                            type="number" 
                            step="0.01" 
                            className="bg-transparent text-xl font-black text-white w-24 text-right outline-none" 
                            value={tempPrice} 
                            onChange={e => setTempPrice(parseFloat(e.target.value) || 0)} 
                          />
                        </div>
                      </div>
                      <div className={`p-4 rounded-2xl flex justify-between items-center ${currentMargin > 50 ? 'bg-green-500/10 text-green-400' : 'bg-orange-500/10 text-orange-400'}`}>
                        <span className="text-xs font-black uppercase tracking-wider">Margen Bruto</span>
                        <span className="text-2xl font-black">{currentMargin.toFixed(1)}%</span>
                      </div>
                    </div>
                  </section>
                </div>

                {/* Columna Derecha: Ingredientes de la Receta */}
                <div className="lg:col-span-8">
                  <section className="space-y-6">
                    <div className="flex justify-between items-center">
                      <h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-l-2 border-orange-500 pl-3">Ingredientes e Insumos</h4>
                      <button 
                        onClick={addIngredientToRecipe} 
                        className="px-4 py-2 bg-slate-900 text-white text-[10px] font-black rounded-xl hover:bg-orange-600 transition-all uppercase tracking-widest"
                      >
                        ➕ Añadir Insumo
                      </button>
                    </div>

                    <div className="space-y-3">
                      {tempRecipe.length === 0 ? (
                        <div className="py-20 bg-slate-50 rounded-[2.5rem] border-2 border-dashed border-slate-200 text-center">
                          <p className="text-slate-400 font-bold">No hay ingredientes definidos aún.</p>
                          <button onClick={addIngredientToRecipe} className="mt-4 text-orange-600 font-black text-sm uppercase">Comenzar receta</button>
                        </div>
                      ) : (
                        <div className="grid grid-cols-1 gap-3">
                          {tempRecipe.map((ri, idx) => {
                            const ing = ingredients.find(i => i.id === ri.ingredientId);
                            return (
                              <div key={idx} className="bg-white border-2 border-slate-100 rounded-3xl p-4 flex flex-col sm:flex-row gap-4 items-center group hover:border-orange-200 transition-all">
                                <div className="flex-1 w-full">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-1 ml-1">Insumo</label>
                                  <select 
                                    className="w-full bg-slate-50 p-3 rounded-xl font-bold text-sm outline-none focus:bg-white focus:border-orange-500 transition-all" 
                                    value={ri.ingredientId} 
                                    onChange={e => updateRecipeItem(idx, { ingredientId: e.target.value })}
                                  >
                                    {ingredients.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
                                  </select>
                                </div>
                                <div className="w-full sm:w-32">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-1 ml-1">Cantidad</label>
                                  <div className="flex items-center gap-2 bg-slate-50 p-3 rounded-xl border border-transparent group-focus-within:border-orange-200">
                                    <input 
                                      type="number" 
                                      step="0.001" 
                                      className="bg-transparent w-full font-black text-sm outline-none text-center" 
                                      value={ri.amount} 
                                      onChange={e => updateRecipeItem(idx, { amount: parseFloat(e.target.value) || 0 })} 
                                    />
                                    <span className="text-[10px] font-black text-slate-400 uppercase shrink-0">{ing?.unit}</span>
                                  </div>
                                </div>
                                <div className="w-full sm:w-32 text-center">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">Costo Línea</label>
                                  <p className="font-black text-slate-900 text-sm py-3">L. {calculateLineCost(ri.ingredientId, ri.amount).toFixed(2)}</p>
                                </div>
                                <button 
                                  onClick={() => setTempRecipe(tempRecipe.filter((_, i) => i !== idx))} 
                                  className="w-10 h-10 rounded-full flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 transition-all"
                                >
                                  🗑️
                                </button>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  </section>
                </div>
              </div>
            </div>

            {/* Footer Fijo con Acciones */}
            <footer className="p-6 lg:p-8 border-t border-slate-100 bg-slate-50 shrink-0">
              <div className="max-w-6xl mx-auto flex flex-col sm:flex-row gap-4 justify-between items-center">
                <p className="text-xs font-medium text-slate-400 italic order-2 sm:order-1 text-center sm:text-left">
                  Los cambios realizados se guardarán permanentemente en el sistema.
                </p>
                <div className="flex gap-3 w-full sm:w-auto order-1 sm:order-2">
                  <button 
                    onClick={() => setEditingItem(null)} 
                    className="flex-1 sm:px-8 py-4 bg-white border-2 border-slate-200 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-100 transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    onClick={handleSave} 
                    className="flex-1 sm:px-12 py-4 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] hover:bg-orange-700 shadow-xl shadow-orange-100 transition-all active:scale-95"
                  >
                    Guardar Cambios
                  </button>
                </div>
              </div>
            </footer>
          </div>
        </div>
      )}

      {/* Formulario Nuevo Plato */}
      {showAddForm && (
        <div className="fixed inset-0 z-[105] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] w-full max-w-2xl p-8 shadow-2xl animate-scaleIn my-8">
            <header className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black text-slate-900">Crear Nuevo Plato</h3>
              <button onClick={() => setShowAddForm(false)} className="text-slate-400 hover:text-slate-900">✕</button>
            </header>
            <form onSubmit={handleCreateNewItem} className="space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Nombre del Plato</label>
                  <input required type="text" className="w-full p-4 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-bold bg-slate-50" value={newItemData.name} onChange={e => setNewItemData({...newItemData, name: e.target.value})} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <div className="flex justify-between items-center mb-2">
                      <label className="block text-[10px] font-black uppercase text-slate-400 ml-1">Categoría</label>
                      <button type="button" onClick={() => setShowCategoryManager(true)} className="text-[9px] font-black text-orange-600 uppercase tracking-tighter">⚙️</button>
                    </div>
                    <select className="w-full p-4 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-bold bg-slate-50" value={newItemData.category} onChange={e => setNewItemData({...newItemData, category: e.target.value})}>
                      {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Precio Sugerido (L.)</label>
                    <input required type="number" step="0.01" className="w-full p-4 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-bold bg-slate-50" value={newItemData.price} onChange={e => setNewItemData({...newItemData, price: parseFloat(e.target.value) || 0})} />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Descripción</label>
                  <textarea className="w-full p-4 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-medium bg-slate-50 resize-none" rows={3} value={newItemData.description} onChange={e => setNewItemData({...newItemData, description: e.target.value})} placeholder="Describe los ingredientes destacados..." />
                </div>
              </div>
              <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-orange-600 transition-all shadow-xl">Crear Plato</button>
            </form>
          </div>
        </div>
      )}

      {/* Vista Principal Listado de Platos */}
      <div className="bg-slate-900 p-8 lg:p-12 rounded-[3rem] text-white flex flex-col md:flex-row justify-between items-center gap-8 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-orange-600/10 blur-[100px] rounded-full -mr-20 -mt-20"></div>
        <div className="relative z-10">
          <h2 className="text-3xl lg:text-4xl font-black">Gestión de Menú</h2>
          <p className="text-slate-400 text-sm font-bold uppercase tracking-[0.2em] mt-2">Rentabilidad y Escandallos en tiempo real</p>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto relative z-10">
          <button 
            onClick={() => setShowCategoryManager(true)} 
            className="bg-slate-800 text-white px-6 py-5 rounded-[2rem] font-black uppercase text-[10px] tracking-widest hover:bg-slate-700 transition-all flex items-center justify-center gap-2"
          >
            ⚙️ Categorías
          </button>
          <button 
            onClick={() => setShowAddForm(true)} 
            className="bg-orange-600 text-white px-10 py-5 rounded-[2rem] font-black uppercase tracking-widest shadow-2xl shadow-orange-900/40 hover:bg-orange-500 transition-all active:scale-95 flex items-center justify-center gap-3"
          >
            ➕ Crear Nuevo Plato
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {menu.map((item) => {
          const cost = calculateTotalCost(item.recipe);
          const margin = ((item.price - cost) / (item.price || 1)) * 100;
          return (
            <div key={item.id} className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100 flex flex-col gap-6 group transition-all hover:border-orange-300 hover:shadow-2xl hover:shadow-slate-200">
              <div className="flex justify-between items-start">
                <div className="flex-1">
                  <span className="inline-block px-3 py-1 bg-slate-50 border border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest rounded-full mb-3">
                    {item.category}
                  </span>
                  <h3 className="text-2xl font-black text-slate-900 group-hover:text-orange-600 transition-colors">{item.name}</h3>
                  <p className="text-slate-400 text-xs mt-2 italic line-clamp-2 leading-relaxed">{item.description}</p>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">PVP</p>
                  <p className="text-3xl font-black text-slate-900">L. {item.price.toFixed(2)}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-4 rounded-3xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Costo Prod.</p>
                  <p className="text-xl font-black text-slate-700">L. {cost.toFixed(2)}</p>
                </div>
                <div className={`p-4 rounded-3xl border ${margin > 50 ? 'bg-green-50 border-green-100 text-green-600' : 'bg-orange-50 border-orange-100 text-orange-600'}`}>
                  <p className="text-[10px] font-black opacity-60 uppercase mb-1">Margen Bruto</p>
                  <p className="text-xl font-black">{margin.toFixed(1)}%</p>
                </div>
              </div>

              <div className="flex gap-3 mt-2">
                <button 
                  onClick={() => startEditing(item)} 
                  className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-orange-600 transition-all shadow-lg shadow-slate-200"
                >
                  ⚙️ Configurar Plato
                </button>
                <button 
                  onClick={() => onDeleteMenuItem(item.id)}
                  className="w-14 h-14 bg-slate-50 text-slate-300 hover:bg-red-50 hover:text-red-500 rounded-2xl flex items-center justify-center transition-all border border-transparent hover:border-red-100"
                >
                  🗑️
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default PriceManager;

export interface Ingredient {
  id: string;
  name: string;
  unit: string;
  stock: number;
  minStock: number;
  costPerUnit: number;
}

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image?: string;
  recipe: {
    ingredientId: string;
    amount: number;
  }[];
}

export interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  notes: string;
  orderHistory: string[];
}

export interface Sale {
  id: string;
  timestamp: Date;
  customerId?: string;
  items: {
    menuItemId: string;
    quantity: number;
    priceAtSale: number;
    customization?: string;
  }[];
  total: number;
}

export type View = 'dashboard' | 'inventory' | 'menu' | 'prices' | 'sales' | 'analysis' | 'reports' | 'customers' | 'online-order';

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Inicialización de estado con persistencia
  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ ...s, timestamp: new Date(s.timestamp) }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  // Guardar en localStorage cuando cambie el estado
  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const addCategory = (category: string) => {
    const cleanCat = category.trim();
    if (cleanCat && !categories.includes(cleanCat)) {
      setCategories([...categories, cleanCat]);
    }
  };

  const deleteCategory = (category: string) => {
    setCategories(categories.filter(c => c !== category));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: string,
    newDescription?: string,
    newImage?: string
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description,
            image: newImage !== undefined ? newImage : item.image
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now()
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido Online',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                availableUnits={availableUnits}
                onAddUnit={addUnit}
                onDeleteUnit={deleteUnit}
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && <Menu menu={menu} />}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                categories={categories}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  categories: string[];
  onAddCategory: (category: string) => void;
  onDeleteCategory: (category: string) => void;
  onUpdatePrice: (id: string, newPrice: number) => void;
  onUpdateRecipe: (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice: number, 
    newName: string, 
    newCategory: string,
    newDescription: string,
    newImage?: string
  ) => void;
  onAddMenuItem: (item: Omit<MenuItem, 'id'>) => void;
  onDeleteMenuItem: (id: string) => void;
}

const PriceManager: React.FC<PriceManagerProps> = ({ 
  menu, 
  ingredients, 
  categories,
  onAddCategory,
  onDeleteCategory,
  onUpdatePrice, 
  onUpdateRecipe, 
  onAddMenuItem, 
  onDeleteMenuItem 
}) => {
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isEditingName, setIsEditingName] = useState<boolean>(false);
  const [tempRecipe, setTempRecipe] = useState<MenuItem['recipe']>([]);
  const [tempPrice, setTempPrice] = useState<number>(0);
  const [tempName, setTempName] = useState<string>('');
  const [tempCategory, setTempCategory] = useState<string>('');
  const [tempDescription, setTempDescription] = useState<string>('');
  const [tempImage, setTempImage] = useState<string | undefined>(undefined);

  const [showAddForm, setShowAddForm] = useState(false);
  const [showCategoryManager, setShowCategoryManager] = useState(false);
  const [newCategoryInput, setNewCategoryInput] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const addFileInputRef = useRef<HTMLInputElement>(null);

  const [newItemData, setNewItemData] = useState<Omit<MenuItem, 'id'>>({
    name: '',
    description: '',
    price: 0,
    category: categories[0] || 'General',
    recipe: []
  });

  const calculateLineCost = (ingredientId: string, amount: number) => {
    const ingredient = ingredients.find(i => i.id === ingredientId);
    return ingredient ? amount * ingredient.costPerUnit : 0;
  };

  const calculateTotalCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => total + calculateLineCost(item.ingredientId, item.amount), 0);
  };

  const startEditing = (item: MenuItem) => {
    setEditingItem(item);
    setTempName(item.name);
    setTempCategory(item.category);
    setTempDescription(item.description);
    setTempRecipe([...item.recipe]);
    setTempPrice(item.price);
    setTempImage(item.image);
    setIsEditingName(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, isNew: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (isNew) {
          setNewItemData({ ...newItemData, image: base64String });
        } else {
          setTempImage(base64String);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const addIngredientToRecipe = () => {
    if (ingredients.length > 0) {
      setTempRecipe([...tempRecipe, { ingredientId: ingredients[0].id, amount: 0 }]);
    }
  };

  const updateRecipeItem = (index: number, updates: Partial<MenuItem['recipe'][0]>) => {
    const updated = [...tempRecipe];
    updated[index] = { ...updated[index], ...updates };
    setTempRecipe(updated);
  };

  const handleSave = () => {
    if (editingItem) {
      onUpdateRecipe(
        editingItem.id, 
        tempRecipe, 
        tempPrice, 
        tempName, 
        tempCategory, 
        tempDescription,
        tempImage
      );
      setEditingItem(null);
    }
  };

  const handleCreateNewItem = (e: React.FormEvent) => {
    e.preventDefault();
    onAddMenuItem(newItemData);
    setShowAddForm(false);
    setNewItemData({
      name: '',
      description: '',
      price: 0,
      category: categories[0] || 'General',
      recipe: []
    });
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCategoryInput.trim()) {
      onAddCategory(newCategoryInput.trim());
      setNewCategoryInput('');
    }
  };

  const currentProductionCost = useMemo(() => calculateTotalCost(tempRecipe), [tempRecipe, ingredients]);
  const currentMargin = useMemo(() => {
    if (tempPrice <= 0) return 0;
    return ((tempPrice - currentProductionCost) / tempPrice) * 100;
  }, [tempPrice, currentProductionCost]);

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Category Manager */}
      {showCategoryManager && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-md w-full shadow-2xl transform animate-scaleIn">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900">Gestionar Categorías</h3>
              <button onClick={() => setShowCategoryManager(false)} className="text-slate-400 hover:text-slate-900 p-2">✕</button>
            </div>
            <form onSubmit={handleAddCategory} className="flex gap-2 mb-6">
              <input 
                type="text" 
                placeholder="Nueva categoría..."
                className="flex-1 bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-orange-500"
                value={newCategoryInput}
                onChange={(e) => setNewCategoryInput(e.target.value)}
              />
              <button type="submit" className="bg-orange-600 text-white px-4 py-2 rounded-xl font-black text-xs uppercase hover:bg-orange-700 transition-all">Añadir</button>
            </form>
            <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar pr-2">
              {categories.map(cat => (
                <div key={cat} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl border border-slate-100 group">
                  <span className="font-bold text-slate-700 uppercase text-[10px] tracking-widest">{cat}</span>
                  <button onClick={() => onDeleteCategory(cat)} className="text-red-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100">🗑️</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal Editor Full Screen / Immersive */}
      {editingItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-xl transition-all duration-300">
          <div className="bg-white w-full h-full lg:h-[90vh] lg:max-w-6xl lg:rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-scaleIn">

            {/* Header Fijo */}
            <header className="px-6 py-4 lg:px-10 lg:py-6 border-b border-slate-100 flex justify-between items-center bg-white shrink-0">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-[10px] font-black text-orange-500 uppercase tracking-[0.2em] bg-orange-50 px-2 py-0.5 rounded">Editor de Receta</span>
                </div>
                <div className="flex items-center gap-3">
                  {isEditingName ? (
                    <div className="flex items-center gap-2 w-full max-w-xl">
                      <input 
                        className="flex-1 p-2 bg-slate-50 border-2 border-orange-500 rounded-xl font-black text-xl lg:text-3xl outline-none" 
                        value={tempName} 
                        onChange={e => setTempName(e.target.value)} 
                        autoFocus
                      />
                      <button 
                        onClick={() => setIsEditingName(false)}
                        className="bg-green-600 text-white p-3 rounded-xl hover:bg-green-700 shadow-lg shadow-green-100"
                        title="Confirmar nombre"
                      >
                        ✓
                      </button>
                    </div>
                  ) : (
                    <div className="flex items-center gap-3 truncate">
                      <h3 className="text-xl lg:text-3xl font-black text-slate-900 truncate">{tempName}</h3>
                      <button 
                        onClick={() => setIsEditingName(true)}
                        className="p-2 text-slate-400 hover:text-orange-600 transition-colors"
                        title="Editar nombre"
                      >
                        ✏️
                      </button>
                    </div>
                  )}
                </div>
              </div>
              <button 
                onClick={() => setEditingItem(null)} 
                className="ml-4 w-10 h-10 lg:w-12 lg:h-12 bg-slate-50 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-full flex items-center justify-center transition-all shrink-0"
              >
                ✕
              </button>
            </header>

            {/* Contenido Desplazable */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 lg:p-10">
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

                {/* Columna Izquierda: Información y Precios */}
                <div className="lg:col-span-4 space-y-8">
                  <section className="space-y-4">
                    <h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-l-2 border-orange-500 pl-3">Datos Generales</h4>

                    {/* Sección de Imagen */}
                    <div className="space-y-3">
                      <label className="block text-[10px] font-bold text-slate-500 uppercase">Fotografía del Plato</label>
                      <div className="relative group">
                        <div className="w-full aspect-video bg-slate-100 rounded-3xl overflow-hidden border-2 border-dashed border-slate-200 flex items-center justify-center relative">
                          {tempImage ? (
                            <img src={tempImage} alt="Vista previa" className="w-full h-full object-cover" />
                          ) : (
                            <div className="text-center p-4">
                              <span className="text-4xl block mb-2 opacity-20">📸</span>
                              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sin imagen</p>
                            </div>
                          )}
                          <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="absolute inset-0 bg-slate-900/0 group-hover:bg-slate-900/40 flex items-center justify-center transition-all duration-300"
                          >
                            <span className="bg-white text-slate-900 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest opacity-0 group-hover:opacity-100 transform translate-y-2 group-hover:translate-y-0 transition-all duration-300">
                              {tempImage ? 'Cambiar Foto' : 'Subir Foto'}
                            </span>
                          </button>
                        </div>
                        <input 
                          type="file" 
                          ref={fileInputRef} 
                          className="hidden" 
                          accept="image/*" 
                          onChange={(e) => handleImageUpload(e)}
                        />
                      </div>
                    </div>

                    <div className="space-y-4 pt-2">
                      <div>
                        <div className="flex justify-between items-center mb-2">
                          <label className="block text-[10px] font-bold text-slate-500 uppercase">Categoría del Plato</label>
                          <button onClick={() => setShowCategoryManager(true)} className="text-[9px] font-black text-orange-600 uppercase tracking-tighter hover:underline">⚙️ Gestionar</button>
                        </div>
                        <select 
                          className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-sm outline-none focus:border-orange-500 transition-all" 
                          value={tempCategory} 
                          onChange={e => setTempCategory(e.target.value)}
                        >
                          {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                        </select>
                      </div>
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2">Descripción Corta</label>
                        <textarea 
                          rows={3}
                          className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-medium text-sm outline-none focus:border-orange-500 transition-all resize-none" 
                          value={tempDescription} 
                          onChange={e => setTempDescription(e.target.value)}
                          placeholder="Escribe los detalles del plato..."
                        />
                      </div>
                    </div>
                  </section>

                  <section className="p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-xl shadow-slate-200">
                    <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-6">Resumen Económico</h4>
                    <div className="space-y-6">
                      <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-slate-400">Costo de Producción</span>
                        <span className="text-xl font-black">L. {currentProductionCost.toFixed(2)}</span>
                      </div>
                      <div className="flex justify-between items-center border-t border-slate-800 pt-6">
                        <span className="text-sm font-bold text-slate-400">Precio de Venta</span>
                        <div className="flex items-center gap-2 bg-slate-800 p-2 rounded-xl">
                          <span className="text-orange-500 font-black">L.</span>
                          <input 
                            type="number" 
                            step="0.01" 
                            className="bg-transparent text-xl font-black text-white w-24 text-right outline-none" 
                            value={tempPrice} 
                            onChange={e => setTempPrice(parseFloat(e.target.value) || 0)} 
                          />
                        </div>
                      </div>
                      <div className={`p-4 rounded-2xl flex justify-between items-center ${currentMargin > 50 ? 'bg-green-500/10 text-green-400' : 'bg-orange-500/10 text-orange-400'}`}>
                        <span className="text-xs font-black uppercase tracking-wider">Margen Bruto</span>
                        <span className="text-2xl font-black">{currentMargin.toFixed(1)}%</span>
                      </div>
                    </div>
                  </section>
                </div>

                {/* Columna Derecha: Ingredientes de la Receta */}
                <div className="lg:col-span-8">
                  <section className="space-y-6">
                    <div className="flex justify-between items-center">
                      <h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-l-2 border-orange-500 pl-3">Ingredientes e Insumos</h4>
                      <button 
                        onClick={addIngredientToRecipe} 
                        className="px-4 py-2 bg-slate-900 text-white text-[10px] font-black rounded-xl hover:bg-orange-600 transition-all uppercase tracking-widest"
                      >
                        ➕ Añadir Insumo
                      </button>
                    </div>

                    <div className="space-y-3">
                      {tempRecipe.length === 0 ? (
                        <div className="py-20 bg-slate-50 rounded-[2.5rem] border-2 border-dashed border-slate-200 text-center">
                          <p className="text-slate-400 font-bold">No hay ingredientes definidos aún.</p>
                          <button onClick={addIngredientToRecipe} className="mt-4 text-orange-600 font-black text-sm uppercase">Comenzar receta</button>
                        </div>
                      ) : (
                        <div className="grid grid-cols-1 gap-3">
                          {tempRecipe.map((ri, idx) => {
                            const ing = ingredients.find(i => i.id === ri.ingredientId);
                            return (
                              <div key={idx} className="bg-white border-2 border-slate-100 rounded-3xl p-4 flex flex-col sm:flex-row gap-4 items-center group hover:border-orange-200 transition-all">
                                <div className="flex-1 w-full">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-1 ml-1">Insumo</label>
                                  <select 
                                    className="w-full bg-slate-50 p-3 rounded-xl font-bold text-sm outline-none focus:bg-white focus:border-orange-500 transition-all" 
                                    value={ri.ingredientId} 
                                    onChange={e => updateRecipeItem(idx, { ingredientId: e.target.value })}
                                  >
                                    {ingredients.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
                                  </select>
                                </div>
                                <div className="w-full sm:w-32">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-1 ml-1">Cantidad</label>
                                  <div className="flex items-center gap-2 bg-slate-50 p-3 rounded-xl border border-transparent group-focus-within:border-orange-200">
                                    <input 
                                      type="number" 
                                      step="0.001" 
                                      className="bg-transparent w-full font-black text-sm outline-none text-center" 
                                      value={ri.amount} 
                                      onChange={e => updateRecipeItem(idx, { amount: parseFloat(e.target.value) || 0 })} 
                                    />
                                    <span className="text-[10px] font-black text-slate-400 uppercase shrink-0">{ing?.unit}</span>
                                  </div>
                                </div>
                                <div className="w-full sm:w-32 text-center">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-1">Costo Línea</label>
                                  <p className="font-black text-slate-900 text-sm py-3">L. {calculateLineCost(ri.ingredientId, ri.amount).toFixed(2)}</p>
                                </div>
                                <button 
                                  onClick={() => setTempRecipe(tempRecipe.filter((_, i) => i !== idx))} 
                                  className="w-10 h-10 rounded-full flex items-center justify-center text-slate-300 hover:text-red-500 hover:bg-red-50 transition-all"
                                >
                                  🗑️
                                </button>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  </section>
                </div>
              </div>
            </div>

            {/* Footer Fijo con Acciones */}
            <footer className="p-6 lg:p-8 border-t border-slate-100 bg-slate-50 shrink-0">
              <div className="max-w-6xl mx-auto flex flex-col sm:flex-row gap-4 justify-between items-center">
                <p className="text-xs font-medium text-slate-400 italic order-2 sm:order-1 text-center sm:text-left">
                  Los cambios realizados se guardarán permanentemente en el sistema.
                </p>
                <div className="flex gap-3 w-full sm:w-auto order-1 sm:order-2">
                  <button 
                    onClick={() => setEditingItem(null)} 
                    className="flex-1 sm:px-8 py-4 bg-white border-2 border-slate-200 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-100 transition-all"
                  >
                    Cancelar
                  </button>
                  <button 
                    onClick={handleSave} 
                    className="flex-1 sm:px-12 py-4 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] hover:bg-orange-700 shadow-xl shadow-orange-100 transition-all active:scale-95"
                  >
                    Guardar Cambios
                  </button>
                </div>
              </div>
            </footer>
          </div>
        </div>
      )}

      {/* Formulario Nuevo Plato */}
      {showAddForm && (
        <div className="fixed inset-0 z-[105] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[2.5rem] w-full max-w-2xl p-8 shadow-2xl animate-scaleIn my-8">
            <header className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black text-slate-900">Crear Nuevo Plato</h3>
              <button onClick={() => setShowAddForm(false)} className="text-slate-400 hover:text-slate-900">✕</button>
            </header>
            <form onSubmit={handleCreateNewItem} className="space-y-6">
              <div className="space-y-4">
                {/* Imagen en Formulario de Creación */}
                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Imagen del Plato</label>
                  <div className="flex items-center gap-4">
                    <div className="w-32 h-32 bg-slate-100 rounded-3xl border-2 border-dashed border-slate-200 overflow-hidden flex items-center justify-center">
                      {newItemData.image ? (
                        <img src={newItemData.image} alt="Nuevo plato" className="w-full h-full object-cover" />
                      ) : (
                        <span className="text-2xl opacity-20">📸</span>
                      )}
                    </div>
                    <div className="flex-1">
                      <button 
                        type="button"
                        onClick={() => addFileInputRef.current?.click()}
                        className="px-4 py-2 bg-slate-100 text-slate-900 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-200"
                      >
                        Seleccionar Foto
                      </button>
                      <input 
                        type="file" 
                        ref={addFileInputRef} 
                        className="hidden" 
                        accept="image/*" 
                        onChange={(e) => handleImageUpload(e, true)}
                      />
                    </div>
                  </div>
                </div>

                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Nombre del Plato</label>
                  <input required type="text" className="w-full p-4 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-bold bg-slate-50" value={newItemData.name} onChange={e => setNewItemData({...newItemData, name: e.target.value})} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <div className="flex justify-between items-center mb-2">
                      <label className="block text-[10px] font-black uppercase text-slate-400 ml-1">Categoría</label>
                      <button type="button" onClick={() => setShowCategoryManager(true)} className="text-[9px] font-black text-orange-600 uppercase tracking-tighter">⚙️</button>
                    </div>
                    <select className="w-full p-4 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-bold bg-slate-50" value={newItemData.category} onChange={e => setNewItemData({...newItemData, category: e.target.value})}>
                      {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Precio Sugerido (L.)</label>
                    <input required type="number" step="0.01" className="w-full p-4 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-bold bg-slate-50" value={newItemData.price} onChange={e => setNewItemData({...newItemData, price: parseFloat(e.target.value) || 0})} />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Descripción</label>
                  <textarea className="w-full p-4 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-medium bg-slate-50 resize-none" rows={3} value={newItemData.description} onChange={e => setNewItemData({...newItemData, description: e.target.value})} placeholder="Describe los ingredientes destacados..." />
                </div>
              </div>
              <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-orange-600 transition-all shadow-xl">Crear Plato</button>
            </form>
          </div>
        </div>
      )}

      {/* Vista Principal Listado de Platos */}
      <div className="bg-slate-900 p-8 lg:p-12 rounded-[3rem] text-white flex flex-col md:flex-row justify-between items-center gap-8 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-orange-600/10 blur-[100px] rounded-full -mr-20 -mt-20"></div>
        <div className="relative z-10">
          <h2 className="text-3xl lg:text-4xl font-black">Gestión de Menú</h2>
          <p className="text-slate-400 text-sm font-bold uppercase tracking-[0.2em] mt-2">Rentabilidad y Escandallos en tiempo real</p>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto relative z-10">
          <button 
            onClick={() => setShowCategoryManager(true)} 
            className="bg-slate-800 text-white px-6 py-5 rounded-[2rem] font-black uppercase text-[10px] tracking-widest hover:bg-slate-700 transition-all flex items-center justify-center gap-2"
          >
            ⚙️ Categorías
          </button>
          <button 
            onClick={() => setShowAddForm(true)} 
            className="bg-orange-600 text-white px-10 py-5 rounded-[2rem] font-black uppercase tracking-widest shadow-2xl shadow-orange-900/40 hover:bg-orange-500 transition-all active:scale-95 flex items-center justify-center gap-3"
          >
            ➕ Crear Nuevo Plato
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {menu.map((item) => {
          const cost = calculateTotalCost(item.recipe);
          const margin = ((item.price - cost) / (item.price || 1)) * 100;
          return (
            <div key={item.id} className="bg-white p-8 rounded-[3rem] shadow-sm border border-slate-100 flex flex-col gap-6 group transition-all hover:border-orange-300 hover:shadow-2xl hover:shadow-slate-200">
              <div className="flex justify-between items-start">
                <div className="flex-1">
                  <span className="inline-block px-3 py-1 bg-slate-50 border border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest rounded-full mb-3">
                    {item.category}
                  </span>
                  <div className="flex gap-4 items-center">
                    {item.image && (
                      <img src={item.image} alt={item.name} className="w-16 h-16 rounded-2xl object-cover shadow-md border border-slate-100" />
                    )}
                    <div>
                      <h3 className="text-2xl font-black text-slate-900 group-hover:text-orange-600 transition-colors">{item.name}</h3>
                      <p className="text-slate-400 text-xs mt-1 italic line-clamp-1 leading-relaxed">{item.description}</p>
                    </div>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">PVP</p>
                  <p className="text-3xl font-black text-slate-900">L. {item.price.toFixed(2)}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-slate-50 p-4 rounded-3xl border border-slate-100">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-1">Costo Prod.</p>
                  <p className="text-xl font-black text-slate-700">L. {cost.toFixed(2)}</p>
                </div>
                <div className={`p-4 rounded-3xl border ${margin > 50 ? 'bg-green-50 border-green-100 text-green-600' : 'bg-orange-50 border-orange-100 text-orange-600'}`}>
                  <p className="text-[10px] font-black opacity-60 uppercase mb-1">Margen Bruto</p>
                  <p className="text-xl font-black">{margin.toFixed(1)}%</p>
                </div>
              </div>

              <div className="flex gap-3 mt-2">
                <button 
                  onClick={() => startEditing(item)} 
                  className="flex-1 bg-slate-900 text-white py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-orange-600 transition-all shadow-lg shadow-slate-200"
                >
                  ⚙️ Configurar Plato
                </button>
                <button 
                  onClick={() => onDeleteMenuItem(item.id)}
                  className="w-14 h-14 bg-slate-50 text-slate-300 hover:bg-red-50 hover:text-red-500 rounded-2xl flex items-center justify-center transition-all border border-transparent hover:border-red-100"
                >
                  🗑️
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

