import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Inicialización de estado con persistencia
  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [menuHeader, setMenuHeader] = useState<{title: string, description: string}>(() => {
    const saved = localStorage.getItem('menuHeader');
    return saved ? JSON.parse(saved) : {
      title: 'Nuestra Carta',
      description: 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'
    };
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ ...s, timestamp: new Date(s.timestamp) }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  // Guardar en localStorage cuando cambie el estado
  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('menuHeader', JSON.stringify(menuHeader)); }, [menuHeader]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const addCategory = (category: string) => {
    const cleanCat = category.trim();
    if (cleanCat && !categories.includes(cleanCat)) {
      setCategories([...categories, cleanCat]);
    }
  };

  const deleteCategory = (category: string) => {
    setCategories(categories.filter(c => c !== category));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: string,
    newDescription?: string,
    newImage?: string
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description,
            image: newImage !== undefined ? newImage : item.image
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now()
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido Online',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                availableUnits={availableUnits}
                onAddUnit={addUnit}
                onDeleteUnit={deleteUnit}
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && (
              <Menu 
                menu={menu} 
                header={menuHeader} 
                onUpdateHeader={(h) => setMenuHeader(h)} 
              />
            )}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                categories={categories}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { MenuItem } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  const categories = Array.from(new Set(menu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  return (
    <div className="space-y-12 animate-fadeIn pb-20">
      <header className="text-center max-w-2xl mx-auto mb-12 relative group">
        {isEditing ? (
          <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 mb-4 bg-slate-50 p-2 rounded-xl outline-none focus:bg-white"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título del Menú"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 font-medium bg-slate-50 p-3 rounded-xl outline-none focus:bg-white resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
              placeholder="Descripción del restaurante..."
            />
            <div className="flex justify-center gap-2 mt-6">
              <button 
                onClick={() => { setIsEditing(false); setTempTitle(header?.title || ''); setTempDescription(header?.description || ''); }}
                className="px-6 py-2 bg-slate-100 text-slate-400 rounded-xl font-black text-xs uppercase"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSaveHeader}
                className="px-8 py-2 bg-orange-600 text-white rounded-xl font-black text-xs uppercase shadow-lg shadow-orange-100"
              >
                Guardar Cambios
              </button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 mb-4">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 font-medium">{header?.description || 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
                className="absolute -top-4 -right-4 w-10 h-10 bg-white border border-slate-100 shadow-md rounded-full flex items-center justify-center text-slate-400 hover:text-orange-600 hover:scale-110 transition-all opacity-0 group-hover:opacity-100"
                title="Editar encabezado"
              >
                ⚙️
              </button>
            )}
          </div>
        )}
      </header>

      {categories.map(cat => (
        <section key={cat} className="space-y-6">
          <div className="flex items-center gap-4">
            <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">{cat}</h3>
            <div className="flex-1 h-px bg-slate-200"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {menu.filter(item => item.category === cat).map(item => (
              <div key={item.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden hover:shadow-2xl hover:scale-[1.02] transition-all duration-300 group">
                {item.image && (
                  <div className="w-full h-48 overflow-hidden relative">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-900/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
                  </div>
                )}
                <div className="p-6">
                  <div className="flex justify-between items-start mb-4">
                    <h4 className="text-xl font-black text-slate-900 leading-tight group-hover:text-orange-600 transition-colors">{item.name}</h4>
                  </div>
                  <p className="text-slate-500 text-sm leading-relaxed mb-6 italic">
                    {item.description}
                  </p>
                  <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Precio Final</span>
                    <span className="text-2xl font-black text-slate-900">L. {item.price.toFixed(2)}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </section>
      ))}
    </div>
  );
};

export default Menu;

import React, { useState } from 'react';
import { MenuItem, Sale } from '../types';

interface OnlineOrderProps {
  menu: MenuItem[];
  onPlaceOrder: (items: any, customerInfo: any) => void;
  onBackToAdmin: () => void;
}

const OnlineOrder: React.FC<OnlineOrderProps> = ({ menu, onPlaceOrder, onBackToAdmin }) => {
  const [cart, setCart] = useState<any[]>([]);
  const [step, setStep] = useState<'browsing' | 'checkout' | 'success'>('browsing');
  const [customer, setCustomer] = useState({ name: '', phone: '', email: '' });

  const categories = Array.from(new Set(menu.map(m => m.category)));

  const addToCart = (item: MenuItem) => {
    setCart([...cart, { ...item, cartId: Date.now(), customization: '' }]);
  };

  const removeFromCart = (cartId: number) => {
    setCart(cart.filter(c => c.cartId !== cartId));
  };

  const total = cart.reduce((sum, item) => sum + item.price, 0);

  if (step === 'success') {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center text-5xl mb-6 shadow-xl shadow-green-200">
          ✓
        </div>
        <h1 className="text-4xl font-black text-slate-900 mb-2">¡Pedido Confirmado!</h1>
        <p className="text-slate-500 mb-8 max-w-md text-lg">Tu asado está en manos de nuestros expertos. Te avisaremos cuando esté listo.</p>
        <button 
          onClick={() => { setStep('browsing'); setCart([]); }}
          className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-lg hover:bg-orange-600 transition-all shadow-xl"
        >
          Hacer otro pedido
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto pb-24 px-4">
      <header className="flex justify-between items-center py-8 mb-8">
        <div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight">Parrilla <span className="text-orange-500">Express</span></h1>
          <p className="text-slate-500 font-medium">Auténtico sabor a la brasa hasta tu mesa.</p>
        </div>
        <button onClick={onBackToAdmin} className="text-xs font-bold text-slate-400 hover:text-slate-900 uppercase tracking-widest bg-slate-100 px-4 py-2 rounded-full transition-colors">
          Cerrar Vista Cliente
        </button>
      </header>

      {step === 'browsing' ? (
        <div className="space-y-12">
          {categories.map(cat => (
            <div key={cat}>
              <h2 className="text-2xl font-black text-slate-800 mb-6 flex items-center gap-4">
                {cat}
                <div className="flex-1 h-px bg-slate-200"></div>
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {menu.filter(m => m.category === cat).map(item => (
                  <div key={item.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col overflow-hidden hover:shadow-xl hover:scale-[1.02] transition-all group">
                    {item.image && (
                      <div className="w-full h-40 overflow-hidden">
                        <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
                      </div>
                    )}
                    <div className="p-6 flex flex-col justify-between flex-1">
                      <div>
                        <h3 className="text-xl font-bold text-slate-900 mb-2">{item.name}</h3>
                        <p className="text-slate-500 text-sm mb-4 leading-relaxed line-clamp-2">{item.description}</p>
                      </div>
                      <div className="flex justify-between items-center mt-4">
                        <span className="text-2xl font-black text-slate-900">L. {item.price.toFixed(2)}</span>
                        <button 
                          onClick={() => addToCart(item)}
                          className="bg-orange-600 text-white px-6 py-2.5 rounded-2xl font-bold hover:bg-orange-500 transition-colors shadow-lg shadow-orange-200"
                        >
                          Añadir +
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="bg-white p-8 rounded-[40px] shadow-2xl border border-slate-100 animate-fadeIn">
          <button onClick={() => setStep('browsing')} className="text-slate-400 font-bold mb-6 flex items-center gap-2 hover:text-slate-900 transition-colors">
            ← Volver al menú
          </button>
          <h2 className="text-3xl font-black text-slate-900 mb-8">Finalizar Pedido</h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
            <div className="space-y-6">
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Nombre Completo</label>
                <input 
                  type="text" 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl p-4 transition-all outline-none font-medium"
                  placeholder="Tu nombre aquí..."
                  value={customer.name}
                  onChange={e => setCustomer({...customer, name: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Teléfono de contacto</label>
                <input 
                  type="tel" 
                  className="w-full bg-slate-50 border-2 border-transparent focus:border-orange-500 focus:bg-white rounded-2xl p-4 transition-all outline-none font-medium"
                  placeholder="+504 9000-0000"
                  value={customer.phone}
                  onChange={e => setCustomer({...customer, phone: e.target.value})}
                />
              </div>
            </div>

            <div className="bg-slate-50 p-6 rounded-3xl">
              <h3 className="font-bold text-slate-900 mb-4 border-b pb-4">Resumen de Compra</h3>
              <div className="space-y-3 max-h-60 overflow-y-auto mb-6 pr-2">
                {cart.map(item => (
                  <div key={item.cartId} className="flex justify-between items-center text-sm">
                    <div className="flex-1">
                      <div className="flex gap-2 items-center">
                        {item.image && (
                          <img src={item.image} className="w-8 h-8 rounded-lg object-cover" />
                        )}
                        <p className="font-bold text-slate-800">{item.name}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4">
                      <span className="font-bold text-slate-900">L. {item.price.toFixed(2)}</span>
                      <button onClick={() => removeFromCart(item.cartId)} className="text-red-400 font-bold hover:text-red-600">×</button>
                    </div>
                  </div>
                ))}
              </div>
              <div className="border-t border-slate-200 pt-4 space-y-2">
                <div className="flex justify-between font-black text-2xl text-slate-900">
                  <span>Total</span>
                  <span className="text-orange-600">L. {total.toFixed(2)}</span>
                </div>
                <button 
                  disabled={!customer.name || !customer.phone || cart.length === 0}
                  onClick={() => {
                    onPlaceOrder(cart, customer);
                    setStep('success');
                  }}
                  className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black text-xl mt-6 hover:bg-orange-600 transition-all disabled:bg-slate-300 shadow-xl active:scale-[0.98]"
                >
                  PAGAR AHORA
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {cart.length > 0 && step === 'browsing' && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-full max-w-md px-4 animate-bounce">
          <button 
            onClick={() => setStep('checkout')}
            className="w-full bg-slate-900 text-white py-5 rounded-[30px] shadow-2xl flex justify-between items-center px-8 hover:bg-orange-600 transition-all group"
          >
            <span className="font-black text-lg">VER CARRITO ({cart.length})</span>
            <div className="flex items-center gap-4">
              <span className="font-bold text-xl group-hover:scale-110 transition-transform">L. {total.toFixed(2)}</span>
              <span className="text-2xl">➔</span>
            </div>
          </button>
        </div>
      )}
    </div>
  );
};

export default OnlineOrder;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Inicialización de estado con persistencia
  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [menuHeader, setMenuHeader] = useState<{title: string, description: string}>(() => {
    const saved = localStorage.getItem('menuHeader');
    return saved ? JSON.parse(saved) : {
      title: 'Nuestra Carta',
      description: 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'
    };
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ ...s, timestamp: new Date(s.timestamp) }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  // Guardar en localStorage cuando cambie el estado
  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('menuHeader', JSON.stringify(menuHeader)); }, [menuHeader]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const addCategory = (category: string) => {
    const cleanCat = category.trim();
    if (cleanCat && !categories.includes(cleanCat)) {
      setCategories([...categories, cleanCat]);
    }
  };

  const deleteCategory = (category: string) => {
    setCategories(categories.filter(c => c !== category));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: string,
    newDescription?: string,
    newImage?: string
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description,
            image: newImage !== undefined ? newImage : item.image
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now()
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                availableUnits={availableUnits}
                onAddUnit={addUnit}
                onDeleteUnit={deleteUnit}
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && (
              <Menu 
                menu={menu} 
                header={menuHeader} 
                onUpdateHeader={(h) => setMenuHeader(h)} 
                onQuickOrder={(items) => addSale(items)}
              />
            )}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                categories={categories}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { MenuItem } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[]) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  // Estado para el carrito de pedido rápido
  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  const categories = Array.from(new Set(menu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    if (newCart[id] > 1) {
      newCart[id] -= 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity
      }));
      onQuickOrder(items);
      clearQuickCart();
    }
  };

  const quickCartCount = Object.values(quickCart).reduce((a, b) => a + b, 0);
  const quickCartTotal = Object.entries(quickCart).reduce((sum, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return sum + (item ? item.price * qty : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-32">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] w-full max-w-md p-8 shadow-2xl animate-scaleIn">
            <h3 className="text-xl font-black text-slate-900 mb-6">Confirmar Pedido Rápido</h3>
            <div className="space-y-4 mb-8 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                return (
                  <div key={id} className="flex justify-between items-center py-2 border-b border-slate-50">
                    <span className="font-bold text-slate-700 text-sm">{qty}x {item?.name}</span>
                    <span className="font-black text-slate-900 text-sm">L. {(item!.price * qty).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>
            <div className="flex justify-between items-center mb-8 border-t pt-4">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total a Pagar</span>
              <span className="text-2xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setIsConfirming(false)} className="flex-1 py-4 bg-slate-50 text-slate-400 rounded-2xl font-black text-xs uppercase hover:bg-slate-100 transition-all">Cancelar</button>
              <button onClick={handleProcessQuickOrder} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase hover:bg-orange-600 transition-all shadow-xl">Procesar Venta</button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group">
        {isEditing ? (
          <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 mb-4 bg-slate-50 p-2 rounded-xl outline-none focus:bg-white"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título del Menú"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 font-medium bg-slate-50 p-3 rounded-xl outline-none focus:bg-white resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
              placeholder="Descripción del restaurante..."
            />
            <div className="flex justify-center gap-2 mt-6">
              <button 
                onClick={() => { setIsEditing(false); setTempTitle(header?.title || ''); setTempDescription(header?.description || ''); }}
                className="px-6 py-2 bg-slate-100 text-slate-400 rounded-xl font-black text-xs uppercase"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSaveHeader}
                className="px-8 py-2 bg-orange-600 text-white rounded-xl font-black text-xs uppercase shadow-lg shadow-orange-100"
              >
                Guardar Cambios
              </button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 mb-4">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 font-medium">{header?.description || 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
                className="absolute -top-4 -right-4 w-10 h-10 bg-white border border-slate-100 shadow-md rounded-full flex items-center justify-center text-slate-400 hover:text-orange-600 hover:scale-110 transition-all opacity-0 group-hover:opacity-100"
                title="Editar encabezado"
              >
                ⚙️
              </button>
            )}
          </div>
        )}
      </header>

      {categories.map(cat => (
        <section key={cat} className="space-y-6">
          <div className="flex items-center gap-4">
            <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">{cat}</h3>
            <div className="flex-1 h-px bg-slate-200"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {menu.filter(item => item.category === cat).map(item => (
              <div key={item.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden hover:shadow-2xl hover:scale-[1.02] transition-all duration-300 group flex flex-col h-full relative">
                {item.image && (
                  <div className="w-full h-48 overflow-hidden relative">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-900/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

                    {/* Botón rápido sobre imagen */}
                    <button 
                      onClick={() => addToQuickCart(item.id)}
                      className="absolute bottom-4 right-4 w-12 h-12 bg-orange-600 text-white rounded-full flex items-center justify-center text-2xl shadow-xl transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300 hover:bg-orange-500 active:scale-90"
                      title="Añadir al pedido rápido"
                    >
                      +
                    </button>
                  </div>
                )}

                <div className="p-6 flex flex-col flex-1">
                  <div className="flex justify-between items-start mb-4">
                    <h4 className="text-xl font-black text-slate-900 leading-tight group-hover:text-orange-600 transition-colors">{item.name}</h4>
                  </div>
                  <p className="text-slate-500 text-sm leading-relaxed mb-6 italic flex-1">
                    {item.description}
                  </p>

                  <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                    <div>
                      <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest block mb-1">Precio Final</span>
                      <span className="text-2xl font-black text-slate-900">L. {item.price.toFixed(2)}</span>
                    </div>

                    {!item.image && (
                      <button 
                        onClick={() => addToQuickCart(item.id)}
                        className="bg-slate-900 text-white px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-orange-600 transition-all"
                      >
                        Añadir +
                      </button>
                    )}
                  </div>
                </div>

                {quickCart[item.id] > 0 && (
                  <div className="absolute top-4 left-4 bg-orange-600 text-white w-8 h-8 rounded-full flex items-center justify-center font-black text-xs shadow-lg animate-scaleIn">
                    {quickCart[item.id]}
                  </div>
                )}
              </div>
            ))}
          </div>
        </section>
      ))}

      {/* Carrito Flotante de Pedido Rápido */}
      {quickCartCount > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-full max-w-2xl px-4 z-[110] animate-fadeIn">
          <div className="bg-slate-900 text-white p-4 sm:p-6 rounded-[2.5rem] shadow-2xl flex flex-col sm:flex-row items-center justify-between gap-4 border border-slate-800">
            <div className="flex items-center gap-6 w-full sm:w-auto">
              <div className="relative">
                <span className="text-3xl">🛒</span>
                <span className="absolute -top-2 -right-2 bg-orange-600 text-white text-[10px] font-black w-5 h-5 rounded-full flex items-center justify-center">
                  {quickCartCount}
                </span>
              </div>
              <div className="hidden sm:block">
                <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Pedido Rápido</p>
                <p className="text-lg font-black text-orange-500">L. {quickCartTotal.toFixed(2)}</p>
              </div>

              {/* Controles rápidos en barra */}
              <div className="flex-1 sm:flex-none flex gap-2 overflow-x-auto custom-scrollbar pb-2 sm:pb-0 px-2">
                 {Object.entries(quickCart).map(([id, qty]) => {
                   const item = menu.find(m => m.id === id);
                   return (
                     <div key={id} className="bg-slate-800 px-3 py-1.5 rounded-xl flex items-center gap-2 shrink-0 border border-slate-700">
                        <span className="text-[10px] font-bold truncate max-w-[80px]">{item?.name}</span>
                        <div className="flex items-center gap-1">
                          <button onClick={() => removeFromQuickCart(id)} className="text-red-400 hover:text-red-300 px-1 font-bold">-</button>
                          <span className="text-[10px] font-black text-white">{qty}</span>
                          <button onClick={() => addToQuickCart(id)} className="text-green-400 hover:text-green-300 px-1 font-bold">+</button>
                        </div>
                     </div>
                   );
                 })}
              </div>
            </div>

            <div className="flex gap-2 w-full sm:w-auto">
               <button 
                onClick={clearQuickCart}
                className="flex-1 sm:flex-none px-6 py-4 bg-slate-800 text-slate-400 rounded-2xl font-black text-xs uppercase hover:text-white transition-all"
               >
                 Vaciar
               </button>
               <button 
                onClick={() => setIsConfirming(true)}
                className="flex-1 sm:flex-none px-10 py-4 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-orange-500 shadow-xl transition-all"
               >
                 Vender L. {quickCartTotal.toFixed(2)}
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Menu;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import { View, Ingredient, MenuItem, Sale, Customer } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Inicialización de estado con persistencia
  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [menuHeader, setMenuHeader] = useState<{title: string, description: string}>(() => {
    const saved = localStorage.getItem('menuHeader');
    return saved ? JSON.parse(saved) : {
      title: 'Nuestra Carta',
      description: 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'
    };
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ ...s, timestamp: new Date(s.timestamp) }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  // Guardar en localStorage cuando cambie el estado
  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('menuHeader', JSON.stringify(menuHeader)); }, [menuHeader]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const addCategory = (category: string) => {
    const cleanCat = category.trim();
    if (cleanCat && !categories.includes(cleanCat)) {
      setCategories([...categories, cleanCat]);
    }
  };

  const deleteCategory = (category: string) => {
    setCategories(categories.filter(c => c !== category));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: string,
    newDescription?: string,
    newImage?: string
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description,
            image: newImage !== undefined ? newImage : item.image
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now()
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: any) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItem = menu.find(m => m.id === si.id || m.id === si.menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItem?.id || '',
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: customerInfo ? 'new' : undefined
    };

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCust: Customer = {
          id: 'c' + Date.now(),
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    setSales(prev => [...prev, newSale]);
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                availableUnits={availableUnits}
                onAddUnit={addUnit}
                onDeleteUnit={deleteUnit}
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && (
              <Menu 
                menu={menu} 
                header={menuHeader} 
                onUpdateHeader={(h) => setMenuHeader(h)} 
                onQuickOrder={(items, customerInfo) => addSale(items, customerInfo)}
              />
            )}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                categories={categories}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

