import React, { useState } from 'react';
import { Sale, MenuItem } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  onAddSale: (saleItems: { menuItemId: string, quantity: number }[]) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, menu, onAddSale }) => {
  const [cart, setCart] = useState<Record<string, number>>({});
  const [showMobileCart, setShowMobileCart] = useState(false);
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);

  // Filtrar menú para mostrar solo items activos
  const activeMenu = menu.filter(m => m.isActive !== false);

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string) => {
    if (!cart[id]) return;
    const newCart = { ...cart };
    if (newCart[id] === 1) delete newCart[id];
    else newCart[id] -= 1;
    setCart(newCart);
  };

  const handleCheckout = () => {
    const items = Object.entries(cart).map(([menuItemId, quantity]) => ({
      menuItemId,
      quantity
    }));
    if (items.length === 0) return;
    onAddSale(items);
    setCart({});
    setShowMobileCart(false);
  };

  const cartTotal: number = Object.entries(cart).reduce((total: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return total + (item ? item.price * quantity : 0);
  }, 0);

  // Added explicit types (a: number, b: number) to fix: Operator '+' cannot be applied to types 'unknown' and 'unknown'.
  const cartCount = Object.values(cart).reduce((a: number, b: number) => a + b, 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fadeIn pb-24 lg:pb-8">
      {/* Modal de Detalle de Venta */}
      {selectedSale && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] w-full max-w-lg p-8 shadow-2xl animate-scaleIn">
            <header className="flex justify-between items-start mb-6">
              <div>
                <h3 className="text-xl font-black text-slate-900">Detalle de Venta</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">
                  ID: #{selectedSale.id} • {new Date(selectedSale.timestamp).toLocaleString()}
                </p>
              </div>
              <button 
                onClick={() => setSelectedSale(null)}
                className="w-10 h-10 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-full flex items-center justify-center transition-colors"
              >
                ✕
              </button>
            </header>

            <div className="space-y-4 mb-8 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
              {selectedSale.items.map((item, idx) => {
                const menuItem = menu.find(m => m.id === item.menuItemId);
                return (
                  <div key={idx} className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div className="flex justify-between items-start mb-1">
                      <span className="font-black text-slate-900 text-sm">
                        {item.quantity}x {menuItem?.name || 'Producto Desconocido'}
                      </span>
                      <span className="font-bold text-slate-600 text-sm">
                        L. {(item.quantity * item.priceAtSale).toFixed(2)}
                      </span>
                    </div>
                    {item.customization && (
                      <p className="text-[11px] text-orange-600 font-bold italic mt-1 bg-orange-50 px-2 py-1 rounded-lg inline-block">
                        Nota: {item.customization}
                      </p>
                    )}
                    <p className="text-[10px] text-slate-400 font-medium">Precio unitario: L. {item.priceAtSale.toFixed(2)}</p>
                  </div>
                );
              })}
            </div>

            <div className="pt-6 border-t border-slate-100 flex justify-between items-center">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Cobrado</p>
                <p className="text-3xl font-black text-slate-900">L. {selectedSale.total.toFixed(2)}</p>
              </div>
              <button 
                onClick={() => setSelectedSale(null)}
                className="px-8 py-3 bg-slate-900 text-white rounded-xl font-black text-xs uppercase tracking-widest hover:bg-orange-600 transition-all"
              >
                CERRAR
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100">
          <h2 className="text-xl font-black text-slate-800 mb-6 uppercase tracking-widest text-sm">Carta de Menú</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {activeMenu.map(item => (
              <div key={item.id} className="p-4 border border-slate-100 rounded-2xl hover:border-orange-300 transition-all flex justify-between items-center bg-slate-50/40 group">
                <div>
                  <h4 className="font-black text-slate-900 text-sm">{item.name}</h4>
                  <p className="text-xs font-bold text-orange-600">L. {item.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  {cart[item.id] > 0 && (
                    <div className="flex items-center gap-2 animate-fadeIn">
                      <button onClick={() => removeFromCart(item.id)} className="w-8 h-8 bg-white border border-slate-200 text-slate-600 rounded-full flex items-center justify-center hover:bg-slate-100 shadow-sm">-</button>
                      <span className="font-black text-sm w-4 text-center">{cart[item.id]}</span>
                    </div>
                  )}
                  <button 
                    onClick={() => addToCart(item.id)} 
                    className="w-10 h-10 bg-slate-900 text-white rounded-full flex items-center justify-center hover:bg-orange-600 transition-all shadow-lg active:scale-90"
                  >
                    +
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden hidden sm:block">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-black text-slate-800 uppercase tracking-widest text-sm">Ventas Recientes</h2>
            <span className="text-[10px] font-bold text-slate-400 uppercase italic">Haz clic en una fila para ver detalles</span>
          </div>
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left min-w-[500px]">
              <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <tr>
                  <th className="px-4 py-3">Hora</th>
                  <th className="px-4 py-3">Resumen de Pedido</th>
                  <th className="px-4 py-3 text-right">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {[...sales].reverse().slice(0, 10).map(sale => (
                  <tr 
                    key={sale.id} 
                    onClick={() => setSelectedSale(sale)}
                    className="text-xs cursor-pointer hover:bg-orange-50 transition-all group"
                  >
                    <td className="px-4 py-4 text-slate-400 font-bold group-hover:text-orange-600">
                      {new Date(sale.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </td>
                    <td className="px-4 py-4 text-slate-900 font-bold">
                      {sale.items.map(i => {
                        const m = menu.find(mi => mi.id === i.menuItemId);
                        return `${i.quantity}x ${m?.name}`;
                      }).join(', ')}
                    </td>
                    <td className="px-4 py-4 text-right font-black text-slate-900">
                      L. {sale.total.toFixed(2)}
                    </td>
                  </tr>
                ))}
                {sales.length === 0 && (
                  <tr>
                    <td colSpan={3} className="py-12 text-center text-slate-400 italic">No hay ventas registradas hoy</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Cart (Sidebar on Desktop, Floating Drawer on Mobile) */}
      <div className={`
        fixed inset-x-0 bottom-0 z-40 bg-slate-900 text-white p-6 rounded-t-[2.5rem] shadow-2xl transition-transform duration-300 transform
        lg:translate-y-0 lg:static lg:rounded-3xl lg:flex lg:flex-col lg:h-[calc(100vh-8rem)] lg:sticky lg:top-6
        ${showMobileCart ? 'translate-y-0' : 'translate-y-[calc(100%-80px)] lg:translate-y-0'}
      `}>
        <div 
          className="flex justify-between items-center mb-6 cursor-pointer lg:cursor-default"
          onClick={() => setShowMobileCart(!showMobileCart)}
        >
          <h3 className="text-lg font-black uppercase tracking-widest flex items-center gap-2">
            <span>🛒</span> Carrito <span className="bg-orange-600 text-[10px] px-2 py-1 rounded-full">{cartCount}</span>
          </h3>
          <span className="lg:hidden text-xl">{showMobileCart ? '↓' : '↑'}</span>
        </div>

        <div className="flex-1 overflow-y-auto space-y-4 mb-6 pr-2 custom-scrollbar min-h-[100px] max-h-[300px] lg:max-h-none">
          {Object.entries(cart).map(([id, qty]) => {
            const item = menu.find(m => m.id === id);
            return (
              <div key={id} className="flex justify-between items-center pb-4 border-b border-slate-800 last:border-0 animate-fadeIn">
                <div className="flex-1">
                  <p className="font-bold text-sm">{item?.name}</p>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{qty} x L. {item?.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  <p className="font-black text-orange-400 text-sm">L. {((qty as number) * (item?.price || 0)).toFixed(2)}</p>
                  <button onClick={() => removeFromCart(id)} className="text-red-500 hover:text-red-400 p-1">✕</button>
                </div>
              </div>
            );
          })}
          {Object.keys(cart).length === 0 && (
            <div className="text-center py-12 text-slate-500 italic text-sm">Selecciona productos para comenzar</div>
          )}
        </div>

        <div className="border-t border-slate-800 pt-6 space-y-4">
          <div className="flex justify-between text-xs font-bold uppercase tracking-widest text-slate-400">
            <span>ISV (15%)</span>
            <span>L. {(cartTotal * 0.15).toFixed(2)}</span>
          </div>
          <div className="flex justify-between text-2xl font-black pt-2">
            <span>TOTAL</span>
            <span className="text-orange-500">L. {cartTotal.toFixed(2)}</span>
          </div>
          <button 
            disabled={Object.keys(cart).length === 0}
            onClick={handleCheckout}
            className="w-full py-4 bg-orange-600 text-white rounded-2xl font-black text-sm uppercase tracking-[0.2em] hover:bg-orange-700 transition-all active:scale-[0.98] disabled:bg-slate-800 disabled:text-slate-600 disabled:cursor-not-allowed shadow-xl shadow-orange-900/40"
          >
            CONFIRMAR VENTA
          </button>
        </div>
      </div>
    </div>
  );
};

export default SalesManager;

import React, { useState, useMemo, useRef } from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  categories: string[];
  onAddCategory: (category: string) => void;
  onDeleteCategory: (category: string) => void;
  onUpdatePrice: (id: string, newPrice: number) => void;
  onUpdateRecipe: (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice: number, 
    newName: string, 
    newCategory: string,
    newDescription: string,
    newImage?: string,
    newIsActive?: boolean
  ) => void;
  onAddMenuItem: (item: Omit<MenuItem, 'id'>) => void;
  onDeleteMenuItem: (id: string) => void;
}

const PriceManager: React.FC<PriceManagerProps> = ({ 
  menu, 
  ingredients, 
  categories,
  onAddCategory,
  onDeleteCategory,
  onUpdatePrice, 
  onUpdateRecipe, 
  onAddMenuItem, 
  onDeleteMenuItem 
}) => {
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isEditingNameHeader, setIsEditingNameHeader] = useState<boolean>(false);
  const [tempRecipe, setTempRecipe] = useState<MenuItem['recipe']>([]);
  const [tempPrice, setTempPrice] = useState<number>(0);
  const [tempName, setTempName] = useState<string>('');
  const [tempCategory, setTempCategory] = useState<string>('');
  const [tempDescription, setTempDescription] = useState<string>('');
  const [tempImage, setTempImage] = useState<string | undefined>(undefined);
  const [tempIsActive, setTempIsActive] = useState<boolean>(true);

  const [showAddForm, setShowAddForm] = useState(false);
  const [showCategoryManager, setShowCategoryManager] = useState(false);
  const [newCategoryInput, setNewCategoryInput] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const addFileInputRef = useRef<HTMLInputElement>(null);

  const [newItemData, setNewItemData] = useState<Omit<MenuItem, 'id'>>({
    name: '',
    description: '',
    price: 0,
    category: categories[0] || 'General',
    recipe: []
  });

  const calculateLineCost = (ingredientId: string, amount: number) => {
    const ingredient = ingredients.find(i => i.id === ingredientId);
    return ingredient ? amount * ingredient.costPerUnit : 0;
  };

  const calculateTotalCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => total + calculateLineCost(item.ingredientId, item.amount), 0);
  };

  const startEditing = (item: MenuItem) => {
    setEditingItem(item);
    setTempName(item.name);
    setTempCategory(item.category);
    setTempDescription(item.description);
    setTempRecipe([...item.recipe]);
    setTempPrice(item.price);
    setTempImage(item.image);
    setTempIsActive(item.isActive !== false);
    setIsEditingNameHeader(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, isNew: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (isNew) {
          setNewItemData({ ...newItemData, image: base64String });
        } else {
          setTempImage(base64String);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const addIngredientToRecipe = () => {
    if (ingredients.length > 0) {
      setTempRecipe([...tempRecipe, { ingredientId: ingredients[0].id, amount: 0 }]);
    }
  };

  const updateRecipeItem = (index: number, updates: Partial<MenuItem['recipe'][0]>) => {
    const updated = [...tempRecipe];
    updated[index] = { ...updated[index], ...updates };
    setTempRecipe(updated);
  };

  const handleSave = () => {
    if (editingItem) {
      onUpdateRecipe(
        editingItem.id, 
        tempRecipe, 
        tempPrice, 
        tempName, 
        tempCategory, 
        tempDescription,
        tempImage,
        tempIsActive
      );
      setEditingItem(null);
    }
  };

  const handleToggleActiveQuick = (item: MenuItem) => {
    onUpdateRecipe(
      item.id,
      item.recipe,
      item.price,
      item.name,
      item.category,
      item.description,
      item.image,
      item.isActive === false
    );
  };

  const handleCreateNewItem = (e: React.FormEvent) => {
    e.preventDefault();
    onAddMenuItem(newItemData);
    setShowAddForm(false);
    setNewItemData({
      name: '',
      description: '',
      price: 0,
      category: categories[0] || 'General',
      recipe: []
    });
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCategoryInput.trim()) {
      onAddCategory(newCategoryInput.trim());
      setNewCategoryInput('');
    }
  };

  const currentProductionCost = useMemo(() => calculateTotalCost(tempRecipe), [tempRecipe, ingredients]);
  const currentMargin = useMemo(() => {
    if (tempPrice <= 0) return 0;
    return ((tempPrice - currentProductionCost) / tempPrice) * 100;
  }, [tempPrice, currentProductionCost]);

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Category Manager */}
      {showCategoryManager && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-md w-full shadow-2xl transform animate-scaleIn">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900">Gestionar Categorías</h3>
              <button onClick={() => setShowCategoryManager(false)} className="text-slate-400 hover:text-slate-900 p-2">✕</button>
            </div>
            <form onSubmit={handleAddCategory} className="flex gap-2 mb-6">
              <input 
                type="text" 
                placeholder="Nueva categoría..."
                className="flex-1 bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-orange-500"
                value={newCategoryInput}
                onChange={(e) => setNewCategoryInput(e.target.value)}
              />
              <button type="submit" className="bg-orange-600 text-white px-4 py-2 rounded-xl font-black text-xs uppercase hover:bg-orange-700 transition-all">Añadir</button>
            </form>
            <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar pr-2">
              {categories.map(cat => (
                <div key={cat} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl border border-slate-100 group">
                  <span className="font-bold text-slate-700 uppercase text-[10px] tracking-widest">{cat}</span>
                  <button onClick={() => onDeleteCategory(cat)} className="text-red-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100">🗑️</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal Editor Full Screen / Immersive */}
      {editingItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-xl transition-all duration-300">
          <div className="bg-white w-full h-full lg:h-[90vh] lg:max-w-6xl lg:rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-scaleIn">

            {/* Header Fijo */}
            <header className="px-6 py-4 lg:px-10 lg:py-6 border-b border-slate-100 flex justify-between items-center bg-white shrink-0">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-[10px] font-black text-orange-500 uppercase tracking-[0.2em] bg-orange-50 px-2 py-0.5 rounded">Editor Maestro</span>
                </div>
                <div className="flex items-center gap-3">
                  {isEditingNameHeader ? (
                    <div className="flex items-center gap-2 w-full max-w-xl">
                      <input 
                        className="flex-1 p-2 bg-slate-50 border-2 border-orange-500 rounded-xl font-black text-xl lg:text-3xl outline-none" 
                        value={tempName} 
                        onChange={e => setTempName(e.target.value)} 
                        autoFocus
                        onBlur={() => setIsEditingNameHeader(false)}
                      />
                      <button 
                        onClick={() => setIsEditingNameHeader(false)}
                        className="bg-green-600 text-white p-3 rounded-xl hover:bg-green-700 shadow-lg shadow-green-100"
                        title="Confirmar"
                      >
                        ✓
                      </button>
                    </div>
                  ) : (
                    <div className="flex items-center gap-3 truncate">
                      <h3 className="text-xl lg:text-3xl font-black text-slate-900 truncate">{tempName}</h3>
                      <button 
                        onClick={() => setIsEditingNameHeader(true)}
                        className="p-2 text-slate-400 hover:text-orange-600 transition-colors"
                        title="Editar nombre rápido"
                      >
                        ✏️
                      </button>
                    </div>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-4 ml-4 shrink-0">
                <div className="flex items-center gap-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Visibilidad:</label>
                   <button 
                     onClick={() => setTempIsActive(!tempIsActive)}
                     className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all border ${tempIsActive ? 'bg-green-600 text-white border-green-600' : 'bg-slate-200 text-slate-500 border-slate-200'}`}
                   >
                     {tempIsActive ? 'Activo' : 'Inactivo'}
                   </button>
                </div>
                <button 
                  onClick={() => setEditingItem(null)} 
                  className="w-10 h-10 lg:w-12 lg:h-12 bg-slate-50 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-full flex items-center justify-center transition-all shrink-0"
                >
                  ✕
                </button>
              </div>
            </header>

            {/* Contenido Desplazable */}
            <div className="flex-1 overflow-y-auto custom-scrollbar p-6 lg:p-10">
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

                {/* Columna Izquierda: Información y Precios */}
                <div className="lg:col-span-4 space-y-8">
                  <section className="space-y-6">
                    <h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-l-2 border-orange-500 pl-3">Identidad del Plato</h4>

                    {/* Sección de Imagen Avanzada */}
                    <div className="space-y-3">
                      <label className="block text-[10px] font-bold text-slate-500 uppercase ml-1 tracking-widest">Fotografía Representativa</label>
                      <div className="relative group">
                        <div className="w-full aspect-video bg-slate-100 rounded-[2rem] overflow-hidden border-2 border-dashed border-slate-200 flex items-center justify-center relative transition-all group-hover:border-orange-300">
                          {tempImage ? (
                            <>
                              <img src={tempImage} alt="Vista previa" className="w-full h-full object-cover" />
                              <button 
                                onClick={() => setTempImage(undefined)}
                                className="absolute top-4 right-4 w-10 h-10 bg-white/90 text-red-500 rounded-full flex items-center justify-center shadow-xl hover:bg-red-500 hover:text-white transition-all z-20"
                                title="Eliminar imagen"
                              >
                                ✕
                              </button>
                            </>
                          ) : (
                            <div className="text-center p-4">
                              <span className="text-4xl block mb-2 opacity-20">📸</span>
                              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Sin imagen definida</p>
                            </div>
                          )}
                          <button 
                            onClick={() => fileInputRef.current?.click()}
                            className="absolute inset-0 bg-slate-900/0 group-hover:bg-slate-900/30 flex items-center justify-center transition-all duration-300 z-10"
                          >
                            <span className="bg-white text-slate-900 px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-300 shadow-2xl">
                              {tempImage ? 'Reemplazar Fotografía' : 'Cargar Fotografía'}
                            </span>
                          </button>
                        </div>
                        <input 
                          type="file" 
                          ref={fileInputRef} 
                          className="hidden" 
                          accept="image/*" 
                          onChange={(e) => handleImageUpload(e)}
                        />
                      </div>
                    </div>

                    <div className="space-y-5 pt-2">
                      {/* Campo Nombre en Formulario */}
                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 ml-1 tracking-widest">Nombre del Plato</label>
                        <input 
                          type="text"
                          className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-sm outline-none focus:border-orange-500 transition-all focus:bg-white"
                          value={tempName}
                          onChange={e => setTempName(e.target.value)}
                          placeholder="Nombre comercial del plato..."
                        />
                      </div>

                      <div>
                        <div className="flex justify-between items-center mb-2">
                          <label className="block text-[10px] font-bold text-slate-500 uppercase ml-1 tracking-widest">Categoría del Plato</label>
                          <button onClick={() => setShowCategoryManager(true)} className="text-[9px] font-black text-orange-600 uppercase tracking-tighter hover:underline">⚙️ Categorías</button>
                        </div>
                        <select 
                          className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black text-sm outline-none focus:border-orange-500 transition-all focus:bg-white" 
                          value={tempCategory} 
                          onChange={e => setTempCategory(e.target.value)}
                        >
                          {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                        </select>
                      </div>

                      <div>
                        <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2 ml-1 tracking-widest">Descripción para el Cliente</label>
                        <textarea 
                          rows={4}
                          className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-medium text-sm outline-none focus:border-orange-500 transition-all resize-none focus:bg-white" 
                          value={tempDescription} 
                          onChange={e => setTempDescription(e.target.value)}
                          placeholder="Escribe los detalles que verá el cliente en el menú..."
                        />
                      </div>
                    </div>
                  </section>

                  <section className="p-8 bg-slate-950 rounded-[2.5rem] text-white shadow-2xl shadow-slate-300 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600/10 blur-3xl rounded-full -mr-16 -mt-16"></div>
                    <h4 className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-6 relative z-10">Métricas Económicas</h4>
                    <div className="space-y-6 relative z-10">
                      <div className="flex justify-between items-center">
                        <span className="text-sm font-bold text-slate-400">Costo Unitario Prod.</span>
                        <span className="text-xl font-black">L. {currentProductionCost.toFixed(2)}</span>
                      </div>
                      <div className="flex justify-between items-center border-t border-slate-800 pt-6">
                        <span className="text-sm font-bold text-slate-400">Precio Sugerido</span>
                        <div className="flex items-center gap-2 bg-slate-900 p-2.5 rounded-xl border border-slate-800">
                          <span className="text-orange-500 font-black">L.</span>
                          <input 
                            type="number" 
                            step="0.01" 
                            className="bg-transparent text-xl font-black text-white w-24 text-right outline-none" 
                            value={tempPrice} 
                            onChange={e => setTempPrice(parseFloat(e.target.value) || 0)} 
                          />
                        </div>
                      </div>
                      <div className={`p-5 rounded-2xl flex justify-between items-center ${currentMargin > 40 ? 'bg-green-600/20 text-green-400 border border-green-900/50' : 'bg-orange-600/20 text-orange-400 border border-orange-900/50'}`}>
                        <span className="text-xs font-black uppercase tracking-widest">Rentabilidad</span>
                        <span className="text-2xl font-black">{currentMargin.toFixed(1)}%</span>
                      </div>
                    </div>
                  </section>
                </div>

                {/* Columna Derecha: Ingredientes de la Receta */}
                <div className="lg:col-span-8">
                  <section className="space-y-6">
                    <div className="flex justify-between items-center">
                      <h4 className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-l-2 border-orange-500 pl-3">Composición de la Receta</h4>
                      <button 
                        onClick={addIngredientToRecipe} 
                        className="px-5 py-3 bg-slate-900 text-white text-[10px] font-black rounded-xl hover:bg-orange-600 transition-all uppercase tracking-[0.15em] shadow-xl"
                      >
                        ➕ Vincular Insumo
                      </button>
                    </div>

                    <div className="space-y-4">
                      {tempRecipe.length === 0 ? (
                        <div className="py-24 bg-slate-50 rounded-[3rem] border-2 border-dashed border-slate-200 text-center">
