                          <p className="text-slate-400 font-black uppercase text-xs tracking-widest">La receta está vacía</p>
                          <button onClick={addIngredientToRecipe} className="mt-4 text-orange-600 font-black text-xs uppercase tracking-tighter hover:bg-orange-50 px-4 py-2 rounded-lg transition-all">Añadir primer ingrediente</button>
                        </div>
                      ) : (
                        <div className="grid grid-cols-1 gap-4">
                          {tempRecipe.map((ri, idx) => {
                            const ing = ingredients.find(i => i.id === ri.ingredientId);
                            return (
                              <div key={idx} className="bg-white border-2 border-slate-100 rounded-[2rem] p-5 flex flex-col sm:flex-row gap-5 items-center group hover:border-orange-200 hover:shadow-xl hover:shadow-slate-100 transition-all">
                                <div className="flex-1 w-full">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1 tracking-widest">Insumo del Inventario</label>
                                  <select 
                                    className="w-full bg-slate-50 p-4 rounded-xl font-bold text-sm outline-none focus:bg-white focus:border-orange-500 transition-all" 
                                    value={ri.ingredientId} 
                                    onChange={e => updateRecipeItem(idx, { ingredientId: e.target.value })}
                                  >
                                    {ingredients.map(i => <option key={i.id} value={i.id}>{i.name}</option>)}
                                  </select>
                                </div>
                                <div className="w-full sm:w-40">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 ml-1 tracking-widest">Ración / Cantidad</label>
                                  <div className="flex items-center gap-2 bg-slate-50 p-4 rounded-xl border border-transparent focus-within:bg-white focus-within:border-orange-200 transition-all">
                                    <input 
                                      type="number" 
                                      step="0.001" 
                                      className="bg-transparent w-full font-black text-sm outline-none text-center" 
                                      value={ri.amount} 
                                      onChange={e => updateRecipeItem(idx, { amount: parseFloat(e.target.value) || 0 })} 
                                    />
                                    <span className="text-[10px] font-black text-slate-400 uppercase shrink-0">{ing?.unit}</span>
                                  </div>
                                </div>
                                <div className="w-full sm:w-32 text-center shrink-0">
                                  <label className="block text-[9px] font-black text-slate-400 uppercase mb-2 tracking-widest">Costo Bruto</label>
                                  <p className="font-black text-slate-900 text-sm py-2">L. {calculateLineCost(ri.ingredientId, ri.amount).toFixed(2)}</p>
                                </div>
                                <button 
                                  onClick={() => setTempRecipe(tempRecipe.filter((_, i) => i !== idx))} 
                                  className="w-12 h-12 rounded-xl flex items-center justify-center text-slate-300 hover:text-white hover:bg-red-500 transition-all shadow-sm shrink-0"
                                >
                                  🗑️
                                </button>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </div>
                  </section>
                </div>
              </div>
            </div>

            {/* Footer Fijo con Acciones */}
            <footer className="p-8 lg:p-10 border-t border-slate-100 bg-white shrink-0">
              <div className="max-w-6xl mx-auto flex flex-col sm:flex-row gap-4 justify-between items-center">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest order-2 sm:order-1 text-center sm:text-left">
                  Módulo de precisión para el control de mermas y costos operativos.
                </p>
                <div className="flex gap-4 w-full sm:w-auto order-1 sm:order-2">
                  <button 
                    onClick={() => setEditingItem(null)} 
                    className="flex-1 sm:px-10 py-5 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                  >
                    Salir sin Guardar
                  </button>
                  <button 
                    onClick={handleSave} 
                    className="flex-1 sm:px-14 py-5 bg-orange-600 text-white rounded-2xl font-black text-xs uppercase tracking-[0.25em] hover:bg-orange-700 shadow-2xl shadow-orange-100 transition-all active:scale-95"
