      {/* Formulario Nuevo Plato */}
      {showAddForm && (
        <div className="fixed inset-0 z-[105] flex items-center justify-center p-4 bg-slate-900/85 backdrop-blur-md overflow-y-auto">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl p-10 shadow-2xl animate-scaleIn my-10 border border-slate-200">
            <header className="flex justify-between items-center mb-10">
