            <form onSubmit={handleCreateNewItem} className="space-y-8">
              <div className="space-y-6">
                {/* Imagen en Formulario de Creación */}
                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-3 ml-1 tracking-widest">Imagen del Plato</label>
                  <div className="flex items-center gap-6">
