                </div>

                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1 tracking-widest">Nombre Comercial</label>
                  <input required type="text" className="w-full p-5 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-black bg-slate-50 transition-all focus:bg-white text-lg" placeholder="Ej: Parrillada Premium Especial" value={newItemData.name} onChange={e => setNewItemData({...newItemData, name: e.target.value})} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <div className="flex justify-between items-center mb-2">
                      <label className="block text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Categoría</label>
                    </div>
                    <select className="w-full p-5 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-bold bg-slate-50 transition-all focus:bg-white" value={newItemData.category} onChange={e => setNewItemData({...newItemData, category: e.target.value})}>
                      {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1 tracking-widest">Precio Inicial (L.)</label>
                    <input required type="number" step="0.01" className="w-full p-5 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-black bg-slate-50 transition-all focus:bg-white text-lg" value={newItemData.price} onChange={e => setNewItemData({...newItemData, price: parseFloat(e.target.value) || 0})} />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1 tracking-widest">Descripción para Carta</label>
                  <textarea className="w-full p-5 rounded-2xl border-2 border-slate-100 focus:outline-none focus:border-orange-500 font-medium bg-slate-50 transition-all focus:bg-white resize-none" rows={3} value={newItemData.description} onChange={e => setNewItemData({...newItemData, description: e.target.value})} placeholder="Describe brevemente los componentes del plato..." />
                </div>
              </div>
              <button type="submit" className="w-full py-6 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-[0.3em] hover:bg-orange-600 transition-all shadow-[0_20px_40px_-10px_rgba(0,0,0,0.3)] active:scale-[0.98]">Confirmar e Iniciar Receta</button>
            </form>
          </div>
        </div>
      )}

      {/* Vista Principal Listado de Platos */}
      <div className="bg-slate-950 p-10 lg:p-14 rounded-[3.5rem] text-white flex flex-col md:flex-row justify-between items-center gap-10 shadow-3xl relative overflow-hidden border border-slate-800">
        <div className="absolute top-0 right-0 w-80 h-80 bg-orange-600/10 blur-[120px] rounded-full -mr-32 -mt-32"></div>
        <div className="absolute bottom-0 left-0 w-64 h-64 bg-blue-600/5 blur-[100px] rounded-full -ml-32 -mb-32"></div>

        <div className="relative z-10 text-center md:text-left">
          <h2 className="text-4xl lg:text-5xl font-black tracking-tight leading-none">Arquitectura de Menú</h2>
          <p className="text-slate-500 text-xs font-black uppercase tracking-[0.4em] mt-3 pl-1">Control de Rentabilidad en Tiempo Real</p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto relative z-10">
          <button 
            onClick={() => setShowCategoryManager(true)} 
            className="bg-slate-900 text-slate-400 px-8 py-5 rounded-2xl font-black uppercase text-[10px] tracking-[0.2em] border border-slate-800 hover:text-white hover:border-slate-600 transition-all flex items-center justify-center gap-3"
          >
            ⚙️ Categorías
          </button>
          <button 
            onClick={() => setShowAddForm(true)} 
            className="bg-orange-600 text-white px-12 py-5 rounded-2xl font-black uppercase tracking-[0.25em] shadow-[0_25px_50px_-12px_rgba(234,88,12,0.4)] hover:bg-orange-500 transition-all active:scale-95 flex items-center justify-center gap-4"
          >
            ➕ Crear Nuevo Plato
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
        {menu.map((item) => {
          const cost = calculateTotalCost(item.recipe);
          const margin = ((item.price - cost) / (item.price || 1)) * 100;
          const isActive = item.isActive !== false;
          return (
            <div key={item.id} className={`bg-white p-10 rounded-[3.5rem] shadow-sm border flex flex-col gap-8 group transition-all hover:shadow-2xl hover:shadow-slate-200 relative overflow-hidden ${isActive ? 'border-slate-100' : 'opacity-70 border-dashed border-slate-300'}`}>
              {!isActive && (
                <div className="absolute top-0 right-0 bg-slate-100 text-slate-500 px-6 py-2 rounded-bl-[1.5rem] font-black text-[9px] uppercase tracking-widest z-10">
                  PLATILLO EN PAUSA
                </div>
              )}

              <div className="flex flex-col sm:flex-row justify-between items-start gap-6">
                <div className="flex-1 space-y-4">
                  <div className="flex items-center gap-3">
                    <span className="inline-block px-4 py-1.5 bg-slate-50 border border-slate-100 text-[9px] font-black text-slate-500 uppercase tracking-[0.2em] rounded-lg">
                      {item.category}
                    </span>
                  </div>
                  <div className="flex gap-6 items-center">
                    {item.image ? (
                      <div className="w-24 h-24 rounded-[1.5rem] overflow-hidden shadow-lg border-2 border-white shrink-0">
                        <img src={item.image} alt={item.name} className={`w-full h-full object-cover transition-all duration-500 group-hover:scale-110 ${!isActive ? 'grayscale' : ''}`} />
                      </div>
                    ) : (
                      <div className="w-24 h-24 rounded-[1.5rem] bg-slate-50 flex items-center justify-center text-4xl border border-slate-100 shrink-0">
                        🥩
                      </div>
                    )}
                    <div className="min-w-0">
                      <h3 className={`text-2xl font-black transition-colors truncate ${isActive ? 'text-slate-950 group-hover:text-orange-600' : 'text-slate-500'}`}>{item.name}</h3>
                      <p className="text-slate-400 text-xs mt-1 italic line-clamp-2 leading-relaxed font-medium">{item.description || 'Sin descripción detallada...'}</p>
                    </div>
                  </div>
                </div>
                <div className="text-right sm:shrink-0 w-full sm:w-auto bg-slate-50 sm:bg-transparent p-4 sm:p-0 rounded-2xl">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Precio PVP</p>
                  <p className={`text-4xl font-black ${isActive ? 'text-slate-950' : 'text-slate-500'}`}>L. {item.price.toFixed(2)}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 group-hover:bg-white group-hover:border-slate-200 transition-all">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Costo Producción</p>
                  <p className="text-2xl font-black text-slate-800">L. {cost.toFixed(2)}</p>
                </div>
                <div className={`p-6 rounded-[2rem] border transition-all ${margin > 45 ? 'bg-green-50 border-green-100 text-green-700' : 'bg-orange-50 border-orange-100 text-orange-600'}`}>
                  <p className="text-[9px] font-black opacity-60 uppercase tracking-widest mb-1">Margen Bruto</p>
                  <p className="text-2xl font-black">{margin.toFixed(1)}%</p>
                </div>
              </div>

              <div className="flex gap-4 mt-2">
                <button 
                  onClick={() => startEditing(item)} 
                  className="flex-[2] bg-slate-950 text-white py-5 rounded-2xl font-black uppercase text-[10px] tracking-[0.2em] hover:bg-orange-600 transition-all shadow-xl shadow-slate-200 active:scale-95"
                >
                  ⚙️ Gestionar Plato
                </button>
                <button 
                  onClick={() => handleToggleActiveQuick(item)}
                  className={`flex-1 rounded-2xl flex items-center justify-center transition-all border font-black text-[10px] uppercase tracking-widest ${isActive ? 'bg-slate-100 text-slate-400 hover:bg-orange-50 hover:text-orange-600 border-slate-200' : 'bg-green-600 text-white border-green-600 shadow-lg shadow-green-100'}`}
                  title={isActive ? "Pausar del menú" : "Reactivar en el menú"}
                >
                  {isActive ? "Pausar" : "Reactivar"}
                </button>
                <button 
                  onClick={() => { if(window.confirm('¿Eliminar este plato permanentemente?')) onDeleteMenuItem(item.id); }}
                  className="w-16 h-16 bg-slate-50 text-slate-300 hover:bg-red-500 hover:text-white rounded-2xl flex items-center justify-center transition-all border border-slate-200 hover:border-red-600 shadow-sm active:rotate-12"
                >
                  🗑️
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default PriceManager;

import React, { useState, useMemo, useRef } from 'react';
import { MenuItem, Ingredient } from '../types';

interface PriceManagerProps {
  menu: MenuItem[];
  ingredients: Ingredient[];
  categories: string[];
  onAddCategory: (category: string) => void;
  onDeleteCategory: (category: string) => void;
  onUpdatePrice: (id: string, newPrice: number) => void;
  onUpdateRecipe: (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice: number, 
    newName: string, 
    newCategory: string,
    newDescription: string,
    newImage?: string,
    newIsActive?: boolean
  ) => void;
  onAddMenuItem: (item: Omit<MenuItem, 'id'>) => void;
  onDeleteMenuItem: (id: string) => void;
}

const PriceManager: React.FC<PriceManagerProps> = ({ 
  menu, 
  ingredients, 
  categories,
  onAddCategory,
  onDeleteCategory,
  onUpdatePrice, 
  onUpdateRecipe, 
  onAddMenuItem, 
  onDeleteMenuItem 
}) => {
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [isEditingNameHeader, setIsEditingNameHeader] = useState<boolean>(false);
  const [tempRecipe, setTempRecipe] = useState<MenuItem['recipe']>([]);
  const [tempPrice, setTempPrice] = useState<number>(0);
  const [tempName, setTempName] = useState<string>('');
  const [tempCategory, setTempCategory] = useState<string>('');
  const [tempDescription, setTempDescription] = useState<string>('');
  const [tempImage, setTempImage] = useState<string | undefined>(undefined);
  const [tempIsActive, setTempIsActive] = useState<boolean>(true);

  const [showAddForm, setShowAddForm] = useState(false);
  const [showCategoryManager, setShowCategoryManager] = useState(false);
  const [newCategoryInput, setNewCategoryInput] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const addFileInputRef = useRef<HTMLInputElement>(null);

  const [newItemData, setNewItemData] = useState<Omit<MenuItem, 'id'>>({
    name: '',
    description: '',
    price: 0,
    category: categories[0] || 'General',
    recipe: []
  });

  const calculateLineCost = (ingredientId: string, amount: number) => {
    const ingredient = ingredients.find(i => i.id === ingredientId);
    return ingredient ? amount * ingredient.costPerUnit : 0;
  };

  const calculateTotalCost = (recipe: MenuItem['recipe']) => {
    return recipe.reduce((total, item) => total + calculateLineCost(item.ingredientId, item.amount), 0);
  };

  const startEditing = (item: MenuItem) => {
    setEditingItem(item);
    setTempName(item.name);
    setTempCategory(item.category);
    setTempDescription(item.description);
    setTempRecipe([...item.recipe]);
    setTempPrice(item.price);
    setTempImage(item.image);
    setTempIsActive(item.isActive !== false);
    setIsEditingNameHeader(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, isNew: boolean = false) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (isNew) {
          setNewItemData({ ...newItemData, image: base64String });
        } else {
          setTempImage(base64String);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const addIngredientToRecipe = () => {
    if (ingredients.length > 0) {
      setTempRecipe([...tempRecipe, { ingredientId: ingredients[0].id, amount: 0 }]);
    }
  };

  const updateRecipeItem = (index: number, updates: Partial<MenuItem['recipe'][0]>) => {
    const updated = [...tempRecipe];
    updated[index] = { ...updated[index], ...updates };
    setTempRecipe(updated);
  };

  const handleSave = () => {
    if (editingItem) {
      onUpdateRecipe(
        editingItem.id, 
        tempRecipe, 
        tempPrice, 
        tempName, 
        tempCategory, 
        tempDescription,
        tempImage,
        tempIsActive
      );
      setEditingItem(null);
    }
  };

  const handleToggleActiveQuick = (item: MenuItem) => {
    onUpdateRecipe(
      item.id,
      item.recipe,
      item.price,
      item.name,
      item.category,
      item.description,
      item.image,
      item.isActive === false
    );
  };

  const handleCreateNewItem = (e: React.FormEvent) => {
    e.preventDefault();
    onAddMenuItem(newItemData);
    setShowAddForm(false);
    setNewItemData({
      name: '',
      description: '',
      price: 0,
      category: categories[0] || 'General',
      recipe: []
    });
  };

  const handleAddCategory = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCategoryInput.trim()) {
      onAddCategory(newCategoryInput.trim());
      setNewCategoryInput('');
    }
  };

  const currentProductionCost = useMemo(() => calculateTotalCost(tempRecipe), [tempRecipe, ingredients]);
  const currentMargin = useMemo(() => {
    if (tempPrice <= 0) return 0;
    return ((tempPrice - currentProductionCost) / tempPrice) * 100;
  }, [tempPrice, currentProductionCost]);

  return (
    <div className="space-y-6 animate-fadeIn pb-12">
      {/* Modal Category Manager */}
      {showCategoryManager && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[2.5rem] p-8 max-w-md w-full shadow-2xl transform animate-scaleIn">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900">Gestionar Categorías</h3>
              <button onClick={() => setShowCategoryManager(false)} className="text-slate-400 hover:text-slate-900 p-2">✕</button>
            </div>
            <form onSubmit={handleAddCategory} className="flex gap-2 mb-6">
              <input 
                type="text" 
                placeholder="Nueva categoría..."
                className="flex-1 bg-slate-50 border-2 border-slate-100 rounded-xl px-4 py-2 text-sm font-bold outline-none focus:border-orange-500"
                value={newCategoryInput}
                onChange={(e) => setNewCategoryInput(e.target.value)}
              />
              <button type="submit" className="bg-orange-600 text-white px-4 py-2 rounded-xl font-black text-xs uppercase hover:bg-orange-700 transition-all">Añadir</button>
            </form>
            <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar pr-2">
              {categories.map(cat => (
                <div key={cat} className="flex justify-between items-center p-3 bg-slate-50 rounded-xl border border-slate-100 group">
                  <span className="font-bold text-slate-700 uppercase text-[10px] tracking-widest">{cat}</span>
                  <button onClick={() => onDeleteCategory(cat)} className="text-red-300 hover:text-red-500 transition-colors opacity-0 group-hover:opacity-100">🗑️</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Modal Editor Full Screen / Immersive */}
      {editingItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-xl transition-all duration-300">
          <div className="bg-white w-full h-full lg:h-[90vh] lg:max-w-6xl lg:rounded-[3rem] shadow-2xl flex flex-col overflow-hidden animate-scaleIn">

            {/* Header Fijo */}
            <header className="px-6 py-4 lg:px-10 lg:py-6 border-b border-slate-100 flex justify-between items-center bg-white shrink-0">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-[10px] font-black text-orange-500 uppercase tracking-[0.2em] bg-orange-50 px-2 py-0.5 rounded">Editor Maestro</span>
                </div>
                <div className="flex items-center gap-3">
                  {isEditingNameHeader ? (
                    <div className="flex items-center gap-2 w-full max-w-xl">
                      <input 
                        className="flex-1 p-2 bg-slate-50 border-2 border-orange-500 rounded-xl font-black text-xl lg:text-3xl outline-none" 
                        value={tempName} 
                        onChange={e => setTempName(e.target.value)} 
                        autoFocus
                        onBlur={() => setIsEditingNameHeader(false)}
                      />
                      <button 
