import React, { useState } from 'react';
import { Sale, MenuItem, Customer, SaleStatus } from '../types';

interface OrdersManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  customers: Customer[];
  onUpdateStatus: (saleId: string, status: SaleStatus) => void;
}

const OrdersManager: React.FC<OrdersManagerProps> = ({ sales, menu, customers, onUpdateStatus }) => {
  const [filter, setFilter] = useState<SaleStatus | 'Todos'>('Todos');

  const statuses: SaleStatus[] = ['Recibido', 'Preparacion', 'Listo', 'Enviado', 'Entregado'];

  const getStatusColor = (status: SaleStatus) => {
    switch (status) {
      case 'Recibido': return 'bg-slate-100 text-slate-600 border-slate-200';
      case 'Preparacion': return 'bg-orange-50 text-orange-600 border-orange-200';
      case 'Listo': return 'bg-green-50 text-green-600 border-green-200';
      case 'Enviado': return 'bg-blue-50 text-blue-600 border-blue-200';
      case 'Entregado': return 'bg-slate-900 text-white border-slate-900';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const filteredSales = sales
    .filter(s => filter === 'Todos' || s.status === filter)
    .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

  return (
    <div className="space-y-8 animate-fadeIn pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Gestión de Órdenes</h2>
          <p className="text-slate-500 font-medium">Control de flujo y tiempos de entrega en tiempo real.</p>
        </div>

        <div className="flex bg-white p-1.5 rounded-2xl shadow-sm border border-slate-200 overflow-x-auto max-w-full custom-scrollbar">
          <button 
            onClick={() => setFilter('Todos')}
            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === 'Todos' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-900'}`}
          >
            Todos
          </button>
          {statuses.map(s => (
            <button 
              key={s}
              onClick={() => setFilter(s)}
              className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === s ? 'bg-orange-600 text-white' : 'text-slate-400 hover:text-slate-900'}`}
            >
              {s}
            </button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredSales.map(sale => {
          const customer = customers.find(c => c.id === sale.customerId) || 
                          (sale.customerId === 'new' ? { name: 'Venta Directa' } : null);

          return (
            <div key={sale.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col overflow-hidden hover:shadow-xl hover:scale-[1.01] transition-all group">
              {/* Card Header */}
              <div className="p-6 border-b border-slate-50">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1 block">Órden #{sale.id.slice(-6)}</span>
                    <h3 className="text-lg font-black text-slate-900">{customer?.name || 'Cliente Final'}</h3>
                  </div>
                  <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase border tracking-widest ${getStatusColor(sale.status)}`}>
                    {sale.status}
                  </div>
                </div>
                <div className="flex items-center gap-2 text-slate-400">
                  <span className="text-xs font-bold">🕒 {sale.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  <span className="text-xs font-bold">•</span>
                  <span className="text-xs font-bold">{sale.timestamp.toLocaleDateString()}</span>
                </div>
              </div>

              {/* Items Detail */}
              <div className="p-6 flex-1 space-y-4">
                <div className="space-y-3">
                  {sale.items.map((item, idx) => {
                    const menuItem = menu.find(m => m.id === item.menuItemId);
                    return (
                      <div key={idx} className="flex justify-between items-center text-sm">
                        <div className="flex items-center gap-3">
                          <span className="w-6 h-6 bg-slate-100 rounded-md flex items-center justify-center font-black text-[10px] text-slate-500">{item.quantity}</span>
                          <span className="font-bold text-slate-700">{menuItem?.name || 'Producto'}</span>
                        </div>
                        <span className="font-bold text-slate-400">L. {(item.priceAtSale * item.quantity).toFixed(2)}</span>
                      </div>
                    );
                  })}
                </div>

                <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                  <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total Cobrado</span>
                  <span className="text-xl font-black text-slate-900">L. {sale.total.toFixed(2)}</span>
                </div>
              </div>

              {/* Status Actions */}
              <div className="p-6 bg-slate-50 border-t border-slate-100">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 text-center">CAMBIAR ESTATUS A:</p>
                <div className="flex flex-wrap gap-2 justify-center">
                  {statuses.map(s => (
                    <button
                      key={s}
                      onClick={() => onUpdateStatus(sale.id, s)}
                      disabled={sale.status === s}
                      className={`px-3 py-2 rounded-xl text-[9px] font-black uppercase tracking-tighter transition-all border ${
                        sale.status === s 
                        ? 'bg-slate-200 text-slate-400 border-slate-200 scale-95 opacity-50 cursor-default' 
                        : 'bg-white text-slate-600 border-slate-200 hover:border-orange-500 hover:text-orange-600 hover:shadow-md'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          );
        })}

        {filteredSales.length === 0 && (
          <div className="col-span-full py-20 text-center bg-white rounded-[3rem] border border-dashed border-slate-200">
            <div className="text-6xl mb-6 opacity-20">📋</div>
            <h3 className="text-xl font-black text-slate-400 uppercase tracking-widest">No hay órdenes en este estado</h3>
            <button onClick={() => setFilter('Todos')} className="mt-4 text-orange-600 font-bold hover:underline">Ver todos los pedidos</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default OrdersManager;

import React, { useState } from 'react';
import { MenuItem } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[], customerInfo?: { name: string, phone: string }) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  // Estado para el carrito de pedido rápido
  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  // Estado para información del cliente en pedido rápido
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // Filtrar menú para mostrar solo items activos
  const activeMenu = menu.filter(m => m.isActive !== false);
  const categories = Array.from(new Set(activeMenu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    if (newCart[id] > 1) {
      newCart[id] -= 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
    setCustomerName('');
    setCustomerPhone('');
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity
      }));

      const customerInfo = customerName.trim() || customerPhone.trim() 
        ? { name: customerName, phone: customerPhone } 
        : undefined;

      onQuickOrder(items, customerInfo);
      clearQuickCart();
    }
  };

  // Fixed type issue in reduce: Operator '+' cannot be applied to types 'unknown' and 'unknown'
  const quickCartCount = Object.values(quickCart).reduce((a: number, b: number) => a + b, 0);
  // Fixed type issue in reduce and arithmetic operation
  const quickCartTotal = Object.entries(quickCart).reduce((sum: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return sum + (item ? item.price * quantity : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-32">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-950/70 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-lg w-full max-w-lg p-8 shadow-2xl animate-scaleIn overflow-y-auto max-h-[90vh] custom-scrollbar border border-slate-200">
            <h3 className="text-xl font-black text-slate-900 mb-6 flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> Confirmar Venta Rápida
            </h3>

            {/* Información del Cliente */}
            <div className="bg-slate-50 p-6 rounded-md mb-6 space-y-4 border border-slate-100">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2 mb-2">
                👤 DATOS DEL CLIENTE
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1 ml-1">Nombre Completo</label>
                  <input 
                    type="text" 
                    placeholder="Ej: Juan Pérez"
                    className="w-full bg-white border border-slate-200 focus:border-orange-500 rounded-md px-4 py-2.5 text-sm font-bold outline-none transition-all"
                    value={customerName}
                    onChange={e => setCustomerName(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1 ml-1">Teléfono</label>
                  <input 
                    type="tel" 
                    placeholder="Ej: 9988-7766"
                    className="w-full bg-white border border-slate-200 focus:border-orange-500 rounded-md px-4 py-2.5 text-sm font-bold outline-none transition-all"
                    value={customerPhone}
                    onChange={e => setCustomerPhone(e.target.value)}
                  />
                </div>
              </div>
            </div>

            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">🛒 DETALLE DEL PEDIDO</h4>
            <div className="space-y-1 mb-8 max-h-[30vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                const quantity = qty as number;
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                    <div>
                      <span className="font-bold text-slate-800 text-sm block">{item?.name}</span>
                      <span className="text-[10px] text-slate-400 font-black uppercase">{quantity}x L. {item?.price.toFixed(2)}</span>
                    </div>
                    {/* Fixed type issue in arithmetic operation */}
                    <span className="font-black text-slate-900 text-sm">L. {(item!.price * quantity).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-between items-center mb-8 border-t-2 border-slate-100 pt-6">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total a Cobrar</span>
              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button 
                onClick={() => setIsConfirming(false)} 
                className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-md font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={handleProcessQuickOrder} 
                className="flex-1 py-4 bg-slate-900 text-white rounded-md font-black text-[10px] uppercase tracking-[0.2em] hover:bg-orange-600 transition-all shadow-xl active:scale-95"
              >
                Confirmar Venta
              </button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group">
        {isEditing ? (
          <div className="bg-white p-6 rounded-md shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 mb-4 bg-slate-50 p-2 rounded-md outline-none focus:bg-white"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título del Menú"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 font-medium bg-slate-50 p-3 rounded-md outline-none focus:bg-white resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
              placeholder="Descripción del restaurante..."
            />
            <div className="flex justify-center gap-2 mt-6">
              <button 
                onClick={() => { setIsEditing(false); setTempTitle(header?.title || ''); setTempDescription(header?.description || ''); }}
                className="px-6 py-2 bg-slate-100 text-slate-400 rounded-md font-black text-xs uppercase"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSaveHeader}
                className="px-8 py-2 bg-orange-600 text-white rounded-md font-black text-xs uppercase shadow-lg"
              >
                Guardar
              </button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 mb-4">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 font-medium">{header?.description || 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
                className="absolute -top-4 -right-4 w-10 h-10 bg-white border border-slate-100 shadow-md rounded-full flex items-center justify-center text-slate-400 hover:text-orange-600 hover:scale-110 transition-all opacity-0 group-hover:opacity-100"
                title="Editar encabezado"
              >
                ⚙️
              </button>
            )}
          </div>
        )}
      </header>

      {categories.map(cat => (
        <section key={cat} className="space-y-6">
          <div className="flex items-center gap-4">
            <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">{cat}</h3>
            <div className="flex-1 h-px bg-slate-200"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {activeMenu.filter(item => item.category === cat).map(item => (
              <div key={item.id} className="bg-white rounded-md shadow-sm border border-slate-100 overflow-hidden hover:shadow-2xl hover:scale-[1.01] transition-all duration-300 group flex flex-col h-full relative">
                {item.image && (
                  <div className="w-full h-48 overflow-hidden relative">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950/70 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

                    <button 
                      onClick={() => addToQuickCart(item.id)}
                      className="absolute bottom-4 right-4 w-12 h-12 bg-orange-600 text-white rounded-md flex items-center justify-center text-2xl shadow-xl transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300 hover:bg-orange-500 active:scale-90"
                      title="Añadir"
                    >
                      +
                    </button>
                  </div>
                )}

                <div className="p-6 flex flex-col flex-1">
                  <div className="flex justify-between items-start mb-4">
                    <h4 className="text-lg font-black text-slate-900 leading-tight group-hover:text-orange-600 transition-colors">{item.name}</h4>
                  </div>
                  <p className="text-slate-500 text-xs leading-relaxed mb-6 flex-1">
                    {item.description}
                  </p>

                  <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                    <div>
                      <span className="text-[9px] font-black uppercase text-slate-400 tracking-widest block mb-1">PVP</span>
                      <span className="text-xl font-black text-slate-900">L. {item.price.toFixed(2)}</span>
                    </div>

                    {!item.image && (
                      <button 
                        onClick={() => addToQuickCart(item.id)}
                        className="bg-slate-900 text-white px-5 py-2 rounded-md font-black text-[10px] uppercase tracking-widest hover:bg-orange-600 transition-all"
                      >
                        Añadir +
                      </button>
                    )}
                  </div>
                </div>

                {/* Fixed type issue: (quickCart[item.id] || 0) > 0 to handle potential undefined */}
                {(quickCart[item.id] || 0) > 0 && (
                  <div className="absolute top-3 left-3 bg-orange-600 text-white w-7 h-7 rounded-md flex items-center justify-center font-black text-[10px] shadow-lg animate-scaleIn border-2 border-white">
                    {quickCart[item.id]}
                  </div>
                )}
              </div>
            ))}
          </div>
        </section>
      ))}

      {/* Barra de Pedido Flotante - CENTRADA Y CUADRADA */}
      {quickCartCount > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-full max-w-2xl px-4 z-[110] animate-fadeIn">
          <div className="bg-slate-950/95 backdrop-blur-lg text-white p-4 sm:p-5 rounded-md shadow-[0_25px_50px_-12px_rgba(0,0,0,0.6)] flex flex-col sm:flex-row items-center justify-between gap-6 border border-slate-800 relative overflow-hidden">
            {/* Indicador lateral elegante */}
            <div className="absolute left-0 top-0 w-1.5 h-full bg-orange-600"></div>

            <div className="flex items-center gap-6 w-full sm:w-auto">
              <div className="relative shrink-0 ml-2">
                <span className="text-2xl">📋</span>
                <span className="absolute -top-2 -right-2 bg-orange-600 text-white text-[9px] font-black w-4.5 h-4.5 rounded-sm flex items-center justify-center border border-slate-950">
                  {quickCartCount}
                </span>
              </div>
              <div className="hidden sm:block shrink-0">
                <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.3em] mb-0.5">ORDEN EN CURSO</p>
                <p className="text-xl font-black text-orange-500 tracking-tight">L. {quickCartTotal.toFixed(2)}</p>
              </div>

              {/* Items seleccionados - Dock central scrollable */}
              <div className="flex-1 sm:flex-none flex gap-2 overflow-x-auto custom-scrollbar pb-1 sm:pb-0 px-2">
                 {Object.entries(quickCart).map(([id, qty]) => {
                   const item = menu.find(m => m.id === id);
                   const quantity = qty as number;
                   return (
                     <div key={id} className="bg-slate-900 border border-slate-800 px-3 py-1.5 rounded-sm flex items-center gap-3 shrink-0 hover:bg-slate-800 transition-colors group/item">
                        <span className="text-[10px] font-bold text-slate-300 truncate max-w-[80px]">{item?.name}</span>
                        <div className="flex items-center gap-1.5 bg-slate-950 px-1.5 py-0.5 rounded-sm border border-slate-800">
                          <button onClick={() => removeFromQuickCart(id)} className="text-red-500 hover:text-red-400 font-black text-xs px-1">-</button>
                          <span className="text-[10px] font-black text-white min-w-[12px] text-center">{quantity}</span>
                          <button onClick={() => addToQuickCart(id)} className="text-green-500 hover:text-green-400 font-black text-xs px-1">+</button>
                        </div>
                     </div>
                   );
                 })}
              </div>
            </div>

            <div className="flex gap-3 w-full sm:w-auto">
               <button 
                onClick={clearQuickCart}
                className="flex-1 sm:flex-none px-6 py-3.5 bg-slate-900 border border-slate-800 text-slate-500 hover:text-slate-300 hover:border-slate-700 rounded-md font-black text-[9px] uppercase tracking-widest transition-all"
               >
                 VACIAR
               </button>
               <button 
                onClick={() => setIsConfirming(true)}
                className="flex-1 sm:flex-none px-8 py-3.5 bg-orange-600 text-white rounded-md font-black text-[9px] uppercase tracking-[0.25em] hover:bg-orange-500 shadow-xl shadow-orange-950/20 transition-all active:scale-[0.96]"
               >
                 COBRAR L. {quickCartTotal.toFixed(2)}
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Menu;

export interface Ingredient {
  id: string;
  name: string;
  unit: string;
  stock: number;
  minStock: number;
  costPerUnit: number;
}

export type SaleStatus = 'Recibido' | 'Preparacion' | 'Listo' | 'Enviado' | 'Entregado';

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image?: string;
  isActive?: boolean;
  recipe: {
    ingredientId: string;
    amount: number;
  }[];
}

export interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  notes: string;
  orderHistory: string[];
}

export interface Sale {
  id: string;
  timestamp: Date;
  customerId?: string;
  customerName?: string; // Nombre para mostrar en órdenes sin ID de cliente formal
  items: {
    menuItemId: string;
    quantity: number;
    priceAtSale: number;
    customization?: string;
  }[];
  total: number;
  status: SaleStatus;
}

export type View = 'dashboard' | 'inventory' | 'menu' | 'prices' | 'sales' | 'analysis' | 'reports' | 'customers' | 'online-order' | 'orders';

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import OrdersManager from './components/OrdersManager';
import { View, Ingredient, MenuItem, Sale, Customer, SaleStatus } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [menuHeader, setMenuHeader] = useState<{title: string, description: string}>(() => {
    const saved = localStorage.getItem('menuHeader');
    return saved ? JSON.parse(saved) : {
      title: 'Nuestra Carta',
      description: 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'
    };
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ 
      ...s, 
      timestamp: new Date(s.timestamp),
      status: s.status || 'Recibido'
    }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('menuHeader', JSON.stringify(menuHeader)); }, [menuHeader]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const addCategory = (category: string) => {
    const cleanCat = category.trim();
    if (cleanCat && !categories.includes(cleanCat)) {
      setCategories([...categories, cleanCat]);
    }
  };

  const deleteCategory = (category: string) => {
    setCategories(categories.filter(c => c !== category));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: string,
    newDescription?: string,
    newImage?: string,
    newIsActive?: boolean
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description,
            image: newImage !== undefined ? newImage : item.image,
            isActive: newIsActive !== undefined ? newIsActive : item.isActive
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now(),
      isActive: true
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: { name: string, phone: string }) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItemId = si.menuItemId || si.id;
      const menuItem = menu.find(m => m.id === menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItemId,
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    let assignedCustomerId: string | undefined = undefined;

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        assignedCustomerId = existing.id;
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCustId = 'c' + Date.now();
        assignedCustomerId = newCustId;
        const newCust: Customer = {
          id: newCustId,
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: assignedCustomerId,
      customerName: customerInfo?.name || 'Cliente de Mostrador',
      status: 'Recibido'
    };

    setSales(prev => [...prev, newSale]);
  };

  const updateSaleStatus = (saleId: string, newStatus: SaleStatus) => {
    setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: newStatus } : s));
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                availableUnits={availableUnits}
                onAddUnit={addUnit}
                onDeleteUnit={deleteUnit}
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && (
              <Menu 
                menu={menu} 
                header={menuHeader} 
                onUpdateHeader={(h) => setMenuHeader(h)} 
                onQuickOrder={(items, customerInfo) => addSale(items, customerInfo)}
              />
            )}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                categories={categories}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'orders' && <OrdersManager sales={sales} menu={menu} customers={customers} onUpdateStatus={updateSaleStatus} />}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Sale, MenuItem, Customer, SaleStatus } from '../types';

interface OrdersManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  customers: Customer[];
  onUpdateStatus: (saleId: string, status: SaleStatus) => void;
}

const OrdersManager: React.FC<OrdersManagerProps> = ({ sales, menu, customers, onUpdateStatus }) => {
  const [filter, setFilter] = useState<SaleStatus | 'Todos'>('Todos');

  const statuses: SaleStatus[] = ['Recibido', 'Preparacion', 'Listo', 'Enviado', 'Entregado'];

  const getStatusColor = (status: SaleStatus) => {
    switch (status) {
      case 'Recibido': return 'bg-slate-100 text-slate-600 border-slate-200';
      case 'Preparacion': return 'bg-orange-50 text-orange-600 border-orange-200';
      case 'Listo': return 'bg-green-50 text-green-600 border-green-200';
      case 'Enviado': return 'bg-blue-50 text-blue-600 border-blue-200';
      case 'Entregado': return 'bg-slate-900 text-white border-slate-900';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const filteredSales = sales
    .filter(s => filter === 'Todos' || s.status === filter)
    .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

  return (
    <div className="space-y-8 animate-fadeIn pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Gestión de Órdenes</h2>
          <p className="text-slate-500 font-medium">Flujo de trabajo desde recepción hasta entrega final.</p>
        </div>

        <div className="flex bg-white p-1.5 rounded-2xl shadow-sm border border-slate-200 overflow-x-auto max-w-full custom-scrollbar">
          <button 
            onClick={() => setFilter('Todos')}
            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === 'Todos' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-900'}`}
          >
            Todos
          </button>
          {statuses.map(s => (
            <button 
              key={s}
              onClick={() => setFilter(s)}
              className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === s ? 'bg-orange-600 text-white' : 'text-slate-400 hover:text-slate-900'}`}
            >
              {s}
            </button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredSales.map(sale => {
          // Intentar obtener el nombre del cliente desde la base de datos o desde los datos directos de la venta
          const customerDb = customers.find(c => c.id === sale.customerId);
          const displayName = customerDb?.name || sale.customerName || 'Venta de Mostrador';

          return (
            <div key={sale.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col overflow-hidden hover:shadow-xl hover:scale-[1.01] transition-all group">
              {/* Card Header */}
              <div className="p-6 border-b border-slate-50">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1 block">Órden #{sale.id.slice(-6)}</span>
                    <h3 className="text-lg font-black text-slate-900 truncate max-w-[180px]">{displayName}</h3>
                  </div>
                  <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase border tracking-widest ${getStatusColor(sale.status)}`}>
                    {sale.status}
                  </div>
                </div>
                <div className="flex items-center gap-2 text-slate-400">
                  <span className="text-xs font-bold">🕒 {sale.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  <span className="text-xs font-bold">•</span>
                  <span className="text-xs font-bold">{sale.timestamp.toLocaleDateString()}</span>
                </div>
              </div>

              {/* Items Detail */}
              <div className="p-6 flex-1 space-y-4">
                <div className="space-y-3">
                  {sale.items.map((item, idx) => {
                    const menuItem = menu.find(m => m.id === item.menuItemId);
                    return (
                      <div key={idx} className="flex justify-between items-center text-sm">
                        <div className="flex items-center gap-3">
                          <span className="w-6 h-6 bg-slate-100 rounded-md flex items-center justify-center font-black text-[10px] text-slate-500">{item.quantity}</span>
                          <span className="font-bold text-slate-700">{menuItem?.name || 'Producto'}</span>
                        </div>
                        <span className="font-bold text-slate-400">L. {(item.priceAtSale * item.quantity).toFixed(2)}</span>
                      </div>
                    );
                  })}
                </div>

                <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                  <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total Cobrado</span>
                  <span className="text-xl font-black text-slate-900">L. {sale.total.toFixed(2)}</span>
                </div>
              </div>

              {/* Status Actions */}
              <div className="p-6 bg-slate-50 border-t border-slate-100">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 text-center">CAMBIAR ESTATUS A:</p>
                <div className="flex flex-wrap gap-2 justify-center">
                  {statuses.map(s => (
                    <button
                      key={s}
                      onClick={() => onUpdateStatus(sale.id, s)}
                      disabled={sale.status === s}
                      className={`px-3 py-2 rounded-xl text-[9px] font-black uppercase tracking-tighter transition-all border ${
                        sale.status === s 
                        ? 'bg-slate-200 text-slate-400 border-slate-200 scale-95 opacity-50 cursor-default' 
                        : 'bg-white text-slate-600 border-slate-200 hover:border-orange-500 hover:text-orange-600 hover:shadow-md'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          );
        })}

        {filteredSales.length === 0 && (
          <div className="col-span-full py-20 text-center bg-white rounded-[3rem] border border-dashed border-slate-200">
            <div className="text-6xl mb-6 opacity-20">📋</div>
            <h3 className="text-xl font-black text-slate-400 uppercase tracking-widest">No hay órdenes en este estado</h3>
            <button onClick={() => setFilter('Todos')} className="mt-4 text-orange-600 font-bold hover:underline">Ver todos los pedidos</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default OrdersManager;

import React, { useState } from 'react';
import { MenuItem } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[], customerInfo?: { name: string, phone: string }) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  // Estado para el carrito de pedido rápido
  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  // Estado para información del cliente en pedido rápido
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // Filtrar menú para mostrar solo items activos
  const activeMenu = menu.filter(m => m.isActive !== false);
  const categories = Array.from(new Set(activeMenu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    if (newCart[id] > 1) {
      newCart[id] -= 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
    setCustomerName('');
    setCustomerPhone('');
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity
      }));

      const customerInfo = customerName.trim() || customerPhone.trim() 
        ? { name: customerName, phone: customerPhone } 
        : undefined;

      onQuickOrder(items, customerInfo);
      clearQuickCart();
    }
  };

  // Fixed type issue in reduce: Operator '+' cannot be applied to types 'unknown' and 'unknown'
  const quickCartCount = Object.values(quickCart).reduce((a: number, b: number) => a + b, 0);
  // Fixed type issue in reduce and arithmetic operation
  const quickCartTotal = Object.entries(quickCart).reduce((sum: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return sum + (item ? item.price * quantity : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-32">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-950/70 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-lg w-full max-w-lg p-8 shadow-2xl animate-scaleIn overflow-y-auto max-h-[90vh] custom-scrollbar border border-slate-200">
            <h3 className="text-xl font-black text-slate-900 mb-6 flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> Confirmar Venta Rápida
            </h3>

            {/* Información del Cliente */}
            <div className="bg-slate-50 p-6 rounded-md mb-6 space-y-4 border border-slate-100">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2 mb-2">
                👤 DATOS DEL CLIENTE
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1 ml-1">Nombre Completo</label>
                  <input 
                    type="text" 
                    placeholder="Ej: Juan Pérez"
                    className="w-full bg-white border border-slate-200 focus:border-orange-500 rounded-md px-4 py-2.5 text-sm font-bold outline-none transition-all"
                    value={customerName}
                    onChange={e => setCustomerName(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1 ml-1">Teléfono</label>
                  <input 
                    type="tel" 
                    placeholder="Ej: 9988-7766"
                    className="w-full bg-white border border-slate-200 focus:border-orange-500 rounded-md px-4 py-2.5 text-sm font-bold outline-none transition-all"
                    value={customerPhone}
                    onChange={e => setCustomerPhone(e.target.value)}
                  />
                </div>
              </div>
            </div>

            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">🛒 DETALLE DEL PEDIDO</h4>
            <div className="space-y-1 mb-8 max-h-[30vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                const quantity = qty as number;
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                    <div>
                      <span className="font-bold text-slate-800 text-sm block">{item?.name}</span>
                      <span className="text-[10px] text-slate-400 font-black uppercase">{quantity}x L. {item?.price.toFixed(2)}</span>
                    </div>
                    {/* Fixed type issue in arithmetic operation */}
                    <span className="font-black text-slate-900 text-sm">L. {(item!.price * quantity).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-between items-center mb-8 border-t-2 border-slate-100 pt-6">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total a Cobrar</span>
              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button 
                onClick={() => setIsConfirming(false)} 
                className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-md font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={handleProcessQuickOrder} 
                className="flex-1 py-4 bg-slate-900 text-white rounded-md font-black text-[10px] uppercase tracking-[0.2em] hover:bg-orange-600 transition-all shadow-xl active:scale-95"
              >
                Confirmar Venta
              </button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group">
        {isEditing ? (
          <div className="bg-white p-6 rounded-md shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 mb-4 bg-slate-50 p-2 rounded-md outline-none focus:bg-white"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título del Menú"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 font-medium bg-slate-50 p-3 rounded-md outline-none focus:bg-white resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
              placeholder="Descripción del restaurante..."
            />
            <div className="flex justify-center gap-2 mt-6">
              <button 
                onClick={() => { setIsEditing(false); setTempTitle(header?.title || ''); setTempDescription(header?.description || ''); }}
                className="px-6 py-2 bg-slate-100 text-slate-400 rounded-md font-black text-xs uppercase"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSaveHeader}
                className="px-8 py-2 bg-orange-600 text-white rounded-md font-black text-xs uppercase shadow-lg"
              >
                Guardar
              </button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 mb-4">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 font-medium">{header?.description || 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
                className="absolute -top-4 -right-4 w-10 h-10 bg-white border border-slate-100 shadow-md rounded-full flex items-center justify-center text-slate-400 hover:text-orange-600 hover:scale-110 transition-all opacity-0 group-hover:opacity-100"
                title="Editar encabezado"
              >
                ⚙️
              </button>
            )}
          </div>
        )}
      </header>

      {categories.map(cat => (
        <section key={cat} className="space-y-6">
          <div className="flex items-center gap-4">
            <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">{cat}</h3>
            <div className="flex-1 h-px bg-slate-200"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {activeMenu.filter(item => item.category === cat).map(item => (
              <div key={item.id} className="bg-white rounded-md shadow-sm border border-slate-100 overflow-hidden hover:shadow-2xl hover:scale-[1.01] transition-all duration-300 group flex flex-col h-full relative">
                {item.image && (
                  <div className="w-full h-48 overflow-hidden relative">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950/70 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

                    <button 
                      onClick={() => addToQuickCart(item.id)}
                      className="absolute bottom-4 right-4 w-12 h-12 bg-orange-600 text-white rounded-md flex items-center justify-center text-2xl shadow-xl transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300 hover:bg-orange-500 active:scale-90"
                      title="Añadir"
                    >
                      +
                    </button>
                  </div>
                )}

                <div className="p-6 flex flex-col flex-1">
                  <div className="flex justify-between items-start mb-4">
                    <h4 className="text-lg font-black text-slate-900 leading-tight group-hover:text-orange-600 transition-colors">{item.name}</h4>
                  </div>
                  <p className="text-slate-500 text-xs leading-relaxed mb-6 flex-1">
                    {item.description}
                  </p>

                  <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                    <div>
                      <span className="text-[9px] font-black uppercase text-slate-400 tracking-widest block mb-1">PVP</span>
                      <span className="text-xl font-black text-slate-900">L. {item.price.toFixed(2)}</span>
                    </div>

                    {!item.image && (
                      <button 
                        onClick={() => addToQuickCart(item.id)}
                        className="bg-slate-900 text-white px-5 py-2 rounded-md font-black text-[10px] uppercase tracking-widest hover:bg-orange-600 transition-all"
                      >
                        Añadir +
                      </button>
                    )}
                  </div>
                </div>

                {/* Fixed type issue: (quickCart[item.id] || 0) > 0 to handle potential undefined */}
                {/* Added explicit type cast (as number) to fix: Operator '>' cannot be applied to types 'unknown' and 'number' */}
                {((quickCart[item.id] as number) || 0) > 0 && (
                  <div className="absolute top-3 left-3 bg-orange-600 text-white w-7 h-7 rounded-md flex items-center justify-center font-black text-[10px] shadow-lg animate-scaleIn border-2 border-white">
                    {quickCart[item.id]}
                  </div>
                )}
              </div>
            ))}
          </div>
        </section>
      ))}

      {/* Barra de Pedido Flotante - CENTRADA Y CUADRADA */}
      {quickCartCount > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-full max-w-2xl px-4 z-[110] animate-fadeIn">
          <div className="bg-slate-950/95 backdrop-blur-lg text-white p-4 sm:p-5 rounded-md shadow-[0_25px_50px_-12px_rgba(0,0,0,0.6)] flex flex-col sm:flex-row items-center justify-between gap-6 border border-slate-800 relative overflow-hidden">
            {/* Indicador lateral elegante */}
            <div className="absolute left-0 top-0 w-1.5 h-full bg-orange-600"></div>

            <div className="flex items-center gap-6 w-full sm:w-auto">
              <div className="relative shrink-0 ml-2">
                <span className="text-2xl">📋</span>
                <span className="absolute -top-2 -right-2 bg-orange-600 text-white text-[9px] font-black w-4.5 h-4.5 rounded-sm flex items-center justify-center border border-slate-950">
                  {quickCartCount}
                </span>
              </div>
              <div className="hidden sm:block shrink-0">
                <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.3em] mb-0.5">ORDEN EN CURSO</p>
                <p className="text-xl font-black text-orange-500 tracking-tight">L. {quickCartTotal.toFixed(2)}</p>
