import React, { useState } from 'react';
import { MenuItem } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[], customerInfo?: { name: string, phone: string }) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  // Estado para el carrito de pedido rápido
  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  // Estado para información del cliente en pedido rápido
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // Filtrar menú para mostrar solo items activos
  const activeMenu = menu.filter(m => m.isActive !== false);
  const categories = Array.from(new Set(activeMenu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    if (newCart[id] > 1) {
      newCart[id] -= 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
    setCustomerName('');
    setCustomerPhone('');
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity
      }));

      const customerInfo = customerName.trim() || customerPhone.trim() 
        ? { name: customerName, phone: customerPhone } 
        : undefined;

      onQuickOrder(items, customerInfo);
      clearQuickCart();
    }
  };

  // Fixed type issue in reduce: Operator '+' cannot be applied to types 'unknown' and 'unknown'
  const quickCartCount = Object.values(quickCart).reduce((a: number, b: number) => a + b, 0);
  // Fixed type issue in reduce and arithmetic operation
  const quickCartTotal = Object.entries(quickCart).reduce((sum: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return sum + (item ? item.price * quantity : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-32">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-950/70 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-lg w-full max-w-lg p-8 shadow-2xl animate-scaleIn overflow-y-auto max-h-[90vh] custom-scrollbar border border-slate-200">
            <h3 className="text-xl font-black text-slate-900 mb-6 flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> Confirmar Venta Rápida
            </h3>

            {/* Información del Cliente */}
            <div className="bg-slate-50 p-6 rounded-md mb-6 space-y-4 border border-slate-100">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2 mb-2">
                👤 DATOS DEL CLIENTE
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1 ml-1">Nombre Completo</label>
                  <input 
                    type="text" 
                    placeholder="Ej: Juan Pérez"
                    className="w-full bg-white border border-slate-200 focus:border-orange-500 rounded-md px-4 py-2.5 text-sm font-bold outline-none transition-all"
                    value={customerName}
                    onChange={e => setCustomerName(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1 ml-1">Teléfono</label>
                  <input 
                    type="tel" 
                    placeholder="Ej: 9988-7766"
                    className="w-full bg-white border border-slate-200 focus:border-orange-500 rounded-md px-4 py-2.5 text-sm font-bold outline-none transition-all"
                    value={customerPhone}
                    onChange={e => setCustomerPhone(e.target.value)}
                  />
                </div>
              </div>
            </div>

            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">🛒 DETALLE DEL PEDIDO</h4>
            <div className="space-y-1 mb-8 max-h-[30vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                const quantity = qty as number;
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                    <div>
                      <span className="font-bold text-slate-800 text-sm block">{item?.name}</span>
                      <span className="text-[10px] text-slate-400 font-black uppercase">{quantity}x L. {item?.price.toFixed(2)}</span>
                    </div>
                    {/* Fixed type issue in arithmetic operation */}
                    <span className="font-black text-slate-900 text-sm">L. {(item!.price * quantity).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-between items-center mb-8 border-t-2 border-slate-100 pt-6">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total a Cobrar</span>
              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button 
                onClick={() => setIsConfirming(false)} 
                className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-md font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={handleProcessQuickOrder} 
                className="flex-1 py-4 bg-slate-900 text-white rounded-md font-black text-[10px] uppercase tracking-[0.2em] hover:bg-orange-600 transition-all shadow-xl active:scale-95"
              >
                Confirmar Venta
              </button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group">
        {isEditing ? (
          <div className="bg-white p-6 rounded-md shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 mb-4 bg-slate-50 p-2 rounded-md outline-none focus:bg-white"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título del Menú"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 font-medium bg-slate-50 p-3 rounded-md outline-none focus:bg-white resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
              placeholder="Descripción del restaurante..."
            />
            <div className="flex justify-center gap-2 mt-6">
              <button 
                onClick={() => { setIsEditing(false); setTempTitle(header?.title || ''); setTempDescription(header?.description || ''); }}
                className="px-6 py-2 bg-slate-100 text-slate-400 rounded-md font-black text-xs uppercase"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSaveHeader}
                className="px-8 py-2 bg-orange-600 text-white rounded-md font-black text-xs uppercase shadow-lg"
              >
                Guardar
              </button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 mb-4">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 font-medium">{header?.description || 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
                className="absolute -top-4 -right-4 w-10 h-10 bg-white border border-slate-100 shadow-md rounded-full flex items-center justify-center text-slate-400 hover:text-orange-600 hover:scale-110 transition-all opacity-0 group-hover:opacity-100"
                title="Editar encabezado"
              >
                ⚙️
              </button>
            )}
          </div>
        )}
      </header>

      {categories.map(cat => (
        <section key={cat} className="space-y-6">
          <div className="flex items-center gap-4">
            <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">{cat}</h3>
            <div className="flex-1 h-px bg-slate-200"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {activeMenu.filter(item => item.category === cat).map(item => (
              <div key={item.id} className="bg-white rounded-md shadow-sm border border-slate-100 overflow-hidden hover:shadow-2xl hover:scale-[1.01] transition-all duration-300 group flex flex-col h-full relative">
                {item.image && (
                  <div className="w-full h-48 overflow-hidden relative">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950/70 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

                    <button 
                      onClick={() => addToQuickCart(item.id)}
                      className="absolute bottom-4 right-4 w-12 h-12 bg-orange-600 text-white rounded-md flex items-center justify-center text-2xl shadow-xl transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300 hover:bg-orange-500 active:scale-90"
                      title="Añadir"
                    >
                      +
                    </button>
                  </div>
                )}

                <div className="p-6 flex flex-col flex-1">
                  <div className="flex justify-between items-start mb-4">
                    <h4 className="text-lg font-black text-slate-900 leading-tight group-hover:text-orange-600 transition-colors">{item.name}</h4>
                  </div>
                  <p className="text-slate-500 text-xs leading-relaxed mb-6 flex-1">
                    {item.description}
                  </p>

                  <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                    <div>
                      <span className="text-[9px] font-black uppercase text-slate-400 tracking-widest block mb-1">PVP</span>
                      <span className="text-xl font-black text-slate-900">L. {item.price.toFixed(2)}</span>
                    </div>

                    {!item.image && (
                      <button 
                        onClick={() => addToQuickCart(item.id)}
                        className="bg-slate-900 text-white px-5 py-2 rounded-md font-black text-[10px] uppercase tracking-widest hover:bg-orange-600 transition-all"
                      >
                        Añadir +
                      </button>
                    )}
                  </div>
                </div>

                {/* Fixed type issue: use Number() to ensure numeric comparison and handle potential 'unknown' or 'undefined' types safely */}
                {(Number(quickCart[item.id]) || 0) > 0 && (
                  <div className="absolute top-3 left-3 bg-orange-600 text-white w-7 h-7 rounded-md flex items-center justify-center font-black text-[10px] shadow-lg animate-scaleIn border-2 border-white">
                    {quickCart[item.id]}
                  </div>
                )}
              </div>
            ))}
          </div>
        </section>
      ))}

      {/* Barra de Pedido Flotante - CENTRADA Y CUADRADA */}
      {quickCartCount > 0 && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-full max-w-2xl px-4 z-[110] animate-fadeIn">
          <div className="bg-slate-950/95 backdrop-blur-lg text-white p-4 sm:p-5 rounded-md shadow-[0_25px_50px_-12px_rgba(0,0,0,0.6)] flex flex-col sm:flex-row items-center justify-between gap-6 border border-slate-800 relative overflow-hidden">
            {/* Indicador lateral elegante */}
            <div className="absolute left-0 top-0 w-1.5 h-full bg-orange-600"></div>

            <div className="flex items-center gap-6 w-full sm:w-auto">
              <div className="relative shrink-0 ml-2">
                <span className="text-2xl">📋</span>
                <span className="absolute -top-2 -right-2 bg-orange-600 text-white text-[9px] font-black w-4.5 h-4.5 rounded-sm flex items-center justify-center border border-slate-950">
                  {quickCartCount}
                </span>
              </div>
              <div className="hidden sm:block shrink-0">
                <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.3em] mb-0.5">ORDEN EN CURSO</p>
                <p className="text-xl font-black text-orange-500 tracking-tight">L. {quickCartTotal.toFixed(2)}</p>
              </div>

              {/* Items seleccionados - Dock central scrollable */}
              <div className="flex-1 sm:flex-none flex gap-2 overflow-x-auto custom-scrollbar pb-1 sm:pb-0 px-2">
                 {Object.entries(quickCart).map(([id, qty]) => {
                   const item = menu.find(m => m.id === id);
                   const quantity = qty as number;
                   return (
                     <div key={id} className="bg-slate-900 border border-slate-800 px-3 py-1.5 rounded-sm flex items-center gap-3 shrink-0 hover:bg-slate-800 transition-colors group/item">
                        <span className="text-[10px] font-bold text-slate-300 truncate max-w-[80px]">{item?.name}</span>
                        <div className="flex items-center gap-1.5 bg-slate-950 px-1.5 py-0.5 rounded-sm border border-slate-800">
                          <button onClick={() => removeFromQuickCart(id)} className="text-red-500 hover:text-red-400 font-black text-xs px-1">-</button>
                          <span className="text-[10px] font-black text-white min-w-[12px] text-center">{quantity}</span>
                          <button onClick={() => addToQuickCart(id)} className="text-green-500 hover:text-green-400 font-black text-xs px-1">+</button>
                        </div>
                     </div>
                   );
                 })}
              </div>
            </div>

            <div className="flex gap-3 w-full sm:w-auto">
               <button 
                onClick={clearQuickCart}
                className="flex-1 sm:flex-none px-6 py-3.5 bg-slate-900 border border-slate-800 text-slate-500 hover:text-slate-300 hover:border-slate-700 rounded-md font-black text-[9px] uppercase tracking-widest transition-all"
               >
                 VACIAR
               </button>
               <button 
                onClick={() => setIsConfirming(true)}
                className="flex-1 sm:flex-none px-8 py-3.5 bg-orange-600 text-white rounded-md font-black text-[9px] uppercase tracking-[0.25em] hover:bg-orange-500 shadow-xl shadow-orange-950/20 transition-all active:scale-[0.96]"
               >
                 COBRAR L. {quickCartTotal.toFixed(2)}
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

