import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import OrdersManager from './components/OrdersManager';
import { View, Ingredient, MenuItem, Sale, Customer, SaleStatus } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [menuHeader, setMenuHeader] = useState<{title: string, description: string}>(() => {
    const saved = localStorage.getItem('menuHeader');
    return saved ? JSON.parse(saved) : {
      title: 'Nuestra Carta',
      description: 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'
    };
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ 
      ...s, 
      timestamp: new Date(s.timestamp),
      status: s.status || 'Recibido'
    }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('menuHeader', JSON.stringify(menuHeader)); }, [menuHeader]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const addCategory = (category: string) => {
    const cleanCat = category.trim();
    if (cleanCat && !categories.includes(cleanCat)) {
      setCategories([...categories, cleanCat]);
    }
  };

  const deleteCategory = (category: string) => {
    setCategories(categories.filter(c => c !== category));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: string,
    newDescription?: string,
    newImage?: string,
    newIsActive?: boolean
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description,
            image: newImage !== undefined ? newImage : item.image,
            isActive: newIsActive !== undefined ? newIsActive : item.isActive
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now(),
      isActive: true
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, item.stock + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (saleItems: any[], customerInfo?: { name: string, phone: string }) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItemId = si.menuItemId || si.id;
      const menuItem = menu.find(m => m.id === menuItemId);
      const price = menuItem ? menuItem.price : 0;
      total += price * (si.quantity || 1);

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * (si.quantity || 1)));
        });
      }

      return {
        menuItemId: menuItemId,
        quantity: si.quantity || 1,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    let assignedCustomerId: string | undefined = undefined;

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        assignedCustomerId = existing.id;
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCustId = 'c' + Date.now();
        assignedCustomerId = newCustId;
        const newCust: Customer = {
          id: newCustId,
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: assignedCustomerId,
      customerName: customerInfo?.name || 'Cliente de Mostrador',
      status: 'Recibido'
    };

    setSales(prev => [...prev, newSale]);
  };

  const updateSaleStatus = (saleId: string, newStatus: SaleStatus) => {
    setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: newStatus } : s));
  };

  const deleteSale = (saleId: string) => {
    const saleToDelete = sales.find(s => s.id === saleId);
    if (saleToDelete) {
      // Devolver stock
      saleToDelete.items.forEach(item => {
        const menuItem = menu.find(m => m.id === item.menuItemId);
        if (menuItem) {
          menuItem.recipe.forEach(ri => {
            updateStock(ri.ingredientId, (ri.amount * item.quantity));
          });
        }
      });
      setSales(prev => prev.filter(s => s.id !== saleId));
    }
  };

  const updateSale = (saleId: string, updatedData: Partial<Sale>) => {
    const oldSale = sales.find(s => s.id === saleId);

    // Si los items han cambiado, necesitamos reconciliar el stock
    if (oldSale && updatedData.items) {
      // 1. Devolver todo el stock de la orden anterior
      oldSale.items.forEach(item => {
        const menuItem = menu.find(m => m.id === item.menuItemId);
        if (menuItem) {
          menuItem.recipe.forEach(ri => {
            updateStock(ri.ingredientId, (ri.amount * item.quantity));
          });
        }
      });

      // 2. Descontar el stock de la nueva composición de la orden
      updatedData.items.forEach(item => {
        const menuItem = menu.find(m => m.id === item.menuItemId);
        if (menuItem) {
          menuItem.recipe.forEach(ri => {
            updateStock(ri.ingredientId, -(ri.amount * item.quantity));
          });
        }
      });
    }

    setSales(prev => prev.map(s => s.id === saleId ? { ...s, ...updatedData } : s));
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  const renderView = () => {
    if (view === 'online-order') {
      return <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />;
    }

    return (
      <div className="flex flex-col lg:flex-row bg-slate-50 min-h-screen text-slate-900 relative">
        <div className="lg:hidden bg-slate-50 text-slate-900 p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200">
          <h1 className="text-xl font-black flex items-center gap-2">
            <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
          </h1>
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 hover:bg-slate-200 rounded-lg transition-colors text-slate-600"
          >
            <span className="text-2xl">☰</span>
          </button>
        </div>

        <Sidebar 
          currentView={view} 
          onNavigate={handleNavigate} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <main className="flex-1 p-4 md:p-8 overflow-y-auto">
          <div className="max-w-6xl mx-auto">
            {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
            {view === 'inventory' && (
              <Inventory 
                ingredients={ingredients} 
                availableUnits={availableUnits}
                onAddUnit={addUnit}
                onDeleteUnit={deleteUnit}
                onUpdateStock={updateStock} 
                onUpdateIngredient={updateIngredient}
                onAddIngredient={addIngredient}
                onDeleteIngredient={deleteIngredient}
              />
            )}
            {view === 'menu' && (
              <Menu 
                menu={menu} 
                header={menuHeader} 
                onUpdateHeader={(h) => setMenuHeader(h)} 
                onQuickOrder={(items, customerInfo) => addSale(items, customerInfo)}
              />
            )}
            {view === 'prices' && (
              <PriceManager 
                menu={menu} 
                ingredients={ingredients} 
                categories={categories}
                onAddCategory={addCategory}
                onDeleteCategory={deleteCategory}
                onUpdatePrice={updatePrice} 
                onUpdateRecipe={updateMenuItemRecipe}
                onAddMenuItem={addMenuItem}
                onDeleteMenuItem={deleteMenuItem}
              />
            )}
            {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items) => addSale(items)} />}
            {view === 'orders' && (
              <OrdersManager 
                sales={sales} 
                menu={menu} 
                customers={customers} 
                onUpdateStatus={updateSaleStatus}
                onDeleteSale={deleteSale}
                onUpdateSale={updateSale}
              />
            )}
            {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
            {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
            {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
          </div>
        </main>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {renderView()}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-fadeIn {
          animation: fadeIn 0.4s ease-out forwards;
        }
        @keyframes scaleIn {
          from { opacity: 0; transform: scale(0.95); }
          to { opacity: 1; transform: scale(1); }
        }
        .animate-scaleIn {
          animation: scaleIn 0.2s ease-out forwards;
        }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: #f1f5f9; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Sale, MenuItem, Customer, SaleStatus } from '../types';

interface OrdersManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  customers: Customer[];
  onUpdateStatus: (saleId: string, status: SaleStatus) => void;
  onDeleteSale: (saleId: string) => void;
  onUpdateSale: (saleId: string, updatedData: Partial<Sale>) => void;
}

const OrdersManager: React.FC<OrdersManagerProps> = ({ 
  sales, 
  menu, 
  customers, 
  onUpdateStatus,
  onDeleteSale,
  onUpdateSale 
}) => {
  const [filter, setFilter] = useState<SaleStatus | 'Todos'>('Todos');
  const [editingSale, setEditingSale] = useState<Sale | null>(null);

  // Estado temporal para el modal de edición
  const [tempCustomerName, setTempCustomerName] = useState('');
  const [tempItems, setTempItems] = useState<Sale['items']>([]);
  const [productSearch, setProductSearch] = useState('');

  const statuses: SaleStatus[] = ['Recibido', 'Preparacion', 'Listo', 'Enviado', 'Entregado'];

  const getStatusColor = (status: SaleStatus) => {
    switch (status) {
      case 'Recibido': return 'bg-slate-100 text-slate-600 border-slate-200';
      case 'Preparacion': return 'bg-orange-50 text-orange-600 border-orange-200';
      case 'Listo': return 'bg-green-50 text-green-600 border-green-200';
      case 'Enviado': return 'bg-blue-50 text-blue-600 border-blue-200';
      case 'Entregado': return 'bg-slate-900 text-white border-slate-900';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const openEditor = (sale: Sale) => {
    setEditingSale(sale);
    setTempCustomerName(sale.customerName || '');
    setTempItems([...sale.items]);
    setProductSearch('');
  };

  const handleUpdateItemQuantity = (index: number, delta: number) => {
    const newItems = [...tempItems];
    newItems[index] = { 
      ...newItems[index], 
      quantity: Math.max(1, newItems[index].quantity + delta) 
    };
    setTempItems(newItems);
  };

  const handleRemoveItem = (index: number) => {
    if (tempItems.length > 1) {
      setTempItems(tempItems.filter((_, i) => i !== index));
    } else {
      alert("La orden debe tener al menos un producto.");
    }
  };

  const handleAddProduct = (item: MenuItem) => {
    const existingIdx = tempItems.findIndex(ti => ti.menuItemId === item.id);
    if (existingIdx >= 0) {
      handleUpdateItemQuantity(existingIdx, 1);
    } else {
      setTempItems([...tempItems, {
        menuItemId: item.id,
        quantity: 1,
        priceAtSale: item.price,
        customization: ''
      }]);
    }
    setProductSearch('');
  };

  const saveChanges = () => {
    if (editingSale) {
      const newTotal = tempItems.reduce((sum, item) => sum + (item.priceAtSale * item.quantity), 0);
      onUpdateSale(editingSale.id, {
        customerName: tempCustomerName,
        items: tempItems,
        total: newTotal
      });
      setEditingSale(null);
    }
  };

  const filteredSales = sales
    .filter(s => filter === 'Todos' || s.status === filter)
    .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

  const searchResults = useMemo(() => {
    if (!productSearch.trim()) return [];
    return menu.filter(m => 
      m.isActive !== false && 
      m.name.toLowerCase().includes(productSearch.toLowerCase())
    ).slice(0, 5);
  }, [productSearch, menu]);

  return (
    <div className="space-y-8 animate-fadeIn pb-20">
      {/* Modal Editor de Pedido */}
      {editingSale && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-slate-900/70 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-[3rem] w-full max-w-2xl p-8 lg:p-10 shadow-2xl animate-scaleIn overflow-hidden flex flex-col max-h-[90vh]">
            <header className="flex justify-between items-center mb-6 shrink-0">
              <div>
                <h3 className="text-2xl font-black text-slate-900">Modificar Pedido</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">ID: #{editingSale.id.slice(-6)}</p>
              </div>
              <button onClick={() => setEditingSale(null)} className="w-12 h-12 bg-slate-50 text-slate-400 hover:text-slate-900 rounded-full flex items-center justify-center transition-all">✕</button>
            </header>

            <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 space-y-8 pb-4">
              {/* Info Cliente */}
              <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1 tracking-widest">Nombre del Cliente</label>
                <input 
                  type="text" 
                  className="w-full p-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-black outline-none focus:border-orange-500 transition-all"
                  value={tempCustomerName}
                  onChange={e => setTempCustomerName(e.target.value)}
                />
              </div>

              {/* Agregar Productos */}
              <div className="relative">
                <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1 tracking-widest">Añadir Producto</label>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">🔍</span>
                  <input 
                    type="text" 
                    placeholder="Buscar plato para añadir..."
                    className="w-full p-4 pl-12 bg-white border-2 border-slate-100 rounded-2xl font-bold outline-none focus:border-orange-500 transition-all"
                    value={productSearch}
                    onChange={e => setProductSearch(e.target.value)}
                  />
                  {searchResults.length > 0 && (
                    <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden z-20">
                      {searchResults.map(item => (
                        <button 
                          key={item.id}
                          onClick={() => handleAddProduct(item)}
                          className="w-full p-4 text-left hover:bg-orange-50 flex justify-between items-center transition-colors group"
                        >
                          <div>
                            <p className="font-black text-slate-900 text-sm group-hover:text-orange-600">{item.name}</p>
                            <p className="text-[10px] text-slate-400 font-bold uppercase">{item.category}</p>
                          </div>
                          <span className="font-black text-slate-900">L. {item.price.toFixed(2)}</span>
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Items Actuales */}
              <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 mb-4 ml-1 tracking-widest">Resumen de la Orden</label>
                <div className="space-y-3">
                  {tempItems.map((item, idx) => {
                    const menuItem = menu.find(m => m.id === item.menuItemId);
                    return (
                      <div key={idx} className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center justify-between group animate-fadeIn">
                        <div className="flex-1">
                          <p className="font-black text-slate-900 text-sm">{menuItem?.name || 'Producto'}</p>
                          <p className="text-[10px] font-bold text-slate-400 uppercase">L. {item.priceAtSale.toFixed(2)} c/u</p>
                        </div>
                        <div className="flex items-center gap-4">
                          <div className="flex items-center gap-2 bg-white p-1 rounded-xl border border-slate-200">
                            <button onClick={() => handleUpdateItemQuantity(idx, -1)} className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-red-500 font-black">-</button>
                            <span className="w-8 text-center font-black text-sm">{item.quantity}</span>
                            <button onClick={() => handleUpdateItemQuantity(idx, 1)} className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-green-500 font-black">+</button>
                          </div>
                          <button onClick={() => handleRemoveItem(idx)} className="text-red-300 hover:text-red-500 p-2 transition-colors">🗑️</button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>

            <footer className="mt-6 pt-6 border-t border-slate-100 shrink-0">
              <div className="flex justify-between items-center mb-6">
                <div>
                  <span className="text-xs font-black text-slate-400 uppercase tracking-widest block">Total de Venta</span>
                  <span className="text-3xl font-black text-slate-900">
                    L. {tempItems.reduce((s, i) => s + (i.priceAtSale * i.quantity), 0).toFixed(2)}
                  </span>
                </div>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setEditingSale(null)} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all">Descartar</button>
                <button onClick={saveChanges} className="flex-1 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] hover:bg-orange-600 transition-all shadow-xl shadow-slate-200">Guardar Cambios</button>
              </div>
            </footer>
          </div>
        </div>
      )}

      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Gestión de Órdenes</h2>
          <p className="text-slate-500 font-medium">Flujo de trabajo desde recepción hasta entrega final.</p>
        </div>

        <div className="flex bg-white p-1.5 rounded-2xl shadow-sm border border-slate-200 overflow-x-auto max-w-full custom-scrollbar">
          <button 
            onClick={() => setFilter('Todos')}
            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === 'Todos' ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-900'}`}
          >
            Todos
          </button>
          {statuses.map(s => (
            <button 
              key={s}
              onClick={() => setFilter(s)}
              className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === s ? 'bg-orange-600 text-white' : 'text-slate-400 hover:text-slate-900'}`}
            >
              {s}
            </button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredSales.map(sale => {
          const customerDb = customers.find(c => c.id === sale.customerId);
          const displayName = customerDb?.name || sale.customerName || 'Venta de Mostrador';

          return (
            <div key={sale.id} className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col overflow-hidden hover:shadow-xl hover:scale-[1.01] transition-all group">
              {/* Card Header */}
              <div className="p-6 border-b border-slate-50">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block">Órden #{sale.id.slice(-6)}</span>
                    </div>
                    <h3 className="text-lg font-black text-slate-900 truncate max-w-[150px]">{displayName}</h3>
                  </div>
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => openEditor(sale)}
                      className="w-8 h-8 bg-slate-50 text-slate-400 hover:text-orange-600 hover:bg-orange-50 rounded-lg flex items-center justify-center transition-all opacity-0 group-hover:opacity-100"
                      title="Editar pedido"
                    >
                      ✏️
                    </button>
                    <button 
                      onClick={() => { if(window.confirm('¿Eliminar esta orden y devolver el stock?')) onDeleteSale(sale.id); }}
                      className="w-8 h-8 bg-slate-50 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg flex items-center justify-center transition-all opacity-0 group-hover:opacity-100"
                      title="Eliminar pedido"
                    >
                      🗑️
                    </button>
                    <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase border tracking-widest ${getStatusColor(sale.status)} ml-2`}>
                      {sale.status}
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2 text-slate-400">
                  <span className="text-xs font-bold">🕒 {sale.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  <span className="text-xs font-bold">•</span>
                  <span className="text-xs font-bold">{sale.timestamp.toLocaleDateString()}</span>
                </div>
              </div>

              {/* Items Detail */}
              <div className="p-6 flex-1 space-y-4">
                <div className="space-y-3">
                  {sale.items.map((item, idx) => {
                    const menuItem = menu.find(m => m.id === item.menuItemId);
                    return (
                      <div key={idx} className="flex justify-between items-center text-sm">
                        <div className="flex items-center gap-3">
                          <span className="w-6 h-6 bg-slate-100 rounded-md flex items-center justify-center font-black text-[10px] text-slate-500">{item.quantity}</span>
                          <span className="font-bold text-slate-700">{menuItem?.name || 'Producto'}</span>
                        </div>
                        <span className="font-bold text-slate-400">L. {(item.priceAtSale * item.quantity).toFixed(2)}</span>
                      </div>
                    );
                  })}
                </div>

                <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                  <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total Cobrado</span>
                  <span className="text-xl font-black text-slate-900">L. {sale.total.toFixed(2)}</span>
                </div>
              </div>

              {/* Status Actions */}
              <div className="p-6 bg-slate-50 border-t border-slate-100">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 text-center">CAMBIAR ESTATUS A:</p>
                <div className="flex flex-wrap gap-2 justify-center">
                  {statuses.map(s => (
                    <button
                      key={s}
                      onClick={() => onUpdateStatus(sale.id, s)}
                      disabled={sale.status === s}
                      className={`px-3 py-2 rounded-xl text-[9px] font-black uppercase tracking-tighter transition-all border ${
                        sale.status === s 
                        ? 'bg-slate-200 text-slate-400 border-slate-200 scale-95 opacity-50 cursor-default' 
                        : 'bg-white text-slate-600 border-slate-200 hover:border-orange-500 hover:text-orange-600 hover:shadow-md'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          );
        })}

        {filteredSales.length === 0 && (
          <div className="col-span-full py-20 text-center bg-white rounded-[3rem] border border-dashed border-slate-200">
            <div className="text-6xl mb-6 opacity-20">📋</div>
            <h3 className="text-xl font-black text-slate-400 uppercase tracking-widest">No hay órdenes en este estado</h3>
            <button onClick={() => setFilter('Todos')} className="mt-4 text-orange-600 font-bold hover:underline">Ver todos los pedidos</button>
          </div>
        )}
      </div>
    </div>
  );
};

