import React, { useState } from 'react';
import { MenuItem } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[], customerInfo?: { name: string, phone: string }) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  // Estado para el carrito de pedido rápido
  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  // Estado para información del cliente en pedido rápido
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // Filtrar menú para mostrar solo items activos
  const activeMenu = menu.filter(m => m.isActive !== false);
  const categories = Array.from(new Set(activeMenu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    // Use nullish coalescing and explicit cast to number for safe comparison
    if (((newCart[id] ?? 0) as number) > 1) {
      newCart[id] -= 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
    setCustomerName('');
    setCustomerPhone('');
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity: quantity as number
      }));

      const customerInfo = customerName.trim() || customerPhone.trim() 
        ? { name: customerName, phone: customerPhone } 
        : undefined;

      onQuickOrder(items, customerInfo);
      clearQuickCart();
    }
  };

  // Fixed type issue in reduce: ensure value is treated as number
  const quickCartCount = Object.values(quickCart).reduce((a: number, b: number) => a + (b as number), 0);
  // Fixed type issue in reduce: ensure value is treated as number
  const quickCartTotal = Object.entries(quickCart).reduce((sum: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return sum + (item ? item.price * quantity : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-32">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-950/70 backdrop-blur-md animate-fadeIn">
          <div className="bg-white rounded-lg w-full max-w-lg p-8 shadow-2xl animate-scaleIn overflow-y-auto max-h-[90vh] custom-scrollbar border border-slate-200">
            <h3 className="text-xl font-black text-slate-900 mb-6 flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> Confirmar Venta Rápida
            </h3>

            {/* Información del Cliente */}
            <div className="bg-slate-50 p-6 rounded-md mb-6 space-y-4 border border-slate-100">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2 mb-2">
                👤 DATOS DEL CLIENTE
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1 ml-1">Nombre Completo</label>
                  <input 
                    type="text" 
                    placeholder="Ej: Juan Pérez"
                    className="w-full bg-white border border-slate-200 focus:border-orange-500 rounded-md px-4 py-2.5 text-sm font-bold outline-none transition-all"
                    value={customerName}
                    onChange={e => setCustomerName(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 uppercase mb-1 ml-1">Teléfono</label>
                  <input 
                    type="tel" 
                    placeholder="Ej: 9988-7766"
                    className="w-full bg-white border border-slate-200 focus:border-orange-500 rounded-md px-4 py-2.5 text-sm font-bold outline-none transition-all"
                    value={customerPhone}
                    onChange={e => setCustomerPhone(e.target.value)}
                  />
                </div>
              </div>
            </div>

            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">🛒 DETALLE DEL PEDIDO</h4>
            <div className="space-y-1 mb-8 max-h-[30vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                const quantity = qty as number;
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                    <div>
                      <span className="font-bold text-slate-800 text-sm block">{item?.name}</span>
                      <span className="text-[10px] text-slate-400 font-black uppercase">{quantity}x L. {item?.price.toFixed(2)}</span>
                    </div>
                    {/* Explicit cast to number for calculation */}
                    <span className="font-black text-slate-900 text-sm">L. {(item!.price * quantity).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-between items-center mb-8 border-t-2 border-slate-100 pt-6">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total a Cobrar</span>
              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button 
                onClick={() => setIsConfirming(false)} 
                className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-md font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={handleProcessQuickOrder} 
                className="flex-1 py-4 bg-slate-900 text-white rounded-md font-black text-[10px] uppercase tracking-[0.2em] hover:bg-orange-600 transition-all shadow-xl active:scale-95"
              >
                Confirmar Venta
              </button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group">
        {isEditing ? (
          <div className="bg-white p-6 rounded-md shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 mb-4 bg-slate-50 p-2 rounded-md outline-none focus:bg-white"
              value={tempTitle}
