                    <button 
                      onClick={() => addToQuickCart(item.id)}
                      className="absolute bottom-4 right-4 w-12 h-12 bg-orange-600 text-white rounded-md flex items-center justify-center text-2xl shadow-xl transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300 hover:bg-orange-500 active:scale-90"
                      title="Añadir"
                    >
                      +
                    </button>
                  </div>
                )}

                <div className="p-6 flex flex-col flex-1">
                  <div className="flex justify-between items-start mb-4">
                    <h4 className="text-lg font-black text-slate-900 leading-tight group-hover:text-orange-600 transition-colors">{item.name}</h4>
                  </div>
                  <p className="text-slate-500 text-xs leading-relaxed mb-6 flex-1">
                    {item.description}
