interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[], customerInfo?: { name: string, phone: string }) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  // Estado para el carrito de pedido rápido
  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  // Estado para información del cliente en pedido rápido
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  // Filtrar menú para mostrar solo items activos
  const activeMenu = menu.filter(m => m.isActive !== false);
  const categories = Array.from(new Set(activeMenu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    if (Number(newCart[id] || 0) > 1) {
      newCart[id] -= 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
    setCustomerName('');
    setCustomerPhone('');
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity: quantity as number
      }));

      const customerInfo = customerName.trim() || customerPhone.trim() 
        ? { name: customerName, phone: customerPhone } 
        : undefined;

      onQuickOrder(items, customerInfo);
      clearQuickCart();
    }
  };

  const quickCartCount = Object.values(quickCart).reduce((a: number, b: number) => a + (b as number), 0);
  const quickCartTotal = Object.entries(quickCart).reduce((sum: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return sum + (item ? item.price * quantity : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-40">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-950/70 backdrop-blur-md animate-fadeIn">
          <div className="bg-white dark:bg-slate-900 rounded-[3rem] w-full max-w-lg p-8 shadow-2xl animate-scaleIn overflow-y-auto max-h-[90vh] custom-scrollbar border border-slate-200 dark:border-slate-800">
            <h3 className="text-xl font-black text-slate-900 dark:text-white mb-6 flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> Confirmar Venta Rápida
            </h3>

            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] mb-6 space-y-4 border border-slate-100 dark:border-slate-700">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2 mb-2">
                👤 DATOS DEL CLIENTE
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase mb-1 ml-1">Nombre</label>
                  <input 
                    type="text" 
                    placeholder="Ej: Juan Pérez"
                    className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none transition-all dark:text-white"
                    value={customerName}
                    onChange={e => setCustomerName(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase mb-1 ml-1">Teléfono</label>
                  <input 
                    type="tel" 
                    placeholder="9988-7766"
                    className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none transition-all dark:text-white"
                    value={customerPhone}
                    onChange={e => setCustomerPhone(e.target.value)}
                  />
                </div>
              </div>
            </div>

            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">🛒 DETALLE DEL PEDIDO</h4>
            <div className="space-y-1 mb-8 max-h-[30vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                const quantity = qty as number;
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 dark:border-slate-800 last:border-0">
                    <div>
                      <span className="font-bold text-slate-800 dark:text-slate-200 text-sm block">{item?.name}</span>
                      <span className="text-[10px] text-slate-400 font-black uppercase">{quantity}x L. {item?.price.toFixed(2)}</span>
                    </div>
                    <span className="font-black text-slate-900 dark:text-white text-sm">L. {(item!.price * quantity).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-between items-center mb-8 border-t-2 border-slate-100 dark:border-slate-800 pt-6">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total a Cobrar</span>
              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button 
                onClick={() => setIsConfirming(false)} 
                className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-200 dark:hover:bg-slate-700 transition-all"
              >
                Cancelar
              </button>
              <button 
                onClick={handleProcessQuickOrder} 
                className="flex-1 py-4 bg-slate-900 dark:bg-orange-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] hover:bg-orange-600 dark:hover:bg-orange-500 transition-all shadow-xl active:scale-95"
              >
                Confirmar Venta
              </button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group px-4">
        {isEditing ? (
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 dark:text-white mb-4 bg-slate-50 dark:bg-slate-800 p-3 rounded-2xl outline-none focus:bg-white dark:focus:bg-slate-700"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título del Menú"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 dark:text-slate-400 font-medium bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl outline-none focus:bg-white dark:focus:bg-slate-700 resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
              placeholder="Descripción del restaurante..."
            />
            <div className="flex justify-center gap-2 mt-6">
              <button 
                onClick={() => { setIsEditing(false); setTempTitle(header?.title || ''); setTempDescription(header?.description || ''); }}
                className="px-6 py-2 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-xl font-black text-xs uppercase"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSaveHeader}
                className="px-8 py-2 bg-orange-600 text-white rounded-xl font-black text-xs uppercase shadow-lg"
              >
                Guardar
              </button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-4">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 dark:text-slate-400 font-medium">{header?.description || 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
                className="absolute -top-4 -right-4 w-10 h-10 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 shadow-md rounded-full flex items-center justify-center text-slate-400 hover:text-orange-600 hover:scale-110 transition-all opacity-0 group-hover:opacity-100"
                title="Editar encabezado"
              >
                ⚙️
              </button>
            )}
          </div>
        )}
      </header>

      {categories.map(cat => (
        <section key={cat} className="space-y-6 px-4 lg:px-0">
          <div className="flex items-center gap-4">
            <h3 className="text-2xl font-black text-slate-800 dark:text-slate-200 uppercase tracking-tighter">{cat}</h3>
            <div className="flex-1 h-px bg-slate-200 dark:bg-slate-800"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {activeMenu.filter(item => item.category === cat).map(item => (
              <div key={item.id} className="bg-white dark:bg-slate-900 rounded-[2rem] shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden hover:shadow-2xl hover:scale-[1.01] transition-all duration-300 group flex flex-col h-full relative">
                {item.image && (
                  <div className="w-full h-48 overflow-hidden relative">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950/70 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>

                    <button 
                      onClick={() => addToQuickCart(item.id)}
                      className="absolute bottom-4 right-4 w-12 h-12 bg-orange-600 text-white rounded-2xl flex items-center justify-center text-2xl shadow-xl transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300 hover:bg-orange-500 active:scale-90"
                      title="Añadir"
                    >
                      +
                    </button>
                  </div>
                )}

                <div className="p-6 flex flex-col flex-1">
                  <div className="flex justify-between items-start mb-4">
                    <h4 className="text-lg font-black text-slate-900 dark:text-white leading-tight group-hover:text-orange-600 transition-colors">{item.name}</h4>
                  </div>
                  <p className="text-slate-500 dark:text-slate-400 text-xs leading-relaxed mb-6 flex-1">
                    {item.description}
                  </p>

                  <div className="pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-between items-center">
                    <div>
                      <span className="text-[9px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest block mb-1">Precio</span>
                      <span className="text-xl font-black text-slate-900 dark:text-white">L. {item.price.toFixed(2)}</span>
                    </div>

                    {!item.image && (
                      <button 
                        onClick={() => addToQuickCart(item.id)}
                        className="bg-slate-900 dark:bg-orange-600 text-white px-5 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-orange-600 dark:hover:bg-orange-500 transition-all"
                      >
                        Añadir +
                      </button>
                    )}
                  </div>
                </div>

                {/* Fixed TypeScript error by ensuring comparison is between numbers */}
                {((quickCart[item.id] as number) || 0) > 0 && (
                  <div className="absolute top-3 left-3 bg-orange-600 text-white w-7 h-7 rounded-lg flex items-center justify-center font-black text-[10px] shadow-lg animate-scaleIn border-2 border-white dark:border-slate-900">
                    {quickCart[item.id]}
                  </div>
                )}
              </div>
            ))}
          </div>
        </section>
      ))}

      {/* BARRA DE PEDIDO REDISEÑADA - DOCK PREMIUM */}
      {quickCartCount > 0 && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[95%] max-w-4xl z-[110] animate-fadeIn">
          <div className="bg-slate-900/95 dark:bg-slate-800/95 backdrop-blur-xl text-white p-3 sm:p-4 rounded-[2.5rem] shadow-[0_25px_60px_-15px_rgba(0,0,0,0.6)] flex flex-col sm:flex-row items-center justify-between gap-4 border border-slate-800 dark:border-slate-700 relative">

            {/* Info y Detalle de Items */}
            <div className="flex items-center gap-4 w-full sm:w-auto flex-1 px-2">
              <div className="relative shrink-0 flex items-center justify-center w-12 h-12 bg-orange-600 rounded-full shadow-lg shadow-orange-950/20">
                <span className="text-xl">📋</span>
                <span className="absolute -top-1 -right-1 bg-white text-orange-600 text-[10px] font-black w-5 h-5 rounded-full flex items-center justify-center shadow-md">
                  {quickCartCount}
                </span>
              </div>

              <div className="flex-1 overflow-x-auto custom-scrollbar flex gap-2 no-scrollbar py-1">
                 {Object.entries(quickCart).map(([id, qty]) => {
                   const item = menu.find(m => m.id === id);
                   const quantity = qty as number;
                   return (
                     <div key={id} className="bg-slate-800 dark:bg-slate-700 px-3 py-1.5 rounded-full flex items-center gap-2 shrink-0 border border-slate-700 dark:border-slate-600 hover:bg-slate-700 transition-colors">
                        <span className="text-[10px] font-bold text-slate-100 truncate max-w-[70px]">{item?.name}</span>
                        <div className="flex items-center gap-1.5 bg-slate-950/40 px-1.5 py-0.5 rounded-full">
                          <button onClick={() => removeFromQuickCart(id)} className="text-red-400 hover:text-red-300 font-black text-[11px] w-4 h-4 flex items-center justify-center">-</button>
                          <span className="text-[10px] font-black text-white min-w-[12px] text-center">{quantity}</span>
                          <button onClick={() => addToQuickCart(id)} className="text-green-400 hover:text-green-300 font-black text-[11px] w-4 h-4 flex items-center justify-center">+</button>
                        </div>
                     </div>
                   );
                 })}
              </div>
            </div>

            {/* Acciones de Cobro */}
            <div className="flex items-center gap-3 w-full sm:w-auto shrink-0 border-t sm:border-t-0 sm:border-l border-slate-800 dark:border-slate-700 pt-3 sm:pt-0 sm:pl-4">
               <div className="hidden md:block mr-2 text-right">
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">SUBTOTAL</p>
                  <p className="text-lg font-black text-orange-500 tracking-tight">L. {quickCartTotal.toFixed(2)}</p>
               </div>

               <button 
                onClick={clearQuickCart}
                className="flex-1 sm:flex-none px-5 py-3.5 bg-slate-800/50 hover:bg-red-950/40 text-slate-400 hover:text-red-400 rounded-full font-black text-[9px] uppercase tracking-widest transition-all border border-slate-700 hover:border-red-900/50"
               >
                 VACIAR
               </button>

               <button 
                onClick={() => setIsConfirming(true)}
                className="flex-[2] sm:flex-none px-8 py-3.5 bg-orange-600 text-white rounded-full font-black text-[11px] uppercase tracking-[0.2em] hover:bg-orange-500 shadow-xl shadow-orange-950/40 transition-all active:scale-[0.96] flex items-center justify-center gap-3 relative overflow-hidden group"
               >
                 <span className="relative z-10">COBRAR L. {quickCartTotal.toFixed(2)}</span>
                 <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
                 <span className="text-base animate-pulse">➔</span>
               </button>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

export default Menu;

import React, { useState } from 'react';
import { MenuItem } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[], customerInfo?: { name: string, phone: string }) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  const activeMenu = menu.filter(m => m.isActive !== false);
  const categories = Array.from(new Set(activeMenu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    if (Number(newCart[id] || 0) > 1) {
      newCart[id] -= 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
    setCustomerName('');
    setCustomerPhone('');
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity: quantity as number
      }));

      const customerInfo = customerName.trim() || customerPhone.trim() 
        ? { name: customerName, phone: customerPhone } 
        : undefined;

      onQuickOrder(items, customerInfo);
      clearQuickCart();
    }
  };

  const quickCartCount = Object.values(quickCart).reduce((a: number, b: number) => a + (b as number), 0);
  const quickCartTotal = Object.entries(quickCart).reduce((sum: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return sum + (item ? item.price * quantity : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-40 lg:pr-80 transition-all duration-500">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-fadeIn">
          <div className="bg-white dark:bg-slate-900 rounded-[3rem] w-full max-w-lg p-8 shadow-2xl animate-scaleIn border border-slate-200 dark:border-slate-800">
            <h3 className="text-xl font-black text-slate-900 dark:text-white mb-6 flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> Finalizar Venta
            </h3>

            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] mb-6 space-y-4 border border-slate-100 dark:border-slate-700">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">IDENTIFICACIÓN</h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <input 
                  type="text" 
                  placeholder="Nombre Cliente"
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none dark:text-white"
                  value={customerName}
                  onChange={e => setCustomerName(e.target.value)}
                />
                <input 
                  type="tel" 
                  placeholder="Teléfono"
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none dark:text-white"
                  value={customerPhone}
                  onChange={e => setCustomerPhone(e.target.value)}
                />
              </div>
            </div>

            <div className="space-y-1 mb-8 max-h-[30vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 dark:border-slate-800 last:border-0 text-sm font-bold">
                    <span className="text-slate-600 dark:text-slate-400">{qty}x {item?.name}</span>
                    <span className="text-slate-900 dark:text-white">L. {(item!.price * (qty as number)).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-between items-center mb-8 border-t-2 border-slate-100 dark:border-slate-800 pt-6">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Monto Total</span>
              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button onClick={() => setIsConfirming(false)} className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-2xl font-black text-[10px] uppercase hover:bg-slate-200 dark:hover:bg-slate-700">Atrás</button>
              <button onClick={handleProcessQuickOrder} className="flex-1 py-4 bg-slate-900 dark:bg-orange-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-xl hover:bg-orange-500">Pagar Orden</button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group px-4">
        {isEditing ? (
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 dark:text-white mb-4 bg-slate-50 dark:bg-slate-800 p-3 rounded-2xl outline-none"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 dark:text-slate-400 font-medium bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl outline-none resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
            />
            <div className="flex justify-center gap-2 mt-6">
              <button onClick={() => setIsEditing(false)} className="px-6 py-2 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-xl font-black text-xs uppercase">Cancelar</button>
              <button onClick={handleSaveHeader} className="px-8 py-2 bg-orange-600 text-white rounded-xl font-black text-xs uppercase">Guardar</button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 dark:text-slate-400 font-medium">{header?.description}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
