              <span className="text-orange-500 text-2xl">🔥</span> Finalizar Venta
            </h3>

            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] mb-6 space-y-4 border border-slate-100 dark:border-slate-700">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">IDENTIFICACIÓN DEL CLIENTE</h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <input 
                  type="text" 
                  placeholder="Nombre Cliente"
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none dark:text-white"
                  value={customerName}
                  onChange={e => setCustomerName(e.target.value)}
                />
                <input 
                  type="tel" 
                  placeholder="Teléfono"
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none dark:text-white"
                  value={customerPhone}
                  onChange={e => setCustomerPhone(e.target.value)}
                />
              </div>
            </div>

            <div className="space-y-1 mb-8 max-h-[30vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 dark:border-slate-800 last:border-0 text-sm font-bold">
                    <span className="text-slate-600 dark:text-slate-400">{qty}x {item?.name}</span>
