              <div className="mt-4 flex items-center justify-between text-[8px] font-bold text-slate-500 uppercase tracking-widest">
                <span>Terminal: 001</span>
                <span>{new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
              </div>
