          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 p-6 md:p-8 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col min-w-0">
          <h3 className="font-black text-slate-800 dark:text-white mb-6 uppercase text-xs tracking-widest flex items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-red-500"></span> Inventario Bajo
          </h3>
          <div className="space-y-3 flex-1 overflow-y-auto max-h-[300px] custom-scrollbar pr-2">
            {ingredients.filter(i => i.stock <= i.minStock).map(item => (
              <div key={item.id} className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-slate-100 dark:border-slate-700 gap-3 group hover:border-red-200 dark:hover:border-red-900/30 transition-all">
                <div>
                  <p className="font-black text-slate-900 dark:text-slate-100 text-sm">{item.name}</p>
                  <p className="text-[10px] font-bold text-slate-400 dark:text-slate-500 uppercase tracking-tight">Stock: {item.stock} {item.unit} (Mín: {item.minStock})</p>
                </div>
                <div className="h-2 w-2 rounded-full bg-red-500 animate-pulse"></div>
              </div>
            ))}
            {lowStockCount === 0 && (
              <div className="text-center py-12">
                <div className="text-4xl mb-3 opacity-20">✅</div>
                <p className="font-black text-slate-300 dark:text-slate-600 uppercase text-[10px] tracking-[0.2em]">Todo el Stock al día</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Sale, Ingredient, MenuItem } from '../types';

interface ReportsProps {
  sales: Sale[];
  ingredients: Ingredient[];
  menu: MenuItem[];
}

const Reports: React.FC<ReportsProps> = ({ sales, ingredients, menu }) => {
  const [period, setPeriod] = useState<'daily' | 'weekly' | 'monthly'>('daily');

  // Logic for daily sales trend
  const salesTrend = sales.slice(-10).map(s => ({
    date: new Date(s.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    total: s.total
  }));

  // Categories breakdown
  const catDataMap: Record<string, number> = {};
  sales.forEach(s => {
    s.items.forEach(i => {
      const item = menu.find(m => m.id === i.menuItemId);
      if (item) {
        catDataMap[item.category] = (catDataMap[item.category] || 0) + (i.priceAtSale * i.quantity);
      }
    });
  });
  const catData = Object.entries(catDataMap).map(([name, value]) => ({ name, value }));
  const COLORS = ['#ea580c', '#1e293b', '#64748b', '#94a3b8'];

  const totalRevenue = sales.reduce((a, b) => a + b.total, 0);
  const totalCost = sales.reduce((acc, sale) => {
    return acc + sale.items.reduce((itemAcc, item) => {
      const menuItem = menu.find(m => m.id === item.menuItemId);
      const recipeCost = menuItem?.recipe.reduce((rAcc, r) => {
        const ing = ingredients.find(ing => ing.id === r.ingredientId);
        return rAcc + (ing?.costPerUnit || 0) * r.amount;
      }, 0) || 0;
      return itemAcc + (recipeCost * item.quantity);
    }, 0);
  }, 0);

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Reportes de Rendimiento</h2>
          <p className="text-slate-500 font-medium">Análisis profundo de la salud financiera de tu parrilla.</p>
        </div>
        <div className="flex bg-white p-1 rounded-xl shadow-sm border border-slate-100">
          {['daily', 'weekly', 'monthly'].map(p => (
            <button 
              key={p}
              onClick={() => setPeriod(p as any)}
              className={`px-4 py-2 rounded-lg text-xs font-bold uppercase transition-all ${period === p ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-900'}`}
            >
              {p === 'daily' ? 'Hoy' : p === 'weekly' ? 'Semana' : 'Mes'}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {[
          { label: 'Ventas Totales', value: totalRevenue, color: 'text-orange-600', bg: 'bg-orange-50' },
          { label: 'Costos de Insumos', value: totalCost, color: 'text-slate-600', bg: 'bg-slate-50' },
          { label: 'Utilidad Bruta', value: totalRevenue - totalCost, color: 'text-green-600', bg: 'bg-green-50' },
          { label: 'Margen Promedio', value: `${((totalRevenue - totalCost) / (totalRevenue || 1) * 100).toFixed(1)}%`, color: 'text-blue-600', bg: 'bg-blue-50' }
        ].map((card, idx) => (
          <div key={idx} className={`${card.bg} p-6 rounded-3xl border border-white shadow-sm`}>
            <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">{card.label}</p>
            <p className={`text-2xl font-black ${card.color}`}>
              {typeof card.value === 'number' ? `L. ${card.value.toLocaleString()}` : card.value}
            </p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] shadow-sm border border-slate-100 min-w-0">
          <h3 className="text-xl font-bold text-slate-900 mb-8 flex items-center gap-2">
            <span className="w-2 h-8 bg-orange-500 rounded-full"></span>
            Tendencia de Ventas (Tiempo Real)
          </h3>
          <div className="h-80 w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%" minHeight={100}>
              <AreaChart data={salesTrend}>
                <defs>
                  <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#ea580c" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#ea580c" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
                <Tooltip 
                  formatter={(value) => [`L. ${value.toLocaleString()}`, 'Venta']}
                  contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)'}}
                />
                <Area type="monotone" dataKey="total" stroke="#ea580c" strokeWidth={3} fillOpacity={1} fill="url(#colorTotal)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-100 min-w-0">
          <h3 className="text-xl font-bold text-slate-900 mb-8">Mix de Ventas</h3>
          <div className="h-64 w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%" minHeight={100}>
              <PieChart>
                <Pie
                  data={catData}
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {catData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip formatter={(value) => [`L. ${value.toLocaleString()}`, 'Total']} />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 space-y-2">
            {catData.map((cat, idx) => (
              <div key={idx} className="flex justify-between items-center text-sm">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full" style={{backgroundColor: COLORS[idx % COLORS.length]}}></div>
                  <span className="text-slate-600 font-medium">{cat.name}</span>
                </div>
                <span className="font-bold text-slate-900">L. {cat.value.toLocaleString()}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState } from 'react';
import { MenuItem } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[], customerInfo?: { name: string, phone: string }) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');

  const activeMenu = menu.filter(m => m.isActive !== false);
  const categories = Array.from(new Set(activeMenu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    const currentQty = Number(newCart[id] || 0);
    if (currentQty > 1) {
      newCart[id] = currentQty - 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
    setCustomerName('');
    setCustomerPhone('');
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity: quantity as number
      }));

      const customerInfo = customerName.trim() || customerPhone.trim() 
        ? { name: customerName, phone: customerPhone } 
        : undefined;

      onQuickOrder(items, customerInfo);
      clearQuickCart();
    }
  };

  const quickCartCount = Object.values(quickCart).reduce((a: number, b: number) => a + (b as number), 0);
  const quickCartTotal = Object.entries(quickCart).reduce((sum: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return sum + (item ? item.price * (qty as number) : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-40 lg:pr-80 transition-all duration-500">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-fadeIn">
          <div className="bg-white dark:bg-slate-900 rounded-[3rem] w-full max-w-lg p-8 shadow-2xl animate-scaleIn border border-slate-200 dark:border-slate-800">
            <h3 className="text-xl font-black text-slate-900 dark:text-white mb-6 flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> Finalizar Venta
            </h3>

            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] mb-6 space-y-4 border border-slate-100 dark:border-slate-700">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">IDENTIFICACIÓN DEL CLIENTE</h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <input 
                  type="text" 
                  placeholder="Nombre Cliente"
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none dark:text-white"
                  value={customerName}
                  onChange={e => setCustomerName(e.target.value)}
                />
                <input 
                  type="tel" 
                  placeholder="Teléfono"
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none dark:text-white"
                  value={customerPhone}
                  onChange={e => setCustomerPhone(e.target.value)}
                />
              </div>
            </div>

            <div className="space-y-1 mb-8 max-h-[30vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 dark:border-slate-800 last:border-0 text-sm font-bold">
                    <span className="text-slate-600 dark:text-slate-400">{qty}x {item?.name}</span>
                    <span className="text-slate-900 dark:text-white">L. {((item?.price || 0) * (qty as number)).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-between items-center mb-8 border-t-2 border-slate-100 dark:border-slate-800 pt-6">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Monto Total</span>
              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button onClick={() => setIsConfirming(false)} className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-2xl font-black text-[10px] uppercase hover:bg-slate-200 dark:hover:bg-slate-700">Atrás</button>
              <button onClick={handleProcessQuickOrder} className="flex-1 py-4 bg-slate-900 dark:bg-orange-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-xl hover:bg-orange-500">Pagar Orden</button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group px-4">
        {isEditing ? (
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 dark:text-white mb-4 bg-slate-50 dark:bg-slate-800 p-3 rounded-2xl outline-none"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 dark:text-slate-400 font-medium bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl outline-none resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
            />
            <div className="flex justify-center gap-2 mt-6">
              <button onClick={() => { setIsEditing(false); setTempTitle(header?.title || ''); setTempDescription(header?.description || ''); }} className="px-6 py-2 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-xl font-black text-xs uppercase">Cancelar</button>
              <button onClick={handleSaveHeader} className="px-8 py-2 bg-orange-600 text-white rounded-xl font-black text-xs uppercase">Guardar</button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 dark:text-slate-400 font-medium">{header?.description}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
                className="absolute -top-4 -right-4 w-10 h-10 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 shadow-md rounded-full flex items-center justify-center text-slate-400 hover:text-orange-600 opacity-0 group-hover:opacity-100 transition-all"
              >
                ⚙️
              </button>
            )}
          </div>
        )}
      </header>

      {categories.map(cat => (
        <section key={cat} className="space-y-6 px-4">
          <div className="flex items-center gap-4">
            <h3 className="text-2xl font-black text-slate-800 dark:text-slate-200 uppercase tracking-tighter">{cat}</h3>
            <div className="flex-1 h-px bg-slate-200 dark:bg-slate-800"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {activeMenu.filter(item => item.category === cat).map(item => (
              <div key={item.id} className="bg-white dark:bg-slate-900 rounded-[2rem] shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden hover:shadow-2xl hover:scale-[1.01] transition-all duration-300 group flex flex-col h-full relative">
                {item.image && (
                  <div className="w-full h-48 overflow-hidden relative">
                    <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950/70 to-transparent opacity-0 group-hover:opacity-100 transition-opacity"></div>
                    <button 
                      onClick={() => addToQuickCart(item.id)}
                      className="absolute bottom-4 right-4 w-12 h-12 bg-orange-600 text-white rounded-2xl flex items-center justify-center text-2xl shadow-xl transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300"
                    >
                      +
                    </button>
                  </div>
                )}

                <div className="p-6 flex flex-col flex-1">
                  <h4 className="text-lg font-black text-slate-900 dark:text-white mb-2 group-hover:text-orange-600 transition-colors">{item.name}</h4>
                  <p className="text-slate-500 dark:text-slate-400 text-xs leading-relaxed mb-6 flex-1 line-clamp-2">{item.description}</p>

                  <div className="pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-between items-center">
                    <div>
                      <span className="text-[9px] font-black uppercase text-slate-400 dark:text-slate-500 tracking-widest block">Precio</span>
                      <span className="text-xl font-black text-slate-900 dark:text-white">L. {item.price.toFixed(2)}</span>
                    </div>
                    {!item.image && (
                      <button 
                        onClick={() => addToQuickCart(item.id)}
                        className="bg-slate-900 dark:bg-orange-600 text-white px-5 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-orange-600"
                      >
                        Añadir +
                      </button>
                    )}
                  </div>
                </div>

                {/* Fix: Operator '>' cannot be applied to types 'unknown' and 'number' by using Number() to ensure type consistency */}
                {(Number(quickCart[item.id]) || 0) > 0 && (
                  <div className="absolute top-4 left-4 bg-orange-600 text-white w-7 h-7 rounded-lg flex items-center justify-center font-black text-[10px] shadow-lg animate-scaleIn border-2 border-white dark:border-slate-900">
                    {quickCart[item.id]}
                  </div>
                )}
              </div>
            ))}
          </div>
        </section>
      ))}

      {/* TICKET DE PEDIDO VERTICAL - DISEÑO RECTANGULAR ALARGADO HACIA ABAJO */}
      {quickCartCount > 0 && (
        <div className="fixed bottom-6 right-6 z-[150] animate-fadeIn w-[280px] lg:w-[300px]">
          <div className="bg-slate-900 dark:bg-slate-800 text-white rounded-[2.5rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.8)] border border-slate-800 dark:border-slate-700 flex flex-col overflow-hidden relative border-t-[6px] border-t-orange-600">

            {/* Cabecera del Ticket (Efecto Papel Térmico) */}
            <div className="p-6 border-b border-slate-800 bg-slate-950/40 relative">
              <div className="flex justify-between items-start">
                <div>
                  <h3 className="text-[9px] font-black uppercase tracking-[0.4em] text-orange-500 mb-1">RESTAURANTE CONTROL</h3>
                  <p className="text-base font-black tracking-tight leading-none uppercase">Ticket de Venta</p>
                </div>
                <div className="bg-white text-slate-900 w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs shadow-md">
                  #{quickCartCount}
                </div>
              </div>
              <div className="mt-4 flex items-center justify-between text-[8px] font-bold text-slate-500 uppercase tracking-widest">
                <span>Terminal: 001</span>
                <span>{new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
              </div>
            </div>

            {/* Listado Principal - La sección más larga (Scrollable) */}
            <div className="flex-1 max-h-[450px] overflow-y-auto custom-scrollbar p-6 space-y-5 bg-slate-950/20">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                return (
                  <div key={id} className="flex flex-col gap-1.5 animate-fadeIn group">
                    <div className="flex justify-between items-start">
                      <span className="text-[10px] font-black text-slate-100 leading-tight flex-1 pr-3 uppercase tracking-tighter line-clamp-2">
                        {item?.name}
                      </span>
                      <span className="text-[10px] font-black text-orange-500 shrink-0">
                        L. {((qty as number) * (item?.price || 0)).toFixed(2)}
                      </span>
                    </div>
                    <div className="flex items-center justify-between mt-0.5">
                      <div className="flex items-center gap-2 bg-slate-800/80 px-2 py-1 rounded-lg border border-slate-700">
                        <button onClick={() => removeFromQuickCart(id)} className="text-red-400 hover:text-red-300 font-black text-sm px-1">-</button>
                        <span className="text-[10px] font-black text-white min-w-[14px] text-center">{qty}</span>
                        <button onClick={() => addToQuickCart(id)} className="text-green-400 hover:text-green-300 font-black text-sm px-1">+</button>
                      </div>
                      <span className="text-[8px] text-slate-500 font-bold uppercase tracking-widest">L. {item?.price.toFixed(2)} c/u</span>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Resumen Final y Acciones */}
            <div className="p-6 bg-slate-900/95 border-t border-slate-800 space-y-5 shadow-[0_-10px_20px_rgba(0,0,0,0.2)]">
              <div className="flex flex-col gap-1">
                <div className="flex justify-between items-center opacity-60">
                   <span className="text-[9px] font-bold uppercase text-slate-400">Subtotal</span>
                   <span className="text-[10px] font-bold">L. {(quickCartTotal * 0.85).toFixed(2)}</span>
                </div>
                <div className="flex justify-between items-center opacity-60">
                   <span className="text-[9px] font-bold uppercase text-slate-400">ISV (15%)</span>
                   <span className="text-[10px] font-bold">L. {(quickCartTotal * 0.15).toFixed(2)}</span>
                </div>
                <div className="flex justify-between items-end mt-2">
                  <span className="text-[10px] font-black text-slate-200 uppercase tracking-[0.2em] mb-1">TOTAL</span>
                  <span className="text-3xl font-black text-white tracking-tighter">L. {quickCartTotal.toFixed(2)}</span>
                </div>
              </div>

              <div className="flex flex-col gap-2.5">
                <button 
                  onClick={() => setIsConfirming(true)}
                  className="w-full py-4.5 bg-orange-600 text-white rounded-2xl font-black text-[12px] uppercase tracking-[0.3em] hover:bg-orange-500 shadow-2xl shadow-orange-950/40 transition-all active:scale-[0.96] flex items-center justify-center gap-3 relative overflow-hidden group"
                >
                  <span className="relative z-10">PAGAR AHORA</span>
                  <span className="text-lg group-hover:translate-x-2 transition-transform duration-300">➔</span>
                </button>

                <button 
                  onClick={clearQuickCart}
                  className="w-full py-3.5 bg-slate-800/40 hover:bg-red-950/30 text-slate-600 hover:text-red-400 rounded-2xl font-black text-[9px] uppercase tracking-widest transition-all border border-slate-700/50"
                >
                  CANCELAR COMANDA
                </button>
              </div>
            </div>

            {/* Decoración Inferior de Ticket Cortado */}
            <div className="h-6 w-full bg-slate-900 flex flex-col items-center justify-center opacity-30">
               <div className="w-1/2 h-[1px] bg-slate-800 mb-1"></div>
               <div className="w-1/4 h-[1px] bg-slate-800"></div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default Menu;

export interface Ingredient {
  id: string;
  name: string;
  unit: string;
  stock: number;
  minStock: number;
  costPerUnit: number;
}

export type SaleStatus = 'Recibido' | 'Preparacion' | 'Listo' | 'Enviado' | 'Entregado';
export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Tarjeta';

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image?: string;
  isActive?: boolean;
  recipe: {
    ingredientId: string;
    amount: number;
  }[];
}

export interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  notes: string;
  orderHistory: string[];
}

export interface Sale {
  id: string;
  timestamp: Date;
  customerId?: string;
  customerName?: string;
  items: {
    menuItemId: string;
    quantity: number;
    priceAtSale: number;
    customization?: string;
  }[];
  total: number;
  status: SaleStatus;
  paymentMethod: PaymentMethod;
}

export type View = 'dashboard' | 'inventory' | 'menu' | 'prices' | 'sales' | 'analysis' | 'reports' | 'customers' | 'online-order' | 'orders';

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import OrdersManager from './components/OrdersManager';
import { View, Ingredient, MenuItem, Sale, Customer, SaleStatus, PaymentMethod } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('theme');
    return saved === 'dark' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [menuHeader, setMenuHeader] = useState<{title: string, description: string}>(() => {
    const saved = localStorage.getItem('menuHeader');
    return saved ? JSON.parse(saved) : {
      title: 'Nuestra Carta',
      description: 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'
    };
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ 
      ...s, 
      timestamp: new Date(s.timestamp),
      status: s.status || 'Recibido',
      paymentMethod: s.paymentMethod || 'Efectivo'
    }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('menuHeader', JSON.stringify(menuHeader)); }, [menuHeader]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const addUnit = (unit: string) => {
    const cleanUnit = unit.trim().toLowerCase();
    if (cleanUnit && !availableUnits.includes(cleanUnit)) {
      setAvailableUnits([...availableUnits, cleanUnit]);
    }
  };

  const deleteUnit = (unit: string) => {
    setAvailableUnits(availableUnits.filter(u => u !== unit));
  };

  const addCategory = (category: string) => {
    const cleanCat = category.trim();
    if (cleanCat && !categories.includes(cleanCat)) {
      setCategories([...categories, cleanCat]);
    }
  };

  const deleteCategory = (category: string) => {
    setCategories(categories.filter(c => c !== category));
  };

  const updatePrice = (id: string, newPrice: number) => {
    setMenu(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const updateMenuItemRecipe = (
    id: string, 
    newRecipe: MenuItem['recipe'], 
    newPrice?: number, 
    newName?: string,
    newCategory?: string,
    newDescription?: string,
    newImage?: string,
    newIsActive?: boolean
  ) => {
    setMenu(prev => prev.map(item => 
      item.id === id 
        ? { 
            ...item, 
            recipe: newRecipe, 
            price: newPrice !== undefined ? newPrice : item.price,
            name: newName !== undefined ? newName : item.name,
            category: newCategory !== undefined ? newCategory : item.category,
            description: newDescription !== undefined ? newDescription : item.description,
            image: newImage !== undefined ? newImage : item.image,
            isActive: newIsActive !== undefined ? newIsActive : item.isActive
          } 
        : item
    ));
  };

  const addMenuItem = (newItem: Omit<MenuItem, 'id'>) => {
    const item: MenuItem = {
      ...newItem,
      id: 'm-' + Date.now(),
      isActive: true
    };
    setMenu(prev => [...prev, item]);
  };

  const deleteMenuItem = (id: string) => {
    setMenu(prev => prev.filter(item => item.id !== id));
  };

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, Number(item.stock) + delta) } : item
    ));
  };

  const updateIngredient = (id: string, updates: Partial<Ingredient>) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, ...updates } : item
    ));
  };

  const addIngredient = (newIng: Omit<Ingredient, 'id'>) => {
    const ingredient: Ingredient = {
      ...newIng,
      id: 'ing-' + Date.now()
    };
    setIngredients(prev => [...prev, ingredient]);
  };

  const deleteIngredient = (id: string) => {
    setIngredients(prev => prev.filter(item => item.id !== id));
  };

  const addSale = (
    saleItems: { menuItemId?: string, id?: string, quantity: number, customization?: string }[], 
    customerInfo?: { name: string, phone: string },
    paymentMethod: PaymentMethod = 'Efectivo'
  ) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItemId = si.menuItemId || si.id || '';
      const menuItem = menu.find(m => m.id === menuItemId);
      const price = menuItem ? menuItem.price : 0;
      const qty = si.quantity || 1;
      total += price * qty;

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * qty));
        });
      }

      return {
        menuItemId: menuItemId,
        quantity: qty,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    let assignedCustomerId: string | undefined = undefined;

    if (customerInfo) {
      const existing = customers.find(c => c.phone === customerInfo.phone);
      if (existing) {
        assignedCustomerId = existing.id;
        setCustomers(prev => prev.map(c => c.id === existing.id ? { ...c, orderHistory: [...c.orderHistory, saleId] } : c));
      } else {
        const newCustId = 'c' + Date.now();
        assignedCustomerId = newCustId;
        const newCust: Customer = {
          id: newCustId,
          name: customerInfo.name,
          email: '',
          phone: customerInfo.phone,
          notes: 'Registrado vía Pedido',
          orderHistory: [saleId]
        };
        setCustomers(prev => [...prev, newCust]);
      }
    }

    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerId: assignedCustomerId,
      customerName: customerInfo?.name || 'Cliente de Mostrador',
      status: 'Recibido',
      paymentMethod: paymentMethod
    };

    setSales(prev => [...prev, newSale]);
  };

  const updateSaleStatus = (saleId: string, newStatus: SaleStatus) => {
    setSales(prev => prev.map(s => s.id === saleId ? { ...s, status: newStatus } : s));
  };

  const deleteSale = (saleId: string) => {
    const saleToDelete = sales.find(s => s.id === saleId);
    if (saleToDelete) {
      saleToDelete.items.forEach(item => {
        const menuItem = menu.find(m => m.id === item.menuItemId);
        if (menuItem) {
          menuItem.recipe.forEach(ri => {
            updateStock(ri.ingredientId, (ri.amount * item.quantity));
          });
        }
      });
      setSales(prev => prev.filter(s => s.id !== saleId));
    }
  };

  const updateSale = (saleId: string, updatedData: Partial<Sale>) => {
    const oldSale = sales.find(s => s.id === saleId);
    if (oldSale && updatedData.items) {
      oldSale.items.forEach(item => {
        const menuItem = menu.find(m => m.id === item.menuItemId);
        if (menuItem) {
          menuItem.recipe.forEach(ri => {
            updateStock(ri.ingredientId, (ri.amount * item.quantity));
          });
        }
      });
      updatedData.items.forEach(item => {
        const menuItem = menu.find(m => m.id === item.menuItemId);
        if (menuItem) {
          menuItem.recipe.forEach(ri => {
            updateStock(ri.ingredientId, -(ri.amount * item.quantity));
          });
        }
      });
    }
    setSales(prev => prev.map(s => s.id === saleId ? { ...s, ...updatedData } : s));
  };

  const handleNavigate = (newView: View) => {
    setView(newView);
    setIsSidebarOpen(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
      {view === 'online-order' ? (
        <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />
      ) : (
        <div className="flex flex-col lg:flex-row bg-slate-50 dark:bg-slate-950 min-h-screen text-slate-900 dark:text-slate-100 relative transition-colors duration-300">
          <div className="lg:hidden bg-white dark:bg-slate-900 text-slate-900 dark:text-white p-4 flex justify-between items-center sticky top-0 z-30 shadow-sm border-b border-slate-200 dark:border-slate-800">
            <h1 className="text-xl font-black flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> ParrillaPro
            </h1>
            <button 
              onClick={() => setIsSidebarOpen(true)}
              className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors text-slate-600 dark:text-slate-400"
            >
              <span className="text-2xl">☰</span>
            </button>
          </div>

          <Sidebar 
            currentView={view} 
            onNavigate={handleNavigate} 
            isOpen={isSidebarOpen} 
            onClose={() => setIsSidebarOpen(false)} 
            isDarkMode={isDarkMode}
            onToggleTheme={toggleTheme}
          />

          <main className="flex-1 p-4 md:p-8 overflow-y-auto">
            <div className="max-w-6xl mx-auto">
              {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
              {view === 'inventory' && (
                <Inventory 
                  ingredients={ingredients} 
                  availableUnits={availableUnits}
                  onAddUnit={addUnit}
                  onDeleteUnit={deleteUnit}
                  onUpdateStock={updateStock} 
                  onUpdateIngredient={updateIngredient}
                  onAddIngredient={addIngredient}
                  onDeleteIngredient={deleteIngredient}
                />
              )}
              {view === 'menu' && (
                <Menu 
                  menu={menu} 
                  header={menuHeader} 
                  onUpdateHeader={(h) => setMenuHeader(h)} 
                  onQuickOrder={(items, customerInfo, paymentMethod) => addSale(items, customerInfo, paymentMethod)}
                />
              )}
              {view === 'prices' && (
                <PriceManager 
                  menu={menu} 
                  ingredients={ingredients} 
                  categories={categories}
                  onAddCategory={addCategory}
                  onDeleteCategory={deleteCategory}
                  onUpdatePrice={updatePrice} 
                  onUpdateRecipe={updateMenuItemRecipe}
                  onAddMenuItem={addMenuItem}
                  onDeleteMenuItem={deleteMenuItem}
                />
              )}
              {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items, paymentMethod) => addSale(items, undefined, paymentMethod)} />}
              {view === 'orders' && (
                <OrdersManager 
                  sales={sales} 
                  menu={menu} 
                  customers={customers} 
                  onUpdateStatus={updateSaleStatus}
                  onDeleteSale={deleteSale}
                  onUpdateSale={updateSale}
                />
              )}
              {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
              {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
              {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
            </div>
          </main>
        </div>
      )}
      <style>{`
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fadeIn { animation: fadeIn 0.4s ease-out forwards; }
        @keyframes scaleIn { from { opacity: 0; transform: scale(0.95); } to { opacity: 1; transform: scale(1); } }
        .animate-scaleIn { animation: scaleIn 0.2s ease-out forwards; }
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 20px; }
        .dark .custom-scrollbar::-webkit-scrollbar-thumb { background: #334155; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { MenuItem, PaymentMethod } from '../types';

interface MenuProps {
  menu: MenuItem[];
  header?: { title: string; description: string };
  onUpdateHeader?: (header: { title: string; description: string }) => void;
  onQuickOrder?: (items: { menuItemId: string, quantity: number }[], customerInfo?: { name: string, phone: string }, paymentMethod?: PaymentMethod) => void;
}

const Menu: React.FC<MenuProps> = ({ menu, header, onUpdateHeader, onQuickOrder }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [tempTitle, setTempTitle] = useState(header?.title || 'Nuestra Carta');
  const [tempDescription, setTempDescription] = useState(header?.description || '');

  const [quickCart, setQuickCart] = useState<Record<string, number>>({});
  const [isConfirming, setIsConfirming] = useState(false);

  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>('Efectivo');

  const activeMenu = menu.filter(m => m.isActive !== false);
  const categories = Array.from(new Set(activeMenu.map(m => m.category)));

  const handleSaveHeader = () => {
    if (onUpdateHeader) {
      onUpdateHeader({ title: tempTitle, description: tempDescription });
    }
    setIsEditing(false);
  };

  const addToQuickCart = (id: string) => {
    setQuickCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromQuickCart = (id: string) => {
    const newCart = { ...quickCart };
    const currentQty = Number(newCart[id] || 0);
    if (currentQty > 1) {
      newCart[id] = currentQty - 1;
    } else {
      delete newCart[id];
    }
    setQuickCart(newCart);
  };

  const clearQuickCart = () => {
    setQuickCart({});
    setIsConfirming(false);
    setCustomerName('');
    setCustomerPhone('');
    setPaymentMethod('Efectivo');
  };

  const handleProcessQuickOrder = () => {
    if (onQuickOrder) {
      const items = Object.entries(quickCart).map(([menuItemId, quantity]) => ({
        menuItemId,
        quantity: quantity as number
      }));

      const customerInfo = customerName.trim() || customerPhone.trim() 
        ? { name: customerName, phone: customerPhone } 
        : undefined;

      onQuickOrder(items, customerInfo, paymentMethod);
      clearQuickCart();
    }
  };

  const quickCartCount = Object.values(quickCart).reduce((a: number, b: number) => a + (b as number), 0);
  const quickCartTotal = Object.entries(quickCart).reduce((sum: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    return sum + (item ? item.price * (qty as number) : 0);
  }, 0);

  return (
    <div className="space-y-12 animate-fadeIn pb-40 lg:pr-80 transition-all duration-500">
      {/* Modal Confirmación Pedido Rápido */}
      {isConfirming && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-fadeIn">
          <div className="bg-white dark:bg-slate-900 rounded-[3rem] w-full max-w-lg p-8 shadow-2xl animate-scaleIn border border-slate-200 dark:border-slate-800">
            <h3 className="text-xl font-black text-slate-900 dark:text-white mb-6 flex items-center gap-2">
              <span className="text-orange-500 text-2xl">🔥</span> Finalizar Venta
            </h3>

            <div className="bg-slate-50 dark:bg-slate-800/50 p-6 rounded-[2rem] mb-6 space-y-4 border border-slate-100 dark:border-slate-700">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">IDENTIFICACIÓN DEL CLIENTE</h4>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <input 
                  type="text" 
                  placeholder="Nombre Cliente"
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none dark:text-white"
                  value={customerName}
                  onChange={e => setCustomerName(e.target.value)}
                />
                <input 
                  type="tel" 
                  placeholder="Teléfono"
                  className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 focus:border-orange-500 rounded-xl px-4 py-2.5 text-sm font-bold outline-none dark:text-white"
                  value={customerPhone}
                  onChange={e => setCustomerPhone(e.target.value)}
                />
              </div>
            </div>

            <div className="mb-6">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3 ml-1">MÉTODO DE PAGO</h4>
              <div className="grid grid-cols-3 gap-2">
                {[
                  { id: 'Efectivo', icon: '💵' },
                  { id: 'Tarjeta', icon: '💳' },
                  { id: 'Transferencia', icon: '📱' }
                ].map(method => (
                  <button
                    key={method.id}
                    onClick={() => setPaymentMethod(method.id as PaymentMethod)}
                    className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${
                      paymentMethod === method.id 
                      ? 'border-orange-500 bg-orange-50 dark:bg-orange-950/20 text-orange-600' 
                      : 'border-slate-100 dark:border-slate-800 text-slate-400'
                    }`}
                  >
                    <span className="text-xl mb-1">{method.icon}</span>
                    <span className="text-[9px] font-black uppercase">{method.id}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-1 mb-8 max-h-[20vh] overflow-y-auto pr-2 custom-scrollbar">
              {Object.entries(quickCart).map(([id, qty]) => {
                const item = menu.find(m => m.id === id);
                return (
                  <div key={id} className="flex justify-between items-center py-3 border-b border-slate-50 dark:border-slate-800 last:border-0 text-sm font-bold">
                    <span className="text-slate-600 dark:text-slate-400">{qty}x {item?.name}</span>
                    <span className="text-slate-900 dark:text-white">L. {((item?.price || 0) * (qty as number)).toFixed(2)}</span>
                  </div>
                );
              })}
            </div>

            <div className="flex justify-between items-center mb-8 border-t-2 border-slate-100 dark:border-slate-800 pt-6">
              <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Monto Total</span>
              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button onClick={() => setIsConfirming(false)} className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-2xl font-black text-[10px] uppercase hover:bg-slate-200 dark:hover:bg-slate-700">Atrás</button>
              <button onClick={handleProcessQuickOrder} className="flex-1 py-4 bg-slate-900 dark:bg-orange-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-xl hover:bg-orange-500">Pagar Orden</button>
            </div>
          </div>
        </div>
      )}

      <header className="text-center max-w-2xl mx-auto mb-12 relative group px-4">
        {isEditing ? (
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 dark:text-white mb-4 bg-slate-50 dark:bg-slate-800 p-3 rounded-2xl outline-none"
              value={tempTitle}
              onChange={e => setTempTitle(e.target.value)}
              placeholder="Título"
              autoFocus
            />
            <textarea 
              className="w-full text-center text-slate-500 dark:text-slate-400 font-medium bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl outline-none resize-none"
              rows={3}
              value={tempDescription}
              onChange={e => setTempDescription(e.target.value)}
            />
            <div className="flex justify-center gap-2 mt-6">
              <button onClick={() => { setIsEditing(false); setTempTitle(header?.title || ''); setTempDescription(header?.description || ''); }} className="px-6 py-2 bg-slate-100 dark:bg-slate-800 text-slate-400 rounded-xl font-black text-xs uppercase">Cancelar</button>
              <button onClick={handleSaveHeader} className="px-8 py-2 bg-orange-600 text-white rounded-xl font-black text-xs uppercase">Guardar</button>
            </div>
          </div>
        ) : (
          <div className="relative inline-block w-full">
            <h2 className="text-4xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">{header?.title || 'Nuestra Carta'}</h2>
            <p className="text-slate-500 dark:text-slate-400 font-medium">{header?.description}</p>
            {onUpdateHeader && (
              <button 
                onClick={() => setIsEditing(true)}
                className="absolute -top-4 -right-4 w-10 h-10 bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 shadow-md rounded-full flex items-center justify-center text-slate-400 hover:text-orange-600 opacity-0 group-hover:opacity-100 transition-all"
              >
