import React, { useState } from 'react';
import { Sale, MenuItem, PaymentMethod } from '../types';

interface SalesManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  onAddSale: (saleItems: { menuItemId: string, quantity: number }[], paymentMethod: PaymentMethod) => void;
}

const SalesManager: React.FC<SalesManagerProps> = ({ sales, menu, onAddSale }) => {
  const [cart, setCart] = useState<Record<string, number>>({});
  const [showMobileCart, setShowMobileCart] = useState(false);
  const [selectedSale, setSelectedSale] = useState<Sale | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>('Efectivo');

  const activeMenu = menu.filter(m => m.isActive !== false);

  const addToCart = (id: string) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: string) => {
    if (!cart[id]) return;
    const newCart = { ...cart };
    if (newCart[id] === 1) delete newCart[id];
    else newCart[id] -= 1;
    setCart(newCart);
  };

  const handleCheckout = () => {
    const items = Object.entries(cart).map(([menuItemId, quantity]) => ({
      menuItemId,
      quantity: quantity as number
    }));
    if (items.length === 0) return;
    onAddSale(items, paymentMethod);
    setCart({});
    setShowMobileCart(false);
    setPaymentMethod('Efectivo');
  };

  const cartTotal: number = Object.entries(cart).reduce((total: number, [id, qty]) => {
    const item = menu.find(m => m.id === id);
    const quantity = qty as number;
    return total + (item ? item.price * quantity : 0);
  }, 0);

  const cartCount = Object.values(cart).reduce((a: number, b: number) => a + (b as number), 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-fadeIn pb-24 lg:pb-8">
      {selectedSale && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-fadeIn">
          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] w-full max-w-lg p-8 shadow-2xl animate-scaleIn">
            <header className="flex justify-between items-start mb-6">
              <div>
                <h3 className="text-xl font-black text-slate-900 dark:text-white">Detalle de Venta</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">
                  ID: #{selectedSale.id.slice(-6)} • {new Date(selectedSale.timestamp).toLocaleString()}
                </p>
                <span className="inline-block mt-2 px-3 py-1 bg-slate-100 dark:bg-slate-800 rounded-full text-[9px] font-black uppercase text-slate-500">
                  Pago: {selectedSale.paymentMethod}
                </span>
              </div>
              <button onClick={() => setSelectedSale(null)} className="w-10 h-10 bg-slate-50 dark:bg-slate-800 text-slate-400 rounded-full flex items-center justify-center transition-colors">✕</button>
            </header>
            <div className="space-y-4 mb-8 max-h-[40vh] overflow-y-auto pr-2 custom-scrollbar">
              {selectedSale.items.map((item, idx) => {
                const menuItem = menu.find(m => m.id === item.menuItemId);
                return (
                  <div key={idx} className="p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-slate-100 dark:border-slate-700">
                    <div className="flex justify-between items-start mb-1">
                      <span className="font-black text-slate-900 dark:text-white text-sm">
                        {item.quantity}x {menuItem?.name || 'Producto Desconocido'}
                      </span>
                      <span className="font-bold text-slate-600 dark:text-slate-400 text-sm">
                        L. {(item.quantity * item.priceAtSale).toFixed(2)}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
            <div className="pt-6 border-t border-slate-100 dark:border-slate-800 flex justify-between items-center">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Cobrado</p>
                <p className="text-3xl font-black text-slate-900 dark:text-white">L. {selectedSale.total.toFixed(2)}</p>
              </div>
              <button onClick={() => setSelectedSale(null)} className="px-8 py-3 bg-slate-900 dark:bg-orange-600 text-white rounded-xl font-black text-xs uppercase tracking-widest transition-all">CERRAR</button>
            </div>
          </div>
        </div>
      )}

      <div className="lg:col-span-2 space-y-6">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800">
          <h2 className="text-xl font-black text-slate-800 dark:text-white mb-6 uppercase tracking-widest text-sm">Carta de Menú</h2>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {activeMenu.map(item => (
              <div key={item.id} className="p-4 border border-slate-100 dark:border-slate-800 rounded-2xl hover:border-orange-300 transition-all flex justify-between items-center bg-slate-50/40 dark:bg-slate-800/30 group">
                <div>
                  <h4 className="font-black text-slate-900 dark:text-white text-sm">{item.name}</h4>
                  <p className="text-xs font-bold text-orange-600">L. {item.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  {(Number(cart[item.id]) || 0) > 0 && (
                    <div className="flex items-center gap-2 animate-fadeIn">
                      <button onClick={() => removeFromCart(item.id)} className="w-8 h-8 bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 text-slate-600 dark:text-white rounded-full flex items-center justify-center hover:bg-slate-100 shadow-sm">-</button>
                      <span className="font-black text-sm w-4 text-center dark:text-white">{cart[item.id]}</span>
                    </div>
                  )}
                  <button onClick={() => addToCart(item.id)} className="w-10 h-10 bg-slate-900 dark:bg-orange-600 text-white rounded-full flex items-center justify-center hover:bg-orange-600 transition-all shadow-lg active:scale-90">+</button>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden hidden sm:block">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-xl font-black text-slate-800 dark:text-white uppercase tracking-widest text-sm">Ventas Recientes</h2>
          </div>
          <div className="overflow-x-auto custom-scrollbar">
            <table className="w-full text-left min-w-[500px]">
              <thead className="bg-slate-50 dark:bg-slate-800 text-slate-400 text-[10px] font-black uppercase tracking-[0.2em]">
                <tr>
                  <th className="px-4 py-3">Hora</th>
                  <th className="px-4 py-3">Pedido</th>
                  <th className="px-4 py-3 text-center">Pago</th>
                  <th className="px-4 py-3 text-right">Total</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
                {[...sales].reverse().slice(0, 10).map(sale => (
                  <tr key={sale.id} onClick={() => setSelectedSale(sale)} className="text-xs cursor-pointer hover:bg-orange-50 dark:hover:bg-slate-800 transition-all group">
                    <td className="px-4 py-4 text-slate-400 font-bold group-hover:text-orange-600">
                      {new Date(sale.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </td>
                    <td className="px-4 py-4 text-slate-900 dark:text-slate-200 font-bold">
                      {sale.items.length} items
                    </td>
                    <td className="px-4 py-4 text-center">
                       <span className="text-[8px] font-black uppercase text-slate-400 bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded">
                         {sale.paymentMethod}
                       </span>
                    </td>
                    <td className="px-4 py-4 text-right font-black text-slate-900 dark:text-white">
                      L. {sale.total.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <div className={`fixed inset-x-0 bottom-0 z-40 bg-slate-900 text-white p-6 rounded-t-[2.5rem] shadow-2xl transition-transform duration-300 transform lg:translate-y-0 lg:static lg:rounded-3xl lg:flex lg:flex-col lg:h-[calc(100vh-8rem)] lg:sticky lg:top-6 ${showMobileCart ? 'translate-y-0' : 'translate-y-[calc(100%-80px)] lg:translate-y-0'}`}>
        <div className="flex justify-between items-center mb-6 cursor-pointer lg:cursor-default" onClick={() => setShowMobileCart(!showMobileCart)}>
          <h3 className="text-lg font-black uppercase tracking-widest flex items-center gap-2">
            <span>🛒</span> Carrito <span className="bg-orange-600 text-[10px] px-2 py-1 rounded-full">{cartCount}</span>
          </h3>
          <span className="lg:hidden text-xl">{showMobileCart ? '↓' : '↑'}</span>
        </div>
        <div className="flex-1 overflow-y-auto space-y-4 mb-6 pr-2 custom-scrollbar min-h-[100px] max-h-[300px] lg:max-h-none">
          {Object.entries(cart).map(([id, qty]) => {
            const item = menu.find(m => m.id === id);
            return (
              <div key={id} className="flex justify-between items-center pb-4 border-b border-slate-800 last:border-0 animate-fadeIn">
                <div className="flex-1">
                  <p className="font-bold text-sm">{item?.name}</p>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{qty} x L. {item?.price.toFixed(2)}</p>
                </div>
                <div className="flex items-center gap-3">
                  <p className="font-black text-orange-400 text-sm">L. {((qty as number) * (item?.price || 0)).toFixed(2)}</p>
                  <button onClick={() => removeFromCart(id)} className="text-red-500 hover:text-red-400 p-1">✕</button>
                </div>
              </div>
            );
          })}
        </div>

        <div className="border-t border-slate-800 pt-6 space-y-6">
          {/* MÉTODOS DE PAGO EN CARRITO */}
          <div>
            <p className="text-[10px] font-black uppercase text-slate-500 tracking-[0.2em] mb-3">Forma de Pago</p>
            <div className="grid grid-cols-3 gap-2">
              {[
                { id: 'Efectivo', icon: '💵' },
                { id: 'Tarjeta', icon: '💳' },
                { id: 'Transferencia', icon: '📱' }
              ].map(m => (
                <button
