      <header className="text-center max-w-2xl mx-auto mb-12 relative group px-4">
        {isEditing ? (
          <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] shadow-xl border-2 border-orange-500 animate-scaleIn">
            <input 
              className="w-full text-center text-3xl font-black text-slate-900 dark:text-white mb-4 bg-slate-50 dark:bg-slate-800 p-3 rounded-2xl outline-none"
