              <div className="flex justify-between items-start mb-4">
                <div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Órden #{sale.id.slice(-6)}</span>
                  <h3 className="text-lg font-black text-slate-900 dark:text-white">{sale.customerName}</h3>
                </div>
                <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase border tracking-widest ${getStatusColor(sale.status)}`}>
                  {sale.status}
                </div>
              </div>
              <div className="flex items-center justify-between mt-2">
                <span className="text-xs font-bold text-slate-400">🕒 {sale.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                <span className="px-3 py-1 bg-slate-50 dark:bg-slate-800 rounded-lg text-[10px] font-black uppercase text-slate-500">
                  {sale.paymentMethod}
                </span>
              </div>
            </div>

            <div className="p-6 flex-1 space-y-3">
              {sale.items.map((item, idx) => {
                const menuItem = menu.find(m => m.id === item.menuItemId);
                return (
                  <div key={idx} className="flex justify-between items-center text-sm">
                    <span className="font-bold text-slate-700 dark:text-slate-300">{item.quantity}x {menuItem?.name || 'Producto'}</span>
                    <span className="font-bold text-slate-400">L. {(item.priceAtSale * item.quantity).toFixed(2)}</span>
                  </div>
                );
              })}
              <div className="pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-between items-center">
                <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Monto Total</span>
                <span className="text-xl font-black text-slate-900 dark:text-white">L. {sale.total.toFixed(2)}</span>
              </div>
            </div>

            <div className="p-6 bg-slate-50 dark:bg-slate-800/50 border-t border-slate-100 dark:border-slate-800">
              {activeTab === 'activas' ? (
                <div className="space-y-4">
                   <div className="flex flex-wrap gap-2 justify-center">
                    {statuses.filter(s => s !== 'Cancelado').map(s => (
                      <button
                        key={s}
                        onClick={() => onUpdateStatus(sale.id, s)}
                        disabled={sale.status === s}
                        className={`px-3 py-2 rounded-xl text-[9px] font-black uppercase tracking-tighter transition-all border ${
                          sale.status === s 
                          ? 'bg-slate-200 text-slate-400 border-slate-200 cursor-default' 
                          : 'bg-white dark:bg-slate-900 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-700 hover:border-orange-500 hover:text-orange-600'
                        }`}
                      >
                        {s}
                      </button>
                    ))}
                  </div>
                  <button 
                    onClick={() => { if(window.confirm('¿ELIMINAR ESTA ORDEN?\n\nLos insumos regresarán al inventario y la orden se moverá al Historial de Eliminadas.')) onDeleteSale(sale.id); }}
                    className="w-full py-3 bg-red-50 hover:bg-red-500 text-red-500 hover:text-white rounded-2xl flex items-center justify-center gap-2 transition-all font-black text-[10px] uppercase tracking-widest border border-red-100"
                  >
                    🗑️ ELIMINAR REGISTRO
                  </button>
                </div>
              ) : (
                <button 
                  onClick={() => { if(window.confirm('¿RESTAURAR ORDEN?\n\nEsto volverá a descontar los insumos del inventario y activará el pedido.')) onRestoreSale?.(sale.id); }}
                  className="w-full py-4 bg-green-600 text-white rounded-2xl flex items-center justify-center gap-3 transition-all font-black text-[10px] uppercase tracking-[0.2em] shadow-lg shadow-green-100 dark:shadow-none"
                >
                  ⚡ RESTAURAR ORDEN
                </button>
              )}
            </div>
          </div>
        ))}

        {filteredSales.length === 0 && (
          <div className="col-span-full py-24 text-center bg-white dark:bg-slate-900 rounded-[3rem] border border-dashed border-slate-200 dark:border-slate-800">
            <div className="text-6xl mb-6 opacity-20">📭</div>
            <h3 className="text-xl font-black text-slate-400 uppercase tracking-widest">
              {activeTab === 'activas' ? 'No hay órdenes activas' : 'La papelera está vacía'}
            </h3>
          </div>
        )}
      </div>
    </div>
  );
};

