import React, { useState } from 'react';
import { Sale, MenuItem, Customer, SaleStatus, PaymentMethod } from '../types';

interface OrdersManagerProps {
  sales: Sale[];
  deletedSales?: Sale[];
  menu: MenuItem[];
  customers: Customer[];
  onUpdateStatus: (saleId: string, status: SaleStatus) => void;
  onDeleteSale: (saleId: string) => void;
  onRestoreSale?: (saleId: string) => void;
  onPurgeTrash?: () => void;
  onUpdateSale: (saleId: string, updatedData: Partial<Sale>) => void;
}

const OrdersManager: React.FC<OrdersManagerProps> = ({ 
  sales, 
  deletedSales = [],
  menu, 
  customers, 
  onUpdateStatus,
  onDeleteSale,
  onRestoreSale,
  onPurgeTrash,
  onUpdateSale 
}) => {
  const [activeTab, setActiveTab] = useState<'activas' | 'canceladas'>('activas');
  const [filter, setFilter] = useState<SaleStatus | 'Todos'>('Todos');

  // Lista completa de estatus para filtros y acciones
  const statuses: SaleStatus[] = ['Recibido', 'Preparacion', 'Listo', 'Enviado', 'Entregado', 'Cancelado'];

  const getStatusColor = (status: SaleStatus) => {
    switch (status) {
      case 'Recibido': return 'bg-slate-100 text-slate-600 border-slate-200';
      case 'Preparacion': return 'bg-orange-50 text-orange-600 border-orange-200';
      case 'Listo': return 'bg-green-50 text-green-600 border-green-200';
      case 'Enviado': return 'bg-blue-50 text-blue-600 border-blue-200';
      case 'Entregado': return 'bg-slate-900 text-white border-slate-900';
      case 'Cancelado': return 'bg-red-50 text-red-600 border-red-200';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const filteredSales = (activeTab === 'activas' ? sales : deletedSales)
    .filter(s => filter === 'Todos' || s.status === filter)
    .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

  const handleStatusChange = (saleId: string, newStatus: SaleStatus) => {
    if (newStatus === 'Cancelado') {
      if (window.confirm('¿Desea CANCELAR esta orden?\n\nLa orden se moverá al apartado de "Canceladas" y los insumos regresarán al inventario.')) {
        onDeleteSale(saleId);
      }
    } else {
      onUpdateStatus(saleId, newStatus);
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">Gestión de Órdenes</h2>
          <p className="text-slate-500 dark:text-slate-400 font-medium">Control operativo de cocina y entregas.</p>
        </div>

        <div className="flex bg-white dark:bg-slate-900 p-1 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800">
          <button 
            onClick={() => { setActiveTab('activas'); setFilter('Todos'); }}
            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'activas' ? 'bg-slate-900 dark:bg-orange-600 text-white shadow-lg' : 'text-slate-400'}`}
          >
            Órdenes Activas
          </button>
          <button 
            onClick={() => { setActiveTab('canceladas'); setFilter('Todos'); }}
            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all relative ${activeTab === 'canceladas' ? 'bg-red-600 text-white shadow-lg' : 'text-slate-400'}`}
          >
            Canceladas
            {deletedSales.length > 0 && activeTab !== 'canceladas' && (
              <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-[9px] flex items-center justify-center rounded-full border-2 border-white dark:border-slate-950">
                {deletedSales.length}
              </span>
            )}
          </button>
        </div>
      </header>

      {/* Barra de Filtros Superior */}
      <div className="flex bg-white dark:bg-slate-900 p-2 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-x-auto custom-scrollbar">
        <button 
          onClick={() => setFilter('Todos')}
          className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === 'Todos' ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white' : 'text-slate-400'}`}
        >
          Todos
        </button>
        {statuses.map(s => (
          <button 
            key={s}
            onClick={() => {
              if (s === 'Cancelado' && activeTab === 'activas') {
                setActiveTab('canceladas');
                setFilter('Cancelado');
              } else {
                setFilter(s);
              }
            }}
            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === s ? (s === 'Cancelado' ? 'bg-red-100 dark:bg-red-900/30 text-red-600' : 'bg-orange-100 dark:bg-orange-900/30 text-orange-600') : 'text-slate-400'}`}
          >
            {s}
          </button>
        ))}
      </div>

      {activeTab === 'canceladas' && deletedSales.length > 0 && (
        <div className="flex justify-end">
          <button 
            onClick={onPurgeTrash}
            className="px-6 py-3 bg-red-50 text-red-600 border border-red-100 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all"
          >
            🗑️ Limpiar Historial Canceladas
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredSales.map(sale => (
          <div key={sale.id} className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col overflow-hidden hover:shadow-xl transition-all group">
            <div className="p-6 border-b border-slate-50 dark:border-slate-800">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Orden #{String(sale.id).slice(-6)}</span>
                  <h3 className="text-lg font-black text-slate-900 dark:text-white truncate">{sale.customerName}</h3>
                </div>
                <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase border tracking-widest ${getStatusColor(sale.status)}`}>
                  {sale.status}
