export default OrdersManager;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import OrdersManager from './components/OrdersManager';
import { View, Ingredient, MenuItem, Sale, Customer, SaleStatus, PaymentMethod } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('theme');
    return saved === 'dark' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [menuHeader, setMenuHeader] = useState<{title: string, description: string}>(() => {
    const saved = localStorage.getItem('menuHeader');
    return saved ? JSON.parse(saved) : {
      title: 'Nuestra Carta',
      description: 'Seleccionamos los mejores cortes y acompañamientos para brindarte una experiencia inigualable a la brasa.'
    };
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(() => {
    const saved = localStorage.getItem('availableUnits');
    return saved ? JSON.parse(saved) : ['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz'];
  });

  const [categories, setCategories] = useState<string[]>(() => {
    const saved = localStorage.getItem('categories');
    return saved ? JSON.parse(saved) : ['Cortes', 'Acompañamientos', 'Bebidas', 'Postres'];
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ 
      ...s, 
      timestamp: new Date(s.timestamp),
      status: s.status || 'Recibido',
      paymentMethod: s.paymentMethod || 'Efectivo'
    }));
  });

  const [deletedSales, setDeletedSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('deletedSales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ 
      ...s, 
      timestamp: new Date(s.timestamp)
    }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [
      { id: 'c1', name: 'Juan Pérez', email: 'juan@mail.com', phone: '3001234567', notes: 'Prefiere el lomo bien cocido.', orderHistory: [] },
      { id: 'c2', name: 'María García', email: 'maria@mail.com', phone: '3109876543', notes: 'Cliente frecuente los fines de semana.', orderHistory: [] }
    ];
  });

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }, [isDarkMode]);

  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('menuHeader', JSON.stringify(menuHeader)); }, [menuHeader]);
  useEffect(() => { localStorage.setItem('availableUnits', JSON.stringify(availableUnits)); }, [availableUnits]);
  useEffect(() => { localStorage.setItem('categories', JSON.stringify(categories)); }, [categories]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('deletedSales', JSON.stringify(deletedSales)); }, [deletedSales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const updateStock = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, Number(item.stock) + delta) } : item
    ));
  };

  const addSale = (
    saleItems: { menuItemId?: string, id?: string, quantity: number, customization?: string }[], 
    customerInfo?: { name: string, phone: string },
    paymentMethod: PaymentMethod = 'Efectivo'
  ) => {
    let total = 0;
    const itemsWithPrices = saleItems.map(si => {
      const menuItemId = si.menuItemId || si.id || '';
      const menuItem = menu.find(m => m.id === menuItemId);
      const price = menuItem ? menuItem.price : 0;
      const qty = si.quantity || 1;
      total += price * qty;

      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStock(ri.ingredientId, -(ri.amount * qty));
        });
      }

      return {
        menuItemId: menuItemId,
        quantity: qty,
        priceAtSale: price,
        customization: si.customization || ''
      };
    });

    const saleId = Date.now().toString();
    const newSale: Sale = {
      id: saleId,
      timestamp: new Date(),
      items: itemsWithPrices,
      total,
      customerName: customerInfo?.name || 'Cliente de Mostrador',
      status: 'Recibido',
      paymentMethod: paymentMethod
    };

    setSales(prev => [...prev, newSale]);
  };

  const deleteSale = (saleId: string) => {
    // Buscamos la venta en el estado actual de ventas
    const saleToDelete = sales.find(s => String(s.id) === String(saleId));
    if (!saleToDelete) return;

    // 1. Recuperar inventario
    const updatedIngredients = [...ingredients];
    saleToDelete.items.forEach(item => {
      const menuItem = menu.find(m => m.id === item.menuItemId);
      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          const ingIndex = updatedIngredients.findIndex(i => i.id === ri.ingredientId);
          if (ingIndex !== -1) {
            updatedIngredients[ingIndex].stock += (ri.amount * item.quantity);
          }
        });
      }
    });

    // 2. Actualizar estados de forma atómica
    setIngredients(updatedIngredients);
    setDeletedSales(prev => [...prev, { ...saleToDelete, status: 'Cancelado' }]);
    setSales(prev => prev.filter(s => String(s.id) !== String(saleId)));
  };

  const restoreSale = (saleId: string) => {
    const saleToRestore = deletedSales.find(s => String(s.id) === String(saleId));
    if (!saleToRestore) return;

    // 1. Descontar insumos nuevamente
    const updatedIngredients = [...ingredients];
    let canRestore = true;

    // Validación de stock antes de restaurar (opcional pero recomendado)
    saleToRestore.items.forEach(item => {
      const menuItem = menu.find(m => m.id === item.menuItemId);
      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          const ing = updatedIngredients.find(i => i.id === ri.ingredientId);
          if (ing && ing.stock < (ri.amount * item.quantity)) {
            // Se puede restaurar incluso con stock negativo si se prefiere, 
            // aquí simplemente procedemos a descontar.
          }
        });
      }
    });

    saleToRestore.items.forEach(item => {
      const menuItem = menu.find(m => m.id === item.menuItemId);
      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          const ingIndex = updatedIngredients.findIndex(i => i.id === ri.ingredientId);
          if (ingIndex !== -1) {
            updatedIngredients[ingIndex].stock -= (ri.amount * item.quantity);
          }
        });
      }
    });

    // 2. Mover a activas y quitar de eliminadas
    setIngredients(updatedIngredients);
    setSales(prev => [...prev, { ...saleToRestore, status: 'Recibido' }]);
    setDeletedSales(prev => prev.filter(s => String(s.id) !== String(saleId)));
  };

  const purgeTrash = () => {
    if(window.confirm('¿Vaciar el historial de canceladas? Esta acción es permanente.')) {
      setDeletedSales([]);
    }
  };

  const updateSaleStatus = (saleId: string, status: SaleStatus) => {
    // Si el estatus es 'Cancelado', delegamos a la función deleteSale que maneja la lógica de inventario
    if (status === 'Cancelado') {
      deleteSale(saleId);
      return;
    }
    setSales(prev => prev.map(s => String(s.id) === String(saleId) ? { ...s, status } : s));
  };

  const updateSale = (saleId: string, updatedData: Partial<Sale>) => {
    setSales(prev => prev.map(s => String(s.id) === String(saleId) ? { ...s, ...updatedData } : s));
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
      {view === 'online-order' ? (
        <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />
      ) : (
        <div className="flex flex-col lg:flex-row bg-slate-50 dark:bg-slate-950 min-h-screen text-slate-900 dark:text-slate-100 relative transition-colors duration-300">
          <Sidebar currentView={view} onNavigate={setView} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} isDarkMode={isDarkMode} onToggleTheme={toggleTheme} />
          <main className="flex-1 p-4 md:p-8 overflow-y-auto">
            <div className="max-w-6xl mx-auto">
              {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
              {view === 'orders' && (
                <OrdersManager 
                  sales={sales} 
                  deletedSales={deletedSales}
                  menu={menu} 
                  customers={customers} 
                  onUpdateStatus={updateSaleStatus}
                  onDeleteSale={deleteSale}
                  onRestoreSale={restoreSale}
                  onPurgeTrash={purgeTrash}
                  onUpdateSale={updateSale}
                />
              )}
              {view === 'inventory' && <Inventory ingredients={ingredients} availableUnits={availableUnits} onAddUnit={u => setAvailableUnits([...availableUnits, u])} onDeleteUnit={u => setAvailableUnits(availableUnits.filter(x => x !== u))} onUpdateStock={updateStock} onUpdateIngredient={(id, upd) => setIngredients(prev => prev.map(i => i.id === id ? {...i, ...upd} : i))} onAddIngredient={i => setIngredients([...ingredients, {...i, id: 'ing-'+Date.now()}])} onDeleteIngredient={id => setIngredients(ingredients.filter(i => i.id !== id))} />}
              {view === 'menu' && <Menu menu={menu} header={menuHeader} onUpdateHeader={setMenuHeader} onQuickOrder={addSale} />}
              {view === 'prices' && <PriceManager menu={menu} ingredients={ingredients} categories={categories} onAddCategory={c => setCategories([...categories, c])} onDeleteCategory={c => setCategories(categories.filter(x => x !== c))} onUpdatePrice={(id, p) => setMenu(prev => prev.map(m => m.id === id ? {...m, price: p} : m))} onUpdateRecipe={(id, r, p, n, cat, d, img, act) => setMenu(prev => prev.map(m => m.id === id ? {...m, recipe: r, price: p, name: n, category: cat, description: d, image: img, isActive: act} : m))} onAddMenuItem={i => setMenu([...menu, {...i, id: 'm-'+Date.now()}])} onDeleteMenuItem={id => setMenu(menu.filter(m => m.id !== id))} />}
              {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items, pm) => addSale(items, undefined, pm)} />}
              {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
              {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
              {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
            </div>
          </main>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Sale, MenuItem, Customer, SaleStatus, PaymentMethod } from '../types';

interface OrdersManagerProps {
  sales: Sale[];
  deletedSales?: Sale[];
  menu: MenuItem[];
  customers: Customer[];
  onUpdateStatus: (saleId: string, status: SaleStatus) => void;
  onDeleteSale: (saleId: string) => void;
  onRestoreSale?: (saleId: string) => void;
  onPurgeTrash?: () => void;
  onUpdateSale: (saleId: string, updatedData: Partial<Sale>) => void;
}

const OrdersManager: React.FC<OrdersManagerProps> = ({ 
  sales, 
  deletedSales = [],
  menu, 
  customers, 
  onUpdateStatus,
  onDeleteSale,
  onRestoreSale,
  onPurgeTrash,
  onUpdateSale 
}) => {
  const [activeTab, setActiveTab] = useState<'activas' | 'canceladas'>('activas');
  const [filter, setFilter] = useState<SaleStatus | 'Todos'>('Todos');

  // Lista de estados operativos incluyendo 'Cancelado' como opción final
  const statuses: SaleStatus[] = ['Recibido', 'Preparacion', 'Listo', 'Enviado', 'Entregado', 'Cancelado'];

  const getStatusColor = (status: SaleStatus) => {
    switch (status) {
      case 'Recibido': return 'bg-slate-100 text-slate-600 border-slate-200';
      case 'Preparacion': return 'bg-orange-50 text-orange-600 border-orange-200';
      case 'Listo': return 'bg-green-50 text-green-600 border-green-200';
      case 'Enviado': return 'bg-blue-50 text-blue-600 border-blue-200';
      case 'Entregado': return 'bg-slate-900 text-white border-slate-900';
      case 'Cancelado': return 'bg-red-600 text-white border-red-600';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const filteredSales = (activeTab === 'activas' ? sales : deletedSales)
    .filter(s => filter === 'Todos' || s.status === filter)
    .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());

  // Manejador centralizado para cambios de estado
  const handleAction = (saleId: string, newStatus: SaleStatus) => {
    if (newStatus === 'Cancelado') {
      const confirmCancel = window.confirm(
        '¿MARCAR ESTA ORDEN COMO CANCELADA?\n\nLa orden se moverá al registro de canceladas y los ingredientes volverán al inventario automáticamente.'
      );
      if (confirmCancel) {
        onUpdateStatus(saleId, 'Cancelado');
      }
    } else {
      onUpdateStatus(saleId, newStatus);
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">Gestión de Órdenes</h2>
          <p className="text-slate-500 dark:text-slate-400 font-medium">Control operativo de flujo de trabajo.</p>
        </div>

        <div className="flex bg-white dark:bg-slate-900 p-1 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800">
          <button 
            onClick={() => { setActiveTab('activas'); setFilter('Todos'); }}
            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'activas' ? 'bg-slate-900 dark:bg-orange-600 text-white shadow-lg' : 'text-slate-400'}`}
          >
            Órdenes Activas
          </button>
          <button 
            onClick={() => { setActiveTab('canceladas'); setFilter('Todos'); }}
            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all relative ${activeTab === 'canceladas' ? 'bg-red-600 text-white shadow-lg' : 'text-slate-400'}`}
          >
            Canceladas
            {deletedSales.length > 0 && activeTab !== 'canceladas' && (
              <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-[9px] flex items-center justify-center rounded-full border-2 border-white dark:border-slate-950">
                {deletedSales.length}
              </span>
            )}
          </button>
        </div>
      </header>

      {/* Filtros de Estado */}
      <div className="flex bg-white dark:bg-slate-900 p-2 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-x-auto custom-scrollbar">
        <button 
          onClick={() => setFilter('Todos')}
          className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === 'Todos' ? 'bg-slate-100 dark:bg-slate-800 text-slate-900 dark:text-white' : 'text-slate-400'}`}
        >
          Todos
        </button>
        {statuses.map(s => (
          <button 
            key={s}
            onClick={() => {
              if (s === 'Cancelado') {
                setActiveTab('canceladas');
                setFilter('Cancelado');
              } else {
                setFilter(s);
              }
            }}
            className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${filter === s ? (s === 'Cancelado' ? 'bg-red-100 dark:bg-red-900/30 text-red-600' : 'bg-orange-100 dark:bg-orange-900/30 text-orange-600') : 'text-slate-400'}`}
          >
            {s}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredSales.map(sale => (
          <div key={sale.id} className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col overflow-hidden hover:shadow-xl transition-all group">
            <div className="p-6 border-b border-slate-50 dark:border-slate-800">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-1">Orden #{String(sale.id).slice(-6)}</span>
                  <h3 className="text-lg font-black text-slate-900 dark:text-white truncate">{sale.customerName}</h3>
                </div>
                <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase border tracking-widest ${getStatusColor(sale.status)}`}>
                  {sale.status}
                </div>
              </div>
              <div className="flex items-center justify-between mt-2">
                <span className="text-xs font-bold text-slate-400">🕒 {sale.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                <span className="px-3 py-1 bg-slate-50 dark:bg-slate-800 rounded-lg text-[10px] font-black uppercase text-slate-500">
                  {sale.paymentMethod}
                </span>
              </div>
            </div>

            <div className="p-6 flex-1 space-y-4">
              <div className="space-y-2 max-h-32 overflow-y-auto custom-scrollbar pr-1">
                {sale.items.map((item, idx) => {
                  const menuItem = menu.find(m => m.id === item.menuItemId);
                  return (
                    <div key={idx} className="flex justify-between items-center text-sm">
                      <span className="font-bold text-slate-700 dark:text-slate-300 line-clamp-1 flex-1 mr-4">
                        {item.quantity}x {menuItem?.name || 'Producto'}
                      </span>
                      <span className="font-bold text-slate-400 shrink-0">L. {(item.priceAtSale * item.quantity).toFixed(2)}</span>
                    </div>
                  );
                })}
              </div>
              <div className="pt-4 border-t border-slate-50 dark:border-slate-800 flex justify-between items-center">
                <span className="text-xs font-black text-slate-400 uppercase tracking-widest">Total</span>
                <span className="text-xl font-black text-slate-900 dark:text-white">L. {sale.total.toFixed(2)}</span>
              </div>
            </div>

            <div className="p-6 bg-slate-50 dark:bg-slate-800/30 border-t border-slate-100 dark:border-slate-800">
              {activeTab === 'activas' ? (
                <div className="space-y-4">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 text-center">Cambiar Estatus</p>
                  <div className="flex flex-wrap gap-2 justify-center">
                    {statuses.map(s => (
                      <button
                        key={s}
                        onClick={(e) => {
                          e.stopPropagation();
                          handleAction(sale.id, s);
                        }}
                        className={`px-3 py-1.5 rounded-lg text-[8px] font-black uppercase transition-all border ${
                          sale.status === s 
                          ? 'bg-orange-500 text-white border-orange-500 shadow-md scale-105' 
                          : s === 'Cancelado'
                            ? 'bg-red-50 text-red-600 border-red-100 hover:bg-red-600 hover:text-white'
                            : 'bg-white dark:bg-slate-800 text-slate-400 border-slate-200 dark:border-slate-700 hover:border-orange-500 hover:text-orange-600'
                        }`}
                      >
                        {s}
                      </button>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="flex gap-2">
                  <button 
                    onClick={() => onRestoreSale && onRestoreSale(sale.id)}
                    className="flex-1 py-3 bg-green-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-green-700 shadow-lg active:scale-95"
                  >
                    ⚡ Restaurar Pedido
                  </button>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {activeTab === 'canceladas' && filteredSales.length > 0 && (
        <div className="mt-12 flex justify-center">
          <button 
            onClick={onPurgeTrash}
            className="px-10 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-[0.2em] hover:bg-red-600 transition-all shadow-xl"
          >
            Vaciar Papelera de Canceladas
          </button>
        </div>
      )}

      {filteredSales.length === 0 && (
        <div className="py-24 text-center bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-slate-800">
          <div className="text-6xl mb-4 opacity-20">📭</div>
          <p className="text-slate-400 font-bold text-xl uppercase tracking-widest">No hay órdenes en esta sección</p>
        </div>
      )}
    </div>
  );
};

export default OrdersManager;

export interface Ingredient {
  id: string;
  name: string;
  unit: string;
  stock: number;
  minStock: number;
  costPerUnit: number;
}

export type SaleStatus = 'Recibido' | 'En Cocina' | 'Listo' | 'Entregado' | 'Cancelado';
export type PaymentMethod = 'Efectivo' | 'Transferencia' | 'Tarjeta';

export interface MenuItem {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image?: string;
  isActive?: boolean;
  recipe: {
    ingredientId: string;
    amount: number;
  }[];
}

export interface Customer {
  id: string;
  name: string;
  email: string;
  phone: string;
  notes: string;
  orderHistory: string[];
}

export interface Sale {
  id: string;
  timestamp: Date;
  customerId?: string;
  customerName?: string;
  items: {
    menuItemId: string;
    quantity: number;
    priceAtSale: number;
    customization?: string;
  }[];
  total: number;
  status: SaleStatus;
  paymentMethod: PaymentMethod;
}

export type View = 'dashboard' | 'inventory' | 'menu' | 'prices' | 'sales' | 'analysis' | 'reports' | 'customers' | 'online-order' | 'orders';

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Inventory from './components/Inventory';
import Menu from './components/Menu';
import PriceManager from './components/PriceManager';
import SalesManager from './components/SalesManager';
import AnalysisView from './components/AnalysisView';
import Reports from './components/Reports';
import CustomerManager from './components/CustomerManager';
import OnlineOrder from './components/OnlineOrder';
import OrdersManager from './components/OrdersManager';
import { View, Ingredient, MenuItem, Sale, Customer, SaleStatus, PaymentMethod } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('theme');
    return saved === 'dark' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ 
      ...s, 
      timestamp: new Date(s.timestamp),
      status: s.status || 'Recibido'
    }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [];
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz']);
  const [categories, setCategories] = useState<string[]>(['Cortes', 'Acompañamientos', 'Bebidas', 'Postres']);
  const [menuHeader, setMenuHeader] = useState({ title: 'Nuestra Carta', description: 'Sabor a la brasa.' });

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const updateStockManually = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, Number(item.stock) + delta) } : item
    ));
  };

  const addSale = (
    saleItems: { menuItemId?: string, id?: string, quantity: number, customization?: string }[], 
    customerInfo?: { name: string, phone: string },
    paymentMethod: PaymentMethod = 'Efectivo'
  ) => {
    const itemsWithPrices = saleItems.map(si => {
      const menuItemId = si.menuItemId || si.id || '';
      const menuItem = menu.find(m => m.id === menuItemId);
      const qty = si.quantity || 1;

      // Descontar stock inicial
      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStockManually(ri.ingredientId, -(ri.amount * qty));
        });
      }

      return {
        menuItemId: menuItemId,
        quantity: qty,
        priceAtSale: menuItem?.price || 0,
        customization: si.customization || ''
      };
    });

    const newSale: Sale = {
      id: Date.now().toString(),
      timestamp: new Date(),
      items: itemsWithPrices,
      total: itemsWithPrices.reduce((acc, curr) => acc + (curr.priceAtSale * curr.quantity), 0),
      customerName: customerInfo?.name || 'Cliente Mostrador',
      status: 'Recibido',
      paymentMethod
    };

    setSales(prev => [...prev, newSale]);
  };

  const updateSaleStatus = (saleId: string, newStatus: SaleStatus) => {
    setSales(prevSales => {
      const saleIndex = prevSales.findIndex(s => s.id === saleId);
      if (saleIndex === -1) return prevSales;

      const oldSale = prevSales[saleIndex];
      const oldStatus = oldSale.status;

      // Lógica de Inventario:
      // 1. Si cambia a CANCELADO -> Devolvemos productos
      if (newStatus === 'Cancelado' && oldStatus !== 'Cancelado') {
        const updatedIngredients = [...ingredients];
        oldSale.items.forEach(item => {
          const menuItem = menu.find(m => m.id === item.menuItemId);
          if (menuItem) {
            menuItem.recipe.forEach(ri => {
              const ingIndex = updatedIngredients.findIndex(i => i.id === ri.ingredientId);
              if (ingIndex !== -1) updatedIngredients[ingIndex].stock += (ri.amount * item.quantity);
            });
          }
        });
        setIngredients(updatedIngredients);
      } 
      // 2. Si estaba CANCELADO y vuelve a la vida -> Volvemos a descontar
      else if (oldStatus === 'Cancelado' && newStatus !== 'Cancelado') {
        const updatedIngredients = [...ingredients];
        oldSale.items.forEach(item => {
          const menuItem = menu.find(m => m.id === item.menuItemId);
          if (menuItem) {
            menuItem.recipe.forEach(ri => {
              const ingIndex = updatedIngredients.findIndex(i => i.id === ri.ingredientId);
              if (ingIndex !== -1) updatedIngredients[ingIndex].stock -= (ri.amount * item.quantity);
            });
          }
        });
        setIngredients(updatedIngredients);
      }

      const updatedSales = [...prevSales];
      updatedSales[saleIndex] = { ...oldSale, status: newStatus };
      return updatedSales;
    });
  };

  const deleteSalePermanently = (id: string) => {
    if (window.confirm('¿Eliminar registro permanentemente? Esto no afectará el inventario actual.')) {
      setSales(prev => prev.filter(s => s.id !== id));
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
      {view === 'online-order' ? (
        <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />
      ) : (
        <div className="flex flex-col lg:flex-row bg-slate-50 dark:bg-slate-950 min-h-screen text-slate-900 dark:text-slate-100 relative">
          <Sidebar currentView={view} onNavigate={setView} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} isDarkMode={isDarkMode} onToggleTheme={() => setIsDarkMode(!isDarkMode)} />
          <main className="flex-1 p-4 md:p-8 overflow-y-auto">
            <div className="max-w-6xl mx-auto">
              {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
              {view === 'orders' && (
                <OrdersManager 
                  sales={sales} 
                  menu={menu} 
                  onUpdateStatus={updateSaleStatus}
                  onDeleteSale={deleteSalePermanently}
                />
              )}
              {view === 'inventory' && <Inventory ingredients={ingredients} availableUnits={availableUnits} onAddUnit={u => setAvailableUnits([...availableUnits, u])} onDeleteUnit={u => setAvailableUnits(availableUnits.filter(x => x !== u))} onUpdateStock={updateStockManually} onUpdateIngredient={(id, upd) => setIngredients(prev => prev.map(i => i.id === id ? {...i, ...upd} : i))} onAddIngredient={i => setIngredients([...ingredients, {...i, id: 'ing-'+Date.now()}])} onDeleteIngredient={id => setIngredients(ingredients.filter(i => i.id !== id))} />}
              {view === 'menu' && <Menu menu={menu} header={menuHeader} onUpdateHeader={setMenuHeader} onQuickOrder={addSale} />}
              {view === 'prices' && <PriceManager menu={menu} ingredients={ingredients} categories={categories} onAddCategory={c => setCategories([...categories, c])} onDeleteCategory={c => setCategories(categories.filter(x => x !== c))} onUpdatePrice={(id, p) => setMenu(prev => prev.map(m => m.id === id ? {...m, price: p} : m))} onUpdateRecipe={(id, r, p, n, cat, d, img, act) => setMenu(prev => prev.map(m => m.id === id ? {...m, recipe: r, price: p, name: n, category: cat, description: d, image: img, isActive: act} : m))} onAddMenuItem={i => setMenu([...menu, {...i, id: 'm-'+Date.now()}])} onDeleteMenuItem={id => setMenu(menu.filter(m => m.id !== id))} />}
              {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items, pm) => addSale(items, undefined, pm)} />}
              {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
              {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
              {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
            </div>
          </main>
        </div>
      )}
    </div>
  );
};

