import { View, Ingredient, MenuItem, Sale, Customer, SaleStatus, PaymentMethod } from './types';
import { INITIAL_INGREDIENTS, INITIAL_MENU } from './constants';

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem('theme');
    return saved === 'dark' || (!saved && window.matchMedia('(prefers-color-scheme: dark)').matches);
  });

  const [ingredients, setIngredients] = useState<Ingredient[]>(() => {
    const saved = localStorage.getItem('ingredients');
    return saved ? JSON.parse(saved) : INITIAL_INGREDIENTS;
  });

  const [menu, setMenu] = useState<MenuItem[]>(() => {
    const saved = localStorage.getItem('menu');
    return saved ? JSON.parse(saved) : INITIAL_MENU;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('sales');
    if (!saved) return [];
    const parsed = JSON.parse(saved);
    return parsed.map((s: any) => ({ 
      ...s, 
      timestamp: new Date(s.timestamp),
      status: s.status || 'Recibido'
    }));
  });

  const [customers, setCustomers] = useState<Customer[]>(() => {
    const saved = localStorage.getItem('customers');
    return saved ? JSON.parse(saved) : [];
  });

  const [availableUnits, setAvailableUnits] = useState<string[]>(['kg', 'g', 'unit', 'lt', 'ml', 'lb', 'oz']);
  const [categories, setCategories] = useState<string[]>(['Cortes', 'Acompañamientos', 'Bebidas', 'Postres']);
  const [menuHeader, setMenuHeader] = useState({ title: 'Nuestra Carta', description: 'Sabor a la brasa.' });

  useEffect(() => {
    document.documentElement.classList.toggle('dark', isDarkMode);
    localStorage.setItem('theme', isDarkMode ? 'dark' : 'light');
  }, [isDarkMode]);

  useEffect(() => { localStorage.setItem('ingredients', JSON.stringify(ingredients)); }, [ingredients]);
  useEffect(() => { localStorage.setItem('menu', JSON.stringify(menu)); }, [menu]);
  useEffect(() => { localStorage.setItem('sales', JSON.stringify(sales)); }, [sales]);
  useEffect(() => { localStorage.setItem('customers', JSON.stringify(customers)); }, [customers]);

  const updateStockManually = (id: string, delta: number) => {
    setIngredients(prev => prev.map(item => 
      item.id === id ? { ...item, stock: Math.max(0, Number(item.stock) + delta) } : item
    ));
  };

  const addSale = (
    saleItems: { menuItemId?: string, id?: string, quantity: number, customization?: string }[], 
    customerInfo?: { name: string, phone: string },
    paymentMethod: PaymentMethod = 'Efectivo'
  ) => {
    const itemsWithPrices = saleItems.map(si => {
      const menuItemId = si.menuItemId || si.id || '';
      const menuItem = menu.find(m => m.id === menuItemId);
      const qty = si.quantity || 1;

      // Descontar stock inicial al recibir la orden
      if (menuItem) {
        menuItem.recipe.forEach(ri => {
          updateStockManually(ri.ingredientId, -(ri.amount * qty));
        });
      }

      return {
        menuItemId: menuItemId,
        quantity: qty,
        priceAtSale: menuItem?.price || 0,
        customization: si.customization || ''
      };
    });

    const newSale: Sale = {
      id: Date.now().toString(),
      timestamp: new Date(),
      items: itemsWithPrices,
      total: itemsWithPrices.reduce((acc, curr) => acc + (curr.priceAtSale * curr.quantity), 0),
      customerName: customerInfo?.name || 'Cliente Mostrador',
      status: 'Recibido',
      paymentMethod
    };

    setSales(prev => [...prev, newSale]);
  };

  const updateSaleStatus = (saleId: string, newStatus: SaleStatus) => {
    setSales(prevSales => {
      const saleIndex = prevSales.findIndex(s => s.id === saleId);
      if (saleIndex === -1) return prevSales;

      const oldSale = prevSales[saleIndex];
      const oldStatus = oldSale.status;

      // Lógica de Inventario:
      // 1. Si cambia a CANCELADO desde cualquier estado activo -> Devolvemos productos
      if (newStatus === 'Cancelado' && oldStatus !== 'Cancelado') {
        const updatedIngredients = [...ingredients];
        oldSale.items.forEach(item => {
          const menuItem = menu.find(m => m.id === item.menuItemId);
          if (menuItem) {
            menuItem.recipe.forEach(ri => {
              const ingIndex = updatedIngredients.findIndex(i => i.id === ri.ingredientId);
              if (ingIndex !== -1) updatedIngredients[ingIndex].stock += (ri.amount * item.quantity);
            });
          }
        });
        setIngredients(updatedIngredients);
      } 
      // 2. Si estaba CANCELADO y se reactiva (Undo de cancelación o Reabrir) -> Volvemos a descontar
      else if (oldStatus === 'Cancelado' && newStatus !== 'Cancelado') {
        const updatedIngredients = [...ingredients];
        oldSale.items.forEach(item => {
          const menuItem = menu.find(m => m.id === item.menuItemId);
          if (menuItem) {
            menuItem.recipe.forEach(ri => {
              const ingIndex = updatedIngredients.findIndex(i => i.id === ri.ingredientId);
              if (ingIndex !== -1) updatedIngredients[ingIndex].stock -= (ri.amount * item.quantity);
            });
          }
        });
        setIngredients(updatedIngredients);
      }

      const updatedSales = [...prevSales];
      updatedSales[saleIndex] = { ...oldSale, status: newStatus };
      return updatedSales;
    });
  };

  const deleteSalePermanently = (id: string) => {
    if (window.confirm('¿Eliminar registro permanentemente? Esto no afectará el inventario actual.')) {
      setSales(prev => prev.filter(s => s.id !== id));
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
      {view === 'online-order' ? (
        <OnlineOrder menu={menu} onPlaceOrder={addSale} onBackToAdmin={() => setView('dashboard')} />
      ) : (
        <div className="flex flex-col lg:flex-row bg-slate-50 dark:bg-slate-950 min-h-screen text-slate-900 dark:text-slate-100 relative">
          <Sidebar currentView={view} onNavigate={setView} isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} isDarkMode={isDarkMode} onToggleTheme={() => setIsDarkMode(!isDarkMode)} />
          <main className="flex-1 p-4 md:p-8 overflow-y-auto">
            <div className="max-w-6xl mx-auto">
              {view === 'dashboard' && <Dashboard ingredients={ingredients} sales={sales} menu={menu} />}
              {view === 'orders' && (
                <OrdersManager 
                  sales={sales} 
                  menu={menu} 
                  onUpdateStatus={updateSaleStatus}
                  onDeleteSale={deleteSalePermanently}
                />
              )}
              {view === 'inventory' && <Inventory ingredients={ingredients} availableUnits={availableUnits} onAddUnit={u => setAvailableUnits([...availableUnits, u])} onDeleteUnit={u => setAvailableUnits(availableUnits.filter(x => x !== u))} onUpdateStock={updateStockManually} onUpdateIngredient={(id, upd) => setIngredients(prev => prev.map(i => i.id === id ? {...i, ...upd} : i))} onAddIngredient={i => setIngredients([...ingredients, {...i, id: 'ing-'+Date.now()}])} onDeleteIngredient={id => setIngredients(ingredients.filter(i => i.id !== id))} />}
              {view === 'menu' && <Menu menu={menu} header={menuHeader} onUpdateHeader={setMenuHeader} onQuickOrder={addSale} />}
              {view === 'prices' && <PriceManager menu={menu} ingredients={ingredients} categories={categories} onAddCategory={c => setCategories([...categories, c])} onDeleteCategory={c => setCategories(categories.filter(x => x !== c))} onUpdatePrice={(id, p) => setMenu(prev => prev.map(m => m.id === id ? {...m, price: p} : m))} onUpdateRecipe={(id, r, p, n, cat, d, img, act) => setMenu(prev => prev.map(m => m.id === id ? {...m, recipe: r, price: p, name: n, category: cat, description: d, image: img, isActive: act} : m))} onAddMenuItem={i => setMenu([...menu, {...i, id: 'm-'+Date.now()}])} onDeleteMenuItem={id => setMenu(menu.filter(m => m.id !== id))} />}
              {view === 'sales' && <SalesManager sales={sales} menu={menu} onAddSale={(items, pm) => addSale(items, undefined, pm)} />}
              {view === 'analysis' && <AnalysisView ingredients={ingredients} menu={menu} sales={sales} />}
              {view === 'reports' && <Reports sales={sales} ingredients={ingredients} menu={menu} />}
              {view === 'customers' && <CustomerManager customers={customers} sales={sales} menu={menu} />}
            </div>
          </main>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Ingredient } from '../types';

interface InventoryProps {
  ingredients: Ingredient[];
  availableUnits: string[];
  onAddUnit: (unit: string) => void;
  onDeleteUnit: (unit: string) => void;
  onUpdateStock: (id: string, amount: number) => void;
  onUpdateIngredient: (id: string, updates: Partial<Ingredient>) => void;
  onAddIngredient: (ingredient: Omit<Ingredient, 'id'>) => void;
  onDeleteIngredient: (id: string) => void;
}

const ITEMS_PER_PAGE = 8;

const Inventory: React.FC<InventoryProps> = ({ 
  ingredients, 
  availableUnits,
  onAddUnit,
  onDeleteUnit,
  onUpdateStock, 
  onUpdateIngredient, 
  onAddIngredient, 
  onDeleteIngredient 
}) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [showUnitManager, setShowUnitManager] = useState(false);
  const [newUnitInput, setNewUnitInput] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editValues, setEditValues] = useState<Partial<Ingredient>>({});
  const [deleteConfirmItem, setDeleteConfirmItem] = useState<Ingredient | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<'all' | 'low'>('all');
  const [currentPage, setCurrentPage] = useState(1);

  const [newIng, setNewIng] = useState({
    name: '',
    unit: availableUnits[0] || 'kg',
    stock: 0,
    minStock: 0,
    costPerUnit: 0
  });

  const filteredIngredients = useMemo(() => {
    return ingredients.filter(ing => {
      const matchesSearch = ing.name.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesFilter = filterType === 'all' || ing.stock <= ing.minStock;
      return matchesSearch && matchesFilter;
    });
  }, [ingredients, searchTerm, filterType]);

  const totalPages = Math.ceil(filteredIngredients.length / ITEMS_PER_PAGE);
  const paginatedIngredients = filteredIngredients.slice(
    (currentPage - 1) * ITEMS_PER_PAGE,
    currentPage * ITEMS_PER_PAGE
  );

  const handleAddSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddIngredient(newIng);
    setNewIng({ name: '', unit: availableUnits[0] || 'kg', stock: 0, minStock: 0, costPerUnit: 0 });
    setShowAddForm(false);
  };

  const handleAddUnit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newUnitInput.trim()) {
      onAddUnit(newUnitInput);
      setNewUnitInput('');
    }
  };

  const startEditing = (item: Ingredient) => {
    setEditingId(item.id);
    setEditValues({ ...item });
  };

  const saveEdit = (id: string) => {
    onUpdateIngredient(id, editValues);
    setEditingId(null);
    setEditValues({});
  };

  const totalValue = ingredients.reduce((sum, item) => sum + (item.stock * item.costPerUnit), 0);

  return (
    <div className="space-y-8 animate-fadeIn pb-20">
      {/* Modales y Confirmaciones (Se mantienen por funcionalidad) */}
      {showUnitManager && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md">
          <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 max-w-md w-full shadow-2xl border border-slate-200 dark:border-slate-800 animate-scaleIn">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-black text-slate-900 dark:text-white uppercase tracking-tight">Unidades de Medida</h3>
              <button onClick={() => setShowUnitManager(false)} className="text-slate-400 hover:text-slate-900 dark:hover:text-white p-2">✕</button>
            </div>
            <form onSubmit={handleAddUnit} className="flex gap-2 mb-6">
              <input 
                type="text" 
                placeholder="Nueva unidad..."
                className="flex-1 bg-slate-50 dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-700 rounded-xl px-4 py-2.5 text-sm font-bold outline-none focus:border-orange-500 dark:text-white"
                value={newUnitInput}
                onChange={(e) => setNewUnitInput(e.target.value)}
              />
              <button type="submit" className="bg-orange-600 text-white px-6 py-2.5 rounded-xl font-black text-[10px] uppercase hover:bg-orange-700 transition-all shadow-lg shadow-orange-900/20">Añadir</button>
            </form>
            <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar pr-2">
              {availableUnits.map(unit => (
                <div key={unit} className="flex justify-between items-center p-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl border border-slate-100 dark:border-slate-800 group transition-all hover:border-orange-200">
                  <span className="font-bold text-slate-700 dark:text-slate-300 uppercase text-[10px] tracking-widest">{unit}</span>
                  <button onClick={() => onDeleteUnit(unit)} className="text-red-400 hover:text-red-600 transition-colors opacity-0 group-hover:opacity-100">🗑️</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {deleteConfirmItem && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
          <div className="bg-white dark:bg-slate-900 rounded-[3rem] p-10 max-w-sm w-full shadow-2xl text-center animate-scaleIn border border-slate-200 dark:border-slate-800">
            <div className="w-20 h-20 bg-red-100 dark:bg-red-900/30 text-red-600 rounded-full flex items-center justify-center text-4xl mb-6 mx-auto">🗑️</div>
            <h3 className="text-xl font-black text-slate-900 dark:text-white mb-2">¿Eliminar Insumo?</h3>
            <p className="text-slate-500 dark:text-slate-400 text-sm mb-8 leading-relaxed">Se perderán todos los datos vinculados a <b>"{deleteConfirmItem.name}"</b>.</p>
            <div className="flex gap-3">
              <button onClick={() => setDeleteConfirmItem(null)} className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-2xl font-black text-[10px] uppercase tracking-widest">Atrás</button>
              <button onClick={() => { onDeleteIngredient(deleteConfirmItem.id); setDeleteConfirmItem(null); }} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-red-900/20">Eliminar</button>
            </div>
          </div>
        </div>
      )}

      {/* Resumen Superior */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        <div className="bg-slate-900 dark:bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-2xl border border-slate-800 relative overflow-hidden group">
          <div className="absolute -right-4 -top-4 w-32 h-32 bg-orange-600/10 rounded-full blur-3xl group-hover:bg-orange-600/20 transition-all"></div>
          <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Valor Total Invertido</p>
          <p className="text-4xl font-black text-white">L. {totalValue.toLocaleString()}</p>
        </div>
        <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Items Registrados</p>
          <p className="text-4xl font-black text-slate-900 dark:text-white">{ingredients.length}</p>
        </div>
        <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.3em] mb-2">Alertas de Stock</p>
          <p className={`text-4xl font-black ${ingredients.filter(i => i.stock <= i.minStock).length > 0 ? 'text-red-500' : 'text-green-600'}`}>
            {ingredients.filter(i => i.stock <= i.minStock).length}
          </p>
        </div>
      </div>

      {/* Barra de Acciones y Búsqueda */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-100 dark:border-slate-800 shadow-sm">
        <div className="relative w-full md:w-96 group">
          <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors">🔍</span>
          <input 
            type="text" 
            placeholder="Filtrar por nombre de insumo..."
            className="w-full bg-slate-50 dark:bg-slate-800 border-2 border-transparent focus:border-orange-500 focus:bg-white dark:focus:bg-slate-950 rounded-[1.5rem] py-4 pl-14 pr-6 outline-none transition-all font-bold text-slate-900 dark:text-white text-sm"
            value={searchTerm}
            onChange={(e) => { setSearchTerm(e.target.value); setCurrentPage(1); }}
          />
        </div>
        <div className="flex items-center gap-2 w-full md:w-auto">
          <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-2xl border border-slate-200 dark:border-slate-700">
            <button onClick={() => { setFilterType('all'); setCurrentPage(1); }} className={`px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${filterType === 'all' ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm' : 'text-slate-400'}`}>Todos</button>
            <button onClick={() => { setFilterType('low'); setCurrentPage(1); }} className={`px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${filterType === 'low' ? 'bg-red-600 text-white shadow-lg' : 'text-slate-400'}`}>Stock Bajo</button>
          </div>
          <button onClick={() => setShowAddForm(!showAddForm)} className="flex-1 md:flex-none bg-slate-900 dark:bg-orange-600 text-white px-8 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-[0.2em] shadow-xl hover:bg-orange-500 transition-all active:scale-95">
            Nuevo Insumo
          </button>
        </div>
      </div>

      {/* Formulario de Adición Rápida */}
      {showAddForm && (
        <form onSubmit={handleAddSubmit} className="bg-orange-50 dark:bg-orange-950/20 border border-orange-100 dark:border-orange-900/30 p-8 rounded-[2.5rem] grid grid-cols-1 md:grid-cols-4 gap-6 animate-fadeIn">
          <div className="md:col-span-2">
            <label className="block text-[10px] font-black uppercase text-orange-700 dark:text-orange-500 mb-2 ml-1 tracking-widest">Nombre del Insumo</label>
            <input required type="text" className="w-full p-4 rounded-2xl border-2 border-orange-200 dark:border-orange-900/40 focus:outline-none focus:border-orange-500 font-bold bg-white dark:bg-slate-900 dark:text-white" placeholder="Ej: Lomo de Res" value={newIng.name} onChange={e => setNewIng({...newIng, name: e.target.value})} />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-orange-700 dark:text-orange-500 mb-2 ml-1 tracking-widest">Unidad</label>
            <select className="w-full p-4 rounded-2xl border-2 border-orange-200 dark:border-orange-900/40 focus:outline-none focus:border-orange-500 font-bold bg-white dark:bg-slate-900 dark:text-white" value={newIng.unit} onChange={e => setNewIng({...newIng, unit: e.target.value})}>
              {availableUnits.map(unit => <option key={unit} value={unit}>{unit.toUpperCase()}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-orange-700 dark:text-orange-500 mb-2 ml-1 tracking-widest">Costo Unitario</label>
            <input required type="number" step="0.01" className="w-full p-4 rounded-2xl border-2 border-orange-200 dark:border-orange-900/40 focus:outline-none focus:border-orange-500 font-bold bg-white dark:bg-slate-900 dark:text-white" value={newIng.costPerUnit} onChange={e => setNewIng({...newIng, costPerUnit: parseFloat(e.target.value) || 0})} />
          </div>
          <button type="submit" className="md:col-start-4 bg-orange-600 text-white p-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] hover:bg-orange-700 transition-all shadow-xl shadow-orange-900/20">Registrar Insumo</button>
        </form>
      )}

      {/* Tabla Moderna y Responsive */}
      <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden">
        <div className="overflow-x-auto no-scrollbar">
          <table className="w-full text-left min-w-[800px]">
            <thead>
              <tr className="bg-slate-50 dark:bg-slate-800/50 text-slate-400 dark:text-slate-500 text-[10px] font-black uppercase tracking-[0.25em]">
                <th className="px-10 py-6">Insumo</th>
                <th className="px-6 py-6 text-center">Stock Actual</th>
                <th className="px-6 py-6 text-center">Unidad</th>
                <th className="px-6 py-6 text-center">Costo Unit.</th>
                <th className="px-6 py-6 text-center">Valor Stock</th>
                <th className="px-10 py-6 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 dark:divide-slate-800">
              {paginatedIngredients.map((item) => {
                const isEditing = editingId === item.id;
                const isCritical = item.stock <= item.minStock;
                const itemTotalValue = item.stock * item.costPerUnit;

                return (
                  <tr key={item.id} className={`${isEditing ? 'bg-orange-50/40 dark:bg-orange-900/10' : 'hover:bg-slate-50/40 dark:hover:bg-slate-800/20'} transition-colors group`}>
                    <td className="px-10 py-6">
                      {isEditing ? (
                        <input 
                          type="text" 
                          className="w-full p-3 bg-white dark:bg-slate-900 border-2 border-orange-500 rounded-xl text-sm font-black outline-none dark:text-white" 
                          value={editValues.name || ''} 
                          onChange={(e) => setEditValues({ ...editValues, name: e.target.value })} 
                          autoFocus 
                        />
                      ) : (
                        <div className="flex items-center gap-4">
                          <div className={`w-2 h-2 rounded-full shrink-0 ${isCritical ? 'bg-red-500 animate-pulse' : 'bg-green-500'}`}></div>
                          <div>
                            <p className="font-black text-slate-900 dark:text-white text-base tracking-tight">{item.name}</p>
                            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-0.5">Mínimo: {item.minStock} {item.unit}</p>
                          </div>
                        </div>
                      )}
                    </td>

                    <td className="px-6 py-6">
                      <div className="flex items-center justify-center gap-3">
                        {isEditing ? (
                          <input 
                            type="number" 
                            className="w-24 p-3 bg-white dark:bg-slate-900 border-2 border-orange-500 rounded-xl text-sm font-black text-center dark:text-white" 
                            value={editValues.stock} 
                            onChange={(e) => setEditValues({ ...editValues, stock: parseFloat(e.target.value) || 0 })} 
                          />
                        ) : (
                          <>
                            <button onClick={() => onUpdateStock(item.id, -1)} className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-400 hover:bg-red-100 hover:text-red-600 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100">-</button>
                            <span className={`px-5 py-2 rounded-2xl text-xs font-black border transition-colors ${isCritical ? 'bg-red-50 text-red-600 border-red-100 dark:bg-red-900/30 dark:border-red-900/50' : 'bg-slate-100 text-slate-700 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700'}`}>
                              {item.stock.toLocaleString()}
                            </span>
                            <button onClick={() => onUpdateStock(item.id, 1)} className="w-8 h-8 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-400 hover:bg-green-100 hover:text-green-600 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100">+</button>
                          </>
                        )}
                      </div>
                    </td>

                    <td className="px-6 py-6 text-center">
                      {isEditing ? (
                        <select className="p-3 bg-white dark:bg-slate-900 border-2 border-orange-500 rounded-xl text-xs font-black outline-none dark:text-white" value={editValues.unit} onChange={(e) => setEditValues({ ...editValues, unit: e.target.value })}>
                          {availableUnits.map(unit => <option key={unit} value={unit}>{unit.toUpperCase()}</option>)}
                        </select>
                      ) : (
                        <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest bg-slate-50 dark:bg-slate-800/50 px-3 py-1.5 rounded-lg border border-slate-100 dark:border-slate-700">
                          {item.unit}
                        </span>
                      )}
                    </td>

                    <td className="px-6 py-6 text-center">
                      <div className="flex items-center justify-center gap-1">
                        <span className="text-slate-400 text-[10px] font-black">L.</span>
                        {isEditing ? (
                          <input 
                            type="number" 
                            step="0.01" 
                            className="w-20 p-2 bg-white dark:bg-slate-900 border-2 border-orange-500 rounded-xl text-sm font-black text-center dark:text-white" 
                            value={editValues.costPerUnit} 
                            onChange={(e) => setEditValues({ ...editValues, costPerUnit: parseFloat(e.target.value) || 0 })} 
                          />
                        ) : (
                          <span className="text-sm font-black text-slate-700 dark:text-slate-300">{item.costPerUnit.toFixed(2)}</span>
                        )}
                      </div>
                    </td>

                    <td className="px-6 py-6 text-center">
                      <span className="text-sm font-black text-slate-900 dark:text-white">L. {itemTotalValue.toLocaleString(undefined, { minimumFractionDigits: 2 })}</span>
                    </td>

                    <td className="px-10 py-6 text-right">
                      {isEditing ? (
                        <div className="flex justify-end gap-2 animate-scaleIn">
                          <button onClick={() => saveEdit(item.id)} className="w-10 h-10 bg-green-600 text-white rounded-xl hover:bg-green-700 transition-all flex items-center justify-center shadow-lg shadow-green-900/20">✓</button>
                          <button onClick={() => setEditingId(null)} className="w-10 h-10 bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-400 rounded-xl hover:bg-slate-300 flex items-center justify-center transition-all">✕</button>
                        </div>
                      ) : (
                        <div className="flex justify-end gap-1">
                          <button onClick={() => startEditing(item)} className="p-3 text-slate-400 hover:text-orange-600 transition-all opacity-0 group-hover:opacity-100">✏️</button>
                          <button onClick={() => setDeleteConfirmItem(item)} className="p-3 text-slate-400 hover:text-red-500 transition-all opacity-0 group-hover:opacity-100">🗑️</button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}

              {paginatedIngredients.length === 0 && (
                <tr>
                  <td colSpan={6} className="py-32 text-center">
                    <div className="text-7xl mb-6 opacity-20">📦</div>
                    <p className="text-slate-400 dark:text-slate-600 font-black uppercase text-sm tracking-widest">No se encontraron resultados</p>
                    <p className="text-slate-300 dark:text-slate-700 text-xs mt-2">Prueba ajustando los filtros o la búsqueda.</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Paginación Moderna */}
        {totalPages > 1 && (
          <div className="px-10 py-6 bg-slate-50 dark:bg-slate-800/30 border-t border-slate-100 dark:border-slate-800 flex flex-col sm:flex-row justify-between items-center gap-4">
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              Mostrando {paginatedIngredients.length} de {filteredIngredients.length} insumos
            </span>
            <div className="flex items-center gap-1">
              <button 
                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                disabled={currentPage === 1}
                className="w-10 h-10 flex items-center justify-center rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-400 hover:text-slate-900 dark:hover:text-white disabled:opacity-30 transition-all"
              >
                ←
              </button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                <button
                  key={page}
                  onClick={() => setCurrentPage(page)}
                  className={`w-10 h-10 flex items-center justify-center rounded-xl text-[10px] font-black transition-all ${currentPage === page ? 'bg-orange-600 text-white shadow-lg' : 'bg-white dark:bg-slate-800 text-slate-400 hover:bg-slate-100 border border-slate-200 dark:border-slate-700'}`}
                >
                  {page}
                </button>
              ))}
              <button 
                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                disabled={currentPage === totalPages}
                className="w-10 h-10 flex items-center justify-center rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-400 hover:text-slate-900 dark:hover:text-white disabled:opacity-30 transition-all"
              >
                →
              </button>
            </div>
          </div>
        )}
      </div>

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

