                        className={`flex-1 py-4 bg-red-50 dark:bg-red-900/10 text-red-600 border border-red-100 dark:border-red-900/30 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all flex items-center justify-center gap-2`}
                      >
                        ❌ Cancelar
                      </button>
                    )}
                  </div>
                </div>

                {/* Acciones para historiales (Entregado/Cancelado) */}
                {isFinalized && (
                  <button 
                    onClick={() => onUpdateStatus(sale.id, 'Recibido')}
                    className="w-full py-3 bg-white dark:bg-slate-800 text-slate-500 border border-slate-100 dark:border-slate-700 rounded-xl font-black text-[9px] uppercase tracking-widest hover:bg-slate-100 flex items-center justify-center gap-2"
                  >
                    🔄 Reabrir Orden
                  </button>
                )}
              </div>
            </div>
          );
        })}

        {filteredSales.length === 0 && (
          <div className="col-span-full py-32 text-center bg-white dark:bg-slate-900 rounded-[4rem] border border-dashed border-slate-200 dark:border-slate-800">
            <div className="text-7xl mb-6 opacity-20">📭</div>
            <h3 className="text-xl font-black text-slate-400 uppercase tracking-widest">Sin registros en "{filter}"</h3>
            <p className="text-slate-300 dark:text-slate-600 mt-2 font-medium">Usa los filtros superiores para navegar por el historial.</p>
          </div>
        )}
      </div>

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .animate-pulse-slow { animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .7; } }
      `}</style>
    </div>
  );
};

