import React, { useState, useMemo } from 'react';
import { Sale, MenuItem, SaleStatus } from '../types';

interface OrdersManagerProps {
  sales: Sale[];
  menu: MenuItem[];
  onUpdateStatus: (saleId: string, status: SaleStatus) => void;
  onDeleteSale: (saleId: string) => void;
}

const OrdersManager: React.FC<OrdersManagerProps> = ({ sales, menu, onUpdateStatus, onDeleteSale }) => {
  const [filter, setFilter] = useState<SaleStatus | 'Activas' | 'Todas'>('Activas');

  const statuses: SaleStatus[] = ['Recibido', 'En Cocina', 'Listo', 'Entregado', 'Cancelado'];

  const filteredSales = useMemo(() => {
    return [...sales]
      .filter(s => {
        if (filter === 'Todas') return true;
        if (filter === 'Activas') return s.status !== 'Entregado' && s.status !== 'Cancelado';
        return s.status === filter;
      })
      .sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
  }, [sales, filter]);

  const getStatusConfig = (status: SaleStatus) => {
    switch (status) {
      case 'Recibido': 
        return { 
          color: 'bg-blue-100 text-blue-700 border-blue-200', 
          icon: '📩', 
          next: 'En Cocina',
          nextLabel: 'Empezar Cocina 🔥',
          prev: null 
        };
      case 'En Cocina': 
        return { 
          color: 'bg-orange-100 text-orange-700 border-orange-200', 
          icon: '🍳', 
          next: 'Listo',
          nextLabel: '¡Listo! ✅',
          prev: 'Recibido' 
        };
      case 'Listo': 
        return { 
          color: 'bg-green-100 text-green-700 border-green-200', 
          icon: '🔔', 
          next: 'Entregado',
          nextLabel: 'Entregar 📦',
          prev: 'En Cocina' 
        };
      case 'Entregado': 
        return { 
          color: 'bg-slate-900 text-white border-slate-900', 
          icon: '✅', 
          next: null,
          nextLabel: '',
          prev: null 
        };
      case 'Cancelado': 
        return { 
          color: 'bg-red-100 text-red-700 border-red-200', 
          icon: '🚫', 
          next: null,
          nextLabel: '',
          prev: null 
        };
      default: 
        return { color: 'bg-slate-100', icon: '❓', next: null, nextLabel: '', prev: null };
    }
  };

  return (
    <div className="space-y-8 animate-fadeIn pb-24">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">Flujo de Trabajo</h2>
          <p className="text-slate-500 dark:text-slate-400 font-medium">Gestiona, cancela o elimina pedidos en tiempo real.</p>
        </div>

        <div className="flex bg-white dark:bg-slate-900 p-1.5 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 overflow-x-auto max-w-full no-scrollbar">
          {['Activas', ...statuses, 'Todas'].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f as any)}
              className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                filter === f 
                ? 'bg-orange-600 text-white shadow-lg' 
                : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'
              }`}
            >
              {f}
            </button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredSales.map(sale => {
          const config = getStatusConfig(sale.status);
          const isFinalized = sale.status === 'Entregado' || sale.status === 'Cancelado';

          return (
            <div key={sale.id} className={`bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col overflow-hidden transition-all hover:shadow-xl group ${sale.status === 'Cancelado' ? 'opacity-60 grayscale-[0.3]' : ''}`}>

              {/* Card Header con Botón de Borrar Permanente */}
              <div className={`p-6 border-b border-slate-50 dark:border-slate-800 transition-colors relative ${sale.status === 'En Cocina' ? 'bg-orange-50/30 dark:bg-orange-900/10' : 'bg-slate-50/30 dark:bg-slate-800/20'}`}>

                {/* BOTÓN BORRAR PERMANENTE - Mejorado para accesibilidad móvil */}
                <button 
                  onClick={(e) => {
                    e.stopPropagation();
                    onDeleteSale(sale.id);
                  }}
                  className="absolute top-4 right-4 w-10 h-10 bg-white dark:bg-slate-800 text-slate-400 hover:text-red-500 rounded-full flex items-center justify-center shadow-md border border-slate-100 dark:border-slate-700 transition-all z-20 opacity-40 group-hover:opacity-100 hover:scale-110 active:rotate-12"
                  title="Eliminar registro permanentemente"
                >
                  <span className="text-xl">🗑️</span>
                </button>

                <div className="flex justify-between items-start mb-4 pr-10">
                  <div className="flex items-center gap-3">
                    <span className="text-2xl animate-pulse-slow">{config.icon}</span>
                    <div>
                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Orden #{sale.id.slice(-5)}</span>
                      <h3 className="text-lg font-black text-slate-900 dark:text-white truncate max-w-[140px]">{sale.customerName}</h3>
                    </div>
                  </div>
                  <div className={`px-3 py-1 rounded-full text-[9px] font-black uppercase border tracking-widest ${config.color}`}>
                    {sale.status}
                  </div>
                </div>
                <div className="flex items-center justify-between text-[10px] font-bold text-slate-400">
                  <span>🕒 {sale.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  <span className="bg-white dark:bg-slate-800 px-2 py-1 rounded shadow-sm border border-slate-100 dark:border-slate-700 uppercase tracking-tighter">{sale.paymentMethod}</span>
                </div>
              </div>

              {/* Items List */}
              <div className="p-6 flex-1 space-y-4">
                <div className="space-y-2.5 max-h-48 overflow-y-auto custom-scrollbar pr-2">
                  {sale.items.map((item, idx) => {
                    const menuItem = menu.find(m => m.id === item.menuItemId);
                    return (
                      <div key={idx} className="flex justify-between items-center group/item">
                        <div className="flex items-center gap-3">
                          <span className="w-7 h-7 rounded-xl bg-orange-100 dark:bg-orange-900/30 text-orange-600 flex items-center justify-center text-[11px] font-black border border-orange-200 dark:border-orange-800">
                            {item.quantity}
                          </span>
                          <div>
                            <span className="text-sm font-bold text-slate-700 dark:text-slate-300 group-hover/item:text-orange-600 transition-colors">
                              {menuItem?.name || 'Item'}
                            </span>
                            {item.customization && (
                              <p className="text-[10px] text-slate-400 italic">"{item.customization}"</p>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
                <div className="pt-4 border-t border-slate-100 dark:border-slate-800 flex justify-between items-end">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Cobro Total</span>
                  <span className="text-2xl font-black text-slate-900 dark:text-white leading-none">L. {sale.total.toFixed(2)}</span>
                </div>
              </div>

              {/* Botonera Dinámica */}
              <div className="p-6 bg-slate-50/50 dark:bg-slate-800/40 border-t border-slate-100 dark:border-slate-800 flex flex-col gap-3">
                <div className="flex flex-col gap-2">
                  {/* Botón de Siguiente Estado */}
                  {config.next && (
                    <button 
                      onClick={() => onUpdateStatus(sale.id, config.next as SaleStatus)}
                      className="w-full py-4 bg-orange-600 hover:bg-orange-500 text-white rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-lg shadow-orange-900/20 transition-all active:scale-95"
                    >
                      {config.nextLabel}
                    </button>
                  )}

                  <div className="flex gap-2 w-full">
                    {/* Botón de Deshacer */}
                    {config.prev && (
                      <button 
                        onClick={() => onUpdateStatus(sale.id, config.prev as SaleStatus)}
                        className="flex-1 py-4 bg-white dark:bg-slate-800 text-slate-400 border border-slate-200 dark:border-slate-700 rounded-2xl flex items-center justify-center hover:bg-slate-100 dark:hover:bg-slate-700 transition-all gap-2"
                      >
                        <span className="text-base leading-none">↺</span>
                        <span className="text-[9px] font-black uppercase tracking-widest">Deshacer</span>
                      </button>
                    )}

                    {/* Botón Cancelar (Cambio de estado) */}
                    {!isFinalized && (
                      <button 
                        onClick={() => { 
                          if(window.confirm('¿ESTÁS SEGURO DE CANCELAR ESTA ORDEN?\n\nLos insumos volverán automáticamente al inventario.')) {
                            onUpdateStatus(sale.id, 'Cancelado'); 
                          }
                        }}
                        className={`flex-1 py-4 bg-red-50 dark:bg-red-900/10 text-red-600 border border-red-100 dark:border-red-900/30 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all flex items-center justify-center gap-2`}
                      >
                        ❌ Cancelar
                      </button>
                    )}
                  </div>
                </div>

                {/* Acciones para historiales (Entregado/Cancelado) */}
                {isFinalized && (
                  <button 
                    onClick={() => onUpdateStatus(sale.id, 'Recibido')}
                    className="w-full py-3 bg-white dark:bg-slate-800 text-slate-500 border border-slate-100 dark:border-slate-700 rounded-xl font-black text-[9px] uppercase tracking-widest hover:bg-slate-100 flex items-center justify-center gap-2"
                  >
                    🔄 Reabrir Orden
                  </button>
                )}
              </div>
            </div>
          );
        })}

        {filteredSales.length === 0 && (
          <div className="col-span-full py-32 text-center bg-white dark:bg-slate-900 rounded-[4rem] border border-dashed border-slate-200 dark:border-slate-800">
            <div className="text-7xl mb-6 opacity-20">📭</div>
            <h3 className="text-xl font-black text-slate-400 uppercase tracking-widest">Sin registros en "{filter}"</h3>
            <p className="text-slate-300 dark:text-slate-600 mt-2 font-medium">Usa los filtros superiores para navegar por el historial.</p>
          </div>
        )}
      </div>

      <style>{`
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .animate-pulse-slow { animation: pulse 3s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
        @keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .7; } }
      `}</style>
    </div>
  );
};

