              <span className="text-3xl font-black text-orange-600">L. {quickCartTotal.toFixed(2)}</span>
            </div>

            <div className="flex gap-3">
              <button onClick={() => setIsConfirming(false)} className="flex-1 py-4 bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400 rounded-2xl font-black text-[10px] uppercase hover:bg-slate-200 dark:hover:bg-slate-700">Atrás</button>
              <button onClick={handleProcessQuickOrder} className="flex-1 py-4 bg-slate-900 dark:bg-orange-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-xl hover:bg-orange-500">Pagar Orden</button>
            </div>
          </div>
        </div>
      )}

